import type { TrendColour } from './instrument-trend';
import type { VitalState } from './quality-posture';

/** A placeholder/flat instrument has no risk direction, so its dot is `flat` — a
 *  fourth, neutral state alongside the three VitalStates. */
export type DotState = VitalState | 'flat';

/** Dot colour by risk state — shared by the Measured cards, the movers band, and
 *  the per-analyser detail header so a palette change lands in one place. */
export const DOT_COLOR: Record<DotState, string> = {
  ok: 'var(--color-done)',
  watch: 'var(--color-warn)',
  risk: 'var(--color-phase-red)',
  flat: 'var(--color-border-strong)',
};

/** Trend stroke/text colour by the keep-low invariant: a falling lower-better
 *  metric is good (green), a rising one bad (red), no movement neutral. */
export const TREND_COLOR: Record<TrendColour, string> = {
  good: 'var(--color-done)',
  bad: 'var(--color-phase-red)',
  neutral: 'var(--color-border-strong)',
};
