import React, { useState, useEffect, useCallback } from 'react';
import { SlidersHorizontal } from 'lucide-react';
import { ConfigEditor } from '../ConfigEditor';
import type { ConfigFlags } from '../../types';

type LoadState =
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'loaded'; flags: ConfigFlags };

/**
 * Global config mount: the brand-new dashboard surface for the
 * `repo > global > defaults` cascade's global tier (previously editable only
 * via `tb config`). Reads + writes `/api/config/flags`; writes land at global
 * scope. Renders the shared ConfigEditor in `global` mode (no clear-override).
 */
export const GlobalConfigSection: React.FC = () => {
  const [state, setState] = useState<LoadState>({ status: 'loading' });
  const [writeError, setWriteError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setState({ status: 'loading' });
    try {
      const res = await fetch('/api/config/flags');
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = (await res.json()) as { flags: ConfigFlags };
      setState({ status: 'loaded', flags: data.flags });
    } catch (err) {
      setState({ status: 'error', message: err instanceof Error ? err.message : 'Unknown error' });
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const handleWrite = useCallback(async (key: string, value: boolean | string) => {
    try {
      const res = await fetch('/api/config/flags', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key, value }),
      });
      if (!res.ok) {
        const detail = (await res.json().catch(() => null)) as { error?: unknown } | null;
        setWriteError(typeof detail?.error === 'string' ? detail.error : 'Failed to save change');
        return;
      }
      const data = (await res.json()) as { flags: ConfigFlags };
      setState({ status: 'loaded', flags: data.flags });
      setWriteError(null);
    } catch {
      setWriteError('Failed to save change');
    }
  }, []);

  return (
    <div className="space-y-6">
      <section className="rounded-2xl panel p-5 md:p-6">
        <div className="mb-4">
          <div className="flex items-center gap-2">
            <SlidersHorizontal className="h-5 w-5 text-blue" />
            <h2 className="text-lg font-semibold text-foreground">Configuration</h2>
          </div>
          <p className="mt-1 text-sm text-subtle">
            Global defaults applied across every repository. A repo can override
            any of these in its own Setup tab.
          </p>
        </div>
        {state.status === 'loading' && (
          <div role="status" className="text-sm text-muted-foreground">
            Loading configuration…
          </div>
        )}
        {state.status === 'error' && (
          <div role="alert" className="text-sm text-destructive">
            Failed to load configuration: {state.message}
          </div>
        )}
        {state.status === 'loaded' && (
          <>
            {writeError && (
              <div role="alert" className="mb-2 text-sm text-destructive">
                {writeError}
              </div>
            )}
            <ConfigEditor flags={state.flags} mode="global" onWrite={handleWrite} />
          </>
        )}
      </section>
    </div>
  );
};

export default GlobalConfigSection;
