import React, { useMemo } from 'react';
import { SidebarCard } from './SidebarCard';
import { cardTitleMarkers } from './CardTitleMarkers';
import MiniStatusRail from './MiniStatusRail';
import { StatusPill, type StatusVariant } from './StatusPill';
import type { Fix } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { toEffectiveTask, deriveFixEffectiveStatus } from '../utils/effective-task';
import { deriveFixDisplayProgress } from '../utils/fix-progress';
import { deriveFixWorktreeBranches } from '../utils/fix-worktree-branches';
import { formatRelativeTime } from '../utils/relative-time';

interface FixCardProps {
  fix: Fix;
  isSelected: boolean;
  onClick: () => void;
  reviewPipeline?: PipelineStep[];
  /**
   * The repo this fix belongs to. When present, a fix with live worktree work
   * gets a clickable worktree marker that opens the delivery island
   * (land/raise/reject/teardown). Absent in contexts without a repo scope.
   */
  repoId?: string;
  /** Open the WorkerRun island for the fix's live run (the rail's Running pill). */
  onOpenRun?: (runId: string) => void;
  /**
   * The authoritative landed axis (server-derived, the SAME
   * `WorkItemProvenance.landed` FixDetail gates on) — drives the failed-run
   * attention predicate for a completed fix (fix
   * failed-run-invisible-on-board-fix-detail task 2). Optional: the archive list
   * (FixCard's only caller) has no provenance feed, so it omits this and a
   * settled archived item degrades to suppression — never an unsound
   * branch-count guess, which cannot tell a landed fix with a lingering worktree
   * from an unlanded one.
   */
  landed?: boolean;
}

// `repoId` stays on the props (callers still pass it) but the card acts on
// nothing — delivery is opened from the fix DETAIL header, and so is the
// idle-state [Launch ▾] (header-only per the item-launch-rail design; cards
// are glance + navigate).
const FixCard: React.FC<FixCardProps> = ({ fix, isSelected, onClick, reviewPipeline, onOpenRun, landed }) => {

  // Shared promote-only rollup so the sidebar pill agrees with the fix-list
  // filter category and the detail eyebrow (cross-ref-status-visibility F5-T1).
  // Equivalent to the inline rollUp it replaces for a consistent projection
  // (rollup ≥ fix.status), but never downgrades below the backend fix.status.
  // Computed up here because the live-run worktree fold-in below gates on it.
  const effectiveFixStatus = deriveFixEffectiveStatus(fix);
  const isResolved = effectiveFixStatus === 'completed' || effectiveFixStatus === 'superseded';

  // The card's ONE narrowed activeRun source (fix launched-state-for-
  // dispatched-runs task 4): the server enrichment already projects what the
  // run means (launched / in_progress) and vetoes stale joins, so the card
  // reads it for not_started AND in_progress work — the old in_progress-only
  // gates hid the whole dispatch→first-commit window. The thin terminal veto
  // stays as defence-in-depth, the settled posture FixDetail and
  // PlanFeatureRow share: a resolved fix's lingering record must not
  // resurrect live chrome even if a payload slips through un-vetoed.
  const railActiveRun = isResolved ? undefined : fix.activeRun;
  // A worker (a live run) is driving this fix when activeRun carries a worker.
  // Single source for both the rail's 🤖 glyph and the worktree pill's icon
  // mode (avoids the predicate drifting between the two).
  const isWorkerDriven = railActiveRun?.worker !== undefined;
  // The launched window (the projected state, not a client re-derivation):
  // worker assigned, nothing landed — the pill says so instead of the git
  // axis's "Not started" beside a Running rail (defect 3 of the fix doc).
  const isLaunched = railActiveRun?.state === 'launched';

  // Branches this fix's work lives on, each flagged with whether a live worktree
  // exists — the fix analogue of PlanCard's marker. Keyed on the BRANCH (the
  // stable identity) so the same physical worktree, surfacing as both a
  // task/source dir-name and a lattice branch ref, collapses to one entry.
  // Lattice refs are filtered to live worktrees (isWorktree) STRICTLY AHEAD of
  // the launch ref; explicit task/source worktrees surface regardless of ahead-
  // status so a fresh/undiverged worktree still shows.
  const runWorktreePath = railActiveRun?.worktreePath;
  const worktreeBranches = useMemo(() => {
    const base = deriveFixWorktreeBranches(fix);
    // A live run's worktree surfaces a badge BEFORE any commit lands
    // (track-commit's task.worktree is a post-commit signal) — launched
    // included (task 4): the dispatch just created the worktree, so the badge
    // appears with the run rather than with the first commit. The terminal
    // veto on railActiveRun keeps a stale record on a completed fix from
    // resurrecting a badge. Dedupe by the worktree dir name (last path
    // segment) against the base entries, so once commits start landing the
    // run badge collapses into the task one.
    const runWorktreeName = runWorktreePath?.split('/').filter(Boolean).slice(-1)[0];
    if (!runWorktreeName || base.some((b) => b.worktreeName === runWorktreeName)) return base;
    return [...base, { branch: runWorktreeName, hasWorktree: true, worktreeName: runWorktreeName }];
  }, [fix, runWorktreePath]);

  // Roll the card status/progress up from WORKTREE-EFFECTIVE task statuses, so a
  // fix whose work is all done on a worktree branch reads done in the sidebar
  // like its detail row icons already do (ADR-0007 display rollup; fix:
  // fix-status-head-only-vs-across-refs). Empty-task fixes keep raw fix.status.
  const effectiveTasks = useMemo(() => fix.tasks.map(toEffectiveTask), [fix.tasks]);

  // Phase-aware completion percentage via the SHARED deriveFixDisplayProgress: the
  // settled short-circuit (worktree-effective terminal → 100) plus the
  // phase-weighted mean. FixCard originated this rule; it now lives in one place so
  // FixDetail and the board open-item override can't drift from the card
  // (unify-settled-progress-short-circuit).
  const progress = useMemo(() => deriveFixDisplayProgress(fix, reviewPipeline), [fix.tasks, fix.status, reviewPipeline]);

  const isInProgress = effectiveFixStatus === 'in_progress';
  const isArchived = fix.archived === true;
  // Failed-run attention (fix failed-run-invisible-on-board-fix-detail task 2):
  // the red glyph shows for ACTIVE work carrying a failed run (a failed dispatch
  // matters before/while working — the pre-existing behaviour) AND for a
  // COMPLETED fix that is explicitly NOT landed (its own completion/land
  // validation failed) — the same completed-unlanded case FixDetail surfaces,
  // keyed on the SAME authoritative `landed` axis so the two never disagree where
  // both render. A landed or superseded fix stays suppressed (moot); when
  // `landed` is unknown (the archive omits it) a completed item degrades to
  // suppression rather than a false positive.
  const showFailedAttention =
    fix.hasFailedRun === true &&
    (!isResolved || (effectiveFixStatus === 'completed' && landed === false));

  const totalTasks = effectiveTasks.length;
  // The pink→blue bar appears whenever there's progress to show — active or
  // resolved. A not-started fix shows just its pill (matching PlanCard).
  const showProgress = isResolved || isInProgress;
  // No gate-derived Validating variant (fix validating-derived-from-review-
  // gates-not-pipeline-runs): an open review gate is the task's own work —
  // the card reads In progress through the whole gates-open window.
  // Validating is a real-pipeline-run fact the BOARD row carries (post-merge);
  // the sidebar card has no such signal and never infers one from tasks.
  const variant: StatusVariant = isResolved
    ? 'done'
    : isInProgress || isLaunched
      ? 'in-progress'
      : 'not-started';
  const relativeDate = formatRelativeTime(fix.resolved ?? fix.reported);

  // Worker-driven state now rides the rail's Bot glyph (not a separate eyebrow /
  // footer). Reads the narrowed railActiveRun (task 4): launched and
  // in_progress runs both light the glyph — the terminal veto above (not an
  // in_progress-only gate) is what keeps a stale record off a resolved fix.
  // A cloud-remote run reads as a remote worker (Bot + Cloud, no chip).
  const railIsWorker = isWorkerDriven;
  const railWhere = railActiveRun?.target === 'cloud-remote' ? 'remote' : 'local';
  // The Running pill (a navigation affordance — opens the WorkerRun island)
  // reads the same narrowed source, so it appears the moment dispatch lands.
  const activeRunId = railActiveRun?.runId;


  return (
    <SidebarCard
      testId={isArchived ? 'archived-card' : 'fix-card'}
      status={variant}
      isSelected={isSelected}
      isArchived={isArchived}
      emphasized={isInProgress || isSelected}
      onClick={onClick}
      title={fix.title}
      titleAside={cardTitleMarkers({ hasAssets: fix.hasAssets, assetCount: fix.assetCount, isArchived })}
      pills={<StatusPill variant={variant} label={isResolved ? 'Completed' : isLaunched ? 'Launched' : undefined} />}
      // Glance-only on the card — acting on the worktree is the detail header.
      rail={
        <MiniStatusRail
          mode="card"
          branches={worktreeBranches}
          activeRunId={activeRunId}
          onOpenRun={activeRunId && onOpenRun ? () => onOpenRun(activeRunId) : undefined}
          isWorkerRun={railIsWorker}
          workerName={railIsWorker ? railActiveRun?.worker : undefined}
          workerModel={railIsWorker ? railActiveRun?.model : undefined}
          where={railWhere}
          envName={railActiveRun?.envName}
          // The red failed glyph (see showFailedAttention above): active work with
          // a failed run, or a completed-but-explicitly-unlanded fix — the same
          // completed-unlanded case FixDetail surfaces, so card and detail agree
          // and both agree with BoardCard.
          attentionStatus={showFailedAttention ? 'failed' : undefined}
        />
      }
      progress={showProgress ? progress : null}
      metaLeft={
        <>
          {totalTasks} <span className="font-sans">{totalTasks === 1 ? 'task' : 'tasks'}</span>
          {showProgress && (
            <>
              {' · '}
              <span className="mono">{progress}%</span>
            </>
          )}
          {' · '}
          <span className="font-sans">{fix.severity}</span>
        </>
      }
      metaRight={relativeDate ?? undefined}
    />
  );
};

export default FixCard;
