interface FixDetailProps {
  fix: Fix;
  repoId: string;
  onArchive?: () => void;
  onUnarchive?: () => void;
  /**
   * Open the WorkerRun island for the fix's live run. Un-retired for the live
   * control strip (fix control-strip-mute-during-live-run task 1): past the
   * launched window the strip's pulsing live glyph clicks through here, so the
   * run stream is one click from the strip.
   */
  onOpenRun?: (runId: string) => void;
  /**
   * The fix branch's MODELED land availability (the F6 delivery model's
   * reconcile-derived axis), when the host knows it (F7 task 2). Drives the
   * validation reconcile lane's reconstruction on refresh (via
   * `withReconcileOverlay`) and gates the end-cap's Merge off a conflicted
   * branch. Absent ⇒ client-edge cap as before.
   */
  landAvailability?: LandAvailability;
  /**
   * The branch's persisted latest verdict + reason (the model's lastReconcile
   * axis) — the reconcile lane's reconstruction source for the FAILURE family,
   * which `landAvailability` deliberately reads as `unknown` (fix
   * verify-outcomes-invisible-in-ui task 1).
   */
  lastReconcile?: LastReconcileFeed;
  /**
   * The branch's LIVE machinery run id (model-named, e.g. a CLI reconcile) —
   * the strip subscribes to it so "Verifying…" renders with no click here
   * (fix verify-outcomes-invisible-in-ui task 2).
   */
  liveReconcileRunId?: string;
  /**
   * The board row's server-derived cleanup signal (done-lane-cleanup task 10):
   * delivery proven AND a typed worktree branch still on disk, joined by the
   * projection (the one place that owns worktree↔item matching). The host
   * passes it because the client-side branch derivation cannot see a landed
   * fix's lingering branch (it filters to strictly-ahead refs, and a landed
   * branch is never ahead). Absent (ArchiveView) ⇒ the client-derived
   * predicate alone decides.
   */
  cleanup?: boolean;
  /**
   * The provenance the selected board row already carries (its `producingRun`
   * who + `landed` bit), projected to a minimal {@link WorkItemProvenance} seed
   * (fix board-detail-provenance-not-seeded-from-summary). The detail pane paints
   * the who glyph and delivery state from this on the first frame, so they no
   * longer flash empty behind the per-item provenance fetch — which still runs
   * and replaces the seed when it lands.
   */
  provenanceSeed?: WorkItemProvenance;
}

// Lowercase status word for the header eyebrow ("Fix · in progress") on the
// GIT axis — not started, in progress, completed (superseded is terminal and
// reads as completed here too). The eyebrow's fourth word, `launched`, is the
// RUN axis and rides the eyebrowLabel derivation below, not this map.
const statusLabels: Record<Fix['status'], string> = {
  not_started: 'not started',
  in_progress: 'in progress',
  completed: 'completed',
  superseded: 'completed',
};

// Severity dot colour for the header pill (low→blue … critical→red).
const severityDot: Record<Fix['severity'], string> = {
  low: 'bg-blue-500',
  medium: 'bg-amber-500',
  high: 'bg-orange-500',
  critical: 'bg-red-500',
};

const FixDetail: React.FC<FixDetailProps> = ({ fix, repoId, onArchive, onUnarchive, onOpenRun, landAvailability, lastReconcile, liveReconcileRunId, cleanup, provenanceSeed }) => {
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId);
  // The fix's land history (work-item-provenance F4 task 4) — when/how it
  // landed, folded into the item's provenance payload like the PRD detail's.
  // Keyed on the live fix payload so the snapshot re-syncs on reprojection.
  // A delivery/reconcile terminal bumps this tick so the provenance snapshot
  // re-syncs with the just-persisted verdict — the refetch that closes the
  // foreign-run loop (adversarial review of 4f79d6c4a, MEDIUM: the hook's
  // onSuccess was production-inert here, proven only by its unit test).
  const [deliveryRefreshTick, setDeliveryRefreshTick] = useState(0);
  const provenanceRefreshKey = useMemo(() => ({ fix, deliveryRefreshTick }), [fix, deliveryRefreshTick]);
  const { provenance, loading: provenanceLoading } = useWorkItemProvenance(
    repoId,
    'fix',
    fix.id,
    provenanceRefreshKey,
  );
  const [sourceOpen, setSourceOpen] = useState(false);
  const [, setSearchParams] = useSearchParams();

  const [rerunning, setRerunning] = useState(false);
  const [rerunError, setRerunError] = useState<string | undefined>(undefined);
  const [dispositionError, setDispositionError] = useState<string | undefined>(undefined);
  // POST a per-mutant disposition, surfacing a failure (never swallowing it) and
  // bumping the refresh tick on success so the re-projected state surfaces.
  const disposeSurvivor = (identity: MutantIdentity, disposition: 'equivalent' | 'accepted', reason?: string) => {
    setDispositionError(undefined);
    void postMutantDisposition(repoId, identity, disposition, reason)
      .then(() => setDeliveryRefreshTick((t) => t + 1))
      .catch((err) => setDispositionError(err instanceof Error ? err.message : 'Failed to record disposition'));
  };
  // Harden a survivor (F5): dispatch a mutant-scoped remediation run, then bump
  // the refresh tick so the just-dispatched run surfaces. A refusal (409 already
  // in flight) is SURFACED, not swallowed.
  const hardenSurvivor = (identity: MutantIdentity) => {
    setDispositionError(undefined);
    void postHardenSurvivor(repoId, `fix:${fix.id}`, identity)
      .then(() => setDeliveryRefreshTick((t) => t + 1))
      .catch((err) => setDispositionError(err instanceof Error ? err.message : 'Failed to dispatch harden run'));
  };
  // Re-run the completion lane, then bump the refresh tick so the just-dispatched
  // run surfaces. A refusal (409 "already running") is SURFACED, not swallowed —
  // it re-enables the button with the route's honest reason (the api contract).
  const onRerunValidation = async () => {
    setRerunning(true);
    setRerunError(undefined);
    try {
      await postRevalidateCompletion(repoId, `fix:${fix.id}`);
      setDeliveryRefreshTick((t) => t + 1);
    } catch (err) {
      setRerunError(err instanceof Error ? err.message : 'Failed to re-run validation');
    } finally {
      setRerunning(false);
    }
  };

  // Count by WORKTREE-EFFECTIVE status, not raw launch-ref status: a task
  // completed on a worktree branch counts as done here just like its row icon
  // already shows (ADR-0007 display rollup; fix: fix-status-head-only-vs-across-refs).
  const effectiveTasks = useMemo(() => fix.tasks.map(toEffectiveTask), [fix.tasks]);

  // Which worktree(s) the fix's work lives on — the same branch-keyed marker the
  // sidebar card carries, so the detail header shows the worktree affordance too
  // (fix fixcard-status-ignores-worktree Task 3).
  const worktreeBranches = useMemo(() => deriveFixWorktreeBranches(fix), [fix]);
  // Open the worktree-merge island as the full content-replacing view (?island=),
  // not inline within the fix detail.
  const openIsland = () => {
    const branch = worktreeBranches[0]?.branch;
    if (!branch) return;
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('island', branch);
      return next;
    });
  };
  // Open the design-assets view (surface-design-assets F3) as a mode of THIS
  // fix — the fix is already the selected item, so `?assets` is a bare marker;
  // the F4 view reads kind + slug from the active area + selected item.
  const openAssets = () => {
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('assets', '');
      return next;
    });
  };
  const totalTasks = effectiveTasks.length;

  // Rows by worktree-effective status, keeping each task's ORIGINAL doc
  // position for its component slug. Completed tasks stay INLINE with the open
  // ones in doc order (user call, 2026-07-24 — the mock's flat list, §03/§04:
  // a fix in review just shows its tasks done); only superseded rows move into
  // their collapsed section (task 38's pattern, retained for retired work).
  const { mainRows, supersededRows, completedCount } = useMemo(() => {
    const mainRows: Array<{ task: Fix['tasks'][number]; index: number }> = [];
    const supersededRows: typeof mainRows = [];
    let completedCount = 0;
    fix.tasks.forEach((task, index) => {
      const status = effectiveTasks[index]?.status;
      if (status === 'superseded') {
        supersededRows.push({ task, index });
        return;
      }
      if (status === 'completed') completedCount += 1;
      mainRows.push({ task, index });
    });
    return { mainRows, supersededRows, completedCount };
  }, [fix.tasks, effectiveTasks]);
  const [supersededExpanded, setSupersededExpanded] = useState(false);

  // The stat readout's counts ARE the row-partition's — one derivation, so the
  // readout and the section labels cannot disagree (adversarial review of
  // 2767f2d49).
  const supersededCount = supersededRows.length;
  const doneTasks = completedCount + supersededCount;
  const left = totalTasks - doneTasks;

  // Phase-aware completion percentage via the SHARED deriveFixDisplayProgress — the
  // settled short-circuit + phase-weighted mean the sidebar FixCard and the board
  // open-item override also use, so the header can never drift from them and a
  // settled fix's bar agrees with its resolved eyebrow
  // (unify-settled-progress-short-circuit; board-card-progress-not-synced-with-open-detail).
  const progress = useMemo(() => deriveFixDisplayProgress(fix, reviewPipeline), [fix, reviewPipeline]);

  const resolvedDetail = supersededCount > 0
    ? `${completedCount} done · ${supersededCount} superseded · ${left} left`
    : `${doneTasks} done · ${left} left`;

  // The header eyebrow follows the worktree-effective fix status (the shared
  // rollup of the per-task effective statuses), so a fix whose work is all done
  // on a worktree reads resolved instead of in progress, and the eyebrow agrees
  // with the sidebar card and the list filter category. Empty-task fixes keep
  // the raw fix.status (a manually-resolved fix carries no tasks to roll up).
  const effectiveFixStatus = deriveFixEffectiveStatus(fix);
  const isResolved = effectiveFixStatus === 'completed' || effectiveFixStatus === 'superseded';
  const isArchived = fix.archived === true;
  // The detail's ONE narrowed activeRun source (fix launched-state-for-
  // dispatched-runs task 3, hardened per the adversarial review of
  // e78349d7e): the server's enrichment derives what the run means
  // (launched / in_progress) from the worktree-effective status and VETOES
  // the join on terminal items, so the old in_progress-only client gate —
  // which swallowed the whole dispatch→first-commit window — is deleted. A
  // thin TERMINAL veto stays as defence-in-depth (the settled posture FixCard
  // shares): a stale record on a resolved fix must not hide the completed tag
  // and unmount the cap column, even if a payload slips through un-vetoed.
  const activeRun = isResolved ? undefined : fix.activeRun;
  // The launched window: worker assigned, nothing landed on any ref. Drives
  // the strip's launched reading, the endcap's inert Launched cap, and the
  // header eyebrow below.
  const launched = activeRun?.state === 'launched';
  // The eyebrow speaks the launched window too (fix launched-status-on-
  // detail-eyebrow): "Fix · launched" in the blue live family — the same
  // state the card pill and the Launched cap render — instead of stamping
  // the git axis's "not started" over a live dispatch. The run axis LEADS
  // whenever the fact is present (even against a contradictory in_progress
  // payload — FixCard's isLaunched parity); every other state keeps its
  // git-derived label, and the terminal veto on `activeRun` above keeps a
  // stale record off a resolved eyebrow.
  const eyebrowLabel = launched ? 'launched' : statusLabels[effectiveFixStatus];
  const eyebrowColor =
    launched || effectiveFixStatus === 'in_progress' ? 'text-blue' : isResolved ? 'text-done' : 'text-subtle';
  const resolution = fix.resolution;
  const hasResolution = !!resolution && (
    !!resolution.rootCause ||
    (resolution.fix?.length ?? 0) > 0 ||
    (resolution.filesModified?.length ?? 0) > 0
  );

  // The whole-fix control strip (detail-action-endcap task 3 — mock §03/§04/§05):
  // a fix has no features, so the one-action end-cap applies ONCE to the whole
  // item. The strip's chips read the fix's synthetic provenance feature (the
  // projection keys a fix's tasks to one feature under the fix id); the land
  // unit is the fix's worktree BRANCH — the same whole-item `/delivery/land`
  // the board's Land button posts, not the PRD's per-feature route.
  const stripBranch = worktreeBranches[0]?.branch;
  // The provenance the who glyph and delivery state paint from: the fetched
  // payload once it lands, else the board row's SEED (fix board-detail-
  // provenance-not-seeded-from-summary) so the first frame shows what the
  // selected row already displayed instead of flashing empty. The seed's
  // `landed` is the SAME git-derived bit the fetch resolves, so the endcap and
  // cleanup gates below read it without risking a mid-fetch contradiction. And
  // the reaped/cleanup split stays stable from the first frame: the board host
  // always threads a DEFINED `cleanup` prop, so the deliverable-row probe never
  // fires (its gate needs `cleanup === undefined`) and `serverSaysCleanup` is
  // frame-1 authoritative — the seed only moves the (already-correct) reaped
  // read one frame earlier, never flips it. Land history stays on the fetched
  // `provenance` — the row carries none, and an empty panel must not flash.
  // (`?? null` keeps the strict `=== null` guards.)
  const effectiveProvenance = provenance ?? provenanceSeed ?? null;
  const fixProvenanceView = effectiveProvenance?.features[0];
  // The resolution retrospective (root cause / fix / files) is a Done-lane
  // section (validation-pipeline-visibility IA): it shows only once the fix has
  // LANDED. An In-Review fix (completed, unlanded) carries the command
  // affordances, not the retrospective — even when it already has resolution
  // content. Gated on the same git-derived `landed` bit the endcap reads, off the
  // effective provenance (seed OR fetch). Deliberately conservative: while
  // provenance is unknown (no seed and the fetch pending/failed) the retrospective
  // stays hidden rather than flash on an unconfirmed-landed fix — the same
  // err-hidden direction every sibling Done gate (inCleanup, reapedLanded, the
  // endcap's `landed`) takes.
  const showResolution = hasResolution && effectiveProvenance?.landed === true;
  // The Done state (settled + landed): the same landed bit `showResolution` and
  // the endcap read. When true the under-strip content groups into three
  // collapsible eyebrow sections (Resolution / Validation / Work), mirroring the
  // PRD `FeatureStatusGroup` eyebrow header (via `EyebrowSection`); every non-Done
  // state renders the flat stack exactly as before.
  const doneLanded = effectiveProvenance?.landed === true;
  // Per-section fold state — Resolution defaults CLOSED (longest, least-read
  // once settled), Validation and Work default OPEN. Each toggles independently.
  const [resolutionOpen, setResolutionOpen] = useState(false);
  const [validationOpen, setValidationOpen] = useState(true);
  const [workOpen, setWorkOpen] = useState(true);
  const live = activeRun !== undefined;
  // Failed-run attention (fix failed-run-invisible-on-board-fix-detail task 2):
  // a COMPLETED fix that is explicitly NOT landed and carries a failed run keeps
  // the red failed glyph the board card shows — the failure IS this item's own
  // completion/land validation, not a stale pre-work dispatch. Scoped to
  // `completed` (not every resolved/in-flight state) so it surfaces exactly the
  // case this fix targets, and gated on `landed === false` — positive, like the
  // cleanup/endcap gates below — so a null/loading provenance never FLASHES red
  // on a fix that turns out landed.
  const failedAttention =
    effectiveFixStatus === 'completed' && fix.hasFailedRun === true && provenance?.landed === false;
  // The live run's stream, one click from the strip (fix control-strip-mute-
  // during-live-run task 1): the pulsing live glyph opens the WorkerRun island
  // via the host's onOpenRun. Narrowed to a const so no `!` assertion is
  // needed, and glance-only (no click) when the host wires no opener.
  const liveRunId = activeRun?.runId;
  const openActiveRun =
    liveRunId !== undefined && onOpenRun !== undefined ? () => onOpenRun(liveRunId) : undefined;
  // Whether the strip's branch is LIVE on disk (task 6): attribution stamps
  // survive a reap, so only a git-derived lattice cell proves the branch still
  // exists — the delivered-and-reaped state must not offer surfaces for it.
  const stripBranchLive = stripBranch !== undefined && hasLiveWorktreeCell(fix.tasks, stripBranch);
  // The server's per-branch deliverable row, probed ONLY in the ambiguous
  // state — landed, no host-threaded board-row signal, and no live lattice
  // cell (fix fix-detail-cleanup-vanishes-for-landed-lingering-worktree):
  // after a fast-forward land `base..branch` is EMPTY, so the lattice probe
  // above reads "reaped" while the worktree may still be on disk, and only
  // the server can tell the two states apart. When the lattice cell IS live
  // the client predicate below already answers, so no fetch fires.
  const probedCleanup = useDeliverableRowCleanup(
    repoId,
    stripBranch,
    cleanup === undefined && effectiveProvenance?.landed === true && !stripBranchLive,
    deliveryRefreshTick,
  );
  // The ONE server verdict on cleanup: the host-passed board-row signal
  // (done-lane-cleanup task 10) where a host threads it, the probed
  // deliverable row where none does. Every gate below reads THIS, never the
  // two sources separately.
  const serverSaysCleanup = cleanup === true || probedCleanup;
  // Delivered-and-reaped: landed while the branch no longer exists — the ONE
  // state every pre-endcap gate below keys on (hoisted per the adversarial
  // review of 459549a4f so the Show-details cap and the endcap branch fact can
  // never disagree about the same reaped fix). A server cleanup verdict proves
  // the branch is still on disk, so it vetoes the lattice's "reaped" read.
  const reapedLanded = effectiveProvenance?.landed === true && !stripBranchLive && !serverSaysCleanup;
  // Cleanup state (done-lane-cleanup task 8): delivery proven on main AND the
  // worktree still on disk. The control strip has nothing left to offer there
  // (no merge, no chips, no teardown cap), so CleanupCommand replaces the whole
  // row — it swaps in, never stacks. The server verdict leads; the client
  // lattice predicate stays as the no-data fallback, and requires the LIVE
  // cell (task 6) so stale attribution on a reaped fix never swaps in a
  // manifest-less (null) command and lose the strip.
  const inCleanup = serverSaysCleanup || (effectiveProvenance?.landed === true && stripBranchLive);
  // Land and teardown are STREAMED delivery runs (adversarial review of
  // 976f3f096, HIGH): the POST resolves `{runId}` and the real outcome —
  // completed / failed / conflicts — arrives on the run stream. useDeliveryActions
  // (the F5 island's wiring) owns that fold, so a refused or conflicted land
  // surfaces its exit reason here instead of resolving silently. Resume stays a
  // plain POST: it starts a NEW run the header rail then picks up.
  const delivery = useDeliveryActions(repoId, stripBranch ?? '', {
    // Terminal ends (self land/reconcile AND watched foreign runs) re-sync the
    // provenance snapshot with the just-persisted verdict.
    onSuccess: () => setDeliveryRefreshTick((t) => t + 1),
    ...(landAvailability !== undefined ? { landAvailability } : {}),
    ...(lastReconcile !== undefined ? { lastReconcile } : {}),
    ...(liveReconcileRunId !== undefined ? { liveReconcileRunId } : {}),
  });
  // The ValidationPanel (props-in-ui F3d): ASSEMBLE the panel from the server-
  // composed `detail` payload — the shared core producers (lifecycle phase +
  // per-step validation panel + post-merge lane + regression evidence + runs) —
  // rather than folding runs on the client. `assembleValidationPanel` shapes those
  // already-derived pieces into the render contract (visibility is the shared
  // git-terminal predicate's call: `hidden` for a non-git-terminal fix or a repo
  // configuring neither pipeline; a receipt / all-pending preview otherwise), and
  // `withReconcileOverlay` layers the LIVE reconcile lane + merge boundary from the
  // client-derived strip (`delivery.reconcile`). `undefined` only when the endpoint
  // attached no detail at all (older payload / fail-soft) — no panel.
  const validationPanel = useMemo(() => {
    const detail = fix.detail;
    if (detail === undefined) return undefined;
    const landed = detail.tddJourney.landed;
    const base = assembleValidationPanel({
      status: fix.status,
      validation: detail.validation,
      validationPanel: detail.validationPanel,
      postMergeLane: detail.postMergeLane,
      regressionEvidence: detail.regressionEvidence,
      landed,
      runs: detail.runs,
    });
    // The reconcile lane is gated until completion has passed; a reconcile / merge /
    // post-merge phase means completion already passed (workItemPassed). The pending
    // post-merge lane previews only when the repo configures a post-land pipeline.
    const workItemPassed =
      detail.validation.pipeline !== 'item_completion' || detail.validation.status === 'passed';
    const postMergeConfigured = detail.postMergeLane !== undefined;
    // The reconcile lane's FAILURE detail (land-failure-surfacing task 5): the reason
    // + conflicting files from the server-composed `lastReconcile` axis, so a failed
    // reconcile names its rung + reason + files + the /merge next step below the row.
    const failureDetail =
      detail.lastReconcile !== undefined
        ? {
            ...(detail.lastReconcile.exitReason !== undefined ? { reason: detail.lastReconcile.exitReason } : {}),
            ...(detail.lastReconcile.conflictedFiles !== undefined
              ? { conflictedFiles: detail.lastReconcile.conflictedFiles }
              : {}),
            // The failing branch builds the copyable `tiny-brain reconcile-branch <branch>`
            // recovery incantation (task 5).
            ...(stripBranch !== undefined ? { branch: stripBranch } : {}),
            // The main a catch-up-conflict moved to (persistent-catch-up-conflict F3):
            // used only when the exitReason is `catch-up-conflict`, to name the moved-to
            // main SHA in place of the raw reason.
            ...(detail.reconciledAgainst !== undefined ? { reconciledAgainst: detail.reconciledAgainst } : {}),
          }
        : undefined;
    const state = withReconcileOverlay(base, {
      reconcile: delivery.reconcile,
      landed,
      workItemPassed,
      postMergeConfigured,
      ...(failureDetail !== undefined ? { failureDetail } : {}),
      // The provisional ready footer (F2) names the main the item is ready as of.
      ...(detail.reconciledAgainst !== undefined ? { reconciledAgainst: detail.reconciledAgainst } : {}),
    });
    // Bundle the render state with the lifecycle phase it was assembled from, so the
    // header phase pill reads `phase` without an optional chain — when `state` is
    // active, `phase` is present by construction (both come off the same `detail`).
    return { state, phase: detail.validation };
  }, [fix.detail, fix.status, delivery.reconcile, stripBranch]);
  const [endcapNotice, setEndcapNotice] = useState<string | null>(null);
  const onEndcapLand = (method: 'ff-only' | 'merge') => {
    // No branch → nothing to land from here (defence-in-depth; the cap only
    // offers merge on done-unlanded work, which lives on a branch). The chooser
    // forwards the picked method (fix merge-cap-lacks-method-and-pr-choice) —
    // the host no longer hardcodes 'ff-only'.
    if (stripBranch === undefined) return;
    setEndcapNotice(null);
    delivery.onLand(method);
  };
  const onEndcapRaise = () => {
    // Raise a PR instead of landing (fix merge-cap-lacks-method-and-pr-choice
    // task 2): the existing /delivery/raise orchestrator, keyed by the fix's
    // branch, with the title prefilled from the fix. The outcome — the PR url,
    // or the honest refusal reason — surfaces through the same notice channel.
    // No branch ⇒ an honest, non-retryable notice (consistent with the PRD
    // host's guard — adversarial review of 6683b2c84), not a silent no-op.
    if (stripBranch === undefined) {
      setEndcapNotice(RAISE_NO_BRANCH_NOTICE);
      return;
    }
    setEndcapNotice(null);
    void postDeliveryRaise(repoId, stripBranch, fix.title, fix.title)
      .then((result) => setEndcapNotice(raiseOutcomeNotice(result)))
      .catch(() => setEndcapNotice(RAISE_FAILED_NOTICE));
  };
  const onEndcapTeardown = () => {
    setEndcapNotice(null);
    // No runIds: the strip's worktree fact carries only the branch (run records
    // ride the F5 island's richer model, not this cap).
    delivery.onTeardown({ worktree: true, branch: true, runIds: [] });
  };
  const onEndcapResume = (runId: string) => {
    setEndcapNotice(null);
    void postRunResume(repoId, runId).catch(() => setEndcapNotice(RESUME_FAILED_NOTICE));
  };
  const onEndcapContinue = () => {
    // Continue parked work (fix incomplete-item-with-completed-run-cannot-
    // relaunch): the POST carries only the item — the server resolves the
    // latest continuable run and relaunches onto its EXISTING worktree. The
    // new run then surfaces as activeRun over the normal SSE tick.
    setEndcapNotice(null);
    void postLaunchContinue(repoId, `fix:${fix.id}`).catch(() =>
      setEndcapNotice(CONTINUE_FAILED_NOTICE),
    );
  };
  // One notice slot: the resume fault (local state) or the streamed land /
  // teardown failure folded out of the delivery hook's channels.
  const stripNotice = endcapNotice ?? delivery.landFailure ?? delivery.teardownError ?? null;

  // Whether the end-cap hosts the Launch control (F6 task 4): no worktree, not
  // resolved, not archived, no live run. The idle strip hint below is driven
  // off the SAME fact so the two surfaces cannot disagree (adversarial review
  // of 6d7ebf86a) — a hand-rolled second gate showed "Click to launch →" while
  // the cap offered Resume.
  const launchTargetPresent =
    worktreeBranches.length === 0 && !isResolved && !isArchived && activeRun === undefined;
  // The muted idle hint points at that Launch cap — shown only when the cap
  // actually resolves to Launch: an untouched fix with no failed run (a failed
  // run makes `mayHaveRun` true, so the cap probes and offers Resume, rung 2,
  // long before Launch, rung 10).
  const showIdleLaunchHint =
    launchTargetPresent && effectiveFixStatus === 'not_started' && fix.hasFailedRun !== true;
  // The settled strip's branch chip: the delivery's own branch, else the
  // lingering worktree branch (the same fold DeliveredProvenance used).
  const settledBranch =
    fixProvenanceView !== undefined
      ? (fixProvenanceView.delivery.where.kind === 'branch'
          ? fixProvenanceView.delivery.where.branch
          : undefined) ?? stripBranch
      : undefined;

  const tasksResolvedReadout =
    totalTasks > 0 ? (
      <StatReadout label="Tasks resolved" value={progress} detail={resolvedDetail} />
    ) : null;

  // The movable Done-lane blocks, defined once and rendered either FLAT (every
  // non-Done state, exactly as before) or grouped under the three collapsible
  // eyebrow sections when `doneLanded` (fix-detail-done-collapsible-sections).

  // Validation panel — the completion/post-merge surface, folded from the run
  // records the fix-detail endpoint threads. Presence is the shared git-terminal
  // predicate (Governing invariant): shown on every git-terminal fix with a
  // configured pipeline, hidden only when the repo configures neither pipeline.
  // The place to ACT on a red: see the failed step + its reason, re-run the
  // lane, or copy `complete`.
  const validationBlock =
    !inCleanup && validationPanel?.state.kind === 'active' ? (
      <div className="space-y-1">
        <ValidationPanel
          state={validationPanel.state}
          validation={validationPanel.phase}
          onRerun={onRerunValidation}
          rerunning={rerunning}
          completeCommand={`tiny-brain complete --fix ${fix.id}`}
          landed={doneLanded}
          // Retry-reconcile (F4): re-run the reconcile ladder for the branch the panel
          // EMITTED — forwarded to `onPrepare` (POST /reconcile) so the named and
          // reconciled branch cannot diverge; `reconcileRunId` is the in-flight
          // (self-started) double-dispatch guard.
          onRetryReconcile={(branch) => delivery.onPrepare(branch)}
          retryReconcileInFlight={delivery.reconcileRunId !== undefined}
          // Per-mutant triage (F4 task 2): POST the disposition; disposeSurvivor
          // surfaces failures and bumps the refresh tick on success.
          onMarkEquivalentSurvivor={(identity) => disposeSurvivor(identity, 'equivalent')}
          onAcceptSurvivor={(identity, reason) => disposeSurvivor(identity, 'accepted', reason)}
          // Harden test (F5): dispatch a mutant-scoped remediation run.
          onHardenSurvivor={hardenSurvivor}
        />
        {dispositionError !== undefined && (
          <p role="alert" className="px-1 text-[11px] text-[var(--color-phase-red)]">
            {dispositionError}
          </p>
        )}
        {rerunError !== undefined && (
          <p role="alert" className="px-1 text-[11px] text-[var(--color-phase-red)]">
            {rerunError}
          </p>
        )}
      </div>
    ) : null;

  // Resolution — root cause / fix / files, as recessed panel-flat cards. A
  // Done-lane section (validation-pipeline-visibility IA): shown once the fix has
  // landed and carries a resolution, not while In-Review.
  const resolutionBlock = showResolution ? (
    <div className="space-y-3">
      <div className="grid gap-3 sm:grid-cols-2">
        {resolution!.rootCause && (
          <PanelFlat className="rounded-2xl p-5">
            <p className="eyebrow text-[10px] text-subtle">Root cause</p>
            <p className="mt-2 text-sm leading-relaxed text-muted-foreground">{resolution!.rootCause}</p>
          </PanelFlat>
        )}
        {resolution!.fix && resolution!.fix.length > 0 && (
          <PanelFlat className="rounded-2xl p-5">
            <p className="eyebrow text-[10px] text-subtle">Fix</p>
            <ol className="mt-2 list-decimal space-y-1 pl-4 text-sm leading-relaxed text-muted-foreground">
              {resolution!.fix.map((step, i) => (
                <li key={i}>{typeof step === 'string' ? step : JSON.stringify(step)}</li>
              ))}
            </ol>
          </PanelFlat>
        )}
      </div>
      {resolution!.filesModified && resolution!.filesModified.length > 0 && (
        <PanelFlat className="rounded-2xl p-5">
          <p className="eyebrow text-[10px] text-subtle">Files modified ({resolution!.filesModified.length})</p>
          <ul className="mono mt-2 space-y-0.5 text-xs text-muted-foreground">
            {resolution!.filesModified.map((file, i) => (
              <li key={i}>{file}</li>
            ))}
          </ul>
        </PanelFlat>
      )}
    </div>
  ) : null;

  // Tasks — heading with the per-commit pipeline legend at its right (user call,
  // 2026-07-26: on the FIX detail the legend reads beside the tasks it
  // annotates), then the task rows in a divided panel.
  const tasksBlock = (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 className="display text-base font-semibold">Tasks</h2>
        <PipelineLegend pipeline={reviewPipeline} />
      </div>
      <div className="mt-3">
        {totalTasks === 0 ? (
          <p className="py-4 text-center text-sm text-muted-foreground">No tasks defined</p>
        ) : (
          <div className="space-y-3">
            {mainRows.length > 0 && (
              <div className="panel divide-y divide-border overflow-hidden rounded-2xl dark:divide-[oklch(0.5_0.06_282/0.2)]">
                {mainRows.map(({ task, index }) => (
                  <TaskRow
                    key={task.id}
                    task={task}
                    repoId={repoId}
                    reviewPipeline={reviewPipeline}
                    slugPath={formatTaskComponentSlug(index + 1)}
                  />
                ))}
              </div>
            )}
            {/* Superseded section (task 38's collapsed-toggle pattern, retained
                for retired work only — completed rows read inline above, per the
                user call of 2026-07-24). */}
            {supersededRows.length > 0 && (
              <div className="space-y-3">
                <button
                  type="button"
                  data-testid="superseded-tasks-toggle"
                  onClick={() => setSupersededExpanded((v) => !v)}
                  aria-expanded={supersededExpanded}
                  className="flex w-full items-center gap-1.5 text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
                >
                  <ChevronRight
                    className={cn('h-4 w-4 transition-transform', supersededExpanded && 'rotate-90')}
                    aria-hidden="true"
                  />
                  Superseded tasks ({supersededRows.length})
                </button>
                {supersededExpanded && (
                  <div className="panel divide-y divide-border overflow-hidden rounded-2xl opacity-70 dark:divide-[oklch(0.5_0.06_282/0.2)]">
                    {supersededRows.map(({ task, index }) => (
                      <TaskRow
                        key={task.id}
                        task={task}
                        repoId={repoId}
                        reviewPipeline={reviewPipeline}
                        slugPath={formatTaskComponentSlug(index + 1)}
                      />
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="h-full flex flex-col">
      <div className="flex-1 overflow-y-auto px-7 py-6">
        <div className="mx-auto max-w-4xl space-y-6">

          {/* Header — the shared DetailHeader shell (eyebrow + title + id copy,
              severity / opened / task-count meta with the Source + archive
              actions), with the expanded merge-mode rail RHS in the eyebrow row
              opening the delivery island. */}
          <DetailHeader
            testId="fix-detail-header"
            eyebrow={
              <p data-testid="fix-eyebrow" className={cn('eyebrow text-[10px]', eyebrowColor)}>
                Fix · {eyebrowLabel}
              </p>
            }
            // No header rail on the FIX detail (user call, 2026-07-26): the
            // control strip below already states the status (and the eyebrow
            // restates it above), so the MSR's Running pill / attention glyph
            // read as duplicates here. Liveness rides the strip's status +
            // the inline WorkerRunActivity; the PRD detail keeps its rail.
            title={
              <h1 data-testid="fix-title" className="display text-2xl font-bold leading-snug">
                {fix.title}
              </h1>
            }
            titleAdornment={<CopyIdButton value={fix.id} kind="Fix" className="flex-shrink-0" />}
            meta={
              <p className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
                <span className="inline-flex items-center gap-1.5 whitespace-nowrap rounded-md border border-border-strong px-2 py-0.5 text-[11px] font-medium text-foreground">
                  <span className={cn('h-1.5 w-1.5 rounded-full', severityDot[fix.severity])} aria-hidden="true" />
                  {fix.severity}
                </span>
                <span>
                  {fix.reported && <>opened {new Date(fix.reported).toLocaleDateString()}</>}
                  {totalTasks > 0 && <>{fix.reported ? ' · ' : ''}{totalTasks} {totalTasks === 1 ? 'task' : 'tasks'}</>}
                </span>
                {isArchived && (
                  <span className="inline-flex items-center whitespace-nowrap rounded-md border border-border-strong px-2 py-0.5 text-[11px] font-medium text-muted-foreground">
                    Archived
                  </span>
                )}
              </p>
            }
            actions={
              <>
                <button
                  type="button"
                  onClick={() => setSourceOpen(true)}
                  aria-label="View fix source"
                  className="inline-flex items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-1.5 text-xs font-medium text-subtle transition-colors hover:bg-accent/50 hover:text-foreground"
                >
                  <FileCode className="h-3.5 w-3.5" /> Source
                </button>
                {fix.hasAssets && (
                  <button
                    type="button"
                    onClick={openAssets}
                    aria-label="View fix assets"
                    className="inline-flex items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-1.5 text-xs font-medium text-subtle transition-colors hover:bg-accent/50 hover:text-foreground"
                  >
                    <Images className="h-3.5 w-3.5" /> Assets
                  </button>
                )}
                {/* Gate each action on its handler: a caller that doesn't pass
                    one (the Archive view for a superseded fix — terminal, not
                    archived, and un-archiving can't un-supersede it) gets no
                    button rather than a no-op. */}
                {isArchived && onUnarchive ? (
                  <button
                    type="button"
                    onClick={onUnarchive}
                    aria-label="Unarchive"
                    className="inline-flex items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-1.5 text-xs font-medium text-subtle transition-colors hover:bg-accent/50 hover:text-foreground"
                  >
                    <Archive className="h-3.5 w-3.5" /> Unarchive
                  </button>
                ) : !isArchived && onArchive ? (
                  // Archiving is a deliberate state change, not a stray click
                  // (fix archive-button-no-confirmation): the shared dialog gates
                  // it behind a confirm. Unarchive stays immediate — it's the undo.
                  <ArchiveConfirmDialog
                    itemKind="fix"
                    itemName={fix.title}
                    onConfirm={onArchive}
                    triggerClassName="inline-flex items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-1.5 text-xs font-medium text-subtle transition-colors hover:bg-accent/50 hover:text-foreground"
                  />
                ) : null}
              </>
            }
          />

          {/* A failed end-cap action's operator notice — the resume fault or
              the streamed land/teardown failure folded out of the delivery
              hook's channels (the endcap-notice idiom the PRD detail uses). */}
          {stripNotice !== null && (
            <div
              data-testid="endcap-notice"
              role="status"
              className="rounded-xl border border-[color-mix(in_oklab,var(--color-warn)_30%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-warn)_9%,transparent)] px-3 py-2 text-xs text-muted-foreground"
            >
              {stripNotice}
            </div>
          )}

          {/* The land run's live/terminal surface renders BELOW the command
              strip (fix land-surface-single-strip-and-legible-phases task 1):
              one operation, one progress surface, the control bar leading. See
              the relocated block just after the control strip section. */}

          {/* The whole-fix control bar (mock §03/§04/§05): ONE row — status
              tag + provenance pills, the shared full-height end-cap closing
              it. The strip is the ONE provenance home since the header rail
              retired (fix fix-control-strip-missing-worker-worktree-pills):
              mid-run it carries the worker + worktree pills (PlanFeatureRow's
              rail idiom — the inline activity panel below owns liveness, so
              no Running pill here); quiet branch work carries the branch
              MsrPill; done keeps DeliveredProvenance. The cap rounds its own
              right edge, so no overflow-hidden. In cleanup state the whole
              row gives way to CleanupCommand (done-lane-cleanup task 8). */}
          {inCleanup ? (
            <CleanupCommand repoId={repoId} workItemId={`fix:${fix.id}`} />
          ) : (
            <FixControlStrip
              attribution={
                <>
                {/* The completed-unlanded failed-run glyph — the FALLBACK only.
                    When a deliverer who is known the settled strip below tints
                    that existing who-glyph red instead (fix ...regression-test-
                    wording task 4), so this standalone red glyph renders ONLY
                    when there is no who-glyph to tint (no separate glyph beside
                    the existing one). */}
                {failedAttention && fixProvenanceView?.who === undefined && (
                  <MiniStatusRail
                    mode="card"
                    where="local"
                    branches={[]}
                    // A failed-run attention IS a worker run (MiniStatusRail: "an
                    // attention run is always a worker run"), so it renders the
                    // red Bot glyph the card also advertises.
                    isWorkerRun
                    attentionStatus="failed"
                    className="shrink-0"
                  />
                )}
                {showIdleLaunchHint ? (
                  // NO status tag in any state (task 3): the eyebrow above
                  // already reads "Fix · <status>"; an untouched fix instead
                  // points at the end-cap's Launch control.
                  <span data-testid="fix-strip-idle-hint" className="text-xs text-muted-foreground">
                    Click to launch →
                  </span>
                ) : live ? (
                  // The live strip keeps MiniStatusRail for the pulsing Bot that
                  // clicks through to the run stream — but the WORKTREE renders
                  // as the same MsrPill the settled strip uses (user call
                  // 2026-08-10), so live and settled read consistently. The rail
                  // gets no branches (branches={[]}); the pill states the branch
                  // beside it.
                  <>
                    <MiniStatusRail
                      mode="card"
                      // The launched window renders the IDENTICAL live rail to
                      // in_progress — pulsing glyph, click-through, name, model
                      // (fix launched-strip-live-glyph-parity): the run is live
                      // from dispatch, so the rail never downgrades to the
                      // static chip. Launched keeps its own end-cap + eyebrow.
                      namedWorker
                      worktreeMode="compact"
                      branches={[]}
                      isWorkerRun={activeRun?.worker !== undefined}
                      workerName={activeRun?.worker}
                      workerModel={activeRun?.model}
                      where={activeRun?.target === 'cloud-remote' ? 'remote' : 'local'}
                      envName={activeRun?.envName}
                      activeRunId={liveRunId}
                      onOpenRun={openActiveRun}
                      className="shrink-0"
                    />
                    {stripBranch !== undefined && (
                      <MsrPill
                        branch={stripBranch}
                        worktreeName={worktreeBranches[0]?.worktreeName}
                        className="shrink-0"
                      />
                    )}
                  </>
                ) : fixProvenanceView !== undefined ? (
                  // Settled: the deliverer as glyph+text (WhoAttribution) + the
                  // branch chip. The landed chip is RIGHT-aligned in the strip's
                  // own slot, never crowding this section (tasks 5 + 9).
                  <>
                    {/* The existing deliverer glyph turns red on a failed run
                        (task 4) — the single failed-run signal, no separate glyph. */}
                    <WhoAttribution who={fixProvenanceView.who} failed={failedAttention} />
                    {settledBranch !== undefined && (
                      <MsrPill
                        branch={settledBranch}
                        worktreeName={worktreeBranches[0]?.worktreeName}
                        className="shrink-0"
                      />
                    )}
                  </>
                ) : stripBranch !== undefined ? (
                  // Quiet branch work with no provenance readout yet.
                  <MsrPill
                    branch={stripBranch}
                    worktreeName={worktreeBranches[0]?.worktreeName}
                    className="shrink-0"
                  />
                ) : null}
                </>
              }
              landedChip={
                // Only pass the chip when it would render (merged / via-fix) —
                // a done-unlanded branch delivery renders null, and passing it
                // anyway leaks an empty right-aligned slot (review of d354b3890).
                !live && fixProvenanceView !== undefined && landedChipRenders(fixProvenanceView.delivery) ? (
                  <LandedChip delivery={fixProvenanceView.delivery} />
                ) : undefined
              }
              timeline={
                // The Timeline island entry (timeline-second-row-and-spike-strip
                // task 1): a quiet inline link on the strip's SECOND body row —
                // every started state with a branch, live included, except a
                // delivered-and-reaped fix whose branch is gone.
                stripBranch !== undefined && !reapedLanded ? <TimelineLink onClick={openIsland} /> : undefined
              }
              endcap={
                <FeatureEndcap
                  repoId={repoId}
                  item={`fix:${fix.id}`}
                  // Provenance FIRST LOAD only ⇒ the inert "…" cap (task 2). The
                  // null guard is load-bearing — the hook keeps the previous
                  // snapshot while refetching, so a settled cap never blanks.
                  settling={provenanceLoading && effectiveProvenance === null}
                  done={effectiveFixStatus === 'completed'}
                  // Retired fix is its own fact, NOT folded into `done`.
                  superseded={effectiveFixStatus === 'superseded'}
                  landed={effectiveProvenance?.landed === true}
                  // A mid-reconcile branch counts as live for the cap ladder (F7
                  // task 2): a verifying branch never offers an enabled Merge.
                  live={live || delivery.reconcile.kind === 'running'}
                  // The running cap's label follows the live run's KIND
                  // (reconcile-segment task 3). The running rung is reachable ONLY
                  // when `live` is true — and `live` here is `activeRun` (a worker
                  // run) OR a running reconcile — so the kind is exactly: a worker
                  // run ⇒ "Running", otherwise a live reconcile ⇒ "Reconciling…".
                  // A land shows its own "Merging…" cap via `landing`, never this
                  // rung, so there is no 'merge' case to feed here.
                  liveRunKind={activeRun !== undefined ? 'worker' : 'reconcile'}
                  launched={launched}
                  landAvailability={landAvailability}
                  // The server-composed genuine-validation merge gate (props-in-ui
                  // task 3), off the fix's detail payload — authoritative for the
                  // Merge rung when present (a non-genuine completion withholds
                  // Merge), else the legacy landAvailability edge.
                  mergeAvailable={fix.detail?.mergeAvailable}
                  // Delivered-and-reaped withholds the branch: a landed fix whose
                  // branch is gone reads Already merged, not a dead-ref teardown.
                  worktree={stripBranch !== undefined && !reapedLanded ? { branch: stripBranch } : undefined}
                  started={effectiveFixStatus !== 'not_started'}
                  // The cap is the ONE launch home (F6 task 4).
                  launch={launchTargetPresent ? { repoId, item: `fix:${fix.id}` } : undefined}
                  // Only a fix that could plausibly own a run probes the
                  // resumable projection.
                  mayHaveRun={
                    effectiveFixStatus !== 'superseded' &&
                    (effectiveFixStatus !== 'not_started' || activeRun !== undefined || fix.hasFailedRun === true)
                  }
                  onLand={onEndcapLand}
                  onRaise={onEndcapRaise}
                  onTeardown={onEndcapTeardown}
                  onResume={onEndcapResume}
                  onContinue={onEndcapContinue}
                  // The running cap is the PRIMARY watch affordance (running-
                  // phase-endcap-consistency task 1): a click opens the worker
                  // run island, exactly as the PRD feature row's cap does. The
                  // rail glyph stays as the secondary watch for parity.
                  onOpenRun={openActiveRun}
                />
              }
            />
          )}

          {/* The live per-phase landing strip is RETIRED (land-failure-surfacing
              task 2): the validation control's reconcile lane is the sole
              land-progress surface. The land RUN's live rungs return there as
              ladder narration in task 4; here only the terminal outcome note
              (below) announces a settled land. */}
          {delivery.landed ? (
            <div
              data-testid="land-outcome"
              role="status"
              className="flex items-center gap-2 rounded-xl border border-[color-mix(in_oklab,var(--color-done)_32%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-done)_11%,transparent)] px-3 py-2 text-xs font-medium text-done"
            >
              <GitMerge className="h-3.5 w-3.5" aria-hidden="true" />
              {LAND_SUCCEEDED_NOTICE}
            </div>
          ) : delivery.landNotice !== undefined ? (
            // A land that settled WITHOUT merging (already-delivered / already-
            // landed): the honest no-merge note, NOT the green merge claim — the
            // run-record lie this fix kills. Neutral tone: nothing changed.
            <div
              data-testid="land-outcome"
              role="status"
              className="flex items-center gap-2 rounded-xl border border-border-strong bg-[color-mix(in_oklab,var(--color-foreground)_4%,transparent)] px-3 py-2 text-xs font-medium text-muted-foreground"
            >
              <GitMerge className="h-3.5 w-3.5" aria-hidden="true" />
              {delivery.landNotice}
            </div>
          ) : null}


          {/* The standalone ReconcileStrip is RETIRED (land-failure-surfacing
              task 2): the reconcile verdict (running phase, conflict / verify
              terminal, reason) now renders ONLY on the validation control's
              reconcile lane, driven by the same `delivery.reconcile` machine via
              `withReconcileOverlay`. Task 5 names the failing rung + reason +
              /merge next step there. */}

          {doneLanded ? (
            // Done state (settled + landed): the under-strip content groups into
            // three collapsible eyebrow sections (fix-detail-done-collapsible-
            // sections) — Resolution (default closed), Validation (open) and Work
            // (the Tasks-resolved readout + the task rows, open) — wearing the PRD
            // eyebrow header (EyebrowSection). Land history + the test plan trail
            // the group, flat and unchanged (out of scope). A landed fix is
            // resolved, so it carries no live worker activity — the liveness panel
            // belongs to the flat branch only. Cleanup (landed + lingering
            // worktree) is DELIBERATELY grouped too: it is still a settled/landed
            // fix, and its `!inCleanup`-gated validation panel simply drops its
            // (empty) section.
            <>
              <div className="space-y-4">
                {resolutionBlock !== null && (
                  <EyebrowSection
                    label="Resolution"
                    accent="var(--color-subtle)"
                    open={resolutionOpen}
                    onToggle={() => setResolutionOpen((v) => !v)}
                  >
                    {resolutionBlock}
                  </EyebrowSection>
                )}
                {validationBlock !== null && (
                  <EyebrowSection
                    label="Validation"
                    accent="var(--color-primary)"
                    open={validationOpen}
                    onToggle={() => setValidationOpen((v) => !v)}
                  >
                    {validationBlock}
                  </EyebrowSection>
                )}
                <EyebrowSection
                  label="Work"
                  accent="var(--color-blue)"
                  count={fix.tasks.length}
                  open={workOpen}
                  onToggle={() => setWorkOpen((v) => !v)}
                >
                  <div className="space-y-3">
                    {tasksResolvedReadout}
                    {tasksBlock}
                  </div>
                </EyebrowSection>
              </div>

              {/* Land history (work-item-provenance F4 task 4) — when/how this fix
                  landed; the panel renders nothing until there IS a landing. */}
              <LandHistoryPanel history={provenance?.landHistory ?? []} />

              {/* Test plan */}
              <TestPlanDetail testPlan={fix.testPlan} />
            </>
          ) : (
            // Every non-Done state: the flat stack — validation panel, Tasks-
            // resolved readout, resolution cards, land history, test plan, then
            // the task list. The bespoke inline live-activity feed is RETIRED
            // (running-phase-endcap-consistency task 1): the running end-cap now
            // opens the worker run island, which streams the same transcript.
            <>
              {validationBlock}
              {tasksResolvedReadout}
              {resolutionBlock}
              <LandHistoryPanel history={provenance?.landHistory ?? []} />
              <TestPlanDetail testPlan={fix.testPlan} />
              {tasksBlock}
            </>
          )}
        </div>
      </div>

      <FixSourceSheet
        repoId={repoId}
        fixId={fix.id}
        isOpen={sourceOpen}
        onClose={() => setSourceOpen(false)}
      />
    </div>
  );
};

export default FixDetail;
