import React, { useMemo, useState } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import type { Feature } from '../types';
import TaskRow from '@/features/tasks/components/TaskRow';
import ValidationPanel from './ValidationPanel';
import { usePipelineConfig } from '../hooks/usePipelineConfig';
import { useFeatureDetail } from '../hooks/useFeatureDetail';
import { assembleValidationPanel } from '../utils/assemble-validation-panel';
import { withReconcileOverlay } from '../utils/reconcile-overlay';
import { useDeliveryActions } from '../hooks/useDeliveryActions';
import { postMutantDisposition, postHardenSurvivor } from '../services/api';
import type { MutantIdentity } from '@magic-ingredients/tiny-brain-core';
import { deriveTasksEffectiveStatus } from '../utils/effective-task';
import { deriveEffectiveStatus, deriveFeatureWorktreeRef, deriveFeatureDetailsBranch, deriveFeatureEffectiveStatus } from '../utils/effective-task-status';
import { formatTaskComponentSlug } from '../utils/task-slug-path';

interface FeatureDetailProps {
  feature: Feature;
  repoId: string;
  /**
   * The owning PRD's id. Required to build each manual task's
   * `manualCompleteContext` — without it the "Mark complete" affordance can't
   * target the `/plans/:planId/...` endpoint, so it stays hidden. Optional
   * because not every caller is plan-scoped.
   */
  planId?: string;
  /**
   * The feature branch's LIVE unended reconcile/land machinery run (e.g. a CLI
   * `tiny-brain reconcile-branch`), resolved by the parent from the delivery-worktree
   * rows and keyed on the branch — the SAME distinct-prop wiring FixDetail takes
   * (fix feature-detail-live-reconcile-parity). Deliberately NOT the persisted
   * verdict run (`lastReconcile.runId`): that one is already terminal, so
   * subscribing to it catches no in-flight foreign reconcile.
   */
  liveReconcileRunId?: string;
}

const FeatureDetail: React.FC<FeatureDetailProps> = ({ feature, repoId, planId, liveReconcileRunId }) => {
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId);
  // The per-feature validation strip (props-in-ui task 2): fetch the feature's
  // SERVER-composed detail LAZILY here — FeatureDetail mounts only in an EXPANDED
  // section, so a collapsed feature reads nothing — and ASSEMBLE the panel from it
  // (the shared core producers: lifecycle phase + per-step panel + post-merge lane
  // + runs), the SAME props-in path FixDetail uses, rather than folding runs on the
  // client. Gated on `completed` (isValidationVisible), so a live / not-started /
  // superseded feature spares the request. `undefined` detail (fetch fault / no
  // detail attached) folds the panel to hidden.
  const featureStatus = deriveTasksEffectiveStatus(feature.tasks ?? []);
  // A reconcile/land terminal bumps this tick (the delivery hook's onSuccess
  // below), forcing useFeatureDetail to refetch so the just-persisted verdict
  // re-seeds the strip — FixDetail's deliveryRefreshTick parity (fix
  // feature-detail-live-reconcile-parity): without it a completed live reconcile
  // silently falls back to the stale on-disk snapshot.
  const [deliveryRefreshTick, setDeliveryRefreshTick] = useState(0);
  const [dispositionError, setDispositionError] = useState<string | undefined>(undefined);
  const disposeSurvivor = (identity: MutantIdentity, disposition: 'equivalent' | 'accepted', reason?: string) => {
    setDispositionError(undefined);
    void postMutantDisposition(repoId, identity, disposition, reason)
      .then(() => setDeliveryRefreshTick((t) => t + 1))
      .catch((err) => setDispositionError(err instanceof Error ? err.message : 'Failed to record disposition'));
  };
  // Harden a survivor (F5): dispatch a mutant-scoped remediation run for this
  // feature, then bump the refresh tick. A 409 (already in flight) is surfaced.
  const hardenSurvivor = (identity: MutantIdentity) => {
    setDispositionError(undefined);
    void postHardenSurvivor(repoId, `prd:${planId}/${feature.id}`, identity)
      .then(() => setDeliveryRefreshTick((t) => t + 1))
      .catch((err) => setDispositionError(err instanceof Error ? err.message : 'Failed to dispatch harden run'));
  };
  const detail = useFeatureDetail(repoId, planId, feature.id, featureStatus === 'completed', deliveryRefreshTick);
  // The feature's branch — the key its live reconcile strip subscribes on, and
  // the branch the failure lane's re-verify incantation names (shared with
  // PlanFeatureRow's endcap facts so the two can't disagree).
  const detailsBranch = deriveFeatureDetailsBranch(feature.tasks ?? []);
  // Live reconcile parity with FixDetail (fix feature-detail-live-reconcile-
  // parity task 1): the EXPANDED feature holds a LIVE reconcile strip keyed on
  // its branch — the SAME `useDeliveryActions` hook FixDetail uses — so the
  // reconcile lane ticks live during a feature land instead of the old
  // snapshot-only view. The persisted verdict axes (`landAvailability` /
  // `lastReconcile`) still seed the strip's disk reconstruction on refresh, and
  // the branch's LIVE machinery run — threaded in from the parent's delivery
  // rows (`liveReconcileRunId`), NOT the terminal verdict run — is subscribed so
  // an in-flight foreign reconcile renders "Verifying…" with no click here. The
  // subscription is bounded to expanded features (mount-on-expand), not every row.
  const delivery = useDeliveryActions(repoId, detailsBranch ?? '', {
    // Terminal ends (self land/reconcile AND watched foreign runs) re-sync the
    // detail with the just-persisted verdict, matching FixDetail's onSuccess.
    onSuccess: () => setDeliveryRefreshTick((t) => t + 1),
    ...(feature.landAvailability !== undefined ? { landAvailability: feature.landAvailability } : {}),
    ...(feature.lastReconcile !== undefined ? { lastReconcile: feature.lastReconcile } : {}),
    ...(liveReconcileRunId !== undefined ? { liveReconcileRunId } : {}),
  });
  // Assemble the panel from the composed detail, memoised on the inputs it reads
  // (mirroring FixDetail's memoised panel), and layer the LIVE reconcile lane +
  // merge boundary from the client-derived strip (`delivery.reconcile`) —
  // `withReconcileOverlay` applied UNCONDITIONALLY, exactly as FixDetail does, so
  // the reconcile lane renders and ticks live in true parity (no `kind !== 'idle'`
  // gate hiding it pre-land).
  const validationPanel = useMemo(() => {
    if (detail === undefined) return undefined;
    const landed = detail.tddJourney.landed;
    const base = assembleValidationPanel({
      status: featureStatus,
      validation: detail.validation,
      validationPanel: detail.validationPanel,
      postMergeLane: detail.postMergeLane,
      regressionEvidence: detail.regressionEvidence,
      landed,
      runs: detail.runs,
    });
    // Reconcile is gated until completion has passed; a reconcile / merge /
    // post-merge phase means completion already passed (workItemPassed).
    const workItemPassed =
      detail.validation.pipeline !== 'item_completion' || detail.validation.status === 'passed';
    // The reconcile lane's FAILURE detail (land-failure-surfacing task 5): the
    // reason + conflicting files from the server-composed `lastReconcile` axis,
    // plus the failing branch for the copyable `tiny-brain reconcile-branch <branch>`
    // recovery incantation — the SAME wire FixDetail builds.
    const failureDetail =
      detail.lastReconcile !== undefined
        ? {
            ...(detail.lastReconcile.exitReason !== undefined ? { reason: detail.lastReconcile.exitReason } : {}),
            ...(detail.lastReconcile.conflictedFiles !== undefined
              ? { conflictedFiles: detail.lastReconcile.conflictedFiles }
              : {}),
            ...(detailsBranch !== undefined ? { branch: detailsBranch } : {}),
            // The main a catch-up-conflict moved to (persistent-catch-up-conflict F3).
            ...(detail.reconciledAgainst !== undefined ? { reconciledAgainst: detail.reconciledAgainst } : {}),
          }
        : undefined;
    const state = withReconcileOverlay(base, {
      reconcile: delivery.reconcile,
      landed,
      workItemPassed,
      postMergeConfigured: detail.postMergeLane !== undefined,
      ...(failureDetail !== undefined ? { failureDetail } : {}),
      // The provisional ready footer (F2) names the main the item is ready as of.
      ...(detail.reconciledAgainst !== undefined ? { reconciledAgainst: detail.reconciledAgainst } : {}),
    });
    // Bundle the render state with the lifecycle phase it was assembled from, so the
    // header pill reads `phase` without an optional chain (both come off `detail`).
    return { state, phase: detail.validation };
    // `delivery.reconcile` has fresh identity each render (deriveReconcileStrip
    // returns a new object), so the reconcile path assembles per-render and the
    // memo effectively caches only the detail-derived base — the same intentional
    // shape as FixDetail's panel memo, kept for parity rather than a perf claim.
  }, [detail, delivery.reconcile, featureStatus, detailsBranch]);
  // When every task's work lives on the same worktree, show it once here so the
  // rows stay clean; a task overriding to a different worktree still shows its
  // own pill (multi-ref-projection / feature-header-worktree-consolidation).
  const featureWorktreeRef = deriveFeatureWorktreeRef(feature.tasks ?? []);
  // Count by worktree-aware effective status, and roll the feature's own status
  // up the same way, so a feature whose work is done on a worktree reads done.
  const effStatuses = (feature.tasks ?? []).map((t) => deriveEffectiveStatus(t).status);
  const completedTasks = effStatuses.filter((s) => s === 'completed').length;
  const supersededTasks = effStatuses.filter((s) => s === 'superseded').length;
  const doneTasks = completedTasks + supersededTasks;
  const totalTasks = feature.tasks?.length || 0;
  const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
  const effectiveFeatureStatus = deriveFeatureEffectiveStatus(feature.tasks ?? []);

  return (
    <div>

      {/* The feature's own validation strip leads its expanded body (fix
          plan-detail-eagerly-builds-every-feature-validation-input task 2) — the
          per-step chips / all-passed receipt for every git-terminal feature, the
          same panel the fix detail renders, fetched lazily on expand. Hidden
          (renders nothing) for non-git-terminal work or an unconfigured repo, so
          live features carry no empty block. */}
      {validationPanel?.state.kind === 'active' && (
        <div className="border-b border-border p-3">
          <ValidationPanel
            state={validationPanel.state}
            validation={validationPanel.phase}
            landed={detail?.tddJourney.landed}
            // Retry-reconcile (F4): re-run reconcile for the branch the panel emitted,
            // forwarded to onPrepare so the named and reconciled branch agree;
            // `reconcileRunId` guards against a self-started duplicate dispatch.
            onRetryReconcile={(branch) => delivery.onPrepare(branch)}
            retryReconcileInFlight={delivery.reconcileRunId !== undefined}
            onMarkEquivalentSurvivor={(identity) => disposeSurvivor(identity, 'equivalent')}
            onAcceptSurvivor={(identity, reason) => disposeSurvivor(identity, 'accepted', reason)}
            onHardenSurvivor={hardenSurvivor}
          />
          {dispositionError !== undefined && (
            <p role="alert" className="mt-1 px-1 text-[11px] text-[var(--color-phase-red)]">
              {dispositionError}
            </p>
          )}
        </div>
      )}

      {/* The body's live-run strip is RETIRED (fix
          feature-card-live-glyph-and-run-watch-surface task 2): watch-live now
          lives on the feature-card header — the pulsing worker glyph and the
          endcap's click-to-view — so a body strip only duplicated it. */}

      {/* Feature Description */}
      {feature.description && (
        <div className="border-b border-border px-4 py-3">
          <p className="text-sm text-muted-foreground">{feature.description}</p>
        </div>
      )}

      {/* Tasks list — plain rows separated by hairline dividers (mockup
          feat-body). No "Tasks" heading; the worktree marker lives only in the
          feature header (PlanDetailsPRD) but featureWorktreeRef is still passed
          to each TaskRow so per-task pills suppress when the whole feature is on
          one worktree. */}
      {totalTasks > 0 ? (
        <div className="divide-y divide-border dark:divide-[oklch(0.5_0.06_282/0.2)]">
          {feature.tasks?.map((task, index) => (
            <TaskRow
              key={task.id}
              task={task}
              repoId={repoId}
              reviewPipeline={reviewPipeline}
              slugPath={formatTaskComponentSlug(index + 1)}
              featureWorktreeRef={featureWorktreeRef}
              manualCompleteContext={
                planId
                  ? { planId, featureId: feature.id, taskNumber: index + 1 }
                  : undefined
              }
            />
          ))}
        </div>
      ) : (
        <p className="text-sm text-muted-foreground px-4 py-4">
          No tasks defined for this feature
        </p>
      )}

      {/* Feature Timeline */}
      {(feature.startedAt || feature.completedAt) && (
        <Card>
          <CardContent className="pt-4">
            <div className="relative">
              {/* Progress percentage above the bar */}
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs text-muted-foreground">Progress</span>
                <span className="text-sm font-semibold">{progress}%</span>
              </div>

              {/* Timeline bar - matching sidebar style */}
              <div className="relative h-2 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700">
                <div
                  className="absolute inset-y-0 left-0 transition-all duration-300"
                  style={{
                    width: `${feature.completedAt ? 100 : progress}%`,
                    backgroundColor: effectiveFeatureStatus === 'completed' ? '#10b981' :
                                   effectiveFeatureStatus === 'in_progress' ? '#3b82f6' : '#9ca3af'
                  }}
                />
              </div>

              {/* Timeline dates below bar */}
              <div className="flex justify-between mt-3 text-xs text-muted-foreground">
                {feature.startedAt && (
                  <span>{new Date(feature.startedAt).toLocaleDateString()}</span>
                )}
                {feature.completedAt && (
                  <span>{new Date(feature.completedAt).toLocaleDateString()}</span>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default FeatureDetail;
