import React from 'react';
import type { StructuredRecommendation } from '../types';

interface QualityWorthDoingProps {
  suggestions: ReadonlyArray<StructuredRecommendation>;
  onCreateFix?: (suggestion: StructuredRecommendation) => void;
}

function SuggestionCard({
  suggestion,
  rank,
  onCreateFix,
}: {
  suggestion: StructuredRecommendation;
  rank: number;
  onCreateFix?: (suggestion: StructuredRecommendation) => void;
}) {
  return (
    <div
      data-testid={`worth-doing-item-${rank}`}
      className="panel-flat lift flex items-start gap-3.5 rounded-2xl p-4"
    >
      <span className="mono mt-0.5 text-sm font-bold text-subtle">
        {String(rank + 1).padStart(2, '0')}
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium leading-snug">{suggestion.title}</p>
        <p className="mt-0.5 text-xs text-muted-foreground">{suggestion.description}</p>
      </div>
      {suggestion.effort && <span className="effort mt-0.5 shrink-0">{suggestion.effort}</span>}
      <button
        type="button"
        onClick={() => onCreateFix?.(suggestion)}
        className="shrink-0 inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-medium text-blue"
        style={{ background: 'color-mix(in oklab, var(--color-blue) 13%, transparent)' }}
      >
        Create Fix
      </button>
    </div>
  );
}

/**
 * The Quality "Worth doing" section — suggestions ranked by risk reduced (the
 * caller ranks via rankWorthDoing), each on the reimagined `panel-flat lift`
 * card with a mono effort tag and a one-click Create Fix. No "points gained".
 */
export const QualityWorthDoing: React.FC<QualityWorthDoingProps> = ({ suggestions, onCreateFix }) => (
  <section data-testid="quality-worth-doing">
    <h2 className="display text-base font-semibold">Worth doing</h2>
    <p className="text-xs text-muted-foreground">Ranked by risk reduced, not points gained.</p>
    <div className="mt-3 space-y-2.5">
      {suggestions.length === 0 ? (
        <div data-testid="worth-doing-empty" className="panel-flat rounded-2xl p-4 text-sm text-muted-foreground">
          Nothing ranked yet — run a quality analysis to surface the highest-leverage work.
        </div>
      ) : (
        suggestions.map((suggestion, i) => (
          <SuggestionCard
            key={`${suggestion.title}-${i}`}
            suggestion={suggestion}
            rank={i}
            onCreateFix={onCreateFix}
          />
        ))
      )}
    </div>
  </section>
);
