import React from 'react';
import { ArrowLeft, ArrowRight, ExternalLink } from 'lucide-react';
import type { Instrument } from '../utils/quality-instruments';
import type { AnalyserDetailPayload, SeverityBuckets } from '../types';
import { DOT_COLOR, TREND_COLOR, type DotState } from '../utils/instrument-palette';

/** Display rank, loudest first. Keyed by `SeverityBuckets` so a new
 *  `IssueSeverity` is a compile error here until it is ranked — it can never be
 *  silently dropped from the caption. */
const SEVERITY_RANK: Record<keyof SeverityBuckets, number> = {
  critical: 0,
  major: 1,
  minor: 2,
  info: 3,
};

/** Narrate severity buckets loudest-first; a zero bucket is omitted, never shown
 *  as "0 info". Iterates the run's own buckets (so an added severity surfaces
 *  rather than dropping out) and returns null when no graded issue is present. */
function severityCaption(buckets: SeverityBuckets): string | null {
  const parts = (Object.keys(buckets) as Array<keyof SeverityBuckets>)
    .filter((severity) => buckets[severity] > 0)
    .sort((a, b) => SEVERITY_RANK[a] - SEVERITY_RANK[b])
    .map((severity) => `${buckets[severity]} ${severity}`);
  return parts.length > 0 ? parts.join(' · ') : null;
}

/** Slot ④ shapes, derived from the payload contract to avoid re-importing them. */
type DetailList = AnalyserDetailPayload['lists'][number];
type DetailRow = DetailList['rows'][number];

const CHART_W = 1000;
const CHART_H = 120;
const CHART_PAD_X = 10;
const CHART_PAD_Y = 10;

/** Project a series into the SVG primitives the trend chart draws: the line
 *  `points` string, the closed `area` path that fills beneath it, and the
 *  per-run `[x, y]` points used to place the dot markers — all within the
 *  trend-chart viewbox. */
function chartGeometry(series: ReadonlyArray<number>): {
  line: string;
  area: string;
  points: ReadonlyArray<readonly [number, number]>;
} {
  const min = Math.min(...series);
  const max = Math.max(...series);
  const range = max - min || 1;
  const n = series.length;
  const usableW = CHART_W - CHART_PAD_X * 2;
  const usableH = CHART_H - CHART_PAD_Y * 2;
  const pts = series.map((v, i) => {
    const x = CHART_PAD_X + (i / (n - 1)) * usableW;
    const y = CHART_PAD_Y + (1 - (v - min) / range) * usableH;
    return [x, y] as const;
  });
  const linePts = pts.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`);
  // Trace the line once (move to the first point, line through the rest), then
  // close down the right edge and back along the baseline.
  const area = `M${linePts[0]} L${linePts.slice(1).join(' L')} L${pts[n - 1][0].toFixed(1)},${CHART_H} L${pts[0][0].toFixed(1)},${CHART_H} Z`;
  return { line: linePts.join(' '), area, points: pts };
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** Format a `YYYY-MM-DD` run date for the axis (`2026-04-30` → `Apr 30`).
 *  Parsed by hand rather than via `Date` to avoid a timezone day-shift. */
function formatRunDate(iso: string): string {
  const [, month, day] = iso.split('-').map(Number);
  if (!month || !day) return iso;
  return `${MONTHS[month - 1]} ${day}`;
}

/**
 * An honest plain-language reading of the latest run-over-run move. "Flat" is
 * driven off the actual direction/delta — never the trend colour — so a scale
 * metric (neutral colour, e.g. the test suite or type-error count) that genuinely
 * moved is described as movement rather than "no change". A lower-better metric
 * that moved reads as improving (falling) or regressing (rising); a neutral one
 * states the move without that judgement, since up/down isn't good or bad for it.
 */
function trendCaption(instrument: Instrument, runs: number): string {
  const { direction, delta, colour } = instrument.trend;
  if (direction === 'flat' || delta === 0) {
    return `Flat across the last ${runs} runs — no change to report.`;
  }
  const move = instrument.deltaLabel ? `${instrument.deltaLabel} this run` : 'Moved this run';
  if (colour === 'neutral') return `${move}.`;
  return `${move} — the line is ${colour === 'good' ? 'improving' : 'regressing'}.`;
}

/**
 * The per-analyser detail drill-down (quality-signals-analyser-detail.html):
 * opened by selecting a Measured instrument, it shows that analyser's header
 * (label / value / facts) on the elevated `panel` surface, with its key-metrics
 * strip, trend over recent runs, and primary lists on `panel-flat` sub-cards. An
 * analyser with fewer than two runs of history shows an honest empty state rather
 * than a fabricated one-point chart.
 *
 * `detail` is the richer per-analyser payload fetched from the quality detail
 * API (analyser-detail-contract). It is optional — the view degrades to the
 * instrument-only header until the payload arrives.
 */
export const AnalyserDetail: React.FC<{
  instrument: Instrument;
  detail?: AnalyserDetailPayload | null;
  onBack: () => void;
}> = ({ instrument, detail, onBack }) => {
  const dotState: DotState = instrument.dotState ?? 'flat';
  const series = instrument.series;
  const hasHistory = !!series && series.length >= 2;
  const colour = TREND_COLOR[instrument.trend.colour];
  // Only lists the run actually backs with rows — an empty list is dropped
  // rather than shown as a hollow section (honesty rule).
  const lists = (detail?.lists ?? []).filter((list) => list.rows.length > 0);
  // A malformed/partial payload (e.g. the analyser-detail endpoint returning a
  // bare scores object) can omit `metrics` despite the contract; guard it the
  // same way as `lists` so the strip silently renders nothing rather than
  // crashing the whole drill-down.
  const metrics = detail?.metrics ?? [];

  return (
    <section data-testid="analyser-detail" className="space-y-5">
      <button
        type="button"
        data-testid="analyser-detail-back"
        onClick={onBack}
        className="hoverable -ml-1 inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-sm text-subtle hover:text-foreground"
      >
        <ArrowLeft className="h-4 w-4" aria-hidden /> Quality signals
      </button>

      <div data-testid="analyser-detail-header" className="panel rounded-2xl p-5">
        <div className="flex items-center gap-2">
          <h1 className="display text-xl font-bold leading-none">{instrument.label}</h1>
          <span className={`dot d-${dotState}`} aria-hidden />
        </div>
        <div className="mt-3 flex items-end gap-3">
          <span className="display text-3xl font-bold leading-none">{instrument.value}</span>
          {instrument.sublabel && <span className="text-sm text-muted-foreground">{instrument.sublabel}</span>}
        </div>
        {detail?.summary && (
          <p data-testid="analyser-detail-summary" className="mt-2 text-sm text-muted">
            {detail.summary}
          </p>
        )}
      </div>

      {metrics.length > 0 && (
        <div
          data-testid="analyser-detail-metrics"
          className="grid grid-cols-2 gap-2 sm:grid-cols-4"
        >
          {metrics.map((metric, i) => (
            <div key={i} className="panel-flat rounded-xl px-3 py-2.5">
              <p className="eyebrow text-[10px] text-subtle">{metric.label}</p>
              <p className="mt-1">
                <span
                  className="display text-lg font-bold"
                  // A metric takes a hue only when it carries a *direction*
                  // (ok/watch/risk); an ungraded metric — absent or the
                  // directionless `flat` — stays the default foreground.
                  style={
                    metric.risk && metric.risk !== 'flat'
                      ? { color: DOT_COLOR[metric.risk] }
                      : undefined
                  }
                >
                  {metric.value}
                </span>
                {metric.unit && <span className="ml-1 text-xs text-muted">{metric.unit}</span>}
                {metric.outOf !== undefined && (
                  <span className="ml-1 text-xs text-muted">of {metric.outOf}</span>
                )}
              </p>
            </div>
          ))}
        </div>
      )}

      {hasHistory && series ? (
        <TrendCard
          instrument={instrument}
          series={series}
          colour={colour}
          newThisRun={detail?.trend?.newThisRun}
          severity={instrument.severity}
        />
      ) : (
        <div
          data-testid="analyser-no-history"
          className="panel-flat rounded-2xl p-5 text-sm text-muted-foreground"
        >
          Not enough history yet — this analyser needs at least two runs to show a trend.
        </div>
      )}

      {lists.length > 0 && (
        <div data-testid="analyser-detail-lists" className="space-y-5">
          {lists.map((list, i) => (
            <AnalyserListSection key={i} list={list} />
          ))}
        </div>
      )}
    </section>
  );
};

/** One slot-④ list section: a titled, item-counted group of card or table rows. */
function AnalyserListSection({ list }: { list: DetailList }) {
  return (
    <div data-testid="analyser-detail-list" className="space-y-3">
      <div className="flex items-end justify-between gap-2">
        <h2 className="display text-base font-semibold">{list.title}</h2>
        <span className="mono text-[11px] text-subtle">
          from the analyser · {list.rows.length} item{list.rows.length === 1 ? '' : 's'}
        </span>
      </div>
      {list.shape === 'card' ? (
        <div className="space-y-2.5">
          {list.rows.map((row, i) => (
            <CardRow key={i} row={row} />
          ))}
        </div>
      ) : (
        <div
          className="panel-flat divide-y rounded-2xl"
          style={{ borderColor: 'var(--panel-flat-border)' }}
        >
          {list.rows.map((row, i) => (
            <TableRow key={i} row={row} />
          ))}
        </div>
      )}
    </div>
  );
}

/** A rich card row: severity, identifier, version delta, ref, description, effort, location. */
function CardRow({ row }: { row: DetailRow }) {
  return (
    <div data-testid="analyser-row-card" className="panel-flat lift rounded-2xl p-4">
      <div className="flex flex-wrap items-center gap-2.5">
        {row.severity && <span className={`pill sev-${row.severity}`}>{row.severity}</span>}
        <span className="mono text-sm font-semibold">{row.label}</span>
        {row.from && row.to && <VersionDelta from={row.from} to={row.to} />}
        {row.refUrl && row.refLabel && (
          <a
            href={row.refUrl}
            target="_blank"
            rel="noreferrer"
            className="mono ml-auto inline-flex items-center gap-1 text-[11px] text-subtle hover:text-fg"
          >
            {row.refLabel} <ExternalLink className="h-3 w-3" aria-hidden />
          </a>
        )}
      </div>
      {row.description && <p className="mt-2 text-sm text-muted">{row.description}</p>}
      {(row.effort || row.location) && (
        <div className="mt-3 flex items-center gap-2">
          {row.effort && <span className="effort">{row.effort}</span>}
          {row.location && <span className="mono text-[11px] text-subtle">{row.location}</span>}
        </div>
      )}
    </div>
  );
}

/** A uniform table row: a fixed-width label, an optional version delta, a trailing pill. */
function TableRow({ row }: { row: DetailRow }) {
  return (
    <div data-testid="analyser-row-table" className="flex items-center gap-3 p-3.5">
      <span className="mono w-40 truncate text-sm font-medium">{row.label}</span>
      {row.from && row.to && <VersionDelta from={row.from} to={row.to} />}
      {row.severity && <span className={`pill sev-${row.severity} ml-auto`}>{row.severity}</span>}
    </div>
  );
}

/** A `from → to` version/value transition, read left-to-right. */
function VersionDelta({ from, to }: { from: string; to: string }) {
  return (
    <span className="mono inline-flex items-center gap-1 text-xs">
      <span className="text-subtle">{from}</span>
      <ArrowRight className="h-3 w-3 text-subtle" aria-hidden />
      <span className="text-fg">{to}</span>
    </span>
  );
}

function TrendCard({
  instrument,
  series,
  colour,
  newThisRun,
  severity,
}: {
  instrument: Instrument;
  series: ReadonlyArray<number>;
  colour: string;
  newThisRun?: string;
  severity?: SeverityBuckets;
}) {
  const { line, area, points } = chartGeometry(series);
  const gradientId = `analyser-area-${instrument.key}`;
  const latest = points[points.length - 1];
  // Each earlier run is a plain dot; the latest run is its own pulsing marker.
  const earlier = points.slice(0, -1);
  const caption = trendCaption(instrument, series.length);
  const sevCaption = severity ? severityCaption(severity) : null;
  // The axis labels the window's extremes from real run dates — shown only when
  // the run carries them, never invented.
  const dates = instrument.seriesDates;
  const axis = dates && dates.length >= 2 ? { first: dates[0], last: dates[dates.length - 1] } : null;
  return (
    <div data-testid="analyser-trend" className="panel-flat rounded-2xl p-5">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="eyebrow text-[10px] text-subtle">{instrument.label} over runs</p>
          {instrument.deltaLabel && (
            <p className="mono mt-1 text-sm" style={{ color: colour }}>
              {instrument.deltaLabel} this run
            </p>
          )}
        </div>
        <span className="mono text-[11px] text-subtle">{series.length} runs</span>
      </div>
      <svg
        viewBox={`0 0 ${CHART_W} ${CHART_H}`}
        className="mt-3 h-24 w-full"
        preserveAspectRatio="none"
        aria-label={`${instrument.label} across the last ${series.length} runs`}
      >
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor={colour} stopOpacity={0.18} />
            <stop offset="1" stopColor={colour} stopOpacity={0} />
          </linearGradient>
        </defs>
        <path d={area} fill={`url(#${gradientId})`} stroke="none" />
        <polyline
          points={line}
          fill="none"
          stroke={colour}
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <g data-testid="analyser-trend-dots">
          {earlier.map(([x, y], i) => (
            <circle
              key={i}
              cx={x.toFixed(1)}
              cy={y.toFixed(1)}
              r={2.8}
              fill="var(--color-background)"
              stroke={colour}
              strokeWidth={1.5}
            />
          ))}
        </g>
        <circle
          data-testid="analyser-trend-latest"
          className="animate-pulse"
          cx={latest[0].toFixed(1)}
          cy={latest[1].toFixed(1)}
          r={4.5}
          fill="var(--color-background)"
          stroke={colour}
          strokeWidth={2.5}
        />
      </svg>
      {axis && (
        <div
          data-testid="analyser-trend-axis"
          className="mono mt-1 flex justify-between text-[10px] text-subtle"
        >
          <span>{formatRunDate(axis.first)}</span>
          <span>{formatRunDate(axis.last)}</span>
        </div>
      )}
      <p data-testid="analyser-trend-caption" className="mt-3 text-xs text-muted">
        {caption}
      </p>
      {sevCaption && (
        <p data-testid="analyser-trend-severity" className="mono mt-2 text-[11px] text-subtle">
          This run: {sevCaption}
        </p>
      )}
      {newThisRun && (
        <p data-testid="analyser-trend-new" className="mt-2 text-xs text-muted">
          <span className="mono text-fg">{newThisRun}</span>
        </p>
      )}
    </div>
  );
}
