import React, { useId, useState } from 'react';
import { CircleAlert, Cpu, RotateCw, Trash2 } from 'lucide-react';
import { Button } from '../ui/button';
import type {
  CustomModelView,
  ModelMutationResult,
  ModelProviderView,
} from '../../hooks/useModels';

/**
 * The custom models panel (custom-worker-models, models-panel.html mockup).
 *
 * Stateless over its data: the container feeds it a `useModels(basePath)`
 * scope and it emits raw add/remove events. It never judges an id — the
 * server owns id shape, provider and collision rules, and the panel shows
 * whatever refusal comes back as an alert. The only local state is the add
 * form's draft and the last refusal.
 *
 * `scope` picks the surface chrome: the global Workers page (`user`, a full
 * panel) or Repo › Settings › Workers (`repo`, a flat inset under the
 * committed-file notice, saved to the committed file).
 */

// The provider pill tints the mockup draws; any other provider stays neutral.
const PROVIDER_PILL: Record<string, string> = {
  anthropic: 'pill-violet',
  openai: 'pill-blue',
};

const Alert: React.FC<{ children: React.ReactNode; className?: string }> = ({
  children,
  className = '',
}) => (
  <div
    role="alert"
    className={`flex items-start gap-2 rounded-[10px] bg-[color-mix(in_oklab,var(--color-phase-red)_10%,transparent)] px-3 py-2 text-xs text-[var(--color-phase-red)] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-phase-red)_30%,transparent)] ${className}`}
  >
    <CircleAlert className="mt-px h-4 w-4 shrink-0" />
    <span>{children}</span>
  </div>
);

const fieldClass =
  'mt-1.5 flex items-center rounded-[10px] border border-[var(--ds-border)] bg-[color-mix(in_oklab,var(--ds-fg)_4%,transparent)] px-2.5 py-2 transition-[border-color,box-shadow] focus-within:border-[var(--ds-blue)] focus-within:shadow-[0_0_0_3px_color-mix(in_oklab,var(--ds-blue)_20%,transparent)]';

export const ModelsPanel: React.FC<{
  models: CustomModelView[];
  providers: ModelProviderView[];
  loading: boolean;
  /** The list failed to load — shown in place of the rows, with Retry. */
  error: string | null;
  onAdd: (model: CustomModelView) => Promise<ModelMutationResult>;
  onRemove: (id: string) => Promise<ModelMutationResult>;
  onRetry?: () => void;
  scope?: 'user' | 'repo';
}> = ({ models, providers, loading, error, onAdd, onRemove, onRetry, scope = 'user' }) => {
  const [id, setId] = useState('');
  const [provider, setProvider] = useState('');
  const [refusal, setRefusal] = useState<string | null>(null);
  // One add or remove at a time: a double click must not send a second POST
  // (which the server would refuse as a duplicate of the one just added).
  const [pending, setPending] = useState(false);
  const headingId = useId();
  const hintId = useId();

  // The provider select falls back to the first offered provider until the
  // user picks one — never a hardcoded name.
  const effectiveProvider = providers.some((p) => p.provider === provider)
    ? provider
    : providers[0]?.provider ?? '';
  const labelFor = (value: string) =>
    providers.find((p) => p.provider === value)?.providerLabel ?? value;

  const run = async (request: () => Promise<ModelMutationResult>): Promise<boolean> => {
    setPending(true);
    const result = await request();
    setPending(false);
    setRefusal(result.ok ? null : result.error);
    return result.ok;
  };

  const add = async () => {
    if (pending) return;
    // The id goes raw: whitespace is the server's call to refuse, not ours.
    if (await run(() => onAdd({ id, provider: effectiveProvider }))) setId('');
  };

  const remove = async (modelId: string) => {
    if (pending) return;
    await run(() => onRemove(modelId));
  };

  const repo = scope === 'repo';
  const hint = repo
    ? 'Exactly as the agent CLI expects it — no spaces. Saved to the committed file, so teammates get it with the workers that use it.'
    : "Exactly as the agent CLI expects it — no spaces. tiny brain doesn't check it against the provider; a typo shows up when the worker runs.";

  const body = () => {
    if (loading) {
      return (
        <div className="mt-3 space-y-2.5" aria-hidden="true">
          <div className="flex items-center gap-3 px-2 py-1.5">
            <span className="h-4 flex-1 animate-pulse rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_9%,transparent)]" />
            <span className="h-4 w-16 animate-pulse rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_9%,transparent)]" />
            <span className="h-4 w-14 animate-pulse rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_9%,transparent)]" />
          </div>
          <div className="flex items-center gap-3 px-2 py-1.5">
            <span className="h-4 w-2/3 animate-pulse rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_9%,transparent)]" />
            <span className="ml-auto h-4 w-16 animate-pulse rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_9%,transparent)]" />
            <span className="h-4 w-14 animate-pulse rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_9%,transparent)]" />
          </div>
        </div>
      );
    }
    if (error !== null) {
      return (
        <>
          <Alert className="mt-3">
            Couldn&apos;t load custom models. The Model list still offers the built-ins.
          </Alert>
          {onRetry && (
            <Button
              variant="ghost"
              size="sm"
              className="mt-2 h-7 px-2 text-xs text-muted-foreground"
              onClick={onRetry}
            >
              <RotateCw className="h-3.5 w-3.5" />
              Retry
            </Button>
          )}
        </>
      );
    }
    if (models.length === 0) {
      return (
        <div className="panel-flat mt-3 rounded-xl px-4 py-6 text-center">
          <Cpu className="mx-auto h-5 w-5 text-[var(--ds-subtle)]" />
          <p className="mt-2 text-sm text-muted-foreground">No custom models yet.</p>
          <p className="mt-0.5 text-xs text-[var(--ds-subtle)]">
            Add one when a provider ships a model tiny brain doesn&apos;t list.
          </p>
        </div>
      );
    }
    return (
      <div className="mt-3" role="list">
        {models.map((model) => (
          <div
            key={model.id}
            role="listitem"
            className="grid grid-cols-[minmax(0,1fr)_auto_auto] items-center gap-3 rounded-[10px] border-b border-[var(--ds-border)] px-2 py-2.5 transition-colors last:border-b-0 hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)]"
          >
            <span className="truncate font-mono text-sm">{model.id}</span>
            <span
              className={`pill justify-self-start ${PROVIDER_PILL[model.provider] ?? 'pill-muted'}`}
            >
              {labelFor(model.provider)}
            </span>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              aria-label={`Remove ${model.id}`}
              disabled={pending}
              onClick={() => void remove(model.id)}
              className="h-7 gap-1.5 rounded-lg px-2 text-xs text-[var(--color-phase-red)] hover:bg-[color-mix(in_oklab,var(--color-phase-red)_12%,transparent)] hover:text-[var(--color-phase-red)] active:scale-[.97]"
            >
              <Trash2 className="h-3.5 w-3.5" />
              Remove
            </Button>
          </div>
        ))}
      </div>
    );
  };

  const count = models.length === 1 ? '1 model' : `${models.length} models`;

  return (
    <section
      aria-labelledby={headingId}
      aria-busy={loading || undefined}
      className={repo ? 'panel-flat rounded-xl p-4' : 'panel rounded-2xl p-4'}
    >
      <div className="flex items-start justify-between gap-3">
        <div>
          {/* `!` beats the legacy global `.dark h2` grey; the mockup draws
              the heading in the foreground colour. */}
          <h2 id={headingId} className="font-display font-semibold !text-foreground">
            Custom models
            {repo && <span className="pill pill-muted ml-1.5 align-middle">repo</span>}
          </h2>
          {!repo && (
            <p className="mt-0.5 text-xs text-muted-foreground">
              Models tiny brain doesn&apos;t ship yet. They join the Model list under their
              provider, and follow the same key and agent rules.
            </p>
          )}
        </div>
        {!repo && !loading && error === null && models.length > 0 && (
          <span className="pill pill-muted shrink-0">{count}</span>
        )}
      </div>

      {body()}

      {refusal !== null && <Alert className="mt-3">{refusal}</Alert>}

      {/* No add form until the scope has loaded: a failed load has no
          provider list to declare a model under. */}
      {!loading && error === null && (
        <form
          aria-label={repo ? 'Add repo custom model' : 'Add custom model'}
          className="mt-4 border-t border-[var(--ds-border)] pt-4"
          onSubmit={(e) => {
            e.preventDefault();
            void add();
          }}
        >
          <div className="grid items-end gap-2 sm:grid-cols-[minmax(0,1fr)_150px_auto]">
            <label className="block">
              <span className="text-xs font-medium text-muted-foreground">Model id</span>
              <span className={fieldClass}>
                <input
                  className="w-full bg-transparent font-mono text-sm outline-none"
                  placeholder="e.g. claude-next-preview"
                  aria-describedby={hintId}
                  value={id}
                  onChange={(e) => setId(e.target.value)}
                />
              </span>
            </label>
            <label className="block">
              <span className="text-xs font-medium text-muted-foreground">Provider</span>
              <span className={fieldClass}>
                <select
                  className="w-full bg-transparent text-sm outline-none"
                  value={effectiveProvider}
                  onChange={(e) => setProvider(e.target.value)}
                >
                  {providers.map((p) => (
                    <option key={p.provider} value={p.provider}>
                      {p.providerLabel}
                    </option>
                  ))}
                </select>
              </span>
            </label>
            {/* Disabled without an id or a provider to declare it under, and
                while a request is in flight. */}
            <Button
              type="submit"
              disabled={pending || id.trim() === '' || effectiveProvider === ''}
              className="glow-blue h-auto rounded-xl bg-[var(--ds-blue)] px-3.5 py-2.5 font-semibold text-[var(--ds-primary-ink)] hover:bg-[var(--ds-blue)] active:scale-[.97] disabled:opacity-45 disabled:shadow-none"
            >
              Add
            </Button>
          </div>
          <p id={hintId} className="mt-1.5 text-[11px] text-[var(--ds-subtle)]">
            {hint}
          </p>
        </form>
      )}
    </section>
  );
};
