import React from 'react';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { getReviewSteps } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { getStepEmoji, getStepLabel } from '../utils/step-display';

/**
 * The shared per-task pipeline legend (header) shown wherever a task's
 * commit pipeline is rendered — the plans-console Features heading and the fix
 * detail. The Red → Green TDD phases always lead; the review steps that follow
 * are read from the repo's configured pipeline (emoji + label) rather than
 * hardcoded, so a custom pipeline (e.g. without mutation, or with extra gates)
 * is reflected here. Hook-executed steps (pre-commit / pre-push) are excluded —
 * they run as git hooks, not as post-commit review gates on the timeline.
 */
export function PipelineLegend({ pipeline }: { pipeline: readonly PipelineStep[] }) {
  // getReviewSteps is the shared core filter (drops hook-executed steps) — use
  // it rather than re-copying `!step.hook` and re-opening the drift it closed.
  const reviewSteps = getReviewSteps([...pipeline]);
  // Every step renders the same way — an emoji then its label — so the Red and
  // Green TDD phases carry emojis like the review steps, and the emphasis
  // (the foreground label vs subtle emoji/arrow) is consistent across all of
  // them. The red/green emojis come from the shared step-display source.
  const steps = [
    { emoji: getStepEmoji('red'), label: getStepLabel('red') },
    { emoji: getStepEmoji('green'), label: getStepLabel('green') },
    ...reviewSteps.map((step) => ({ emoji: step.emoji, label: step.label })),
  ];
  return (
    <p className="text-xs text-subtle">
      Per task pipeline:{' '}
      {steps.map((step, i) => (
        <React.Fragment key={`${i}-${step.label}`}>
          {i > 0 && ' → '}
          {step.emoji} <span className="text-foreground">{step.label}</span>
        </React.Fragment>
      ))}
    </p>
  );
}

export default PipelineLegend;
