/**
 * Structural view of the `parseDiff` output we read — just the bits needed to
 * walk added lines and locate them. Kept local so this util doesn't couple to
 * react-diff-view's full type surface.
 */
interface DiffChange {
  readonly type: string;
  readonly content: string;
  /** New-file line number of the change (present on insert/normal changes). */
  readonly lineNumber?: number;
}
interface DiffHunk {
  readonly changes: readonly DiffChange[];
}
interface DiffFile {
  readonly newPath?: string;
  readonly oldPath?: string;
  readonly hunks: readonly DiffHunk[];
}

/** A test declaration located in a diff — its title and where it lives, so the
 *  rail can anchor (scroll/highlight) the diff to it. */
export interface TestRef {
  readonly name: string;
  /** The (new) file path the test was declared in. */
  readonly path: string;
  /** 1-based new-file line of the `it(`/`test(` declaration. */
  readonly line: number;
}

// `it(`, `test(`, with optional `.skip` / `.only` / `.concurrent` etc.,
// followed by the title string (single/double/back-quoted).
const TEST_TITLE = /\b(?:it|test)\s*(?:\.\w+)?\s*\(\s*(['"`])(.*?)\1/;

/**
 * Derive the tests introduced by a RED commit, by reading the `it(...)` /
 * `test(...)` calls on the diff's *added* lines. Each entry carries the test
 * title plus its source coordinate (file path + line) — per-test runtime output
 * (pass/fail messages, timing) is never recorded by the pipeline, so the
 * failing-tests rail is sourced from the test source itself rather than a run,
 * and the coordinate lets the rail anchor the diff to the selected test.
 *
 * An insert change without a resolvable line number can't be anchored, so it is
 * dropped rather than emitted with a bogus coordinate — every returned entry
 * carries a real, 1-based `line`.
 */
export function extractTests(files: readonly DiffFile[]): TestRef[] {
  const tests: TestRef[] = [];
  for (const file of files) {
    const path = file.newPath ?? file.oldPath ?? '';
    for (const hunk of file.hunks ?? []) {
      for (const change of hunk.changes) {
        if (change.type !== 'insert') continue;
        if (typeof change.lineNumber !== 'number') continue;
        const match = TEST_TITLE.exec(change.content);
        if (match) tests.push({ name: match[2], path, line: change.lineNumber });
      }
    }
  }
  return tests;
}
