import type { RunKind, WorkRef } from '@magic-ingredients/tiny-brain-core';

/**
 * A run's resolved doc titles — the structural shape shared by the runs-lens
 * card (`useRepoRuns`'s `RunWorkTitles`) and the run island (`useRunDetail`),
 * both of which hand-mirror the server's `RunWorkTitles`. Kept structural so the
 * two mirrors flow into the same helpers without a common import.
 */
export interface RunTitleParts {
  prd?: string;
  feature?: string;
  fix?: string;
}

/**
 * The human role label for a branch-keyed delivery/regression run — the runs
 * whose workRef is a branch (`reconcile` / `land`) or a tip SHA
 * (`main-validation`), which resolve NO doc title. Naming the role keeps an
 * opaque branch/SHA off the heading. `worker` / `completion` carry the item
 * workRef so their title resolves — they never reach this map (undefined here ⇒
 * the slug fallback still applies).
 */
const RUN_ROLE_LABEL: Partial<Record<RunKind, string>> = {
  'main-validation': 'Post-merge regression test',
  reconcile: 'Reconcile',
  land: 'Land',
};

/**
 * The run's heading title — the resolved work-item doc title (PRD, then fix),
 * else the run's ROLE label for a branch-keyed delivery/regression run (so a
 * reconcile/land/main-validation run never reads as an opaque branch/SHA id),
 * else the work-item slug so the heading is NEVER blank. The single title rule
 * both run surfaces (the runs-lens card and the run island header) share, rather
 * than each re-deriving it inline.
 */
export function runHeadingTitle(workRef: WorkRef, titles?: RunTitleParts, kind?: RunKind): string {
  const roleLabel = kind !== undefined ? RUN_ROLE_LABEL[kind] : undefined;
  return titles?.prd ?? titles?.fix ?? roleLabel ?? workRef.id;
}

/**
 * The feature label beneath the heading on a PRD run — the resolved feature
 * title, falling back to the feature slug so a half-resolved read still names
 * it. `null` for any run that is not a PRD run carrying a feature (a fix run, a
 * bare PRD, a spike/task), so the caller renders no feature line.
 */
export function runFeatureLabel(workRef: WorkRef, titles?: RunTitleParts): string | null {
  if (workRef.kind !== 'prd' || workRef.feature === undefined) return null;
  return titles?.feature ?? workRef.feature;
}
