import { useSearchParams } from 'react-router';
import { Archive, ScrollText, Settings } from 'lucide-react';
import { cn } from '@/lib/utils';
import { QualitySparkline, RAIL_CONTROL, RAIL_HOVER, RAIL_SELECTED } from './railControls';

/**
 * The repo workspace's Quality and Settings view-switches, surfaced in the top
 * breadcrumb rail. Both are URL-driven (`?view=quality` / `?settings`), the same
 * params RepoDetailPage reads and the breadcrumb crumbs already navigate to — so
 * these are permanent shortcuts to those nav actions, no prop threading from the
 * page below the global header.
 */
export function RepoViewControls({ className }: { className?: string }) {
  const [searchParams, setSearchParams] = useSearchParams();

  const settingsOpen =
    searchParams.get('settings') !== null || searchParams.get('section') !== null;
  const archiveOpen = searchParams.has('archive');
  // Runs is a board sub-mode (a bare `?runs` marker) — its toggle lives in the
  // board's filter rail, not here. It still gates the top-rail active states so
  // Quality/Decisions don't read as active while the runs board is showing.
  const runsOpen = searchParams.has('runs');
  const qualityActive =
    !settingsOpen && !archiveOpen && !runsOpen && searchParams.get('view') === 'quality';
  const decisionsActive =
    !settingsOpen && !archiveOpen && !runsOpen && searchParams.get('view') === 'decisions';

  // Mirror RepoDetailPage.setActiveTab('quality'): select Quality and drop any
  // open Settings + the previous area's item/analyser drill-downs. Also clears
  // `?archive`: the Archive view is a content-replacing surface whose early
  // return precedes Quality's, so leaving it stale would swallow this click.
  const openQuality = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('view', 'quality');
      next.delete('settings');
      next.delete('section');
      next.delete('item');
      next.delete('analyser');
      next.delete('archive');
      next.delete('runs');
      return next;
    });

  // Mirror setActiveTab('decisions'): select the ADR assets gallery and drop
  // the same drill-downs (+ `?archive`) so nothing stale shadows it.
  const openDecisions = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('view', 'decisions');
      next.delete('settings');
      next.delete('section');
      next.delete('item');
      next.delete('analyser');
      next.delete('assets');
      next.delete('archive');
      next.delete('runs');
      return next;
    });

  // The Archive view (board-first-chrome T3) is a content-replacing surface (bare
  // `?archive` marker) for the archived plans + fixes the board drops. Setting it
  // clears any open Settings so the archive isn't rendered behind the Setup pane.
  const openArchive = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('archive', '');
      next.delete('settings');
      next.delete('section');
      next.delete('runs');
      return next;
    });

  // Mirror RepoDetailPage.openSettings: Settings is an overlay view, so it only
  // sets `?settings`. It must clear `?archive` too — the Archive early return
  // precedes the Settings render, so an open Archive would swallow this click.
  const openSettings = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('settings', '');
      next.delete('archive');
      next.delete('runs');
      return next;
    });

  return (
    <div className={cn('flex shrink-0 items-center gap-2', className)}>
      {/* Presentational scope label — these controls act on the current repo,
          not global state. Sits inside the group (adjacent to the controls), so
          it reads as scoping them rather than as a separate nav item. */}
      <span className="mono text-[11px] uppercase tracking-wider text-muted-foreground">Repo:</span>

      <button
        type="button"
        onClick={openQuality}
        aria-current={qualityActive ? 'page' : undefined}
        className={cn(RAIL_CONTROL, qualityActive ? RAIL_SELECTED : cn('text-muted-foreground', RAIL_HOVER))}
      >
        <QualitySparkline />
        Quality
      </button>

      <button
        type="button"
        onClick={openDecisions}
        aria-current={decisionsActive ? 'page' : undefined}
        className={cn(RAIL_CONTROL, decisionsActive ? RAIL_SELECTED : cn('text-muted-foreground', RAIL_HOVER))}
      >
        <ScrollText className="h-4 w-4" />
        Decisions
      </button>

      {/* Runs moved OUT of this top nav rail into the board's filter rail (beside
          All/Plans/Fixes/Spikes + Attention), where Runs is a work-item filter —
          not a top-level view switch. See BoardView's `board-runs-toggle`. */}

      <button
        type="button"
        onClick={openArchive}
        aria-current={archiveOpen ? 'page' : undefined}
        className={cn(RAIL_CONTROL, archiveOpen ? RAIL_SELECTED : cn('text-muted-foreground', RAIL_HOVER))}
      >
        <Archive className="h-4 w-4" />
        Archive
      </button>

      <span className="h-7 w-px self-center bg-border-strong" aria-hidden="true" />

      <button
        type="button"
        onClick={openSettings}
        aria-current={settingsOpen ? 'page' : undefined}
        className={cn(RAIL_CONTROL, settingsOpen ? RAIL_SELECTED : cn('text-muted-foreground', RAIL_HOVER))}
      >
        <Settings className="h-4 w-4" />
        Settings
      </button>
    </div>
  );
}

export default RepoViewControls;
