import type { LifecyclePhase } from '@magic-ingredients/tiny-brain-core';
import type { ValidationPill } from './validation-panel-state';

/**
 * work-item-detail-service-rewrite / props-in-ui — the pure client mapping from
 * the SERVER-computed `LifecyclePhase` (core `getValidation`, ADR-0038) to the
 * validation panel's BASE pill.
 *
 * The panel layers an ACTIVE delivery pill (reconciling / merging / validating-on-
 * main, from {@link describeLifecyclePhasePill}) over this base; the base is what
 * shows when no active delivery pill applies, AND it selects the panel body
 * (`failed` → the failure block, `regression` → the evidence block). So:
 *  - `item_completion` names the work-item verdict directly: running → validating,
 *    failed → failed, passed → passed, not_started → pending (the all-pending
 *    preview, no run yet).
 *  - `reconciliation` / `merge` mean completion ALREADY passed; a failure there is a
 *    DELIVERY signal the reconcile lane + active pill carry, never a work-item red —
 *    so the base shield stays green (`passed`).
 *  - `post_merge` names the on-main verdict: running → validating, failed →
 *    regression (drives the evidence block), passed / not_started → passed
 *    (completion is done).
 *  - `tdd` is the pre-delivery floor — nothing has validated yet, so `pending`.
 */
export function panelPillFromLifecycle(validation: LifecyclePhase): ValidationPill {
  const { pipeline, status } = validation;
  switch (pipeline) {
    case 'planning':
      // ADR-0040: the front-of-lifecycle Backlog phase — nothing has validated
      // yet, so it reads as the pre-delivery `pending` floor, like `tdd`. It
      // never reaches the validation panel (Backlog, not In-review) but is
      // enumerated to keep the exhaustiveness guard satisfied.
      return 'pending';
    case 'tdd':
      return 'pending';
    case 'item_completion':
      return status === 'running'
        ? 'validating'
        : status === 'failed'
          ? 'failed'
          : status === 'passed'
            ? 'passed'
            : 'pending';
    case 'reconciliation':
    case 'merge':
      // Completion already passed; a reconcile/merge failure is a DELIVERY signal
      // the reconcile lane + active delivery pill carry, so the base shield is green.
      return 'passed';
    case 'post_merge':
      // Completion is done, so anything but a live run or a red reads passed. A red
      // post-merge phase reads `regression` here — the common case; a post-merge run
      // that CRASHED without a regression verdict (no evidence) is refined back to a
      // plain `failed` by the F2 adapter, which also holds the regression evidence
      // this phase-only mapping cannot see (getValidation collapses both to failed).
      return status === 'running' ? 'validating' : status === 'failed' ? 'regression' : 'passed';
    default:
      return assertNever(pipeline);
  }
}

/** Exhaustiveness guard — a compile error here means a new lifecycle pipeline went unhandled. */
function assertNever(value: never): never {
  throw new Error(`Unhandled lifecycle pipeline: ${String(value)}`);
}
