import { useEffect, useState } from 'react'
import { useParams } from 'react-router'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { Drama, Clock, CheckCircle, FileText, Shield, BookOpen, Info, Tag } from 'lucide-react'
import { useSSE } from '@/hooks/useSSE'
import { useTheme } from '@/contexts/ThemeContext'
import type { PersonaDetails } from '@/types/personas'

export default function PersonaDetailPage() {
  const { personaId } = useParams<{ personaId: string }>()
  const sseState = useSSE()
  const { resolvedTheme } = useTheme()
  const currentPersona = sseState.personaId || 'default'
  const [personaDetails, setPersonaDetails] = useState<PersonaDetails | null>(null)
  const [loading, setLoading] = useState(true)

  const isActivePersona = personaId === currentPersona

  useEffect(() => {
    const fetchPersonaDetails = async () => {
      try {
        setLoading(true)
        const response = await fetch(`/api/personas/${personaId}`)
        if (response.ok) {
          const data: PersonaDetails = await response.json()
          setPersonaDetails(data)
        } else {
          console.error('Failed to fetch persona details:', response.statusText)
          setPersonaDetails({ name: personaId })
        }
      } catch (error) {
        console.error('Error fetching persona details:', error)
        setPersonaDetails({ name: personaId })
      } finally {
        setLoading(false)
      }
    }

    if (personaId) {
      fetchPersonaDetails()
    }
  }, [personaId])

  const goldenRules = personaDetails?.persona?.user?.rules
  const systemRules = personaDetails?.persona?.system?.rules
  const systemDetails = personaDetails?.persona?.system?.details
  const userDetails = personaDetails?.persona?.user?.details
  const metadata = personaDetails?.metadata
  const files = personaDetails?.files
  const lastUpdated = personaDetails?.metadata?.lastUpdated
  const description =
    personaDetails?.persona?.system?.metadata?.description ||
    personaDetails?.metadata?.description ||
    'Persona configuration'

  const proseClasses = `prose prose-sm max-w-none ${
    resolvedTheme === 'dark'
      ? 'prose-invert'
      : ''
  }`

  return (
    <div className="h-full flex flex-col">
      {/* Header with persona details */}
      <div className="border-b">
        <div className="p-4 md:p-6">
          {loading ? (
            <div className="animate-pulse">
              <div className="h-8 w-48 bg-gray-200 dark:bg-gray-700 rounded mb-2" />
              <div className="h-4 w-64 bg-gray-200 dark:bg-gray-700 rounded" />
            </div>
          ) : (
            <div data-testid="persona-detail-header" className="flex items-start justify-between">
              <div className="flex items-center gap-4">
                <span
                  className="grid h-14 w-14 shrink-0 place-items-center rounded-lg"
                  style={{
                    background: `color-mix(in oklab, ${isActivePersona ? 'var(--color-primary)' : 'var(--color-blue)'} 16%, transparent)`,
                  }}
                >
                  <Drama
                    className="h-8 w-8"
                    style={{ color: isActivePersona ? 'var(--color-primary)' : 'var(--color-blue)' }}
                  />
                </span>
                <div>
                  <h1 className="display text-2xl font-bold">{personaId}</h1>
                  <p className="text-muted">{description}</p>
                  <div className="flex items-center gap-4 mt-2">
                    {isActivePersona && (
                      <span
                        className="inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-xs font-semibold text-white"
                        style={{ background: 'var(--color-primary)' }}
                      >
                        <CheckCircle className="h-3 w-3" />
                        Active
                      </span>
                    )}
                    {lastUpdated && (
                      <div className="flex items-center gap-1 text-xs text-subtle">
                        <Clock className="h-3 w-3" />
                        Last updated: {new Date(lastUpdated).toLocaleDateString()}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Persona details sections */}
      <div className="flex-1 overflow-auto p-4 md:p-6 space-y-6">
        {/* Golden Rules */}
        {goldenRules && goldenRules.length > 0 && (
          <section className="rounded-2xl border border-border p-4">
            <h2 className="flex items-center gap-2 text-lg font-semibold mb-3">
              <Shield className="h-5 w-5 text-amber-500" />
              Golden Rules
            </h2>
            <ul className="space-y-2">
              {goldenRules.map((rule, i) => (
                <li key={i} className="flex items-start gap-2 text-sm text-muted-foreground">
                  <span className="mt-1 h-1.5 w-1.5 rounded-full bg-amber-500 shrink-0" />
                  {rule}
                </li>
              ))}
            </ul>
          </section>
        )}

        {/* System Rules */}
        {systemRules && systemRules.length > 0 && (
          <section className="rounded-2xl border border-border p-4">
            <h2 className="flex items-center gap-2 text-lg font-semibold mb-3">
              <BookOpen className="h-5 w-5 text-blue-500" />
              System Rules
            </h2>
            <ul className="space-y-2">
              {systemRules.map((rule, i) => (
                <li key={i} className="flex items-start gap-2 text-sm text-muted-foreground">
                  <span className="mt-1 h-1.5 w-1.5 rounded-full bg-blue-500 shrink-0" />
                  {rule}
                </li>
              ))}
            </ul>
          </section>
        )}

        {/* System Details */}
        {systemDetails && (
          <section className="rounded-2xl border border-border p-4">
            <h2 className="flex items-center gap-2 text-lg font-semibold mb-3">
              <Info className="h-5 w-5 text-purple-500" />
              System Details
            </h2>
            <div className={proseClasses}>
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{systemDetails}</ReactMarkdown>
            </div>
          </section>
        )}

        {/* User Details */}
        {userDetails && (
          <section className="rounded-2xl border border-border p-4">
            <h2 className="flex items-center gap-2 text-lg font-semibold mb-3">
              <Info className="h-5 w-5 text-green-500" />
              User Details
            </h2>
            <div className={proseClasses}>
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{userDetails}</ReactMarkdown>
            </div>
          </section>
        )}

        {/* Metadata */}
        {metadata && Object.keys(metadata).length > 0 && (
          <section className="rounded-2xl border border-border p-4">
            <h2 className="flex items-center gap-2 text-lg font-semibold mb-3">
              <Tag className="h-5 w-5 text-gray-500" />
              Metadata
            </h2>
            <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 text-sm">
              {Object.entries(metadata).map(([key, value]) => (
                <div key={key} className="contents">
                  <dt className="font-medium text-muted-foreground">{key}</dt>
                  <dd className="text-foreground">
                    {Array.isArray(value)
                      ? value.join(', ')
                      : String(value ?? '')}
                  </dd>
                </div>
              ))}
            </dl>
          </section>
        )}

        {/* Files */}
        {files && files.length > 0 && (
          <section className="rounded-2xl border border-border p-4">
            <h2 className="flex items-center gap-2 text-lg font-semibold mb-3">
              <FileText className="h-5 w-5 text-gray-500" />
              Files
            </h2>
            <ul className="space-y-1">
              {files.map((file, i) => (
                <li key={i} className="text-sm font-mono text-muted-foreground">
                  {file}
                </li>
              ))}
            </ul>
          </section>
        )}
      </div>
    </div>
  )
}
