import { X, CircleX, Loader2, AlertCircle } from 'lucide-react';
import { extractTests } from '../utils/extract-tests';
import { useHunkAnchor } from '../hooks/useHunkAnchor';
import { useCommitDiff } from '../hooks/useCommitDiff';
import DiffFileView from './DiffFileView';
import { PhaseEmptyState } from './PhaseEmptyState';

interface RedTabProps {
  repoId: string;
  /** The task's RED (test:) commit SHA, if it has one. */
  commitSha?: string;
  /** Whether the red phase is live (work underway, no commit yet) — drives the
   *  empty state to read "in progress" rather than "not started". */
  inProgress?: boolean;
}

/**
 * The Red tab — the spec, written to fail first. A rail of the failing tests
 * (derived from the test source the RED commit added; per-test runtime output
 * is never recorded, so the rail is sourced from the diff itself, not a run)
 * beside the test-source diff for that commit. Selecting a test anchors the
 * diff to its hunk — highlighting that line and scrolling it into view.
 */
export default function RedTab({ repoId, commitSha, inProgress }: RedTabProps) {
  // `commitSha` is the literal 'skipped' for skip-RED tasks (--phase green);
  // there's no RED commit to diff against (useCommitDiff no-fetches on it).
  const hasRedCommit = !!commitSha && commitSha !== 'skipped';
  const { files, loading, error } = useCommitDiff(repoId, commitSha);

  // Prefer the test-source files; fall back to the whole diff if the commit
  // touched no recognisable test file. Computed once and shared by the rail and
  // the diff pane so they never disagree. (On a no-commit render `files` is
  // empty, so these are harmless.)
  const testFiles = files.filter((f) => /\.(test|spec)\./.test(f.newPath ?? f.oldPath ?? ''));
  const displayFiles = testFiles.length > 0 ? testFiles : files;
  const tests = extractTests(displayFiles);

  // Rail → diff anchor: selecting a test highlights its line in the diff and
  // scrolls it into view. The hook is the single source of truth for the
  // selection — `isSelected` (active row) and `selectedKey` (highlight) move
  // together, so they can't diverge. Called before the early return below so
  // the hook order is stable across a hasRedCommit flip (Rules of Hooks).
  const { containerRef, selectedKey, isSelected, anchor } = useHunkAnchor(displayFiles);

  if (!hasRedCommit) {
    // Skip-RED is terminal, not in-flight, so it reads as empty even mid-phase.
    const skipped = commitSha === 'skipped';
    return (
      <PhaseEmptyState
        inProgress={!skipped && !!inProgress}
        message={
          skipped
            ? 'RED was skipped for this task — no failing tests to show.'
            : inProgress
              ? 'Writing the failing tests…'
              : 'No red commit yet — no failing tests written.'
        }
      />
    );
  }

  return (
    <div className="grid h-full min-h-0 grid-cols-1 lg:grid-cols-[320px_minmax(0,1fr)]">
      {/* Failing-tests rail */}
      <aside className="flex min-h-0 flex-col border-r border-border">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="eyebrow text-[10px]" style={{ color: 'var(--color-phase-red)' }}>
            Failing tests
          </p>
          <span data-testid="failing-test-count" className="mono text-[11px] text-muted-foreground">
            {tests.length}
          </span>
        </div>
        <p className="px-4 pt-2 text-[13px] leading-snug text-muted-foreground">
          The spec, written to fail first — no implementation exists yet.
        </p>

        <div className="mt-3 min-h-0 flex-1 overflow-y-auto pb-3">
          {tests.map((test, i) => {
            const isActive = isSelected({ path: test.path, line: test.line });
            return (
              <button
                key={`${test.name}-${i}`}
                type="button"
                aria-pressed={isActive}
                onClick={() => anchor({ path: test.path, line: test.line })}
                className="flex w-full gap-3 border-l-2 px-4 py-3 text-left transition-colors hover:bg-muted/40"
                style={
                  isActive
                    ? {
                        borderLeftColor: 'var(--color-phase-red)',
                        background: 'color-mix(in oklab, var(--color-phase-red) 12%, transparent)',
                      }
                    : { borderLeftColor: 'transparent' }
                }
              >
                <span
                  className="grid h-5 w-5 flex-none place-items-center rounded-full border"
                  style={{
                    color: 'var(--color-phase-red)',
                    background: 'color-mix(in oklab, var(--color-phase-red) 16%, transparent)',
                    borderColor: 'color-mix(in oklab, var(--color-phase-red) 45%, transparent)',
                  }}
                >
                  <X className="h-3.5 w-3.5" />
                </span>
                <div className="min-w-0">
                  <p className="text-[13px] leading-snug">{test.name}</p>
                </div>
              </button>
            );
          })}

          {tests.length > 0 && (
            <div className="mx-4 mt-4 rounded-xl border border-border bg-muted/30 p-3">
              <p className="eyebrow text-[9px] text-muted-foreground">Suite</p>
              <p
                data-testid="red-suite-summary"
                className="mono mt-1 inline-flex items-center gap-1.5 text-[12px]"
                style={{ color: 'var(--color-phase-red)' }}
              >
                <CircleX className="h-3.5 w-3.5" /> {tests.length}{' '}
                {tests.length === 1 ? 'test' : 'tests'} · failing
              </p>
            </div>
          )}
        </div>
      </aside>

      {/* Test-source diff */}
      <section ref={containerRef} className="tb-diff min-h-0 overflow-y-auto">
        {loading && (
          <div className="flex items-center gap-2 p-4 text-sm text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" /> Loading diff…
          </div>
        )}
        {error && (
          <div className="flex items-start gap-2 p-4 text-sm text-red-500">
            <AlertCircle className="mt-0.5 h-4 w-4 flex-none" /> {error}
          </div>
        )}
        {!loading &&
          !error &&
          displayFiles.map((file, fileIndex) => (
            <DiffFileView
              key={`${file.newPath ?? file.oldPath ?? ''}-${fileIndex}`}
              file={file}
              selectedChanges={selectedKey ? [selectedKey] : []}
            />
          ))}
      </section>
    </div>
  );
}
