import type { RunUsage } from '@magic-ingredients/tiny-brain-core';

/** Compact a token count: `950` → `950`, `1500` → `1.5k`, `2_000_000` → `2M`. */
function compactTokens(n: number): string {
  const trim = (x: number) => x.toFixed(1).replace(/\.0$/, '');
  if (n < 1000) return String(n);
  if (n < 1_000_000) return `${trim(n / 1000)}k`;
  return `${trim(n / 1_000_000)}M`;
}

/**
 * The run's token usage as a lens row shows it: the input + output tokens as one
 * compact count (cache tokens are excluded — they're not the spend signal a
 * glance wants). An em dash when a record carries no usage.
 */
export function formatRunUsage(usage: RunUsage | undefined): string {
  if (!usage) return '—';
  return `${compactTokens(usage.inputTokens + usage.outputTokens)} tok`;
}
