/**
 * Live stored-as preview for the Key name field (fix:
 * env-edit-keys-and-table-nits task 3). MIRRORS core's
 * `normaliseKeyReference` — client code must not value-import the core
 * barrel (it pulls node builtins into the Vite bundle), and the two-line
 * rule is cheaper duplicated than plumbed. The server remains the
 * authority; this only previews what it will store.
 */

const BARE_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;

const SHARED_REFERENCE_BY_PROVIDER: Record<string, (name: string) => string> = {
  railway: (name) => `\${{ shared.${name} }}`,
};

/**
 * The wrapped reference the server will store for a bare name, or null when
 * the (trimmed) value passes through as-is — empty input previews nothing.
 */
export function sharedReferencePreview(provider: string, value: string): string | null {
  const trimmed = value.trim();
  if (trimmed.length === 0) return null;
  const wrap = SHARED_REFERENCE_BY_PROVIDER[provider];
  if (wrap === undefined || !BARE_NAME.test(trimmed)) return null;
  return wrap(trimmed);
}
