import type { AcceptanceState, DeliveryQueueStatus } from '@magic-ingredients/tiny-brain-core';

/**
 * The sidebar status buckets for the Worktrees list — the worktree analogue of
 * {@link ListStatus} and the single source of truth for both a card's status
 * pill and the header filter pills. In-progress worktrees come from the
 * in-flight feed; the rest are derived from a delivery row's queue status +
 * acceptance state ({@link deliveryWorktreeStatus}).
 */
export type WorktreeListStatus =
  | 'in-progress'
  | 'ready-to-merge'
  | 'pr-open'
  | 'conflict'
  | 'rejected'
  | 'ready-to-clean';

/**
 * Every bucket, in display order: the actionable `in-progress` / `ready-to-merge`
 * lead, then the additional states a worktree can be in (`pr-open` / `conflict` /
 * `rejected`), then `ready-to-clean` (merged out, worktree still on disk) last.
 * The union above is kept in this same order so the two don't drift.
 */
export const WORKTREE_LIST_STATUSES: readonly WorktreeListStatus[] = [
  'in-progress',
  'ready-to-merge',
  'pr-open',
  'conflict',
  'rejected',
  'ready-to-clean',
];

/**
 * The buckets shown by default — every bucket. The Worktrees sidebar defaults to
 * showing ALL worktrees (terminal `rejected` and `ready-to-clean` included); the
 * filter pills let the user narrow from there rather than starting narrowed.
 */
export const DEFAULT_WORKTREE_STATUSES: readonly WorktreeListStatus[] = WORKTREE_LIST_STATUSES;

/** Exhaustiveness guard — a compile error here means a new bucket source went unhandled. */
function assertNever(value: never): never {
  throw new Error(`Unhandled worktree status source: ${String(value)}`);
}

/**
 * Map a deliverable worktree's queue status + acceptance state to its sidebar
 * bucket.
 *
 * Acceptance is the terminal axis and outranks the queue snapshot: a `landed`
 * acceptance means the work merged out (the worktree is now a clean-up candidate)
 * and `rejected` work is terminally discarded — neither is a merge candidate
 * regardless of what the queue status still reads (a row whose work merged out,
 * or was rejected, from under a still-actionable snapshot). `not-ready` work is
 * done on no ref, so it has no deliverable queue state and reads as `in-progress`.
 *
 * For `pending-acceptance` work the queue status drives the bucket: `cleanup`
 * means the work already merged out (awaiting disk cleanup) → `ready-to-clean`; a
 * PRD group's `mixed` state reads as `ready-to-merge` (it carries ready work).
 */
export function deliveryWorktreeStatus(
  status: DeliveryQueueStatus,
  acceptance: AcceptanceState,
): WorktreeListStatus {
  switch (acceptance) {
    case 'landed':
      return 'ready-to-clean';
    case 'rejected':
      return 'rejected';
    case 'not-ready':
      return 'in-progress';
    case 'pending-acceptance':
      break;
    default:
      return assertNever(acceptance);
  }

  switch (status) {
    case 'cleanup':
      return 'ready-to-clean';
    case 'conflict':
      return 'conflict';
    case 'pr-open':
      return 'pr-open';
    case 'ready-to-land':
    case 'mixed':
      return 'ready-to-merge';
    default:
      return assertNever(status);
  }
}

/**
 * A worktree's lifecycle. `not_started`/`in_progress`/`complete`/`merged` are the
 * forward path; `rejected` is the discard terminal (its work was abandoned, not
 * landed). Acceptance selects only the two TERMINALS (`merged`/`rejected`); the
 * forward tri-state is driven by the task counts + git position, so a
 * deliverable-but-partial row still reads by its true progress.
 */
export type WorktreeLifecycle = 'not_started' | 'in_progress' | 'complete' | 'merged' | 'rejected';

/** The signals the progress rollup reads — acceptance + contents counts + git position. */
export interface WorktreeProgressInput {
  /** The row's derived acceptance state — selects the terminal states (landed/rejected). */
  readonly acceptanceState: AcceptanceState;
  /** Completed / total task counts from `contents` (the still-to-land scope). */
  readonly completed: number;
  readonly total: number;
  /** How many tasks the branch delivered — populated once merged, where `total` is 0. */
  readonly deliveredCount: number;
  /** Commits ahead of base; `0` ⇒ level with main (no unlanded work of its own). */
  readonly ahead: number;
}

/** A worktree's lifecycle plus the display figures the surface renders. */
export interface WorktreeProgress {
  readonly lifecycle: WorktreeLifecycle;
  /**
   * 0..100. `100` when complete or merged. `0` when not_started, when rejected
   * (its work was discarded), and — unavoidably — for in_progress work that has
   * commits but no tracked tasks to measure (`ahead > 0`, `total = 0`).
   */
  readonly percent: number;
  /** Display task count for the "N tasks" readout — delivered count once merged. */
  readonly total: number;
  /** Tearing down loses unlanded work → warn. True only while in_progress or complete. */
  readonly teardownWarns: boolean;
}

/**
 * Derive a worktree's lifecycle and the figures the merge surface shows, so a
 * fully-merged worktree reads 100% / safe-to-tear-down and a fresh one reads 0%
 * — the two the reachability-scoped `contents` alone can't tell apart (both are
 * empty). Acceptance picks the terminals; `ahead`/`deliveredCount` split the two
 * `not-ready`-with-empty-contents cases (fresh vs under-way); the counts drive
 * complete-vs-in_progress.
 */
export function deriveWorktreeProgress(input: WorktreeProgressInput): WorktreeProgress {
  const { acceptanceState, completed, total, deliveredCount, ahead } = input;
  const pct = (done: number, all: number): number => (all > 0 ? Math.round((done / all) * 100) : 0);

  // Merged: work landed on main. `contents` is empty (nothing still to land), so
  // the delivered tasks are the durable record for the count. Safe to tear down.
  if (acceptanceState === 'landed') {
    return { lifecycle: 'merged', percent: 100, total: deliveredCount, teardownWarns: false };
  }
  // Rejected: the work was discarded, not landed — a terminal with nothing left to
  // lose, so teardown never warns (warning "loses work" here would be backwards).
  if (acceptanceState === 'rejected') {
    return { lifecycle: 'rejected', percent: 0, total, teardownWarns: false };
  }
  // No work and level with main = a fresh, unstarted worktree.
  const started = total > 0 || deliveredCount > 0 || ahead > 0;
  if (!started) {
    return { lifecycle: 'not_started', percent: 0, total: 0, teardownWarns: false };
  }
  // Complete: every tracked task done but not yet landed — ready to land. Driven
  // by the counts (not the acceptance state), so a deliverable-but-partial row
  // (e.g. 3/5 pending-acceptance) stays in_progress at its true percent.
  if (total > 0 && completed >= total) {
    return { lifecycle: 'complete', percent: 100, total, teardownWarns: true };
  }
  // Otherwise work is under way: in_progress at its true percent (0 when it has
  // commits but no tracked tasks to measure).
  return { lifecycle: 'in_progress', percent: pct(completed, total), total, teardownWarns: true };
}

/**
 * Aggregate a list of bucket assignments into per-bucket counts for the filter
 * pills. Every bucket is zero-filled so each pill always renders a count, even
 * when no worktree currently falls in it.
 */
export function countWorktreesByStatus(
  statuses: readonly WorktreeListStatus[],
): Record<WorktreeListStatus, number> {
  const counts: Record<WorktreeListStatus, number> = {
    'in-progress': 0,
    'ready-to-merge': 0,
    'pr-open': 0,
    conflict: 0,
    rejected: 0,
    'ready-to-clean': 0,
  };
  for (const status of statuses) counts[status] += 1;
  return counts;
}
