import { useEffect, useState } from 'react';
import { fetchDeliveryWorktree } from '../services/api';

/**
 * Whether the branch's server deliverable row reads `cleanup` — the fix
 * detail's truth source when no host threads the board-row signal (fix
 * fix-detail-cleanup-vanishes-for-landed-lingering-worktree). After a
 * fast-forward land `base..branch` is EMPTY, so the branch stops contributing
 * statusByRef cells and the client lattice probe reads "reaped" while the
 * worktree is still on disk; only the server can tell the two states apart.
 *
 * The probe is a per-branch on-demand read (the same O(1)-per-opened-item
 * budget the worktree detail pays — dashboard-landing-perf task 3), so the
 * caller gates `enabled` to the AMBIGUOUS state only: no host signal, landed,
 * and no live lattice cell. Only a row reading `cleanup` is a positive
 * answer; a null row (no longer deliverable), any other status, or a failed
 * fetch returns false and leaves the caller's lattice fallback in charge.
 */
export function useDeliverableRowCleanup(
  repoId: string,
  branch: string | undefined,
  enabled: boolean,
  refreshTick: number,
): boolean {
  const [probedCleanup, setProbedCleanup] = useState(false);
  useEffect(() => {
    setProbedCleanup(false);
    if (!enabled || branch === undefined) return;
    let cancelled = false;
    fetchDeliveryWorktree(repoId, branch)
      .then((row) => {
        if (!cancelled && row?.status === 'cleanup') setProbedCleanup(true);
      })
      .catch(() => {
        // No data — the caller's lattice fallback stays in charge.
      });
    return () => {
      cancelled = true;
    };
  }, [repoId, branch, enabled, refreshTick]);
  return probedCleanup;
}
