import type { RunResources } from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';
import { formatBytes } from '@/components/PrdTeardownIsland';

export interface RunResourceFootprintProps {
  /**
   * The run's sampled OS-resource footprint (run-resource-sampling F4), or
   * `undefined` when the run predates sampling / a provider never populated it.
   */
  resources?: RunResources;
  /**
   * Memory-only variant (validation-surface-misreads-ready-to-land-fix task 2) —
   * drop the CPU figure and the CPU arm of the runaway warn, keeping only the peak
   * memory metric and its ≥4 GiB warn. For a settled MULTI-CORE run (a Stryker
   * mutation subtree) whose CPU legitimately exceeds 100%, so the CPU sample is
   * neither actionable nor a runaway — a false amber otherwise. The memory arm (a
   * near-OOM peak RSS) is still a genuine signal and stays.
   */
  memoryOnly?: boolean;
}

/**
 * The single presentational threshold a footprint reaches to read as a runaway:
 * peak resident memory at or above 4 GiB (a vitest OOM) or CPU at or above a
 * pegged core (100%). Pure render-time constant, not new server state; module-
 * local — the component is its only consumer.
 */
const RUN_RESOURCE_WARN_THRESHOLD = {
  peakRssBytes: 4 * 1024 ** 3,
  cpuPercent: 100,
} as const;

/** At-or-above either arm warns — one inclusive (`>=`) rule for both, so the cutoff
 *  is a single defined line. In `memoryOnly` mode the CPU arm is dropped: a settled
 *  multi-core run's CPU is not a runaway, so only the memory arm can warn. */
function isOverThreshold(resources: RunResources, memoryOnly: boolean): boolean {
  if (resources.peakRssBytes >= RUN_RESOURCE_WARN_THRESHOLD.peakRssBytes) return true;
  return !memoryOnly && resources.lastCpuPercent >= RUN_RESOURCE_WARN_THRESHOLD.cpuPercent;
}

/**
 * The run's resource footprint on its card — a labelled peak resident memory
 * (human bytes) and last CPU% sample, beside the token line. Renders nothing when the
 * run carries no sampled resources (honesty rule — never a fabricated `0 MB`).
 * A footprint over {@link RUN_RESOURCE_WARN_THRESHOLD} gets an amber warn tint
 * so a runaway reads as attention-worthy, distinct from the plain footprint.
 * The tint is the whole VISIBLE cue: an earlier prepended glyph shifted the
 * metric text left/right as it appeared and vanished across samples (judder),
 * so the non-colour accessible cue is a visually-hidden (sr-only) label that
 * takes no layout space.
 */
export function RunResourceFootprint({ resources, memoryOnly = false }: RunResourceFootprintProps) {
  if (!resources) return null;
  const overThreshold = isOverThreshold(resources, memoryOnly);
  return (
    <span
      data-testid="run-resource-footprint"
      className={cn(
        'mono flex flex-shrink-0 items-center gap-1 text-xs tabular-nums',
        overThreshold ? 'text-amber-500' : 'text-muted-foreground',
      )}
    >
      {overThreshold && (
        // Non-colour accessible cue only — visually hidden so it adds no
        // horizontal box and never shifts the metric text (the removed glyph
        // did). Colour (the amber tint above) is the sole visible signal.
        <span data-testid="run-resource-warn" role="img" aria-label="over resource threshold" className="sr-only" />
      )}
      Memory {formatBytes(resources.peakRssBytes)}
      {!memoryOnly && <> · {Math.round(resources.lastCpuPercent)}% CPU</>}
    </span>
  );
}

export default RunResourceFootprint;
