import { useState } from 'react';
import { cn } from '@/lib/utils';
import MiniStatusRail, { type MiniStatusRailProps } from '@/components/MiniStatusRail';
import { GradientProgress } from '@/components/ui/GradientProgress';
import { formatRelativeTime } from '@/utils/relative-time';
import type { BoardRow, BoardCardSummary, BoardProvisioning } from '@/hooks/useBoard';
import type { Fix } from '@/types';
import JourneyBar from './JourneyBar';
import { shapeJourney, journeyMicrocopy } from '../utils/shape-journey';
// `describeEarlyPhase` is a runtime value: import it from the browser-safe
// `/board-lane` subpath, never the core barrel — the barrel re-exports Node-only
// storage code (storage-path-builder → `path`) that Vite externalises, crashing
// the dashboard in the browser. The `LifecyclePhase` TYPE is erased at build, so
// a bare-root `import type` is safe.
import { describeEarlyPhase } from '@magic-ingredients/tiny-brain-core/board-lane';
import type { LifecyclePhase } from '@magic-ingredients/tiny-brain-core';
import { describeLifecyclePhasePill, describeLifecyclePendingCue } from '../utils/lifecycle-pill';
import { RUN_FAILED_REMEDIATION, type PillRemediation } from '@/hooks/useDeliveryActions';
import { PlanningChecksRow } from '@/components/PlanningChecksRow';

/**
 * board-surface F1 — the board's own card, a faithful port of the mockup
 * `.card` (docs/prd/work-board/assets/work-board.html): a tag row (kind +
 * settled-lane echo + a stalled/failed sub-status), the title, the
 * MiniStatusRail who/where glance on every live-capable lane (In progress /
 * In review), a task progress bar on In-progress, and a mono meta line
 * (`done/total tasks · severity` + branch). Severity is metadata, not a pill.
 * There is no status pill — the lane column IS the settled status. The card is
 * select-primary (a stretched select button) and carries NO delivery action:
 * the In-review Land button is RETIRED (user call, 2026-07-26) — landing
 * happens from the detail's Merge cap, the one action home.
 */
export interface BoardCardProps {
  row: BoardRow;
  selected: boolean;
  onSelect: (row: BoardRow) => void;
  /** Open the WorkerRun island for the row's live run (the rail's pulsing
   *  live Bot glyph — the card's Running pill is retired, fix
   *  sidebar-backlog-card-missing-launched-pill task 2). */
  onOpenRun?: (runId: string) => void;
  /**
   * Fire a failure pill's remediation INTENT (delivery-lifecycle-pill-taxonomy
   * F3). The card stays dumb: it derives the intent purely from the pill and
   * fires it here; the HOST owns the POST / navigation (open Runs / open detail
   * / dispatch reconcile / dispatch merge). Absent ⇒ the failure pills still
   * render, but as plain labels (an unwired host — Storybook, read-only shells).
   */
  onRemediate?: (remediation: PillRemediation, row: BoardRow) => void;
  /**
   * Retry a failed launch provisioning (worktree-readiness-commands F8 task 4):
   * re-run the whole setup list from the start. The card stays dumb — it fires
   * this intent with the row; the HOST owns the POST to the re-provision route.
   * Absent ⇒ the Retry control is not rendered (never a dead click).
   */
  onRetryProvisioning?: (row: BoardRow) => void;
  /** RETIRED with the card's Land button (user call, 2026-07-26) — accepted so container wiring keeps compiling, never rendered. */
  onLand?: (row: BoardRow) => void;
  /** RETIRED with the card's Land button — accepted for wiring compatibility, never rendered. */
  landState?: 'landing' | 'error';
}

// Settled-lane echo pills are RETIRED as a class (user call, 2026-07-26): the
// In-review `awaiting land` echo first, the Done `on main` echo with it
// (done-lane-cleanup task 2). Both were static per lane — restating the lane
// header on every card. The lane IS the state; card pills mark exceptions only
// (the stalled/failed sub-status below, cleanup debt).
const SUBSTATUS_PILL: Record<'stalled' | 'failed', { label: string; tone: string }> = {
  stalled: { label: 'stalled', tone: 'tb-pill--stalled' },
  failed: { label: 'run failed', tone: 'tb-pill--red' },
};

/**
 * The failure pill's remediation intent, derived from the SHARED lifecycle phase
 * (fix retire-legacy-deliverypill-from-board-card task 1) so the board card routes
 * off `row.lifecycle`, the one producer the detail panel also reads, instead of
 * the retired `row.deliveryPill`. Only a FAILED delivery-side phase is routable; a
 * running/settled phase (and the `tdd` floor) names no fix to reach and returns
 * null, so the card renders it as a plain, non-interactive label. The crashed-run
 * badge is orthogonal and carries its own {@link RUN_FAILED_REMEDIATION}.
 *
 * NOTE — a deliberate, non-cosmetic consequence of moving off `row.deliveryPill`:
 * `deriveLifecyclePhase` collapses a rebase CONFLICT (`merging`/failed) and a
 * build-failed reconcile (`reconciling`/failed) into ONE `reconciliation`/failed
 * phase (lifecycle-phase.ts), so this coarser vocabulary cannot tell them apart.
 * The legacy `pillRemediation` routed a conflict to the `/merge` hand-off; here
 * BOTH route to `dispatch-reconcile` ("Re-run reconcile"), which now agrees with
 * the "reconcile failed" pill the card already displays (F8) and the detail's
 * Re-check — a re-run surfaces the `/merge` hand-off again if the conflict stands.
 * `merge`/failed therefore never reaches this function (a `merge` phase is only
 * ever `running` — a live land — or `passed`), so that arm names no CTA.
 */
function lifecyclePhaseRemediation(phase: LifecyclePhase | undefined): PillRemediation | null {
  if (phase === undefined || phase.status !== 'failed') return null;
  switch (phase.pipeline) {
    case 'item_completion':
      return { kind: 'open-detail', label: 'Open the item to see the failed steps', placeholder: false };
    case 'reconciliation':
      // Covers a plain build-failed reconcile AND a rebase conflict — the producer
      // folds both to `reconciliation`/failed (see the note above).
      return { kind: 'dispatch-reconcile', label: 'Re-run reconcile', placeholder: false };
    case 'post_merge':
      return { kind: 'post-merge', label: 'Post-merge pipeline UI is not yet built', placeholder: true };
    case 'merge':
    case 'tdd':
    case 'planning':
      // `merge`/failed never occurs (a live land is `running`, a settled one
      // `passed`); the `tdd` floor never emits `failed` (a red test is normal);
      // and `planning` (ADR-0040) is a Backlog, informational phase that never
      // reaches this In-review remediation path. All enumerated so the switch
      // stays exhaustive across LifecyclePipeline.
      return null;
  }
}

export function BoardCard({ row, selected, onSelect, onOpenRun, onRemediate, onRetryProvisioning }: BoardCardProps) {
  const d = derive(row);
  // The In-review Land button is RETIRED (user call, 2026-07-26): landing
  // happens from the detail's Merge cap — the one action home — so the card
  // carries no delivery action. `onLand` / `landState` stay accepted so
  // existing container wiring keeps compiling; they are never rendered.
  // hasFailedRun is the unmasked failed signal — a failed run whose own recent
  // activity masked liveness to 'live' still reads failed here
  // (fix: failed-run-not-surfaced-on-card-and-header).
  const attention =
    row.hasFailedRun || row.liveness === 'failed'
      ? 'failed'
      : row.liveness === 'stalled'
        ? 'stalled'
        : undefined;
  // The delivery-phase pill taxonomy (delivery-lifecycle-pill-taxonomy F2 task
  // 2), replacing the single collapsed `validating` pill: the card renders F1's
  // primary `row.deliveryPill` as a DISTINCT status/failure pill per phase+state
  // — validating / reconciling / merging / validating-on-main, and the failure
  // classes validation-failed / reconcile-failed / merge-failed. IN-REVIEW ONLY
  // (the 2026-08-09 lane ruling the old validating pill kept): Done stays
  // pill-free (settled), backlog / in-progress are unchanged (their phase is
  // `none`). Unlike the old pill this does NOT yield to a failed run — the two
  // are orthogonal (see the badge below): a validation-suite failure is its own
  // named pill, and a crashed run rides beside it, so neither hides the other.
  const delivery = row.lane === 'in-review' ? describeLifecyclePhasePill(row.lifecycle) : null;
  // The ORTHOGONAL crashed-run badge — a run for the item failed and was not
  // resumed. In-review only (where the phase pill lives). Computed here (ahead of
  // its render slot below) because the resting-state cue yields to it: a crashed
  // run already fills the slot with a signal, so pairing "ready to land" beside
  // "run failed" — a contradictory read — is suppressed.
  // The crashed-run signal is the row's own `hasFailedRun` (fix
  // retire-legacy-deliverypill-from-board-card task 1), not the retired
  // `row.deliveryPill.runFailed` — the server folds both from the SAME
  // `runAttachment.failed`, so this is behaviour-identical while dropping the
  // legacy pill read. In-review only (where the phase pill lives).
  const showRunFailedBadge = row.lane === 'in-review' && row.hasFailedRun === true;
  // The in-review "no active phase" cue (fix in-review-card-no-active-phase-
  // indication): when the lifecycle names no ACTIVE pill, the slot would render
  // blank and the card reads as inert. Fill it with the resting-state cue the
  // lifecycle already reports (validation pending / ready to land) — In-review
  // only, only when the active pill is absent (so the two never double up), and
  // not while the crashed-run badge already speaks for the slot.
  const deliveryCue =
    row.lane === 'in-review' && delivery === null && !showRunFailedBadge
      ? describeLifecyclePendingCue(row.lifecycle, row.validation?.reconcile?.reconciledAgainst)
      : null;
  // The failure pill's remediation intent (F3) — pure, table-driven, derived
  // only when a delivery pill actually renders. Now routes off the SHARED
  // lifecycle phase (fix retire-legacy-deliverypill-from-board-card task 1) so
  // board and detail read the one producer; null for a running/settled phase
  // (nothing to route to), so those pills stay plain labels.
  const deliveryRemediation = delivery !== null ? lifecyclePhaseRemediation(row.lifecycle) : null;
  const fireRemediation = onRemediate !== undefined ? (r: PillRemediation) => onRemediate(r, row) : undefined;
  // `showRunFailedBadge` is defined above (it also gates the resting-state cue):
  // the crashed-run badge is In-review only (where the phase pill lives);
  // in-progress / backlog keep their existing `run failed` sub-status pill. It
  // sits BESIDE the phase pill, never in its place (PRD: `run-failed → Runs view,
  // restart`).
  // Backlog joins the failed chrome on the PROJECTED liveness alone (fix
  // failed-dispatch-invisible-on-board-backlog-card, hardened per the
  // adversarial review of 964d8850a): `attention` also reads hasFailedRun,
  // and a fresh dispatch running beside an older unresumed failure carries
  // liveness 'live' + hasFailedRun — the live run leads there (the fold's
  // precedence), so the card must not stack a red "run failed" pill beside
  // the live signal; the stalled pill stays in-progress-only (backlog
  // liveness never carries stalled by fold design).
  const backlogFailed = row.lane === 'backlog' && row.liveness === 'failed';
  // The launched window (fix sidebar-backlog-card-missing-launched-pill): a
  // backlog row with LIVE liveness is a dispatched-but-uncommitted run — the
  // lane stays git-truth backlog until the first commit, so the pill (not a
  // lane move) is what makes the click visibly land. STRICTLY live: a
  // failed-dispatch backlog row is backlogFailed and wears the red pill
  // alone — stacking "launched" beside "run failed" would be a lie. Once the
  // lane says in-progress, the lane is the statement.
  const backlogLaunched = row.lane === 'backlog' && row.liveness === 'live';
  // In-review joins the failed chrome (adversarial review of 8b00952cd): the
  // relocated validating hold lanes a failed completion suite In review, and
  // the failure must not go silent on the card — the failed-run attention
  // survives in the data AND on screen. Stalled remains in-progress-only by
  // fold design (in-review liveness is live/failed via the validation axis).
  const inReviewFailed = row.lane === 'in-review' && attention === 'failed';
  // The ONE input for run attention (MSR rule 4's no-drift clause, fix
  // sidebar-backlog-card-missing-launched-pill task 4): the lanes that
  // surface a failed/stalled run feed BOTH the sub-status pill and the rail's
  // glyph tint from this value, so the words and the colour always read the
  // same state. The shared value unifies the INPUT, not every outcome: with a
  // live run on the row the rail's live glyph outranks the tint
  // (MiniStatusRail: "a LIVE run wins") while the pill still renders — the
  // failure stays legible through a retry. The old pill-only `!validating`
  // conjunct was dead and is dropped: validating requires a non-failed
  // in-review row, while this gate's only in-review arm (inReviewFailed)
  // requires failed — the two can never both hold.
  const surfacedAttention =
    (row.lane === 'in-progress' || inReviewFailed || backlogFailed) && attention ? attention : undefined;
  const subStatus = surfacedAttention !== undefined ? SUBSTATUS_PILL[surfacedAttention] : undefined;

  // The named backlog predicates feed BOTH the pills and the rail (the file's
  // own no-drift rule): an in-progress/in-review lane always rails; a backlog
  // lane rails exactly when launched or failed — an idle backlog row stays
  // rail-less (fixes launched-run-invisible / failed-dispatch-invisible
  // -on-board-backlog-card).
  const showRail =
    row.lane === 'in-progress' || row.lane === 'in-review' || backlogLaunched || backlogFailed;
  const showProgress = row.lane === 'in-progress' && d.progress !== null;
  // The early-lifecycle pill (ADR-0040 / early-lifecycle-phases F5): the item's
  // `planning.running` → "planning" / `planning.passed` → "planned" readiness
  // signal, mapped by the core-pure `describeEarlyPhase`. Backlog-ONLY, mirroring
  // the planning-checks row — the phase refines the Backlog position and is a
  // dispatch-readiness question, so it drops the moment work starts. Null (no
  // earlyPhase, or a non-planning phase) renders nothing.
  const earlyPill =
    row.lane === 'backlog' && row.earlyPhase !== undefined ? describeEarlyPhase(row.earlyPhase) : null;

  // The board glance splits by who produced the work ('board' mode, task 30):
  // an interactive session shows the User glyph and no location; a worker shows
  // the Bot and its local/remote location. The signal is the row's
  // `producingRun` — the run that PRODUCED the work, not a live run — so in-review
  // (awaiting-land) rows read the real provenance instead of the human/local
  // default. A stalled/failed run is NOT signalled on the rail (task 34): the
  // sub-status pill already carries it. The summary's worktree attribution
  // (task 35) rides as a branch ref: interactive-in-worktree reads
  // `[worktree] [user]` — the rail itself hides the chip for a worker.
  const producingRun = row.producingRun;
  const worktree = row.summary.worktree;
  // Narrowed const so the closure below needs no assertion (the PlanFeatureRow
  // pattern: "one narrowed const instead of `!`").
  const activeRunId = row.activeRunId;
  const rail: MiniStatusRailProps = {
    mode: 'board',
    isWorkerRun: producingRun !== undefined,
    where: producingRun?.where ?? 'local',
    workerName: producingRun?.worker,
    workerModel: producingRun?.model,
    branches: worktree !== undefined ? [{ branch: worktree.branch, hasWorktree: true, worktreeName: worktree.name }] : [],
    // The pill's surfacedAttention, verbatim — see the no-drift statement at
    // its definition. No producingRun gate (task 3): the rail splits stalled
    // by worker-ness so interactive work is never misrepresented as a worker
    // Bot; failed always wears the Bot (a failed liveness always originates
    // from a run).
    ...(surfacedAttention !== undefined ? { attentionStatus: surfacedAttention } : {}),
    // A live INTERACTIVE session (MSR rule 2, task 3): live liveness with no
    // producing run and no worker run id means a person's session is driving
    // the item — the rail pulses the User glyph. In-progress ONLY. In-review
    // is excluded because its live liveness rides the validation axis (the
    // 2026-08-09 lane ruling), not a human session; backlog is excluded
    // because a live backlog row without a projected run id may be a dispatch
    // whose run record hasn't landed yet — pulsing the User there would
    // misattribute a worker launch to a person, and the launched pill already
    // owns that window (adversarial review of 88e6d3689).
    interactiveLive:
      row.lane === 'in-progress' &&
      row.liveness === 'live' &&
      producingRun === undefined &&
      activeRunId === undefined,
    // The live-run link (fix: prd-feature-live-run-stream-unreachable task 1,
    // reshaped by sidebar-backlog-card-missing-launched-pill task 2): a live
    // run reads as the rail's pulsing live Bot, which opens the WorkerRun
    // island when a handler is wired. activeRunId passes unconditionally — an
    // unwired host (Storybook, read-only shells) gets the glyph as a
    // glance-only span, which can't eat the card-select click the way the
    // retired Running pill's dead button could. When the live glyph leads,
    // the rail's failed worker-glyph tint intentionally yields
    // (MiniStatusRail: "a LIVE run wins") — same precedence FixCard gets.
    ...(activeRunId !== undefined
      ? { activeRunId, ...(onOpenRun ? { onOpenRun: () => onOpenRun(activeRunId) } : {}) }
      : {}),
  };

  const select = () => onSelect(row);

  return (
    <article data-testid={d.testId} data-selected={selected} className="tb-card">
      {/* The card's PRIMARY action — selecting it — is a real, stretched button
          filling the card behind the content. A native button carries the
          keyboard + screen-reader affordance for free, and keeping it a SIBLING
          of the content (not an ancestor role="button") lets the Land button be a
          valid, independently-focusable control rather than a focusable
          descendant of a button. The body is pointer-events:none so a click
          anywhere on the card lands on this select button; the Land button
          re-enables its own pointer events to sit above. */}
      <button
        type="button"
        data-testid="board-card-select"
        aria-label={`Open ${d.title}`}
        className="tb-card__select"
        onClick={select}
      />

      <div className="tb-card__body">
        <div className="tb-card__tags">
          {/* Each kind wears its own tone so PLAN, SPIKE and FIX cards don't
              read alike in grey: plan bronze, spike teal, fix neutral grey
              (KIND_PILL_TONE). */}
          <span className={cn('tb-pill', KIND_PILL_TONE[row.summary.kind])}>
            {d.kindLabel}
          </span>
          {/* The early-lifecycle pill (ADR-0040 / early-lifecycle-phases F5) — the
              "planning"/"planned" dispatch-readiness signal that ADR-0040 exists to
              provide, so a dispatcher scanning the Backlog can tell a half-shaped
              plan from a dispatch-ready one at a glance. Sits in the tag row next
              to the type badge, at a fixed standard width (`tb-pill--early`), and
              is toned to match the (i) states legend: `planning` bronze
              (`tb-pill--plan`), `planned` blue (`tb-pill--blue`). Backlog-only
              (see `earlyPill`); PRD-only in practice (fix/spike carry no
              earlyPhase). Null renders nothing. */}
          {earlyPill !== null && (
            <span
              className={cn('tb-pill', 'tb-pill--early', earlyPill.label === 'planned' ? 'tb-pill--blue' : 'tb-pill--plan')}
              data-testid="early-phase-pill"
            >
              {earlyPill.label}
            </span>
          )}
          {/* The regression pill (split-land-from-validation F6) leads the row
              and is independent of `subStatus`: main being broken outranks this
              item's own trouble, so a card that ALSO has a failed run wears
              both rather than having the regression crowded out. Exactly one
              card can carry it — an ambiguous verdict lights none, because a
              pill we are not sure of is a lie. */}
          {row.regression === true && <span className="tb-pill tb-pill--red">regression</span>}
          {/* The stalled / run-failed sub-status is the WORKING-lane exception
              (in-progress + backlog). In-review's failure is named by the
              delivery-phase pill below (validation/reconcile/merge failed) plus
              the orthogonal run-failed badge, so the collapsed pill is gated off
              that lane to avoid a duplicate. */}
          {subStatus && row.lane !== 'in-review' && (
            <span className={cn('tb-pill', subStatus.tone)}>{subStatus.label}</span>
          )}
          {/* Launched — the backlog window pill: a run is driving the item,
              nothing has committed yet. Live blue (the launched hue everywhere
              else), never the purple review tone. Reads beside the rail. */}
          {backlogLaunched && <span className="tb-pill tb-pill--live">launched</span>}
          {/* The delivery-phase pill (F2 task 2) — the distinct status/failure
              pill for the item's lifecycle position. In-review only; behind
              regression (main being broken outranks this item's own phase). A
              FAILURE pill is a remediation CTA (F3): it fires its intent; the
              host owns the POST. A running/settled phase (no remediation) stays
              a plain label. */}
          {delivery && (
            <DeliveryPillTag
              label={delivery.label}
              tone={delivery.tone}
              testId={delivery.testId}
              remediation={deliveryRemediation}
              onFire={fireRemediation}
            />
          )}
          {/* The in-review "no active phase" cue (fix in-review-card-no-active-
              phase-indication) — a quiet resting-state chip in the slot the active
              pill would fill, so an in-review card is never inert. Non-interactive
              (nothing to remediate): a plain label, like a running/settled pill. */}
          {deliveryCue && (
            <span className={cn('tb-pill', deliveryCue.tone)} data-testid={deliveryCue.testId}>
              {deliveryCue.label}
            </span>
          )}
          {/* The orthogonal crashed-run badge — rides BESIDE the phase pill, red,
              never in its place. Always a CTA to the Runs view (F3). */}
          {showRunFailedBadge && (
            <DeliveryPillTag
              label="run failed"
              tone="tb-pill--red"
              testId="run-failed-badge"
              remediation={RUN_FAILED_REMEDIATION}
              onFire={fireRemediation}
            />
          )}
          {/* Cleanup debt (done-lane-cleanup task 4): delivery proven, artifacts
              unreaped. An exception pill, not a lane echo — reaped done cards
              wear nothing. Amber: the exception tone freed when stalled moved
              to orange. */}
          {row.cleanup === true && <span className="tb-pill tb-pill--warn">cleanup</span>}
          {showRail && (
            <span className="tb-card__rail">
              <MiniStatusRail {...rail} />
            </span>
          )}
        </div>

        <h3 className="tb-card__title">{d.title}</h3>

        {/* The planning-checks row (readiness-rail-ui F3) — the item's folded
            design-review states. Backlog-ONLY: readiness answers "is this ready
            to dispatch?", a backlog question, so the row rides Backlog cards and
            drops the moment work starts; the detail header keeps the pills for
            the item's whole life. The component renders nothing when the row
            carries no planning states, so a lane check alone gates it. */}
        {row.lane === 'backlog' && <PlanningChecksRow variant="card" checks={row.planning} />}

        {showProgress && <GradientProgress value={d.progress ?? 0} />}

        {/* The validation journey bar (validation-pipeline-visibility F5) — in
            the slot where in-progress cards show their task bar. Gated to the
            COMPLETED-item lanes carrying a summary (In-Review AND Done, fix
            validation-strip-always-shown-when-pipeline-configured task 2): a
            stale or hand-built backlog / in-progress row must never render the
            bar, where it would stack with GradientProgress. On Done the bar
            reads all-passed with a filled diamond. A mono microcopy line names
            the current step, since a 5px bar alone is a riddle at card size. */}
        {(row.lane === 'in-review' || row.lane === 'done') && row.validation !== undefined && (
          <div className="tb-card__journey">
            <JourneyBar model={shapeJourney(row.validation)} />
            <JourneyMeta validation={row.validation} />
          </div>
        )}

        {/* The launch provisioning stage (worktree-readiness-commands F8): a
            "setting up" state while the worktree is made ready, or an
            environment-fault panel when a setup command failed. Rendered on any
            lane the launch run reaches — the server sets the field only while the
            worktree is provisioning or a setup fault stands. */}
        {row.provisioning !== undefined && (
          <ProvisioningPanel
            provisioning={row.provisioning}
            onRetry={onRetryProvisioning !== undefined ? () => onRetryProvisioning(row) : undefined}
          />
        )}

        <div data-testid="card-meta-row" className="tb-card__meta">
          <span>
            {d.metaLeft}
            {d.severity && (
              <>
                {' · '}
                <span className="sev">{d.severity}</span>
              </>
            )}
          </span>
          {d.metaRight !== undefined && <span className="truncate">{d.metaRight}</span>}
        </div>

      </div>
    </article>
  );
}

/**
 * A delivery / run-failure pill (delivery-lifecycle-pill-taxonomy F2 render, F3
 * CTA). Three shapes, one label + tone + testId:
 *   - `remediation === null` — a running/settled status pill: a plain,
 *     non-interactive `<span>` (nothing to route to).
 *   - `remediation.placeholder` — a not-yet-built target (`post-merge-failed`):
 *     a DISABLED button, inert-but-labelled — reads as unavailable, never a
 *     dead-looking-but-clickable span (the "no misleading click" rule).
 *   - otherwise — a routable failure pill: a `<button>` that fires the intent.
 *     `.tb-pill--cta` re-enables pointer events (the card body disables them,
 *     like the retired `.tb-card__land`) so the click lands here, not on the
 *     stretched select button beneath.
 */
function DeliveryPillTag({
  label,
  tone,
  testId,
  remediation,
  onFire,
}: {
  label: string;
  tone: string;
  testId: string;
  remediation: PillRemediation | null;
  onFire?: (remediation: PillRemediation) => void;
}) {
  if (remediation === null) {
    return (
      <span className={cn('tb-pill', tone)} data-testid={testId}>
        {label}
      </span>
    );
  }
  const className = cn('tb-pill', tone, 'tb-pill--cta');
  const ariaLabel = `${label} — ${remediation.label}`;
  if (remediation.placeholder) {
    // Inert but DISCOVERABLE: `aria-disabled` (NOT the native `disabled`
    // attribute) marks it unavailable while keeping it in the tab order, so a
    // keyboard / assistive-tech user can reach and hear the "not yet built"
    // label. It carries no onClick, so activating it dispatches nothing — never
    // a dead or misleading click.
    return (
      <button type="button" className={className} data-testid={testId} aria-disabled="true" title={remediation.label} aria-label={ariaLabel}>
        {label}
      </button>
    );
  }
  return (
    <button
      type="button"
      className={className}
      data-testid={testId}
      title={remediation.label}
      aria-label={ariaLabel}
      onClick={onFire !== undefined ? () => onFire(remediation) : undefined}
    >
      {label}
    </button>
  );
}

/**
 * The launch provisioning panel (worktree-readiness-commands F8) — the item's
 * launch worktree stage on the card. Two shapes:
 *   - `setting-up` — a quiet "Setting up…" status line while the worktree is
 *     made ready.
 *   - `failed-at-step` — an ENVIRONMENT-fault panel: the failed step's label plus
 *     a few expandable lines of its output (collapsed by default). The output
 *     control appears only when the failed command produced a tail.
 */
function ProvisioningPanel({ provisioning, onRetry }: { provisioning: BoardProvisioning; onRetry?: () => void }) {
  if (provisioning.status === 'setting-up') {
    return (
      <p data-testid="card-provisioning" className="tb-card__provisioning">
        {/* The gear is decorative; the visible "Setting up…" text carries the state. */}
        <span aria-hidden="true">⚙</span> <span>Setting up…</span>
      </p>
    );
  }
  return (
    <ProvisioningFault failedStep={provisioning.failedStep} outputTail={provisioning.outputTail} onRetry={onRetry} />
  );
}

/**
 * The environment-fault panel (worktree-readiness-commands F8 tasks 2–3): names
 * the failed setup step and, when the command produced output, offers an
 * expandable few-line tail — collapsed by default so a card stays compact, the
 * output one click away. A controlled disclosure (not native `<details>`) so the
 * collapsed state is deterministic and the tail is absent from the DOM until
 * asked for.
 *
 * Styled as an ENVIRONMENT problem (`is-environment-fault`, the amber warn tone
 * + an "environment" marker), visibly distinct from a code-red failing check: a
 * setup fault says nothing about the item's code, so it must never read like a
 * failed test/validation pill.
 */
function ProvisioningFault({
  failedStep,
  outputTail,
  onRetry,
}: {
  failedStep: string;
  outputTail?: string;
  onRetry?: () => void;
}) {
  const [showOutput, setShowOutput] = useState(false);
  return (
    <div data-testid="card-provisioning" className="tb-card__provisioning is-environment-fault">
      <p className="tb-card__provisioning-head">
        {/* The wrench is decorative (aria-hidden); the visible "Setup failed: …"
            text carries the fault state, announced once. */}
        <span aria-hidden="true">🔧</span> <span>Setup failed: {failedStep}</span>
        {/* The environment marker — names this an environment/setup problem, not a
            code failure, so it reads distinct from a red failing-check pill. */}
        <span className="tb-card__provisioning-kind">environment</span>
      </p>
      {outputTail !== undefined && (
        <>
          <button
            type="button"
            className="tb-card__provisioning-toggle"
            aria-expanded={showOutput}
            onClick={() => setShowOutput((v) => !v)}
          >
            {showOutput ? 'Hide output' : 'Show output'}
          </button>
          {showOutput && (
            <pre data-testid="card-provisioning-output" className="tb-card__provisioning-output">
              {outputTail}
            </pre>
          )}
        </>
      )}
      {/* Retry re-runs the WHOLE setup list from the start — the natural next
          action after the user fixes the repo or edits the readiness config.
          Rendered only when the host wires a handler, so an unwired shell shows
          no dead click; the host owns the POST to the re-provision route. */}
      {onRetry !== undefined && (
        <button type="button" className="tb-card__provisioning-retry" onClick={onRetry}>
          Retry
        </button>
      )}
    </div>
  );
}

/** `118_000 → "1m 58s"`. Computed at render — no per-card interval (the board
 *  re-renders on the run-change SSE, and the pulsing segment carries liveness),
 *  so N cards do not spin N timers. */
function formatCardElapsed(sinceIso: string): string {
  const start = Date.parse(sinceIso);
  if (Number.isNaN(start)) return '';
  const total = Math.max(0, Math.floor((Date.now() - start) / 1000));
  const minutes = Math.floor(total / 60);
  return minutes > 0 ? `${minutes}m ${total % 60}s` : `${total}s`;
}

/** The journey bar's microcopy line: `🧟 mutation testing · 1m 58s` while a step
 *  runs, `✗ mutation testing` when one failed. Renders nothing when the summary
 *  names no current step (all-passed / all-pending). */
function JourneyMeta({ validation }: { validation: NonNullable<BoardRow['validation']> }) {
  const micro = journeyMicrocopy(validation);
  if (micro === undefined) return null;
  if (micro.tone === 'failed') {
    return (
      <p data-testid="card-journey-meta" className="tb-journey__meta is-failed">
        {/* The ✗ is decorative — the sr-only word carries the failed state, so
            AT hears "failed: Mutation Testing", not a bare step name. The JSX
            space text-node keeps the glyph off the label for sighted readers
            ("✗ Test Suite"), the same mechanism as the running branch's spaced
            emoji (never an in-string trailing space, which can be trimmed). */}
        <span aria-hidden="true">✗</span>{' '}
        <span className="sr-only">failed: </span>
        {micro.label}
      </p>
    );
  }
  return (
    <p data-testid="card-journey-meta" className="tb-journey__meta">
      <span aria-hidden="true">{micro.emoji}</span> {micro.label}
      {/* Elapsed rides only a genuine run's start — a config-only preview strip
          (no anchoring run) names its step but shows no clock. */}
      {micro.since !== undefined && <span className="tb-journey__meta-ms"> · {formatCardElapsed(micro.since)}</span>}
    </p>
  );
}

interface Derived {
  // NB `testId` stays `board-card-{prd,fix,spike}` regardless of the display
  // label — it tracks `row.summary.kind`, the projection's wire kind, not the pill
  // wording (a PRD's summary is `kind: 'prd'`, shown as `plan`). Renaming it to
  // follow the label would decouple the test hook from the payload it selects.
  testId: string;
  kindLabel: string;
  /** Severity is rendered as metadata text in the meta line, never a pill. */
  severity?: Fix['severity'];
  title: string;
  progress: number | null;
  metaLeft: string;
  metaRight?: string;
}

// The board's noun for a PRD is `plan` — the thing the /plan skill creates.
// Lowercase, beside the sibling `fix` / `spike` pills. Not the internal "PRD"
// acronym; not "epic"; not "feature" (a plan's features are its parts, not rows).
const KIND_LABEL: Record<BoardCardSummary['kind'], string> = { fix: 'fix', prd: 'plan', spike: 'spike' };

// The kind pill's tone, per kind — so no two kinds read alike in grey. Plans
// wear Radix bronze (`tb-pill--plan`), spikes a dedicated teal
// (`tb-pill--teal`, board-card-pill-and-spacing-polish nit 2), fixes the
// neutral grey kind pill (`tb-pill--kind`).
const KIND_PILL_TONE: Record<BoardCardSummary['kind'], string> = {
  prd: 'tb-pill--plan',
  spike: 'tb-pill--teal',
  fix: 'tb-pill--kind',
};

const taskWord = (n: number): string => (n === 1 ? 'task' : 'tasks');

/** The meta-line left text, from the pre-derived summary counts. */
function metaLeft(s: BoardCardSummary): string {
  if (s.kind === 'spike') {
    return `${s.tasksTotal} ${taskWord(s.tasksTotal)}${s.timebox ? ` · ${s.timebox}` : ''}`;
  }
  // A plan with no tasks yet shows its feature count instead.
  if (s.kind === 'prd' && s.tasksTotal === 0) {
    const fc = s.featureCount ?? 0;
    return `${fc} ${fc === 1 ? 'feature' : 'features'}`;
  }
  // Fixes singularise "task"; a plan with tasks always reads "tasks".
  return `${s.tasksDone}/${s.tasksTotal} ${s.kind === 'fix' ? taskWord(s.tasksTotal) : 'tasks'}`;
}

// The server pre-derives the card's fields (dashboard-landing-perf task 4); the
// client only formats them — the branch/timestamp meta-right and the counts
// string — keeping relative-time client-side (it drifts) but shipping no record.
function derive(row: BoardRow): Derived {
  const s = row.summary;
  return {
    testId: `board-card-${s.kind}`,
    kindLabel: KIND_LABEL[s.kind],
    severity: s.severity,
    title: s.title,
    progress: s.progress,
    metaLeft: metaLeft(s),
    metaRight: s.branch ?? formatRelativeTime(s.timestamp) ?? undefined,
  };
}

export default BoardCard;
