import React, { useEffect, useId, useState } from 'react';
import { Bot, Check, ChevronDown, Cloud, Copy, HardDrive, Loader2, PlaneTakeoff, RotateCcw, Terminal, TriangleAlert } from 'lucide-react';
import { GlyphChip, TwoLineTip } from './glyph-chip';
import { StateChangeButton } from './ui/state-change-button';
import { Skeleton } from './ui/skeleton';

/**
 * The rail's idle-state [Launch ▾] (workers PRD, item-launch-rail
 * tasks 3 + 4): nothing is staffed on this item yet, so the rail offers
 * the two-branch staffing menu instead of empty space.
 *
 * - WORKER branch: pick a dispatchable worker (each row carries the
 *   environment its `worker.environment` resolves to) and POST the
 *   dispatch — the control then transitions to the live worker state
 *   (bot glyph + run id) with the trigger gone, so a second dispatch is
 *   unrepresentable; while a dispatch is starting every row is disabled.
 * - USER branch: "Copy launch command" copies the core-emitted go
 *   string fetched from the item-launch route (never spelled here).
 *
 * Presentational beyond its own lazy fetches: dumb to status/run
 * gating — hosts decide whether to render it at all.
 */
export interface LaunchTarget {
  repoId: string;
  /** The work item as a work-ref slug (fix:x · prd:x/y · spike:x). */
  item: string;
  /**
   * Host-known failure state for this item's latest run (the rail's
   * attentionStatus, passed through). Marks the closed trigger without a
   * fetch — the control itself still fetches nothing until opened.
   *
   * Deliberately a HINT, not the authority: the menu's Continue row comes
   * from the record store via /launch/resumable at open time and wins
   * whenever the two disagree (e.g. the host's projection lags a resume
   * that already happened). The pill draws the eye; the fetch decides.
   */
  attention?: 'failed' | 'stalled';
}

/** One dispatchable worker as the menu consumes it (effort stays server-side). */
interface DispatchableWorker {
  name: string;
  model: string;
  environment: string;
  where: 'local' | 'remote';
}

type DispatchPhase =
  | { phase: 'idle' }
  | { phase: 'starting' }
  // worker: null = a continued run — resumed via the runs route, so no
  // dispatch-time worker row to speak glyphs for.
  | { phase: 'dispatched'; worker: DispatchableWorker | null; runId: string };

/** What GET /launch/resumable projects — the run Continue would resume. */
interface ResumableRun {
  runId: string;
  status: string;
  exitReason?: string;
}

// The trigger skins, as FULL literal class strings (Tailwind's JIT only sees
// complete literals — the accent token must never be interpolated in). The
// `failed` skins wear the shared phase-red failure vocabulary; the idle skins
// wear brand-primary. Cap owns its own tint, so its trigger is plain text; the
// rail trigger is a filled pill.
const TRIGGER_SKIN = {
  capIdle:
    'flex-col gap-1 bg-transparent px-0 py-0 text-xs font-semibold text-[var(--ds-primary,#8b7cf6)] shadow-none enabled:hover:brightness-110',
  capFailed:
    'flex-col gap-1 bg-transparent px-0 py-0 text-xs font-semibold text-[var(--color-phase-red)] shadow-none enabled:hover:brightness-110',
  railIdle:
    'bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_12%,transparent)] text-[var(--ds-primary,#8b7cf6)] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--ds-primary,#8b7cf6)_45%,transparent)] enabled:hover:bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_20%,transparent)]',
  railFailed:
    'bg-[color-mix(in_oklab,var(--color-phase-red)_12%,transparent)] text-[var(--color-phase-red)] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-phase-red)_45%,transparent)] enabled:hover:bg-[color-mix(in_oklab,var(--color-phase-red)_20%,transparent)]',
} as const;

const triggerSkin = (variant: 'rail' | 'cap', failed: boolean): string => {
  if (variant === 'cap') return failed ? TRIGGER_SKIN.capFailed : TRIGGER_SKIN.capIdle;
  return failed ? TRIGGER_SKIN.railFailed : TRIGGER_SKIN.railIdle;
};

const LaunchControl: React.FC<
  LaunchTarget & {
    /**
     * Host geometry (fix launched-state-for-dispatched-runs task 5, folded
     * with the F6 task 4 cap trigger skin per the adversarial review of
     * 0a09ab798 — one fact, one prop). `rail` (default): the pill trigger and
     * the horizontal dispatched run-id + glyph-chip row. `cap`: the end-cap
     * host — plain cap-text trigger (the cap carries the tint), a vertical
     * Launched column with a truncating run id for the transient dispatched
     * state (the rail row overflowed the 6.75rem cap), and a cap-width
     * truncating error line. The dispatched state only spans the sub-tick
     * window before the server's launched projection takes the cap over.
     */
    variant?: 'rail' | 'cap';
  }
> = ({ repoId, item, attention, variant = 'rail' }) => {
  const [open, setOpen] = useState(false);
  const [command, setCommand] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const [copied, setCopied] = useState<'idle' | 'copied' | 'failed'>('idle');
  const [workers, setWorkers] = useState<DispatchableWorker[] | null>(null);
  const [workersFailed, setWorkersFailed] = useState(false);
  const [dispatch, setDispatch] = useState<DispatchPhase>({ phase: 'idle' });
  const [dispatchError, setDispatchError] = useState<string | null>(null);
  // The full failure reason is collapsed by default (endcap-dumps-full-launch-
  // failure-stack): the endcap reads "Launch failed" and the reason — which can
  // be a whole build stack — is revealed on demand, never dumped into the cap.
  const [showFailureDetail, setShowFailureDetail] = useState(false);
  // Stable id linking the Details toggle (aria-controls) to the reason region.
  const failureReasonId = useId();
  const [resumable, setResumable] = useState<ResumableRun | null>(null);

  const base = `/api/repos/${encodeURIComponent(repoId)}/launch`;

  // Fetch lazily on first open — a closed control costs nothing. A failed
  // fetch is NOT terminal: each reopen re-runs the effect and retries, so a
  // transient failure never dead-ends the menu.
  useEffect(() => {
    if (!open || command !== null) return;
    setFailed(false);
    let cancelled = false;
    void (async () => {
      try {
        // This is the "Run yourself in a local worktree" affordance, so the
        // copied command is the --local base — request it explicitly rather
        // than leaning on the route's remote default.
        const res = await fetch(`${base}/command?item=${encodeURIComponent(item)}&where=local`);
        if (!res.ok) {
          if (!cancelled) setFailed(true);
          return;
        }
        const data = (await res.json()) as { command?: string };
        if (cancelled) return;
        if (typeof data.command === 'string') {
          setCommand(data.command);
        } else {
          setFailed(true);
        }
      } catch {
        if (!cancelled) setFailed(true);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, command, base, item]);

  // The Worker branch's rows, fetched the same lazy way. A failed fetch
  // flags an explicit unavailable state (never a stuck "Loading…") and
  // retries on the next open, mirroring the command fetch above.
  useEffect(() => {
    if (!open || workers !== null) return;
    setWorkersFailed(false);
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch(`${base}/workers`);
        if (!res.ok) {
          if (!cancelled) setWorkersFailed(true);
          return;
        }
        const data = (await res.json()) as { workers?: DispatchableWorker[] };
        if (!cancelled) setWorkers(data.workers ?? []);
      } catch {
        if (!cancelled) setWorkersFailed(true);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, workers, base]);

  // Whether this workref has a run to CONTINUE — refetched on every open so
  // a failure that landed while the menu was closed still surfaces. Fail-
  // soft: an unreachable route just means no Continue row, never an error.
  useEffect(() => {
    if (!open) return;
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch(`${base}/resumable?item=${encodeURIComponent(item)}`);
        if (!res.ok) {
          // Clear, don't keep: a stale Continue row from a previous open
          // would 409 on click. No row is honest; it returns next open.
          if (!cancelled) setResumable(null);
          return;
        }
        const data = (await res.json()) as { run?: ResumableRun | null };
        if (!cancelled) setResumable(data.run ?? null);
      } catch {
        // Same fail-soft shape as the non-ok branch — fresh launch stays
        // available, the stale row does not.
        if (!cancelled) setResumable(null);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, base, item]);

  const copy = async (value: string) => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied('copied');
    } catch {
      // Permissions / insecure context — say so instead of silently
      // swallowing the rejection; the command stays visible to select.
      setCopied('failed');
    }
  };

  // Continue the workref's failed run through the EXISTING resume route —
  // same worktree + branch, no fresh dispatch. Shares the dispatch phase so
  // Continue and Relaunch can never race each other.
  const continueRun = async (run: ResumableRun) => {
    if (dispatch.phase !== 'idle') return; // double-dispatch guard
    // Instant feedback: the menu collapses into the Preparing trigger the
    // moment the run is picked — never greyed rows for the length of the POST.
    setOpen(false);
    setDispatch({ phase: 'starting' });
    setDispatchError(null);
    setShowFailureDetail(false);
    try {
      const res = await fetch(
        `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(run.runId)}/resume`,
        { method: 'POST' },
      );
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        setDispatchError(body.error ?? `Continue failed (HTTP ${res.status})`);
        setDispatch({ phase: 'idle' });
        return;
      }
      const data = (await res.json()) as { runId?: string };
      if (typeof data.runId !== 'string') {
        setDispatchError('Continue failed — no run id returned');
        setDispatch({ phase: 'idle' });
        return;
      }
      setDispatch({ phase: 'dispatched', worker: null, runId: data.runId });
    } catch (err) {
      setDispatchError(err instanceof Error ? err.message : 'Continue failed');
      setDispatch({ phase: 'idle' });
    }
  };

  const dispatchWorker = async (worker: DispatchableWorker) => {
    if (dispatch.phase !== 'idle') return; // double-dispatch guard
    setOpen(false); // same instant collapse as continueRun
    setDispatch({ phase: 'starting' });
    setDispatchError(null);
    setShowFailureDetail(false);
    try {
      const res = await fetch(`${base}/dispatch`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ item, workerName: worker.name }),
      });
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        setDispatchError(body.error ?? `Dispatch failed (HTTP ${res.status})`);
        setDispatch({ phase: 'idle' });
        return;
      }
      const data = (await res.json()) as { runId?: string };
      setDispatch({
        phase: 'dispatched',
        worker,
        runId: typeof data.runId === 'string' ? data.runId : 'run pending',
      });
    } catch (err) {
      setDispatchError(err instanceof Error ? err.message : 'Dispatch failed');
      setDispatch({ phase: 'idle' });
    }
  };

  // Dispatched: the control transitions to the live worker state — the rail's
  // glyph language (bot + env + run id) until the server projection takes
  // over on the next data refresh. The trigger is gone: no double-dispatch.
  // A CONTINUED run has no dispatch-time worker (worker: null) — the run id
  // alone carries the state until the projection catches up.
  if (dispatch.phase === 'dispatched') {
    const { worker, runId } = dispatch;
    if (variant === 'cap') {
      // Cap-shaped (task 5): the host column is 6.75rem wide, so the state
      // reads vertically and the run id truncates. No glyph-chip row — the
      // server's launched projection (worker rail + Launched cap) takes over
      // on the next tick and carries the identity properly.
      return (
        <div
          className="flex w-full min-w-0 flex-col items-center gap-1"
          onClick={(e) => e.stopPropagation()}
          data-testid="launch-dispatched"
        >
          <PlaneTakeoff className="h-4 w-4" aria-hidden="true" />
          <span>Launched</span>
          <span className="w-full min-w-0 truncate font-mono text-[10px] text-muted-foreground">{runId}</span>
        </div>
      );
    }
    const EnvIcon = worker?.where === 'remote' ? Cloud : HardDrive;
    return (
      <div
        className="inline-flex items-center gap-1.5"
        onClick={(e) => e.stopPropagation()}
        data-testid="launch-dispatched"
      >
        <span className="font-mono text-[11px] text-muted-foreground">{runId}</span>
        {/* Same shadcn-tooltip glyphs as the MiniStatusRail — worker name over
            model, env name — so the dispatched state speaks the rail's tooltip
            language, not a native title=. */}
        {worker !== null && (
          <>
            <GlyphChip label={worker.name} tooltip={<TwoLineTip title={worker.name} detail={worker.model} />}>
              <Bot className="h-4 w-4" />
            </GlyphChip>
            <GlyphChip label={worker.environment}>
              <EnvIcon className="h-4 w-4" />
            </GlyphChip>
          </>
        )}
      </div>
    );
  }

  return (
    // The control lives inside hosts that may themselves be clickable.
    // Every interaction here must stay inside the control — opening the
    // menu, copying, or dispatching must never also fire the host. The cap
    // variant stacks vertically at cap width so nothing it renders can push
    // the 6.75rem column wide.
    <div
      className={variant === 'cap' ? 'relative flex w-full min-w-0 flex-col items-center' : 'relative inline-flex'}
      onClick={(e) => e.stopPropagation()}
    >
      <StateChangeButton
        data-testid="launch-trigger"
        aria-haspopup="menu"
        aria-expanded={open}
        // A held dispatch error is a first-class trigger state: the control
        // reads "Launch failed" (red glyph + headline) instead of silently
        // returning to Launch, so the one moment the user is watching the
        // control they clicked never renders below glance threshold. It stays
        // clickable — clicking retries by reopening the menu.
        current={
          dispatch.phase === 'starting' ? 'starting' : dispatchError !== null ? 'failed' : 'idle'
        }
        onClick={() => setOpen((v) => !v)}
        states={[
          {
            key: 'idle',
            glyph: <PlaneTakeoff className="h-3 w-3" />,
            caption: (
              <>
                Launch
                {/* The host-known failed/stalled pill (rail attentionStatus
                    passed through) — marks the closed trigger with zero
                    fetches. */}
                {attention !== undefined && (
                  <span className="inline-flex items-center gap-1 rounded-md bg-[color-mix(in_oklab,#ef4444_15%,transparent)] px-1 text-[10px] font-semibold uppercase text-red-500 dark:text-red-300">
                    {attention}
                  </span>
                )}
                <ChevronDown className="h-3 w-3" />
              </>
            ),
          },
          {
            key: 'starting',
            glyph: <Loader2 className="h-3 w-3 animate-spin" />,
            caption: 'Preparing…',
            disabled: true,
          },
          {
            key: 'failed',
            glyph: <TriangleAlert className="h-3 w-3" />,
            caption: (
              <>
                Launch failed
                <ChevronDown className="h-3 w-3" />
              </>
            ),
          },
        ]}
        // A held dispatchError is the failure skin (dispatchError is cleared
        // the instant a new dispatch starts, so this never overlaps Preparing).
        className={triggerSkin(variant, dispatchError !== null)}
      />
      {/* The failure reason lives behind a Details disclosure (endcap-dumps-full-
          launch-failure-stack): the endcap already reads "Launch failed" on the
          trigger, so the reason — which can be a whole build stack — is revealed
          on demand rather than dumped inline. Kept until the next attempt starts
          (reopening must not clear it). */}
      {dispatchError !== null && (
        <div className={variant === 'cap' ? 'mt-1 w-full min-w-0' : 'ml-1.5 self-center'}>
          {/* The UNSOLICITED failure signal: announce that the launch failed the
              moment it does (the visible trigger also switches to "Launch failed",
              so this alert is screen-reader-only to avoid a duplicate line). The
              detailed reason below is user-requested, so it is a region, not an
              assertive alert. */}
          <span role="alert" className="sr-only">
            Launch failed
          </span>
          <button
            type="button"
            onClick={() => setShowFailureDetail((v) => !v)}
            aria-expanded={showFailureDetail}
            aria-controls={failureReasonId}
            aria-label="Show launch failure details"
            title={dispatchError}
            className="inline-flex items-center gap-0.5 text-[11px] leading-snug text-[var(--color-phase-red)] underline-offset-2 hover:underline"
          >
            Details
            <ChevronDown
              className={`h-3 w-3 transition-transform ${showFailureDetail ? 'rotate-180' : ''}`}
            />
          </button>
          {showFailureDetail && (
            <span
              id={failureReasonId}
              role="region"
              aria-label="Launch failure reason"
              className="mt-1 block w-full min-w-0 whitespace-normal break-words text-[11px] leading-snug text-[var(--color-phase-red)]"
            >
              {dispatchError}
            </span>
          )}
        </div>
      )}
      {open && (
        <div
          role="menu"
          aria-label="Staff this item"
          // The CONTRAST surface (bg-background + strong border), fully
          // opaque: the menu floats over raised .panel areas that share the
          // --ds-panel colour, so a panel-coloured (or translucent) popover
          // fades straight into them.
          className="absolute right-0 top-7 z-50 w-[380px] rounded-xl border border-[var(--ds-border-strong)] bg-background p-2 text-left shadow-xl"
        >
          {/* Continue leads (fix failed-run-continue-relaunch task 3): when
              the workref's latest run is resumable, continuing it — same
              worktree + branch — is the default; fresh dispatch is demoted
              to an explicit "Relaunch fresh" below. */}
          {resumable !== null && (
            <>
              <button
                type="button"
                aria-label={`Continue ${resumable.status} run`}
                disabled={dispatch.phase !== 'idle'}
                onClick={() => void continueRun(resumable)}
                className="flex w-full items-center gap-2.5 rounded-lg bg-[color-mix(in_oklab,#ef4444_8%,transparent)] px-2 py-1.5 text-left transition-colors hover:bg-[color-mix(in_oklab,#ef4444_16%,transparent)] disabled:opacity-60"
              >
                <RotateCcw className="h-4 w-4 shrink-0 text-red-500 dark:text-red-300" />
                <span className="min-w-0 flex-1">
                  {/* Named by the run's REAL status — a stalled or cancelled
                      run must not be presented as failed. */}
                  <span className="block truncate text-sm font-semibold leading-tight">
                    {`Continue ${resumable.status} run`}
                  </span>
                  <span className="block truncate font-mono text-[11px] text-muted-foreground">
                    {resumable.runId}
                    {resumable.exitReason !== undefined ? ` — ${resumable.exitReason}` : ''}
                  </span>
                </span>
              </button>
              <div className="my-1.5 border-t border-[var(--ds-border)]" />
            </>
          )}
          {workersFailed ? (
            <p className="px-2 py-1.5 text-xs text-muted-foreground">
              Workers unavailable — reopen to retry.
            </p>
          ) : workers === null ? (
            // In-flight fetch: worker-row-shaped skeletons, not a text flash
            // (loading-text-flash-replace-with-skeletons task 1). The wrapper
            // announces the load; only the bars are decorative.
            <div
              data-testid="launch-workers-skeleton"
              role="status"
              aria-label="Loading workers…"
              className="flex flex-col gap-1.5 px-2 py-1.5"
            >
              <Skeleton aria-hidden className="h-4 w-full" />
              <Skeleton aria-hidden className="h-4 w-3/4" />
            </div>
          ) : workers.length === 0 ? (
            <p className="px-2 py-1.5 text-xs text-muted-foreground">
              No dispatchable workers — create one on the Workers page.
            </p>
          ) : (
            // Grouped by where the work runs: local machine first, then each
            // remote — the user's mental model is the destination, not the
            // worker registry.
            (['local', 'remote'] as const).map((where) => {
              const group = workers.filter((worker) => worker.where === where);
              if (group.length === 0) return null;
              return (
                <React.Fragment key={where}>
                  <p className="eyebrow px-2 pt-1 pb-1 text-[9px] text-muted-foreground">
                    {/* With something to continue, a fresh dispatch orphans the
                        failed run's branch — the label says so explicitly. */}
                    {resumable !== null
                      ? where === 'local'
                        ? 'Relaunch fresh — local worker'
                        : 'Relaunch fresh — remote worker'
                      : where === 'local'
                        ? 'Send to a local worker'
                        : 'Send to a remote worker'}
                  </p>
                  {group.map((worker) => (
                    <button
                      key={worker.name}
                      type="button"
                      aria-label={`Dispatch ${worker.name}`}
                      disabled={dispatch.phase !== 'idle'}
                      onClick={() => void dispatchWorker(worker)}
                      className="flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left transition-colors hover:bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_14%,transparent)] disabled:opacity-60 disabled:hover:bg-transparent"
                    >
                      <Bot className="h-4 w-4 shrink-0 text-muted-foreground" />
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-semibold leading-tight">
                          {worker.name}
                        </span>
                        <span className="block truncate font-mono text-[11px] text-muted-foreground">
                          {worker.model}
                        </span>
                      </span>
                      <span className="eyebrow inline-flex shrink-0 items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_7%,transparent)] px-1.5 py-0.5 text-[10px] text-muted-foreground">
                        {where === 'remote' ? (
                          <Cloud className="h-3 w-3" />
                        ) : (
                          <HardDrive className="h-3 w-3" />
                        )}
                        {worker.environment}
                      </span>
                    </button>
                  ))}
                </React.Fragment>
              );
            })
          )}
          <div className="mt-1.5 border-t border-[var(--ds-border)] pt-1.5">
            <p className="eyebrow px-2 pt-0.5 pb-1 text-[9px] text-muted-foreground">
              Run yourself in a local worktree
            </p>
            {failed ? (
              <p className="px-2 pb-1.5 text-xs text-muted-foreground">
                Launch command unavailable — is the item still tracked?
              </p>
            ) : command === null ? (
              <div
                data-testid="launch-command-skeleton"
                role="status"
                aria-label="Loading launch command…"
                className="px-2 pb-1.5"
              >
                <Skeleton aria-hidden className="h-4 w-full" />
              </div>
            ) : (
              // Mirrors a worker row: leading icon, the launch command as the
              // flex-1 "thing", and the copy action/state as a trailing chip in
              // the env-chip slot — so the WHOLE row is the copy target, not a
              // stray icon. No command echo: it truncates uselessly here and the
              // clipboard gets the full core-emitted string.
              <button
                type="button"
                onClick={() => void copy(command)}
                className="flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left transition-colors hover:bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_14%,transparent)]"
              >
                <Terminal className="h-4 w-4 shrink-0 text-muted-foreground" />
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-semibold leading-tight">
                    Launch command
                  </span>
                  <span className="block truncate font-mono text-[11px] text-muted-foreground">
                    tiny-brain go … --local
                  </span>
                </span>
                <span className="eyebrow inline-flex shrink-0 items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_7%,transparent)] px-1.5 py-0.5 text-[10px] text-muted-foreground">
                  {copied === 'copied' ? (
                    <Check className="h-3 w-3" />
                  ) : (
                    <Copy className="h-3 w-3" />
                  )}
                  {copied === 'copied' ? 'Copied' : 'Copy'}
                </span>
              </button>
            )}
            {copied === 'failed' && (
              <p className="px-2 pb-1 text-[11px] text-muted-foreground">
                Copy failed — select the command text instead
              </p>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default LaunchControl;
