import { useRef, useState } from 'react';
import { Archive } from 'lucide-react';

export interface SpikeParkButtonProps {
  repoId: string;
  spikeId: string;
  /** Called after a successful park (worktree removed, field cleared). */
  onParked?: () => void;
}

type State =
  | { kind: 'idle' }
  | { kind: 'parking' }
  | { kind: 'confirm-force' }
  | { kind: 'error'; message: string };

/**
 * The dashboard half of `tb spike park`: DELETE the worktree endpoint to remove
 * the on-disk worktree and clear the field, KEEPING the branch. A dirty worktree
 * returns 409 — rather than silently discarding uncommitted work, the button
 * prompts an explicit discard-and-park confirm, then retries with ?force=true.
 */
export function SpikeParkButton({ repoId, spikeId, onParked }: SpikeParkButtonProps) {
  const [state, setState] = useState<State>({ kind: 'idle' });
  // Ref guard against a double-DELETE (the endpoint mutates); the disabled
  // attribute only stops a second click after a re-render.
  const inFlightRef = useRef(false);

  const park = async (force: boolean) => {
    if (inFlightRef.current) return;
    inFlightRef.current = true;
    setState({ kind: 'parking' });
    try {
      const url = `/api/repos/${encodeURIComponent(repoId)}/spikes/${encodeURIComponent(spikeId)}/worktree${
        force ? '?force=true' : ''
      }`;
      const res = await fetch(url, { method: 'DELETE' });
      if (res.ok) {
        setState({ kind: 'idle' });
        onParked?.();
        return;
      }
      if (res.status === 409) {
        // Dirty worktree — surface the discard-and-park confirm instead of
        // force-removing uncommitted work behind the user's back.
        setState({ kind: 'confirm-force' });
        return;
      }
      setState({ kind: 'error', message: 'Failed to park the spike worktree.' });
    } catch {
      setState({ kind: 'error', message: 'Failed to park the spike worktree.' });
    } finally {
      inFlightRef.current = false;
    }
  };

  if (state.kind === 'confirm-force') {
    return (
      <div role="alert" className="flex flex-col gap-2 rounded-md border border-amber-300 dark:border-amber-700 bg-amber-50 dark:bg-amber-900/30 p-3 text-amber-900 dark:text-amber-200">
        <p className="text-xs">
          This worktree has uncommitted changes. Parking will discard them (the
          branch is kept). Discard and park?
        </p>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => park(true)}
            aria-label="Discard uncommitted changes and park spike worktree"
            className="w-fit rounded-md border border-amber-400 dark:border-amber-600 bg-amber-200 dark:bg-amber-800 px-2.5 py-1.5 text-xs font-medium text-amber-900 dark:text-amber-100 transition-colors hover:bg-amber-300 dark:hover:bg-amber-700"
          >
            Discard &amp; park
          </button>
          <button
            type="button"
            onClick={() => setState({ kind: 'idle' })}
            className="w-fit rounded-md border border-border px-2.5 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
          >
            Cancel
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-2">
      <button
        type="button"
        onClick={() => park(false)}
        disabled={state.kind === 'parking'}
        aria-label="Park spike worktree"
        className="inline-flex w-fit items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-not-allowed disabled:opacity-50"
      >
        <Archive className="h-3.5 w-3.5" aria-hidden="true" />
        {state.kind === 'parking' ? 'Parking…' : 'Park'}
      </button>
      {state.kind === 'error' && (
        <p role="alert" className="text-xs text-red-700 dark:text-red-300">
          {state.message}
        </p>
      )}
    </div>
  );
}
