import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { ADVERSARIAL_STEP, canonicalStepType, stringToStep } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';
import type { RepoAnalysisFile } from '../types';

/** The subset of a discovered capability the palette builder reads. */
export interface PaletteCapability {
  id: string;
  name: string;
  emoji: string;
  agent: string;
  hasInstallSection: boolean;
}

/** Every configured lane, keyed by role — the input to the active-pipeline fold. */
export interface ActivePipelineLanes {
  commit: PipelineStep[];
  push: PipelineStep[];
  quality: PipelineStep[];
  completion: PipelineStep[];
  postLand: PipelineStep[];
  /** The authoring-time planning gates (deliverability, architecture-alignment). */
  planning: PipelineStep[];
}

/**
 * Fold every configured lane into the single "active pipelines" set the palette
 * builder reads. Each lane contributes its steps in order — INCLUDING `planning`,
 * so the two gate agents surface in the palette alongside adversarial, sourced
 * straight from config. A lane the repo leaves empty contributes nothing. Kept a
 * pure helper (not an inline spread at the call site) so the planning fold is
 * guarded by a unit test rather than only reachable through the DOM.
 */
export function collectActivePipelineSteps(lanes: ActivePipelineLanes): PipelineStep[] {
  return [
    ...lanes.commit,
    ...lanes.push,
    ...lanes.quality,
    ...lanes.completion,
    ...lanes.postLand,
    ...lanes.planning,
  ];
}

export interface PaletteInputs {
  /** The union of the active review / push / quality pipelines. */
  activePipelines: PipelineStep[];
  discoveredCapabilities: PaletteCapability[];
  userInstalledCapabilities: string[];
  installedCapTypes: string[];
  analysis: RepoAnalysisFile | null;
}

/**
 * Derive a pipeline step type from a capability agent name:
 * "tiny-brain:coverage-reviewer" → "coverage".
 */
const deriveStepType = (agent: string): string =>
  agent.replace(/^tiny-brain:/, '').replace(/-reviewer$/, '');

/**
 * Build the `available` step palette the pipeline builder drags from.
 *
 * Extracted verbatim from SetupTab's inline construction so the one behaviour
 * that matters can be unit-tested. The map's LATER `set` wins, which encodes the
 * precedence: built-in seeds first (adversarial, the validation `test`
 * analyser), then a user's active-pipeline step of the same type overrides the
 * seed, then capabilities / installed types / detected analysers fill the rest.
 *
 * The `test` (Test Suite) analyser is seeded from the registry
 * (`stringToStep('test')`) rather than left to the analysis.json loop — that
 * loop builds a bare step with no `runsTests`, and validation IS that analyser,
 * so it must carry the flag the hooks read to skip it during TDD RED. Seeding it
 * early (like adversarial) keeps a user's own configured test step winning.
 */
/**
 * The always-on built-in seeds — surfaced with no config, overridable by a
 * user's own step of the same type. Held apart because they must NOT feed the
 * substring dedup guard below: `test` is a 4-char type that is a substring of
 * real installed types (`testing`, `e2e-test`), and a seed suppressing a
 * distinct analyser it merely spells into would silently drop it from the
 * palette. Only genuinely-configured types dedup installed types.
 */
const SEED_TYPES = new Set(['adversarial', 'test', 'mutation', 'coverage']);

export function buildPipelinePalette(inputs: PaletteInputs): PipelineStep[] {
  const { activePipelines, discoveredCapabilities, userInstalledCapabilities, installedCapTypes, analysis } = inputs;

  const stepMap = new Map<string, PipelineStep>();
  // Always-available built-in seeds. Set before the active pipelines so a
  // user's configured step of the same type overrides the default.
  stepMap.set('adversarial', ADVERSARIAL_STEP);
  stepMap.set('test', stringToStep('test'));
  // mutation and coverage are registered runsTests analysers whose only lifecycle
  // home is the completion (Work item) stage — seed them so they are always
  // draggable, exactly like the validation `test` analyser. A user's configured
  // step of the same type overrides these below.
  stepMap.set('mutation', stringToStep('mutation'));
  stepMap.set('coverage', stringToStep('coverage'));

  // Steps from active pipelines.
  for (const step of activePipelines) {
    stepMap.set(step.type, step);
  }

  // Steps from installed capabilities only (pre-installed or user-installed).
  const installedSet = new Set([
    ...userInstalledCapabilities,
    ...discoveredCapabilities.filter(c => !c.hasInstallSection).map(c => canonicalStepType(c.id)),
  ]);
  for (const cap of discoveredCapabilities) {
    const derivedType = deriveStepType(cap.agent);
    if (installedSet.has(canonicalStepType(cap.id)) && !stepMap.has(cap.id) && !stepMap.has(derivedType)) {
      stepMap.set(cap.id, { type: cap.id, agent: cap.agent, label: cap.name, emoji: cap.emoji });
    }
  }

  // Steps from installed types (may not have metadata — use sensible defaults).
  // The substring guard dedups an installed type against an existing one it
  // extends (e.g. skip `code-coverage` when `coverage` exists), but the seeds
  // are excluded from it — see SEED_TYPES — so `test` never suppresses `testing`.
  const existingTypes = [...stepMap.keys()].filter(key => !SEED_TYPES.has(key));
  for (const t of [...installedCapTypes, ...userInstalledCapabilities]) {
    // Dedup an installed ALIAS against its canonical seed (mutation-testing →
    // mutation, code-coverage → coverage) so a seed in SEED_TYPES — excluded from
    // the substring guard — still absorbs its own alias instead of duplicating it.
    if (!stepMap.has(t) && !stepMap.has(canonicalStepType(t)) && !existingTypes.some(key => t.includes(key))) {
      stepMap.set(t, { type: t, agent: `tiny-brain:${t}-reviewer`, label: t, emoji: '\u{1F50D}' });
    }
  }

  // Steps from detected analyzers (from analysis.json).
  if (analysis?.analyzers) {
    for (const analyzer of analysis.analyzers) {
      if (!stepMap.has(analyzer.id)) {
        stepMap.set(analyzer.id, {
          type: analyzer.id,
          agent: 'tiny-brain:analyzer-agent',
          label: analyzer.name,
          emoji: analyzer.emoji ?? '\u{1F4CA}', // 📊
          color: analyzer.color,
          analyzer: analyzer.id,
        });
      }
    }
  }

  return [...stepMap.values()];
}
