import type { FeatureProvenanceView, ProvenanceCounts, WorkItemProvenance } from '@magic-ingredients/tiny-brain-core';

/** Stable empty covered-set — a fresh [] every render would defeat memo/prop identity. */
const NO_FEATURE_CLEANUP: ReadonlyMap<string, readonly string[]> = new Map();
const NO_COVERED_BRANCHES: readonly string[] = [];

interface PlanDetailsPRDProps {
  plan: Plan;
  repoId?: string;
  /** Archive/unarchive the plan — wired to the header action. */
  onArchive?: () => void;
  onUnarchive?: () => void;
  /** Open the WorkerRun island for a feature's live run (rail pill click). */
  onOpenRun?: (runId: string) => void;
  /**
   * The board row's server-attributed cleanup branches (fix
   * prd-cleanup-pill-not-attributed-to-features task 1): the live typed
   * branches that tripped the container's cleanup pill. Consumed by the
   * feature cleanup fold in task 2.
   */
  serverCleanupBranches?: readonly string[];
  /**
   * The board row's provenance SEED (fix board-detail-provenance-not-seeded-
   * from-summary): one seed feature per real feature id carrying the container
   * who the board card already showed. The feature rows read it for the who
   * glyph while the per-item provenance fetch is still in flight, so the glyph
   * no longer flashes empty on selection. The container-level reads (the
   * resolved-% readout, cleanup folds) stay on the FETCHED `provenance` so the
   * seed — which has no per-feature landed/counts — can never regress them.
   */
  provenanceSeed?: WorkItemProvenance;
  /**
   * The server-composed delivery-worktree rows, forwarded to each feature row so
   * an expanded FeatureDetail resolves its branch's LIVE reconcile run and reaches
   * true parity with FixDetail (fix feature-detail-live-reconcile-parity).
   */
  deliveryWorktrees?: readonly { branch: string; model: { liveReconcileRunId?: string } }[];
}

// The header-action button skin (shared with the legacy header's cluster).
const headerActionClass =
  'inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground';

// Per-plan storage for the feature accordion's open set. Feature open/closed is
// view-local layout — it lives in localStorage keyed by prdId, never the URL, so
// each PRD remembers its own open features across reloads.
const featuresStorageKey = (prdId: string | undefined): string | null =>
  prdId ? `tiny-brain:plan:${prdId}:expandedFeatures` : null;

const readExpandedFeatures = (prdId: string | undefined): Set<number> | null => {
  const key = featuresStorageKey(prdId);
  if (!key) return null;
  try {
    const raw = window.localStorage.getItem(key);
    if (raw === null) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed)
      ? new Set(parsed.filter((n): n is number => typeof n === 'number'))
      : null;
  } catch {
    return null;
  }
};

const PlanDetailsPRD: React.FC<PlanDetailsPRDProps> = ({ plan, repoId, onArchive, onUnarchive, onOpenRun, serverCleanupBranches, provenanceSeed, deliveryWorktrees }) => {
  const [expandedFeatures, setExpandedFeatures] = useState<Set<number>>(
    () => readExpandedFeatures(plan.prdId) ?? new Set(),
  );
  const [supersededExpanded, setSupersededExpanded] = useState(false);
  // The Source sheet (fix: prd-source-not-viewable) — raw prd.md / feature
  // markdown behind the utility row's Source action. The picker list is
  // memoised so the sheet's prop identity survives unrelated re-renders.
  const [sourceOpen, setSourceOpen] = useState(false);
  const sourceFeatures = useMemo(
    () => (plan.features ?? []).map((f) => ({ id: f.id, title: f.title })),
    [plan.features],
  );
  // Mock §01 group defaults: fresh work is collapsed, live work is open.
  const [notStartedOpen, setNotStartedOpen] = useState(false);
  const [inProgressOpen, setInProgressOpen] = useState(true);
  // `null` = follow the In-Review default (expanded); a boolean = the user's own
  // choice, which then wins over the default until they navigate away.
  const [completedExpanded, setCompletedExpanded] = useState<boolean | null>(null);
  const [, setSearchParams] = useSearchParams();

  // Open the design-assets view (surface-design-assets F3) as a mode of THIS
  // PRD — the PRD is already the selected item, so `?assets` is a bare marker;
  // the F4 view reads kind + slug from the active area + selected item. The
  // header shows the Assets action only when the PRD actually has assets.
  const openAssets = () => {
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('assets', '');
      return next;
    });
  };

  const persistExpanded = (next: Set<number>) => {
    const key = featuresStorageKey(plan.prdId);
    if (!key) return;
    try {
      window.localStorage.setItem(key, JSON.stringify([...next]));
    } catch {
      // Storage unavailable (private mode / quota) — open state just won't persist.
    }
  };

  const toggleFeature = (featureNumber: number) => {
    // Derive the next set from the current render's value (this is a user event
    // handler, so it's up to date) and keep the state updater pure — persistence
    // is a side effect that belongs outside it.
    const next = new Set(expandedFeatures);
    if (next.has(featureNumber)) {
      next.delete(featureNumber);
    } else {
      next.add(featureNumber);
    }
    setExpandedFeatures(next);
    persistExpanded(next);
  };

  // Extract features from plan
  const features = useMemo(() => plan.features || [], [plan.features]);

  // The ONE feature land in flight (fix feature-land-has-no-live-feedback):
  // its feature id pins the row's pending Merging… cap AND the row's status-
  // group classification (task 3 — captured as `rollup` at dispatch); its
  // branch (the feature's delivered `where`, when known) keys the
  // ReconcileStrip. Declared above the partition so the pin can feed it.
  const [landingFeature, setLandingFeature] = useState<{
    featureId: string;
    branch?: string;
    rollup: ReturnType<typeof deriveTasksEffectiveStatus>;
  } | null>(null);
  // The provenance refresh tick — bumped on the land run's terminal (the
  // FixDetail deliveryRefreshTick pattern) so the snapshot re-syncs with the
  // just-persisted verdict.
  const [provTick, setProvTick] = useState(0);
  // The streamed delivery fold (the FixDetail wiring, keyed by the landing
  // feature's branch): the land POST resolves {runId}, the run stream feeds
  // the fold, and the strip renders the live phases + the typed terminal.
  const delivery = useDeliveryActions(repoId ?? '', landingFeature?.branch ?? '', {
    onSuccess: () => setProvTick((t) => t + 1),
  });
  // The row whose cap pins to Merging… — only while the land run is genuinely
  // in flight (POST or stream); a terminal drops the pin and the refetched
  // provenance settles the row.
  const landingFeatureId = delivery.busy && landingFeature !== null ? landingFeature.featureId : undefined;

  // Terminal features leave the live accordion for their own collapsed
  // sections — Completed (task 39) beside the existing Superseded (plans-console
  // task 5) — so open work reads uncluttered and history expands on demand.
  // The four-way bucket (detail-provenance-restyle task 2 — mock §01) reads the
  // pulse-aware worktree-effective rollup (the same status the feature header
  // shows). Features are sorted numerically FIRST, so every group renders its
  // rows in numeric order.
  const { notStartedFeatures, inProgressFeatures, completedFeatures, supersededFeatures } = useMemo(() => {
    const notStartedFeatures: typeof features = [];
    const inProgressFeatures: typeof features = [];
    const completedFeatures: typeof features = [];
    const supersededFeatures: typeof features = [];
    for (const feature of [...features].sort((a, b) => a.number - b.number)) {
      // A LIVE land run pins the landing row's classification at its
      // dispatch-time value (fix feature-land-has-no-live-feedback task 3):
      // the reconcile touches the branch mid-run and the reprojection would
      // otherwise move — or vanish — the one row carrying the Merging… state.
      // Only the run's terminal drops the pin; the next derivation then moves
      // the row exactly once.
      const rollup =
        landingFeatureId !== undefined && landingFeature !== null && feature.id === landingFeatureId
          ? landingFeature.rollup
          : deriveTasksEffectiveStatus(feature.tasks ?? []);
      const bucket =
        rollup === 'superseded'
          ? supersededFeatures
          : rollup === 'completed'
            ? completedFeatures
            : rollup === 'not_started'
              ? notStartedFeatures
              : inProgressFeatures;
      bucket.push(feature);
    }
    return { notStartedFeatures, inProgressFeatures, completedFeatures, supersededFeatures };
  }, [features, landingFeatureId, landingFeature]);

  // The active (in-progress) feature, derived once — it's both the auto-expand
  // target and the scroll target on load. First of the in-progress group (the
  // same worktree-aware effective status the partition uses), so a terminal
  // feature is never chosen.
  const activeFeature = inProgressFeatures[0] ?? null;

  // Load the open set for this plan: a stored (user-chosen) set wins; otherwise
  // fall back to auto-expanding the active feature. Keyed on prdId so switching
  // plans re-syncs to the right stored set.
  React.useEffect(() => {
    const stored = readExpandedFeatures(plan.prdId);
    if (stored !== null) {
      setExpandedFeatures(stored);
      return;
    }
    setExpandedFeatures(activeFeature ? new Set([activeFeature.number]) : new Set());
  }, [plan.prdId, activeFeature]);

  // Scroll the active feature into view on load. Its expanded body holds the
  // current task, so `block: 'start'` lands the eye on the live work (not just
  // the row's edge) when resuming a deep route.
  const scrollTargetRef = React.useRef<HTMLDivElement | null>(null);
  React.useEffect(() => {
    if (activeFeature) {
      // Optional-chain the method too: jsdom (and SSR) have no scrollIntoView.
      scrollTargetRef.current?.scrollIntoView?.({ block: 'start', behavior: 'smooth' });
    }
  }, [activeFeature, plan.prdId]);

  // The configured review pipeline drives the header legend (and the per-task
  // chips inside FeatureDetail read it themselves) — not a hardcoded list.
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId || '');

  // The work item's delivered provenance (work-item-provenance F4) — per-feature
  // where/who/landed, keyed by feature id so each section row reads its own.
  // Keyed on the live plan payload: each reprojection re-syncs the provenance
  // snapshot, so the feature partition and the delivery facts can't drift.
  // The tick re-syncs after a streamed feature land's terminal (the FixDetail
  // deliveryRefreshTick pattern) — the run persisted the verdict server-side.
  const provenanceRefreshKey = useMemo(() => ({ plan, provTick }), [plan, provTick]);
  const { provenance, loading: provenanceLoading } = useWorkItemProvenance(
    repoId,
    'prd',
    plan.prdId,
    provenanceRefreshKey,
  );
  // The per-feature views the rows render their who glyph from: the FETCHED
  // payload once it lands, else the board row's SEED (fix board-detail-
  // provenance-not-seeded-from-summary) so the feature rows show the container
  // who the card already displayed instead of an empty flash. Only the who axis
  // is seeded — the seed carries no per-feature landed/counts — and the fetch
  // replaces the whole map in place the moment it resolves; the container reads
  // below (resolved %, cleanup) deliberately stay on `provenance`, never this.
  // Seed the who ONLY until the fetch lands: once `provenance` is present the
  // seed is inert, so its (rebuilt-every-parent-render) identity is dropped from
  // the deps here — otherwise the fetched map, and the whole cleanup/distribution
  // memo cascade below, would recompute on every unrelated render (the
  // NO_FEATURE_CLEANUP hazard). While loading, the seed's churn recomputes only
  // this cheap map.
  const seedFeatures = provenance === null ? provenanceSeed?.features ?? null : null;
  const provenanceByFeature = useMemo<ReadonlyMap<string, FeatureProvenanceView>>(
    () => new Map((provenance?.features ?? seedFeatures ?? []).map((f) => [f.featureId, f])),
    [provenance, seedFeatures],
  );
  // The endcap settling fact (fix endcap-resumes-pipeline-runs task 2): FIRST
  // load only — the hook keeps the previous snapshot while the SSE-bumped
  // refresh key refetches, so a settled row must never blank back to "…". A
  // single derived boolean threads through FeatureStatusGroup, mirroring how
  // the group already receives the per-feature provenance views rather than
  // the raw payload.
  const provenanceSettling = provenanceLoading && provenance === null;
  // Reserve the distribution row on first paint (fix prd-detail-skeletons-
  // stabilize-layout task 1): while settling, the counts rail is the primary
  // judder — it inserts on resolve and shoves the feature groups down. Render a
  // same-height skeleton in its slot instead of nothing, but only when there are
  // features to distribute (a zero-feature scope draws no rail settled either,
  // so reserving one would itself be a shift). First-load only, so a background
  // refetch never blanks the settled rail back to a skeleton.
  const showDistributionSkeleton = provenanceSettling && features.length > 0;

  // The pulse-aware plan status the header shows AND the In-Review derivation
  // read — computed once so the two can't drift.
  const planStatus = derivePlanEffectiveStatus(plan);

  // The shared-worktree Cleanup collapse (done-lane-cleanup task 5, reworked
  // by fix prd-cleanup-row-keys-dead-attribution-branch): when EVERY live
  // feature landed AND a live shared branch is PROVEN by the lattice, the
  // single CleanupCommand row above the features owns the cleanup and the
  // Completed rows' caps go inert. The row keys the WORK ITEM — the server
  // resolves the branch, so a dead attribution stamp can never 500 it.
  // Computed as the intersection FOLD (task 2): its non-emptiness is the
  // collapse gate AND its members are the suppression key, one computation
  // for both (adversarial review of 657495936).
  const sharedCleanupBranches = useMemo(
    () =>
      sharedLiveCleanupBranches(features, (id) => provenanceByFeature.get(id)?.delivery.landed === true),
    [features, provenanceByFeature],
  );
  const cleanupCollapsed = sharedCleanupBranches.length > 0;
  // ONE gate drives both the row and the cap suppression (adversarial review
  // of 9e615a030, MEDIUM): a collapse that cannot render its row (no repoId /
  // prdId) must not orphan the cleanup by muting the per-feature caps.
  const showCleanupRow = Boolean(repoId && plan.prdId && cleanupCollapsed);
  // The mixed-branch case (fix prd-cleanup-rows-not-attributed-to-features):
  // when the shared collapse does NOT fire, cleanup is attributed PER FEATURE
  // — nothing stacks above the feature list. Stacked branch-keyed rows
  // carried no feature attribution and fetched every manifest on mount
  // (unusable on many-branch PRDs; observed live on `workers`, 2026-07-27).
  // Each landed live feature OWNS the branches its finished work sits on
  // (first owner in feature order wins a shared branch — the fold's caller
  // contract holds: `features` is the markdown display order every surface
  // renders); the owning row wears the pill and mounts the branch-keyed
  // CleanupCommand only on expand. Gated on repoId — the row's commands and
  // pills key the repo-scoped manifest routes.
  const featureCleanupBranches = useMemo(
    () =>
      !cleanupCollapsed && repoId
        ? deriveFeatureCleanupBranches(
            features,
            (id) => provenanceByFeature.get(id)?.delivery.landed === true,
            // The board row's server-attributed branches (fix prd-cleanup-
            // pill-not-attributed-to-features task 2) — corroborates the
            // container pill at feature level when the lattice yields nothing.
            plan.prdId && serverCleanupBranches !== undefined
              ? { prdId: plan.prdId, branches: serverCleanupBranches }
              : undefined,
          )
        : NO_FEATURE_CLEANUP,
    [cleanupCollapsed, repoId, features, provenanceByFeature, plan.prdId, serverCleanupBranches],
  );
  // The branches a rendered cleanup affordance covers — the suppression key.
  // Suppression must never outrun a rendered owner (adversarial review of
  // dc9b52698, HIGH — the invariant from 9e615a030): the shared prd-keyed
  // row covers exactly its intersection fold; the mixed case covers the
  // branches the per-feature rows own PLUS the protected active workspaces
  // (adversarial review of 2590d297b, HIGH + user report on `workers`,
  // 2026-07-27). A protected branch is some live feature's — or, via
  // reachability cells, some other work item's — running workspace: it is
  // not cleanup, and leaving it "uncovered" would re-arm the endcap's
  // Delete-worktree re-targeting against it. Covered ⇒ either an in-row
  // command offers the teardown (owned) or nothing may (protected).
  const coveredCleanupBranches = useMemo(() => {
    if (showCleanupRow) return sharedCleanupBranches;
    if (!repoId || cleanupCollapsed) return NO_COVERED_BRANCHES;
    const isLanded = (id: string) => provenanceByFeature.get(id)?.delivery.landed === true;
    return [
      ...new Set([...[...featureCleanupBranches.values()].flat(), ...protectedWorkspaceBranches(features, isLanded)]),
    ].sort();
  }, [showCleanupRow, sharedCleanupBranches, repoId, cleanupCollapsed, featureCleanupBranches, features, provenanceByFeature]);

  // The count rail states FEATURE counts (user call, 2026-07-24): it sits
  // directly above the feature status groups, so it is single-sourced from the
  // SAME partition that renders them — the rail and the group headers can
  // never disagree. The Completed umbrella splits by each feature's delivered
  // fact (landed ⇒ Merged, else Done); the task axis lives in the
  // Tasks-resolved bar above.
  const featureDistribution = useMemo<ProvenanceCounts>(() => {
    const merged = completedFeatures.filter(
      (f) => provenanceByFeature.get(f.id)?.delivery.landed === true,
    ).length;
    return {
      total: features.length,
      notStarted: notStartedFeatures.length,
      inProgress: inProgressFeatures.length,
      done: completedFeatures.length - merged,
      merged,
      superseded: supersededFeatures.length,
    };
  }, [features, notStartedFeatures, inProgressFeatures, completedFeatures, supersededFeatures, provenanceByFeature]);

  // The compact headline bars' percentages (F10 task 1). Once the provenance
  // payload arrives, Tasks-resolved reads the SAME counts as the distribution
  // beneath it — one source, so the % can never contradict the row below.
  // derivePlanStats only bridges the pre-load frame (and Features built, which
  // has no task-level counts equivalent).
  const planStats = useMemo(() => derivePlanStats(features), [features]);
  const resolvedPct =
    provenance !== null ? resolvedPctFromCounts(provenance.counts) : tasksResolvedReadout(planStats);

  // In-Review presentation (F4 task 3). "Done but not merged" work — completed
  // tasks not yet landed on main — is the whole reason to open a completed item.
  // An In-Review card (the whole PRD done, some work still unmerged) surfaces its
  // Completed section inline rather than collapsed, AND offers a link to the merge
  // details island. Both key on `isInReview`, not `hasUnmergedDone` alone, so a
  // still-in-progress PRD that happens to carry a completed-but-unmerged feature
  // keeps that feature in the collapsed section with no premature "act on it"
  // prompt. A fully-merged PRD has zero `done`, so it is never In-Review.
  const hasUnmergedDone = (provenance?.counts.done ?? 0) > 0;
  const isInReview = planStatus === 'completed' && hasUnmergedDone;

  // The end-cap actions (detail-action-endcap task 2): the rows fire ids, this
  // host POSTs to the on-main routes — /delivery/land-feature (F5 t1), the
  // branch-keyed /delivery/teardown (F5 t2), /runs/:runId/resume (the same
  // route Launch's Continue posts). Non-landed land outcomes surface as the
  // F5-style notice; the reprojection-keyed provenance refetch settles the row
  // after a successful action. Wired only in a repo scope with a real prd id.
  const [endcapNotice, setEndcapNotice] = useState<string | null>(null);
  // Const capture: property narrowing doesn't survive into the callbacks.
  const endcapPrdId = plan.prdId;
  const endcapActions =
    repoId && endcapPrdId
      ? {
          onLandFeature: (featureId: string, method: 'ff-only' | 'merge') => {
            // The Merge cap is a chooser (fix merge-cap-lacks-method-and-pr-
            // choice): forward the picked method to the streamed per-feature
            // land — the outcome rides the run stream, never this handler.
            // ONE fold, one land at a time (adversarial review of 1f5170911,
            // LOW): a second feature's Merge while a land streams would
            // silently abandon the first run's fold, so it is ignored — the
            // landing row's own cap is already pinned to Merging….
            if (delivery.busy) return;
            setEndcapNotice(null);
            const where = provenanceByFeature.get(featureId)?.delivery.where;
            const branch = where?.kind === 'branch' ? where.branch : undefined;
            // Capture the row's classification at dispatch — the partition's
            // pin holds the row there for the whole land (task 3).
            const rollup = deriveTasksEffectiveStatus(
              features.find((f) => f.id === featureId)?.tasks ?? [],
            );
            setLandingFeature({ featureId, rollup, ...(branch !== undefined ? { branch } : {}) });
            delivery.onLandFeature(endcapPrdId, featureId, method);
          },
          onRaiseFeature: (featureId: string) => {
            // Raise PR… for one feature (fix merge-cap-lacks-method-and-pr-
            // choice task 2): the existing /delivery/raise keyed by the
            // feature's own branch (its delivered `where`), title prefilled
            // from the feature. The PR url — or the honest refusal — surfaces
            // through the shared notice channel.
            const where = provenanceByFeature.get(featureId)?.delivery.where;
            const branch = where?.kind === 'branch' ? where.branch : undefined;
            if (branch === undefined) {
              // Non-retryable: no branch to open a PR from (adversarial review
              // of 6683b2c84 — honest copy, not the retryable failure).
              setEndcapNotice(RAISE_NO_BRANCH_NOTICE);
              return;
            }
            const title = features.find((f) => f.id === featureId)?.title ?? featureId;
            setEndcapNotice(null);
            void postDeliveryRaise(repoId, branch, title, title)
              .then((result) => setEndcapNotice(raiseOutcomeNotice(result)))
              .catch(() => setEndcapNotice(RAISE_FAILED_NOTICE));
          },
          onTeardownFeature: (branch: string) => {
            setEndcapNotice(null);
            // No runIds: the row's worktree fact carries only the branch (run
            // records ride the F5 island's richer model, not this cap).
            void postDeliveryAction(repoId, 'teardown', {
              workItemId: branch,
              worktree: true,
              branch: true,
            }).catch(() => setEndcapNotice(TEARDOWN_FAILED_NOTICE));
          },
          onResumeRun: (runId: string) => {
            setEndcapNotice(null);
            void postRunResume(repoId, runId).catch(() => setEndcapNotice(RESUME_FAILED_NOTICE));
          },
          onContinueFeature: (featureId: string) => {
            // Continue parked work (fix incomplete-item-with-completed-run-
            // cannot-relaunch): the server resolves the feature's latest
            // continuable run and relaunches onto its existing worktree.
            setEndcapNotice(null);
            void postLaunchContinue(repoId, `prd:${endcapPrdId}/${featureId}`).catch(() =>
              setEndcapNotice(CONTINUE_FAILED_NOTICE),
            );
          },
        }
      : undefined;
  const completedOpen = completedExpanded ?? isInReview;
  // Whether the strip has a surface to own the streamed terminal — it is
  // keyed by the landing feature's branch, which a branchless (`to-do`)
  // delivered-where cannot supply.
  const stripVisible = landingFeature?.branch !== undefined;
  // A BRANCHLESS land's stream terminal (adversarial review of 1f5170911,
  // MEDIUM): with no strip rendered, the hook's strip-ownership gate would
  // otherwise swallow the failure entirely — so the banner carries the
  // outcome-mapped notice exactly when no strip surface exists. ready-to-land
  // never fires here (a landed run streams no terminal frame).
  const branchlessLandNotice = (() => {
    if (stripVisible || landingFeature === null) return null;
    const r = delivery.reconcile;
    if (r.kind !== 'terminal' || r.source !== 'stream' || r.terminal === 'ready-to-land') return null;
    return r.terminal === 'conflict' ? LAND_FEATURE_NOTICES.conflicts : LAND_FEATURE_NOTICES.failed;
  })();
  // One notice slot, terminal-only rendering: a synchronous action's fault
  // (endcapNotice), the streamed land failure the strip does NOT own (a POST
  // fault before any run started), or the branchless fallback above. A
  // stream-settled terminal WITH a strip renders there — never restated here.
  const stripNotice = endcapNotice ?? delivery.landFailure ?? branchlessLandNotice ?? null;
  // After a COMPLETED land the strip has nothing to render (a landed run
  // streams no terminal frame) and the refetched provenance settles the row —
  // drop the stale branch keying (adversarial review of 1f5170911, LOW). A
  // conflict/failed terminal keeps it: the strip's hand-off + Re-check stay
  // keyed by the branch until a new action supersedes them.
  React.useEffect(() => {
    if (landingFeature !== null && !delivery.busy && delivery.reconcile.kind === 'idle' && !delivery.landError) {
      setLandingFeature(null);
    }
  }, [landingFeature, delivery.busy, delivery.reconcile.kind, delivery.landError]);
  // The read-only provenance island's entry (F6 task 3): each STARTED row's
  // Show details opens `?island=<branch>` — the header's "Merge details" link
  // is retired (the header only ever carries Running / attention / Launch).
  const openBranchIsland = (branch: string) =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('island', branch);
      return next;
    });

  return (
    <div className="h-full flex flex-col">
      {/* The whole main section scrolls as one (consistent with FixDetail and
          SpikeDetail) — no fixed KPI rail, no collapse-on-scroll header. */}
      <div
        data-testid="plan-detail-scroll"
        className="flex-1 overflow-y-auto px-7 py-6 space-y-4"
      >
        {/* Plan detail header (UI Refresh): status eyebrow + title + copy-id
            only — no subtitle line (user call, 2026-07-24); the actions moved
            onto the legend row below. Lives inside the scroll region so the
            whole section scrolls as one (matching FixDetail). */}
        <PlanDetailHeader
          {...planHeaderPropsFromPlan(plan)}
          status={planStatus}
          repoId={repoId}
          showMeta={false}
        />

        {/* One utility row: the item actions (Assets · Archive) LHS, the
            per-task pipeline legend RHS — ONCE at item level (user call,
            2026-07-24), never restated per feature or per group. */}
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-1">
            {/* Source needs a repo scope to fetch from — no dead button (and no
                permanently-failing sheet) in repo-less read-only shells. */}
            {repoId && (
              <button
                type="button"
                onClick={() => setSourceOpen(true)}
                aria-label="View plan source"
                className={headerActionClass}
              >
                <FileCode className="h-3.5 w-3.5" /> Source
              </button>
            )}
            {plan.hasAssets && (
              <button type="button" onClick={openAssets} aria-label="View plan assets" className={headerActionClass}>
                <Images className="h-3.5 w-3.5" /> Assets
              </button>
            )}
            {/* Unarchive stays immediate (restoring is the undo). Archive is a
                deliberate state change (fix archive-button-no-confirmation): its
                button opens an AlertDialog and onArchive fires only on confirm. */}
            {plan.type === 'archived' ? (
              onUnarchive && (
                <button
                  type="button"
                  onClick={onUnarchive}
                  aria-label="Unarchive"
                  className={headerActionClass}
                >
                  <Archive className="h-3.5 w-3.5" />
                  Unarchive
                </button>
              )
            ) : onArchive ? (
              <ArchiveConfirmDialog
                itemKind="PRD"
                itemName={plan.title || plan.name || ''}
                onConfirm={onArchive}
                triggerClassName={headerActionClass}
              />
            ) : null}
          </div>
          <PipelineLegend pipeline={reviewPipeline} />
        </div>

        {/* The fused Provenance panel (detail-provenance-restyle tasks 1 + 4 —
            mock §01, cap label since dropped by user call): ONE panel-flat
            surface — the Features-built / Tasks-resolved bars split by an
            interior border on the top row, the distribution fused beneath. The
            distribution SUBSUMES the old done · skipped · left breakdown; it
            renders only once the provenance payload arrives. */}
        <div>
          <div data-testid="provenance-panel" className="panel-flat overflow-hidden rounded-2xl">
            <div className={cn('flex', (provenance !== null || showDistributionSkeleton) && 'border-b border-border')}>
              <HeadlineBar label="Features built" value={featuresBuiltReadout(planStats)} />
              <HeadlineBar label="Tasks resolved" value={resolvedPct} className="border-l border-border" />
            </div>
            {provenance !== null ? (
              <StatusDistribution counts={featureDistribution} />
            ) : showDistributionSkeleton ? (
              <StatusDistributionSkeleton />
            ) : null}
          </div>
        </div>

        {/* The status groups (detail-provenance-restyle task 2 — mock §01/§02):
            ONE group idiom for all four states, ordered Not started (collapsed)
            → In progress (open) → Completed → Superseded (dimmed). Empty groups
            render nothing, so an In-Review item shows only Completed. */}
        {stripNotice !== null && (
          <div
            data-testid="endcap-notice"
            role="status"
            className="rounded-xl border border-[color-mix(in_oklab,var(--color-warn)_30%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-warn)_9%,transparent)] px-3 py-2 text-xs text-muted-foreground"
          >
            {stripNotice}
          </div>
        )}

        {/* The streamed feature land's landing strip renders BELOW the feature
            rows (fix land-surface-single-strip-and-legible-phases task 1): the
            command strip (the landing feature row's cap) leads, the progress
            follows. See the relocated ReconcileStrip just below the status
            groups. */}

        {/* The shared-worktree Cleanup row (done-lane-cleanup task 5, mock
            §05): every feature landed from one live shared branch, so its
            cleanup is one act above the feature rows — the per-feature caps
            below go inert while this renders. Keyed by the WORK ITEM; the
            server resolves the live typed branch (fix
            prd-cleanup-row-keys-dead-attribution-branch). */}
        {showCleanupRow && repoId && plan.prdId && (
          <CleanupCommand repoId={repoId} workItemId={`prd:${plan.prdId}`} />
        )}

        <FeatureStatusGroup
          label="Not started"
          testId="not-started-features-toggle"
          accent="var(--color-subtle)"
          features={notStartedFeatures}
          expanded={notStartedOpen}
          onToggleSection={() => setNotStartedOpen((v) => !v)}
          repoId={repoId || ''}
          prdId={plan.prdId}
          expandedFeatures={expandedFeatures}
          toggleFeature={toggleFeature}
          provenanceByFeature={provenanceByFeature}
          provenanceSettling={provenanceSettling}
          onOpenRun={onOpenRun}
          endcapActions={endcapActions}
          landingFeatureId={landingFeatureId}
          onShowDetails={openBranchIsland}
        />

        <FeatureStatusGroup
          label="In progress"
          testId="in-progress-features-toggle"
          accent="var(--color-blue)"
          features={inProgressFeatures}
          expanded={inProgressOpen}
          onToggleSection={() => setInProgressOpen((v) => !v)}
          repoId={repoId || ''}
          prdId={plan.prdId}
          expandedFeatures={expandedFeatures}
          toggleFeature={toggleFeature}
          provenanceByFeature={provenanceByFeature}
          provenanceSettling={provenanceSettling}
          onOpenRun={onOpenRun}
          endcapActions={endcapActions}
          landingFeatureId={landingFeatureId}
          onShowDetails={openBranchIsland}
          scrollTargetNumber={activeFeature?.number}
          scrollRef={scrollTargetRef}
        />

        <FeatureStatusGroup
          label="Completed"
          testId="completed-features-toggle"
          accent="var(--color-done)"
          features={completedFeatures}
          expanded={completedOpen}
          onToggleSection={() => setCompletedExpanded(!completedOpen)}
          repoId={repoId || ''}
          prdId={plan.prdId}
          expandedFeatures={expandedFeatures}
          toggleFeature={toggleFeature}
          provenanceByFeature={provenanceByFeature}
          provenanceSettling={provenanceSettling}
          endcapActions={endcapActions}
          landingFeatureId={landingFeatureId}
          onShowDetails={openBranchIsland}
          // Scoped to THIS group only (adversarial review of 30f82821e,
          // MEDIUM): the cleanup folds derive over LIVE features, and landed
          // work is all completed — suppressing the other groups could orphan
          // a superseded row's own lingering worktree on another branch. Task
          // 2: the set replaces the blanket boolean, so within the group each
          // row folds only when its OWN finished branches are covered.
          coveredCleanupBranches={coveredCleanupBranches}
          // The per-feature ownership (prd-cleanup-rows-not-attributed-to-
          // features task 2): owned branches only exist for LANDED features,
          // which all bucket here — so the pill/expand affordance is scoped
          // with the suppression it justifies.
          cleanupBranchesByFeature={featureCleanupBranches}
          // Only the completed group's features land/reconcile — their expanded
          // FeatureDetail resolves its branch's LIVE reconcile run from these rows
          // (fix feature-detail-live-reconcile-parity). The other groups have no
          // reconcile, so they take the undefined default.
          deliveryWorktrees={deliveryWorktrees}
        />

        <FeatureStatusGroup
          label="Superseded"
          testId="superseded-features-toggle"
          // The superseded orange every other superseded marker reads —
          // TaskRow's icon (text-orange-500), ProgressBar's segment, the dist
          // tile — sourced from the SAME Tailwind palette token those class
          // forms render, so a palette move keeps them in lockstep. Theme-
          // constant on purpose: the superseded colour does not flip on dark
          // anywhere (unlike the sibling groups' --color-* accents), and this
          // group must match the markers, not the siblings (fix
          // fix-strip-status-tag-and-superseded-accent-nits task 2).
          accent="var(--color-orange-500)"
          features={supersededFeatures}
          expanded={supersededExpanded}
          onToggleSection={() => setSupersededExpanded((v) => !v)}
          dim
          repoId={repoId || ''}
          prdId={plan.prdId}
          expandedFeatures={expandedFeatures}
          toggleFeature={toggleFeature}
          provenanceByFeature={provenanceByFeature}
          provenanceSettling={provenanceSettling}
          endcapActions={endcapActions}
          landingFeatureId={landingFeatureId}
        />

        {/* The streamed feature land's ReconcileStrip (fix feature-land-has-
            no-live-feedback task 2), relocated BELOW the feature rows (fix
            land-surface-single-strip-and-legible-phases task 1): the same
            machine-fed strip the fix detail renders — the honest running phase
            while the run streams, the typed terminal (conflict hand-off,
            failure family) when it settles. Keyed by the landing feature's
            branch; renders nothing while idle, so it is the ONE progress
            surface, sitting under the landing row's cap. */}
        {landingFeature?.branch !== undefined && (
          <ReconcileStrip
            state={delivery.reconcile}
            branch={landingFeature.branch}
            output={delivery.runOutput}
            onRecheck={delivery.onPrepare}
          />
        )}

        {/* The standalone PRD-altitude "Landed" section is retired (fix
            prd-completed-feature-header-merged-pill task 3): a landing is a
            per-feature event, and each completed feature's header now names how
            it reached main (ff / merge-commit sha), so the separate block only
            duplicated that fact. The land history still rides the provenance
            payload for any surface that wants it; the PRD detail no longer
            renders it here. */}
      </div>

      {repoId && (
        <PlanSourceSheet
          repoId={repoId}
          planId={plan.prdId || plan.id}
          features={sourceFeatures}
          isOpen={sourceOpen}
          onClose={() => setSourceOpen(false)}
        />
      )}
    </div>
  );
};

/** Resolved % from the provenance counts — terminal tasks over total. */
const resolvedPctFromCounts = (c: ProvenanceCounts): number =>
  c.total > 0 ? Math.round(((c.done + c.merged + c.superseded) / c.total) * 100) : 0;

/**
 * One compact headline bar of the fused panel (mock §01 top row): eyebrow
 * label · gradient track · mono %. The StatReadout card idiom stays on
 * FixDetail; here the bars are panel ROWS, not floating cards.
 */
function HeadlineBar({ label, value, className }: { label: string; value: number; className?: string }) {
  const pct = Number.isFinite(value) ? Math.min(100, Math.max(0, value)) : 0;
  return (
    <div className={cn('flex flex-1 items-center gap-2.5 px-4 py-3', className)}>
      <span className="eyebrow shrink-0 text-[10px] text-subtle">{label}</span>
      <GradientProgress value={pct} className="flex-1" />
      <span className="mono text-sm font-semibold text-blue">{Math.round(pct)}%</span>
    </div>
  );
}

/** One count · label cell of the distribution rail — a BIG display-font number
 *  over a tiny uppercase mono label (mock .pv-n / .pv-l). */
function DistributionCell({ testId, n, label, tone }: { testId: string; n: number; label: string; tone?: string }) {
  return (
    <span data-testid={testId} className="inline-flex items-baseline gap-1.5">
      <span className={cn('display text-xl font-bold leading-none', tone ?? 'text-foreground')}>{n}</span>
      <span className="mono text-[10px] uppercase tracking-[0.08em] text-subtle">{label}</span>
    </span>
  );
}

/** The `·` between visible Completed-breakdown segments. */
function SegmentDot() {
  return (
    <span className="mono text-[10px] text-subtle/40" aria-hidden="true">
      ·
    </span>
  );
}

/**
 * The FEATURE-status distribution rail (detail-provenance-restyle tasks 1 + 4
 * — mock §01 provrow): border-divided cells fused under the headline bars,
 * led by the "N features" cue. The counts are per FEATURE and single-sourced
 * from the same partition that renders the status groups beneath, so the rail
 * and the group headers can never disagree (the task axis lives in the
 * Tasks-resolved bar above). Completed is the TERMINAL umbrella split into
 * Done · Merged · Superseded — a DELIBERATE mock-parity choice: superseded
 * work is terminal, and the split names it explicitly. Zero cells render
 * nothing (0 Done · 0 Superseded is noise, not signal); a zero-feature scope
 * renders nothing at all.
 */
function StatusDistribution({ counts }: { counts: ProvenanceCounts }) {
  if (counts.total === 0) return null;
  const completed = counts.done + counts.merged + counts.superseded;
  const breakdown = [
    { testId: 'dist-done', n: counts.done, label: 'Done', tone: 'text-subtle' },
    { testId: 'dist-merged', n: counts.merged, label: 'Merged', tone: 'text-[var(--color-phase-review)]' },
    { testId: 'dist-superseded', n: counts.superseded, label: 'Superseded', tone: 'text-orange-500' },
  ].filter((seg) => seg.n > 0);
  return (
    <div data-testid="status-distribution" className="flex items-stretch divide-x divide-border">
      <div className="flex flex-1 items-baseline justify-center gap-1.5 px-2 py-2.5">
        <DistributionCell testId="dist-total" n={counts.total} label="features" />
      </div>
      {counts.notStarted > 0 && (
        <div className="flex flex-1 items-baseline justify-center gap-1.5 px-2 py-2.5">
          <DistributionCell testId="dist-not-started" n={counts.notStarted} label="Not started" tone="text-subtle" />
        </div>
      )}
      {counts.inProgress > 0 && (
        <div className="flex flex-1 items-baseline justify-center gap-1.5 px-2 py-2.5">
          <DistributionCell testId="dist-in-progress" n={counts.inProgress} label="In progress" tone="text-blue" />
        </div>
      )}
      {completed > 0 && (
        <div className="flex flex-[2.4] flex-wrap items-baseline justify-center gap-x-2 gap-y-1 px-2 py-2.5">
          <DistributionCell testId="dist-completed" n={completed} label="Completed:" tone="text-done" />
          {breakdown.length > 0 && (
            <span className="mono text-[10px] uppercase tracking-[0.08em] text-subtle/70">of which,</span>
          )}
          {breakdown.map((seg, i) => (
            <React.Fragment key={seg.testId}>
              {i > 0 && <SegmentDot />}
              <DistributionCell testId={seg.testId} n={seg.n} label={seg.label} tone={seg.tone} />
            </React.Fragment>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * The first-paint placeholder for {@link StatusDistribution} (fix
 * prd-detail-skeletons-stabilize-layout task 1): three fused cells sized to the
 * real rail's `px-2 py-2.5` big-number cell (an `h-5` block ≈ the display-font
 * count's height), so the counts row reserves its exact space while provenance
 * settles and the real rail swaps in place with no reflow. Purely decorative —
 * hidden from assistive tech.
 */
function StatusDistributionSkeleton() {
  return (
    <div
      data-testid="status-distribution-skeleton"
      aria-hidden="true"
      className="flex items-stretch divide-x divide-border"
    >
      {[0, 1, 2].map((i) => (
        <div key={i} className="flex flex-1 items-center justify-center px-2 py-2.5">
          <Skeleton className="h-5 w-20" />
        </div>
      ))}
    </div>
  );
}

/**
 * One status group of features (detail-provenance-restyle task 2 — mock §01) —
 * the SINGLE idiom every state renders through (grown from the terminal-only
 * CollapsibleFeatureSection, so completed/superseded kept their toggles and
 * tests). Header: chevron · accent bar · label · count · rule line. Renders
 * NOTHING when empty — an In-Review item shows only its Completed group.
 * `onOpenRun` is passed only by the non-terminal groups (the Running-pill
 * affordance is for live work); the In-progress group also carries the
 * active-feature scroll target.
 */
function FeatureStatusGroup({
  label,
  testId,
  accent,
  features,
  expanded,
  onToggleSection,
  dim = false,
  repoId,
  prdId,
  expandedFeatures,
  toggleFeature,
  provenanceByFeature,
  provenanceSettling,
  endcapActions,
  landingFeatureId,
  onOpenRun,
  onShowDetails,
  coveredCleanupBranches,
  cleanupBranchesByFeature,
  deliveryWorktrees,
  scrollTargetNumber,
  scrollRef,
}: {
  label: string;
  testId: string;
  /** The group accent bar colour (a CSS colour/var expression). */
  accent: string;
  /** The bucketed features — always a real array (the partition built it). */
  features: NonNullable<Plan['features']>;
  expanded: boolean;
  onToggleSection: () => void;
  /** Superseded is retired work and renders dimmed; the others do not. */
  dim?: boolean;
  repoId: string;
  /** Optional, matching PlanFeatureRow's own prop (slugs degrade without it). */
  prdId?: string;
  expandedFeatures: ReadonlySet<number>;
  toggleFeature: (featureNumber: number) => void;
  /** Per-feature delivered provenance, keyed by feature id (F4). */
  provenanceByFeature: ReadonlyMap<string, FeatureProvenanceView>;
  /** Provenance is on its FIRST load — every row holds the inert settling cap (fix endcap-resumes-pipeline-runs task 2). */
  provenanceSettling: boolean;
  /** The end-cap POST owners (F9 task 2) — absent in read-only scopes. */
  endcapActions?: {
    onLandFeature: (featureId: string, method: 'ff-only' | 'merge') => void;
    onRaiseFeature: (featureId: string) => void;
    onTeardownFeature: (branch: string) => void;
    onResumeRun: (runId: string) => void;
    onContinueFeature: (featureId: string) => void;
  };
  /** The feature whose land run is in flight — its row pins the Merging… cap (fix feature-land-has-no-live-feedback task 2). */
  landingFeatureId?: string;
  /** Open the run island from a row's Running pill — live groups only. */
  onOpenRun?: (runId: string) => void;
  /** Open the read-only provenance island for a row's branch (F6 task 3). */
  onShowDetails?: (branch: string) => void;
  /** The branches a rendered Cleanup row covers (task 2) — a row's cap folds to the inert already-merged rung only when its own finished branches are all in here. */
  coveredCleanupBranches?: readonly string[];
  /** Per-feature owned cleanup branches (prd-cleanup-rows-not-attributed-to-features task 2) — each owning row wears the pill and expand-mounts its commands. */
  cleanupBranchesByFeature?: ReadonlyMap<string, readonly string[]>;
  /** The server-composed delivery rows, forwarded to each row so an expanded FeatureDetail resolves its branch's LIVE reconcile run (fix feature-detail-live-reconcile-parity). */
  deliveryWorktrees?: readonly { branch: string; model: { liveReconcileRunId?: string } }[];
  /** The feature number whose row carries the scroll-target ref. */
  scrollTargetNumber?: number;
  scrollRef?: React.Ref<HTMLDivElement>;
}) {
  if (features.length === 0) return null;
  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2">
        {/* The mock's `.grp-btn` eyebrow header: mono-uppercase label, 7px
            round dot accent, count, rule line — not sans text with a bar. */}
        <button
          type="button"
          data-testid={testId}
          onClick={onToggleSection}
          aria-expanded={expanded}
          className="eyebrow flex flex-1 items-center gap-2 text-[10px] text-subtle transition-colors hover:text-foreground"
        >
          <ChevronRight
            className={cn('h-3.5 w-3.5 shrink-0 text-border-strong transition-transform', expanded && 'rotate-90')}
            aria-hidden="true"
          />
          <span
            data-testid="group-accent-dot"
            aria-hidden="true"
            className="h-[7px] w-[7px] shrink-0 rounded-full"
            style={{ background: accent }}
          />
          {/* The label wears its group accent too (user call) — the dot alone
              was too quiet a state cue; the count stays muted. */}
          <span className="shrink-0" style={{ color: accent }}>
            {label} <span className="text-muted-foreground">· {features.length}</span>
          </span>
          <span aria-hidden="true" className="ml-1 flex-1 border-t border-border" />
        </button>
      </div>
      {expanded && (
        <div className={cn('space-y-3', dim && 'opacity-70')}>
          {features.map((feature) => (
            // Transparent wrapper so the active row can carry the scroll ref
            // without touching PlanFeatureRow's own styling.
            <div key={feature.id} ref={feature.number === scrollTargetNumber ? scrollRef : undefined}>
              <PlanFeatureRow
                feature={feature}
                repoId={repoId}
                prdId={prdId}
                expanded={expandedFeatures.has(feature.number)}
                onToggle={() => toggleFeature(feature.number)}
                onOpenRun={onOpenRun}
                provenance={provenanceByFeature.get(feature.id)}
                // The parent-derived first-load fact (fix endcap-resumes-
                // pipeline-runs task 2) — threaded as one boolean, like
                // provenanceByFeature above.
                provenanceSettling={provenanceSettling}
                onLandFeature={endcapActions ? (method) => endcapActions.onLandFeature(feature.id, method) : undefined}
                landing={landingFeatureId === feature.id}
                onRaiseFeature={endcapActions ? () => endcapActions.onRaiseFeature(feature.id) : undefined}
                onTeardownFeature={endcapActions?.onTeardownFeature}
                onResumeRun={endcapActions?.onResumeRun}
                onContinueItem={endcapActions ? () => endcapActions.onContinueFeature(feature.id) : undefined}
                onShowDetails={onShowDetails}
                coveredCleanupBranches={coveredCleanupBranches}
                cleanupBranches={cleanupBranchesByFeature?.get(feature.id)}
                deliveryWorktrees={deliveryWorktrees}
              />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default PlanDetailsPRD;
