import React from 'react';
import { Bolt } from 'lucide-react';
import FixCard from './FixCard';
import type { Fix } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { fixSortRank } from '../utils/list-category';

interface FixListProps {
  fixes: Fix[];
  selectedFixId: string | null;
  onSelectFix: (fixId: string) => void;
  reviewPipeline?: PipelineStep[];
  /** Threaded to each card so a worktree fix gets its delivery marker. */
  repoId?: string;
  /** Threaded to each card so a live-run fix's Running pill opens the run island. */
  onOpenRun?: (runId: string) => void;
}

const FixList: React.FC<FixListProps> = ({ fixes, selectedFixId, onSelectFix, reviewPipeline, repoId, onOpenRun }) => {
  if (fixes.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <Bolt className="h-12 w-12 text-muted-foreground mb-3" aria-hidden="true" />
        <p className="text-text-secondary text-center">No fixes found</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Use <code className="font-mono">/fix</code> skill to create a fix document
        </p>
      </div>
    );
  }

  const handleFixClick = (fixId: string) => {
    console.log('[FixList] Fix clicked:', fixId);
    onSelectFix(fixId);
  };

  // Default ordering: in-progress first, then completed-but-not-merged ("ready
  // to merge"), then everything else — each band broken by severity descending
  // (critical > high > medium > low). The rank is the worktree-effective one
  // (shared fixSortRank), so it agrees with the card status and the filter.
  const severityOrder: Record<string, number> = {
    critical: 0,
    high: 1,
    medium: 2,
    low: 3,
  };

  const sortedFixes = [...fixes].sort((a, b) => {
    const rankA = fixSortRank(a);
    const rankB = fixSortRank(b);
    if (rankA !== rankB) return rankA - rankB;

    // Within the same band, sort by severity descending.
    const sevA = severityOrder[a.severity] ?? 2;
    const sevB = severityOrder[b.severity] ?? 2;
    return sevA - sevB;
  });

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Fixes">
      {sortedFixes.map((fix) => (
        <FixCard
          key={fix.id}
          fix={fix}
          isSelected={fix.id === selectedFixId}
          onClick={() => handleFixClick(fix.id)}
          reviewPipeline={reviewPipeline}
          repoId={repoId}
          onOpenRun={onOpenRun}
        />
      ))}
    </div>
  );
};

export default FixList;
