import { useEffect, useRef } from 'react';
import { useRunStream } from './useRunStream';
import { foldRunOutcome } from './run-outcome';
import { deriveReconcileStrip, type ReconcileStripState } from '../utils/reconcile-strip';

/**
 * The FOREIGN machinery-run fold: subscribe to a reconcile/land run this
 * client did not start (a CLI `tiny-brain reconcile-branch`, another
 * session's merge) and fold its stream into the strip machine
 * (reconcile-verify-progress-invisible). The one shared home for
 * status-only surfaces, so the `useRunStream → foldRunOutcome →
 * deriveReconcileStrip` composition doesn't fork per consumer —
 * {@link useDeliveryActions} keeps the self+foreign COMPOSITE (its watch is
 * entangled with self-run ownership: busy gating, error channels, the
 * pinned-watch rule) and is deliberately not built on this.
 *
 * `onTerminal` fires ONCE per run when the watched run ends (exit frame or
 * broken stream) — the consumer's refetch seam, so the surface's persisted
 * facts (availability chip, `liveReconcileRunId`) catch up with the verdict
 * instead of sitting stale under a streamed terminal.
 */
export function useLiveReconcileStrip(
  repoId: string,
  runId: string | undefined,
  onTerminal?: () => void,
): ReconcileStripState {
  const { events, error: streamError } = useRunStream(repoId, runId ?? '');
  const outcome = foldRunOutcome(events, runId, streamError);
  const streaming = runId !== undefined && outcome.exit === undefined && !outcome.streamBroke;

  const notifiedRunId = useRef<string | undefined>(undefined);
  const terminated = outcome.exit !== undefined || outcome.streamBroke;
  useEffect(() => {
    if (runId === undefined || !terminated || notifiedRunId.current === runId) return;
    notifiedRunId.current = runId;
    onTerminal?.();
  }, [runId, terminated, onTerminal]);

  return deriveReconcileStrip({ events: runId !== undefined ? events : [], streaming });
}

export default useLiveReconcileStrip;
