/**
 * SSE-driven refetch triggers for the per-repo detail surface
 * (RepoDetailPage).
 *
 * Fix: dashboard-drops-filewatcher-sse-events — RepoDetailPage fetches
 * plans/fixes locally and only live-updates on `invalidate` events,
 * which the file watcher emits on git-ref changes (commits landing). A
 * markdown edit instead emits `prd-doc-change` / `fix-doc-change`; these
 * hooks bridge those into a repo-scoped refetch, mirroring
 * `useSpikeDocLive`.
 *
 * Unlike the spike hook (scoped to the selected spikeId), a plan/fix doc
 * edit refetches the whole list — the list and detail panes both read
 * from the same `/api/repos/:id/{plans,fixes}` fetch, so any matching
 * `repoId` event is a refetch signal.
 */

import { useEffect } from 'react';
import { sseManager, type SSEEvent } from '../services/SSEManager';

/** Refetch the repo's plans when a PRD/feature markdown doc changes. */
export function usePrdDocLive(repoId: string | null, onChange: () => void): void {
  useEffect(() => {
    if (!repoId) return;

    const handle = (event: SSEEvent): void => {
      if (event.type !== 'prdDocChange') return;
      // Doc events are per-WORKING-TREE, never clone-aliased — canonical only.
      if (event.repoId !== repoId) return;
      onChange();
    };

    return sseManager.on('prdDocChange', handle);
  }, [repoId, onChange]);
}

/** Refetch the repo's fixes when a fix markdown doc changes. */
export function useFixDocLive(repoId: string | null, onChange: () => void): void {
  useEffect(() => {
    if (!repoId) return;

    const handle = (event: SSEEvent): void => {
      if (event.type !== 'fixDocChange') return;
      // Doc events are per-WORKING-TREE, never clone-aliased — canonical only.
      if (event.repoId !== repoId) return;
      onChange();
    };

    return sseManager.on('fixDocChange', handle);
  }, [repoId, onChange]);
}
