import { useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router';

/**
 * localStorage key holding the last non-root route (`pathname + search`).
 * The URL stays the source of truth for navigation — selected PRD/fix/spike
 * (`?item=`) and active view (`?view=`) ride along inside it — and this key
 * is only a mirror so a bare landing can resume where you left off.
 */
export const LAST_ROUTE_KEY = 'tiny-brain:last-route';

const BARE_ROOT = '/';

function readStoredRoute(): string | null {
  try {
    return window.localStorage.getItem(LAST_ROUTE_KEY);
  } catch {
    return null;
  }
}

/**
 * Mirror the current route to localStorage and, on a bare-root landing,
 * resume the last stored route. Mount this once beneath the router.
 *
 * - Store: every navigation writes `pathname + search`, except the bare root
 *   (never clobber a real remembered location with `/`).
 * - Resume: on initial mount, if we land on `/` and a stored route exists,
 *   replace-navigate to it. Runs once and only from `/`, so it can't loop.
 */
export function useRouteMemory(): void {
  const location = useLocation();
  const navigate = useNavigate();
  const didResume = useRef(false);

  // Resume once, on initial mount, only from a bare-root landing.
  useEffect(() => {
    if (didResume.current) return;
    didResume.current = true;
    if (location.pathname !== BARE_ROOT) return;
    const stored = readStoredRoute();
    if (stored && stored !== BARE_ROOT) {
      navigate(stored, { replace: true });
    }
    // Mount-only: resume reflects where the session was, not later navigation.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Store the current route on every navigation (skip the bare root). Guard on
  // pathname only, so it stays symmetric with the resume guard above — a bare
  // root is never a location worth remembering, query string or not.
  useEffect(() => {
    if (location.pathname === BARE_ROOT) return;
    try {
      window.localStorage.setItem(LAST_ROUTE_KEY, location.pathname + location.search);
    } catch {
      // Storage unavailable (private mode / quota) — resume simply won't work.
    }
  }, [location.pathname, location.search]);
}
