import { useState, useEffect } from 'react';
import { getSystemNotifications } from '../services/api';
import type { Notification } from '../types';

/**
 * Fetches the system notifications feed once on mount. Fail-soft: any error
 * (offline, route unavailable) leaves the list empty rather than surfacing a
 * false signal — the same stance as the producer that feeds it.
 */
export function useSystemNotifications(): { notifications: Notification[] } {
  const [notifications, setNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    let cancelled = false;
    getSystemNotifications()
      .then((result) => {
        if (!cancelled) setNotifications(result.notifications);
      })
      .catch(() => {
        // Fail-soft — no notifications rather than a broken bell.
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return { notifications };
}
