import React, { useEffect, useState } from 'react';
import { Wrench } from 'lucide-react';
import type { WorktreeReadinessCommand } from '@magic-ingredients/tiny-brain-core';
import { WorktreeReadinessEditor } from './WorktreeReadinessEditor';

/**
 * Worktree-readiness card (worktree-readiness-commands F6) — sits alongside the
 * pipeline editors in the setup surface. Loads the resolved readiness set from
 * the server (stored or analysis-seeded) and POSTs edits back; the server + core
 * schema own validation and persistence to `.tiny-brain/config.json`.
 */
export const WorktreeReadinessCard: React.FC<{ repoId: string }> = ({ repoId }) => {
  const [readiness, setReadiness] = useState<WorktreeReadinessCommand[]>([]);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch(`/api/repos/${repoId}/readiness`)
      .then((r) => {
        if (!r.ok) throw new Error(`readiness load failed: ${r.status}`);
        return r.json();
      })
      .then((data) => {
        if (data?.readiness) setReadiness(data.readiness);
        setError(null);
      })
      .catch(() => setError('Could not load readiness commands.'));
  }, [repoId]);

  const save = async (list: WorktreeReadinessCommand[]) => {
    // Optimistic: show the edit immediately, but keep the last persisted set so a
    // failed PUT rolls the UI back instead of leaving a phantom "saved" state.
    const previous = readiness;
    setReadiness(list);
    setSaving(true);
    setError(null);
    try {
      const res = await fetch(`/api/repos/${repoId}/readiness`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ readiness: list }),
      });
      if (!res.ok) {
        setReadiness(previous);
        const detail = (await res.json().catch(() => null)) as { error?: unknown } | null;
        setError(typeof detail?.error === 'string' ? detail.error : 'Failed to save readiness commands.');
        return;
      }
      const data = await res.json();
      if (data?.readiness) setReadiness(data.readiness);
    } catch {
      setReadiness(previous);
      setError('Failed to save readiness commands.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="rounded-2xl panel overflow-hidden">
      <div className="pipe-group-head">
        <span className="flex items-center gap-3">
          <span className="pipe-disc"><Wrench className="h-5 w-5" /></span>
          <span>
            <span className="block font-semibold text-sm">Worktree readiness</span>
            <span className="block text-xs text-muted-foreground">
              Commands every worktree runs, in order, before its analysers — install, codegen, build. Seeded from analysis.
            </span>
          </span>
        </span>
      </div>
      <div className="p-4">
        {error && (
          <div role="alert" className="mb-2 text-sm text-destructive">
            {error}
          </div>
        )}
        <WorktreeReadinessEditor readiness={readiness} onSave={save} saving={saving} />
      </div>
    </div>
  );
};

export default WorktreeReadinessCard;
