import React from 'react';
import { Bot, GitBranch } from 'lucide-react';
import { cn } from '@/lib/utils';
import WorktreeIcon from './WorktreeIcon';
import { dedupeByBranch, diverges, type WorktreeBranchRef } from './worktree-branches';
import { ChipShell } from './glyph-chip';

/**
 * Shared parts for the worktree indicators, all now owned by {@link MiniStatusRail}:
 *   - the compact, icon-only chip (`compact` mode) on cards, task rows, and features.
 *   - {@link WorktreeMergeBar} — the LONG, labelled chip (`merge` mode) on the
 *     PRD / fix / spike detail HEADERS.
 * Both wear the same purple chip skin, read `[robot?][branch]`, and list full
 * branch/worktree names in the tooltip; the long one adds a visible CTA label.
 * Kept here so the glyphs, label, chip skin, and tooltip body never drift between
 * the two variants (the former standalone WorktreeTag/WorktreeBar components).
 */

/** The shared purple chip skin. A subtle tint + inset ring (not a solid
 *  fill + border) so it reads at the same visual weight and 11px type as the
 *  rail's [Launch ▾] pill — worktree keeps the purple hue for identity, but no
 *  longer out-shouts the neutral runner/env glyphs beside it. 8px radius to
 *  match the status pills and the commit-pipeline chips. */
export const WORKTREE_CHIP_CLASS =
  'inline-flex flex-shrink-0 items-center gap-1 rounded-lg text-[11px] font-medium bg-[color-mix(in_oklab,#a855f7_10%,transparent)] text-purple-700 dark:text-purple-300 shadow-[inset_0_0_0_1px_color-mix(in_oklab,#a855f7_35%,transparent)]';

/** Slightly lighter glyph stroke (lucide defaults to 2) shared by the compact
 *  worktree chip and the rail glyphs on the task-row / card surfaces. */
export const GLYPH_STROKE_WIDTH = 1.5;

/**
 * The worktree indicators' chip: {@link ChipShell} wearing the purple worktree
 * skin. Callers supply the inner glyphs/text and the tooltip body. Keeps the
 * skin from drifting between {@link WorktreeMergeBar} (long CTA) and the
 * compact rail chip; the button/span split and tooltip wiring live in the
 * shared shell.
 */
export const WorktreeChip: React.FC<{
  /** Testid for the chip element (button or span). */
  'data-testid'?: string;
  /** Accessible name — convey the ACTION for the clickable variant. */
  ariaLabel: string;
  /** When set the chip is a button firing this; omitted ⇒ a glance-only span. */
  onClick?: () => void;
  /** Tooltip body (typically {@link WorktreeTooltipBody}). */
  tooltip: React.ReactNode;
  className?: string;
  children: React.ReactNode;
}> = ({ 'data-testid': testId, ariaLabel, onClick, tooltip, className = '', children }) => (
  <ChipShell
    testId={testId}
    ariaLabel={ariaLabel}
    onClick={onClick}
    tooltip={tooltip}
    tooltipClassName="max-w-none"
    className={cn(WORKTREE_CHIP_CLASS, 'px-1.5 py-0.5', className)}
    buttonClassName="transition-colors hover:bg-[color-mix(in_oklab,#a855f7_18%,transparent)]"
  >
    {children}
  </ChipShell>
);

/** The leading glyphs the small tag shares: an optional worker robot in front
 *  of the branch glyph (the worker glyph reads "a worker, not the operator"). */
export const WorktreeGlyphs: React.FC<{ workerDriven?: boolean }> = ({ workerDriven }) => (
  <>
    {workerDriven && (
      <Bot
        data-testid="worker-indicator"
        aria-label="worker-driven"
        strokeWidth={GLYPH_STROKE_WIDTH}
        className="h-3 w-3 flex-shrink-0"
      />
    )}
    <GitBranch data-testid="branch-indicator" strokeWidth={GLYPH_STROKE_WIDTH} className="h-3 w-3 flex-shrink-0" />
  </>
);

/** The tooltip body both indicators share: every branch, with a worktree-dir row
 *  when the branch and its worktree dir name diverge. */
export const WorktreeTooltipBody: React.FC<{ model: readonly WorktreeBranchRef[]; heading?: string }> = ({
  model,
  heading,
}) => (
  <span className="flex flex-col gap-1">
    {heading && <span className="font-medium">{heading}</span>}
    {model.map((b) => (
      <span key={b.branch} className="flex flex-col gap-0.5">
        <span className="flex items-center gap-1 whitespace-nowrap">
          <GitBranch className="h-3 w-3 flex-shrink-0" />
          {b.branch}
        </span>
        {diverges(b) && (
          <span data-testid="worktree-dir-row" className="flex items-center gap-1 whitespace-nowrap">
            <WorktreeIcon aria-hidden="true" />
            {b.worktreeName}
          </span>
        )}
      </span>
    ))}
  </span>
);

/**
 * The LONG worktree indicator: a branch glyph plus a call-to-action label
 * ("View merge status"). Rendered by {@link MiniStatusRail} in merge mode as the
 * delivery affordance on the PRD / fix / spike detail HEADERS. Which worktree the
 * work lived on is secondary — the full branch + worktree-dir names stay in the
 * tooltip. The icon-only sibling is the compact chip (compact mode).
 *
 * Folded here from the former standalone `WorktreeBar` component (now deleted) so
 * the rail owns both its indicator variants through the shared chip shell.
 */
export const WorktreeMergeBar: React.FC<{
  /** Branches this surface's work lives on; deduped by branch. Surfaced only in
   *  the tooltip — the bar itself no longer names the worktree. */
  branches: readonly WorktreeBranchRef[];
  /** Accessible label for the chip and heading for the tooltip. */
  label: string;
  /** Visible call-to-action text next to the branch glyph. */
  text?: string;
  className?: string;
  /** Override the testid so distinct surfaces can target their own. */
  'data-testid'?: string;
  /** Size classes for the branch glyph (default `h-3 w-3`). */
  iconClassName?: string;
  /** When set, the chip is a button firing this handler; omitted ⇒ glance-only. */
  onClick?: () => void;
}> = ({
  branches,
  label,
  text = 'View merge status',
  className = '',
  'data-testid': testId = 'worktree-bar',
  iconClassName = 'h-3 w-3',
  onClick,
}) => {
  const model = dedupeByBranch(branches);
  if (model.length === 0) return null;
  // The header bar is a delivery affordance, not a status surface: it reads the
  // CTA and opens the merge island. The detail-header eyebrow already states the
  // item's lifecycle, so the bar never duplicates it with a merge-state pill.
  return (
    <WorktreeChip
      data-testid={testId}
      ariaLabel={label}
      onClick={onClick}
      className={className}
      tooltip={<WorktreeTooltipBody model={model} heading={label} />}
    >
      <GitBranch data-testid="branch-indicator" className={cn(iconClassName, 'flex-shrink-0')} />
      <span className="truncate">{text}</span>
    </WorktreeChip>
  );
};
