import React from 'react';

export interface FixControlStripProps {
  /**
   * The LHS attribution content — the idle "Click to launch →" hint, the live
   * MiniStatusRail, or a settled deliverer (glyph+text who + branch chip). This
   * is the "who / where the work ran" section; it leads the strip and is never
   * pushed around by the landed chip (fix endcap-resumes-pipeline-runs task 9 —
   * the worker section stays put on the left).
   */
  attribution: React.ReactNode;
  /**
   * The delivery landed chip (`merged → main` / `via fix <slug>`), RIGHT-aligned
   * against the end cap rather than crowding the LHS attribution (task 9). Omit
   * for non-delivered states.
   */
  landedChip?: React.ReactNode;
  /**
   * The read-only provenance-island entry (a `TimelineLink`). It renders as a
   * quiet inline link on the SAME vertically-centered row as the attribution,
   * pushed to the right (timeline-second-row-and-spike-strip) — no longer a
   * full-height cap column, and no longer a stacked second row (the fix/spike
   * strip has no title/tasks, so a lone second row read unbalanced). Omit when
   * there is no branch to inspect.
   */
  timeline?: React.ReactNode;
  /** The full-height one-action end cap closing the row. */
  endcap: React.ReactNode;
}

/**
 * The whole-fix control strip (mock §§03–05), extracted from FixDetail's inline
 * JSX (fix endcap-resumes-pipeline-runs task 6) so every state is storyable.
 * ONE vertically-centred row: the LHS attribution, then the delivery landed chip
 * and the quiet Timeline link pushed to the RIGHT (`ml-auto`) so they read
 * against the end cap. The one full-height end cap closes the row and rounds its
 * own right edge, so no overflow-hidden. Purely presentational — the host
 * derives which attribution / landed chip / timeline / cap to pass.
 */
export function FixControlStrip({ attribution, landedChip, timeline, endcap }: FixControlStripProps) {
  const hasLanded = landedChip !== undefined && landedChip !== null;
  return (
    <section data-testid="fix-control-strip" className="panel-flat flex items-stretch rounded-2xl">
      <div
        data-testid="fix-strip-body"
        className="flex min-h-14 min-w-0 flex-1 flex-wrap items-center gap-2.5 px-4 py-3.5"
      >
        {attribution}
        {hasLanded && (
          <span data-testid="fix-strip-landed" className="ml-auto shrink-0">
            {landedChip}
          </span>
        )}
        {timeline !== undefined && timeline !== null && (
          // Right-aligned: it takes the `ml-auto` itself when no landed chip
          // preceded it, else it rides alongside the chip on the right.
          <span data-testid="fix-strip-timeline" className={hasLanded ? 'shrink-0' : 'ml-auto shrink-0'}>
            {timeline}
          </span>
        )}
      </div>
      {endcap}
    </section>
  );
}

export default FixControlStrip;
