import { useCallback, useEffect, useRef, useState } from 'react';
import { responseError } from './response-error';

/** A user-declared model, as GET <base>/models lists it. */
export interface CustomModelView {
  id: string;
  provider: string;
}

/** A provider a custom model may be declared under. */
export interface ModelProviderView {
  provider: string;
  providerLabel: string;
}

/** An add or remove outcome: a refusal always carries the server's message. */
export type ModelMutationResult = { ok: true } | { ok: false; error: string };

/**
 * The model registry feed for one Workers surface: list on mount, and dumb
 * add/remove that send raw input for the server to judge (id shape,
 * provider, collisions and in-use are core's rules), report its message,
 * and reload on success.
 *
 * `basePath` selects the scope exactly as `useWorkers` does — the global
 * `/api/workers` (default) or a repo's `/api/repos/:repoId/workers`.
 */
export function useModels(basePath: string = '/api/workers') {
  const [models, setModels] = useState<CustomModelView[]>([]);
  const [providers, setProviders] = useState<ModelProviderView[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Only the latest load may write state: a slower response for a previous
  // scope (or an earlier reload) must not overwrite the current one.
  const latestLoad = useRef(0);

  const reload = useCallback(async (): Promise<void> => {
    const load = ++latestLoad.current;
    const current = () => load === latestLoad.current;
    const fail = (message: string) => {
      // A failed reload must not leave the previous rows beside its error.
      setModels([]);
      setProviders([]);
      setError(message);
    };
    try {
      const res = await fetch(`${basePath}/models`);
      if (!res.ok) {
        const message = await responseError(res);
        if (current()) fail(message);
        return;
      }
      const data = (await res.json()) as {
        models?: CustomModelView[];
        providers?: ModelProviderView[];
      };
      if (!current()) return;
      setModels(data.models ?? []);
      setProviders(data.providers ?? []);
      setError(null);
    } catch (err) {
      if (current()) fail(err instanceof Error ? err.message : 'Failed to load models');
    } finally {
      if (current()) setLoading(false);
    }
  }, [basePath]);

  // A scope switch starts from a clean, loading slate — the previous scope's
  // rows are not this scope's.
  useEffect(() => {
    setModels([]);
    setProviders([]);
    setError(null);
    setLoading(true);
    void reload();
  }, [reload]);

  const mutate = useCallback(
    async (url: string, init: RequestInit): Promise<ModelMutationResult> => {
      try {
        const res = await fetch(url, init);
        if (!res.ok) return { ok: false, error: await responseError(res) };
      } catch (err) {
        return { ok: false, error: err instanceof Error ? err.message : 'Request failed' };
      }
      await reload();
      return { ok: true };
    },
    [reload],
  );

  const add = useCallback(
    (model: CustomModelView) =>
      mutate(`${basePath}/models`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(model),
      }),
    [mutate, basePath],
  );

  const remove = useCallback(
    (id: string) => mutate(`${basePath}/models/${encodeURIComponent(id)}`, { method: 'DELETE' }),
    [mutate, basePath],
  );

  return { models, providers, loading, error, add, remove, reload };
}
