export interface ValidationPanelProps {
  /** The panel machine state ({@link deriveValidationPanel}) — this renders it. */
  state: ValidationPanelState;
  /** href for the header's open-run link, built by the host from `state.runId`. */
  runHref?: string;
  /** Re-run the completion validation (POSTs the F3 revalidate route) — offered
   *  on a failed run; omitted when the host wires no handler. */
  onRerun?: () => void;
  /** A re-run this host fired is in flight — greys the button as a best-effort
   *  guard against an obvious double-click. It is HOST-CONTROLLED, not an
   *  internal latch, so the server's per-item 409 remains the real backstop
   *  against a stacked duplicate suite. */
  rerunning?: boolean;
  /** The copyable manual fallback (`tiny-brain complete --fix <slug>`), built
   *  by the host from the work ref; shown beside the re-run button. */
  completeCommand?: string;
  /** The item's git-derived landed bit (delivery state, not a validation fold).
   *  A landed + passed item drops the "Ready to land" footer — there is no
   *  pending land (fix validation-footer-landed-and-post-land-single-phase). */
  landed?: boolean;
  /** The server-computed lifecycle phase (core `getValidation`) — the props-in-ui
   *  source for the header's active delivery pill, via {@link describeLifecyclePhasePill}
   *  (the SAME phase the board card names). Always supplied by the detail pages; an
   *  absent / idle / passed phase names no active pill and the panel's own
   *  {@link ValidationPill} stands. The legacy `state.deliveryPill` fallback is
   *  retired (fix retire-legacy-deliverypill-from-board-card task 2). */
  validation?: LifecyclePhase;
  /** Re-run the reconcile ladder for the failing branch (retry-reconcile-action F4) —
   *  wired only by the detail hosts, which POST /reconcile with the emitted branch id.
   *  The button is presence-gated on this AND a failed reconcile carrying a branch. */
  onRetryReconcile?: (branch: string) => void;
  /** A reconcile this host fired is in flight — greys the Retry button as a
   *  best-effort double-dispatch guard (the server's per-item gate is the backstop). */
  retryReconcileInFlight?: boolean;
  /** Dispose an untriaged mutation survivor as equivalent (F4 task 2). Wired by
   *  the detail hosts, which POST /mutation-triage with the emitted identity. */
  onMarkEquivalentSurvivor?: (identity: MutantIdentity) => void;
  onHardenSurvivor?: (identity: MutantIdentity) => void;
  /** Accept an untriaged mutation survivor with a reason (F4 task 2). */
  onAcceptSurvivor?: (identity: MutantIdentity, reason: string) => void;
}

/** `238_000ms → "3m 58s"`, `41_000ms → "41s"` — coarse, reads as a clock. */
function formatElapsed(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const minutes = Math.floor(total / 60);
  return minutes > 0 ? `${minutes}m ${total % 60}s` : `${total}s`;
}

/**
 * The elapsed readout. Whether it TICKS is decided by liveness — the pill — not
 * by the presence of an `endedAt`: a LIVE run (`validating`) ticks from `since`
 * (the tick IS the liveness signal — a static count is indistinguishable from a
 * hang, the reconcile-strip lesson), and a SETTLED run never ticks (a live
 * stopwatch under a settled pill is the exact lie this panel exists to prevent,
 * and `until`/`endedAt` is optional so it cannot be trusted to gate the freeze).
 * A settled run shows its frozen `since → until` duration when an end instant
 * was recorded, and renders nothing when it wasn't — never a fabricated count.
 *
 * aria-hidden: the panel is a role="status" live region, and a per-second tick
 * inside it would re-announce the whole panel every second — the tick is a
 * sighted affordance; the pill carries the announcement.
 */
function Elapsed({ since, until, live }: { since: string; until?: string; live: boolean }) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!live) return undefined;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [live]);

  const start = Date.parse(since);
  if (Number.isNaN(start)) return null;

  // Settled: a frozen receipt from the recorded end instant, or nothing when
  // none was stamped — never `since → now`, which would tick a finished run.
  if (!live) {
    if (until === undefined) return null;
    const end = Date.parse(until);
    if (Number.isNaN(end)) return null;
    return (
      <span
        data-testid="validation-elapsed"
        aria-hidden="true"
        className="inline-flex items-center gap-1 tabular-nums text-subtle"
      >
        <Timer className="h-3 w-3" aria-hidden="true" />
        {`ran ${formatElapsed(end - start)}`}
      </span>
    );
  }

  return (
    <span
      data-testid="validation-elapsed"
      aria-hidden="true"
      className="inline-flex items-center gap-1 tabular-nums text-subtle"
    >
      <Timer className="h-3 w-3" aria-hidden="true" />
      {formatElapsed(now - start)}
    </span>
  );
}

/**
 * The colour-coded merge boundary between the reconcile lane and the post-merge
 * lane (reconcile-segment task 1) — a rotated diamond + "merge · <state>"
 * eyebrow, the same vocabulary the board journey diamond uses (task 2). `pending`
 * is a hollow neutral diamond; `ready` / `blocked` / `merged` fill in the done /
 * red / primary tone.
 */
// The tone AGREES with the diamond node's `mergeNodeState` (F6): ready/merged →
// done-green (ok node), blocked → red (fail node), pending → subtle (grey node).
// `merged` reads green here (a landed success terminal), matching its `ok` node —
// never the header `merged` pill's brand tone, which would leave a green diamond
// beside a blue label.
const MERGE_MARKER: Record<MergeBoundaryState, { label: string; tone: string; filled: boolean }> = {
  pending: { label: 'merge · pending', tone: 'var(--color-subtle)', filled: false },
  ready: { label: 'merge · ready', tone: 'var(--color-done)', filled: true },
  blocked: { label: 'merge · blocked', tone: 'var(--color-phase-red)', filled: true },
  merged: { label: 'merge · merged', tone: 'var(--color-done)', filled: true },
};

/**
 * The merge step's BODY label (validation-panel-step-timeline F6) — the diamond
 * itself is now the timeline node in the rail, so this renders just the "merge ·
 * <state>" eyebrow. Keeps `validation-merge` + `data-state` as the merge lane's
 * stable hook (existing consumers read the raw boundary here, not the node tone).
 */
function MergeMarker({ state }: { state: MergeBoundaryState }) {
  const m = MERGE_MARKER[state];
  return (
    <div data-testid="validation-merge" data-state={state} className="flex items-center gap-2 py-1">
      <span className="eyebrow text-[10px]" style={{ color: state === 'pending' ? 'var(--color-subtle)' : m.tone }}>
        {m.label}
      </span>
    </div>
  );
}

/**
 * One timeline node (validation-panel-step-timeline F6 task 1): a circle for a
 * compute lane, a diamond for the merge/land step, toned by its state. The
 * running pulse is the CSS `.vnode--run::after` ring (reduced-motion honoured in
 * the stylesheet) — never a hand-rolled inline animation. `aria-hidden`: the node
 * is decorative chrome; the lane row it sits beside carries the accessible state.
 */
function StepNode({ state, shape = 'circle' }: { state: StepNodeState; shape?: 'circle' | 'diamond' }) {
  return (
    <span
      data-testid="validation-step-node"
      data-node-state={state}
      data-node-shape={shape}
      className={cn('vnode', `vnode--${state}`, shape === 'diamond' && 'vnode--diamond')}
      aria-hidden="true"
    >
      {shape === 'circle' && state === 'ok' && <Check aria-hidden="true" />}
      {shape === 'circle' && state === 'fail' && <X aria-hidden="true" />}
    </span>
  );
}

/**
 * One row of the step timeline (F6 task 1): the connector rail (with its status
 * node, unless this is a node-less detail row like the conflict block) beside the
 * row body. `first`/`last` trim the thread so it starts and ends at a node.
 */
function TimelineStep({
  node,
  shape,
  first,
  last,
  tail,
  tint,
  children,
}: {
  node?: StepNodeState;
  shape?: 'circle' | 'diamond';
  first: boolean;
  last: boolean;
  /** A node-less row PAST the last node (e.g. a trailing failure block): the
   *  thread already ended at that node, so this row draws no rail — never a
   *  segment dangling into empty space. */
  tail?: boolean;
  tint?: string;
  children: ReactNode;
}) {
  return (
    <div
      data-testid="validation-step"
      className={cn('vstep', first && 'is-first', last && 'is-last', tail === true && 'is-tail')}
      style={tint !== undefined ? { background: tint } : undefined}
    >
      <div className="vstep__rail">{node !== undefined && <StepNode state={node} shape={shape} />}</div>
      <div className="vstep__body">{children}</div>
    </div>
  );
}

/** Pill tone + copy per state — validating carries a pulsing dot for liveness. */
/** Sentence-case a lower-case phase label (e.g. `reconcile failed` → `Reconcile
 *  failed`) for the footer, without a second naming of the phases. */
const sentenceCase = (label: string): string => label.charAt(0).toUpperCase() + label.slice(1);

const PILL: Record<ValidationPill, { cls: string; label: string; live: boolean }> = {
  validating: { cls: 'pill-violet', label: 'validating', live: true },
  passed: { cls: 'pill-done', label: 'passed', live: false },
  failed: { cls: 'pill-red', label: 'failed', live: false },
  regression: { cls: 'pill-red', label: 'Regression test', live: false },
  // The all-pending preview: a git-terminal item with a configured pipeline but
  // no genuine run yet (an interactive land / laundered scoping-fault). Muted —
  // nothing has run, so it is neither a live nor a settled verdict.
  pending: { cls: 'pill-muted', label: 'pending', live: false },
};

/**
 * The header's active delivery pill from the server-computed lifecycle phase
 * (props-in-ui) — the same board-identical label + testId {@link
 * describeLifecyclePhasePill} gives the card, mapped to the PANEL's own `pill-*`
 * tones (the board's `tb-pill--*` hues live in board.css, unloaded here). Returns
 * null for an idle / passed / TDD phase — the caller falls back to the panel's own
 * {@link ValidationPill}. This is now the ONLY header-pill source (the legacy
 * `state.deliveryPill` fold `deliveryPhasePill` was retired, fix
 * retire-legacy-deliverypill-from-board-card task 2).
 */
function phasePillFromLifecycle(
  validation: LifecyclePhase | undefined,
): { cls: string; label: string; live: boolean; testId: string } | null {
  // Early-out on the absent phase up front (adversarial review, LOW): it narrows
  // `validation` for the tone switch below and drops the redundant
  // `validation === undefined` disjunct that describeLifecyclePhasePill already covers.
  if (validation === undefined) return null;
  const view = describeLifecyclePhasePill(validation);
  if (view === null) return null;
  const cls = validation.status === 'failed' ? 'pill-red' : validation.pipeline === 'merge' ? 'pill-blue' : 'pill-violet';
  return { cls, label: view.label, live: validation.status === 'running', testId: view.testId };
}

/**
 * The post-merge regression's failing evidence (F4 task 4), straight off the
 * main-validation run record: the failing tests (file · package — test) and the
 * persisted output tail. Renders only on a `regression` verdict.
 */
function EvidenceBlock({ evidence }: { evidence: MainValidationEvidence }) {
  return (
    <div data-testid="validation-evidence" className="border-t border-[var(--color-border)] px-3 py-2">
      <p className="eyebrow text-[10px] text-subtle">Failing evidence · {evidence.failingTests.length} tests</p>
      <ul className="mono mt-1 space-y-0.5 text-[10px] leading-relaxed text-muted-foreground">
        {evidence.failingTests.map((t) => (
          <li key={`${t.file}:${t.test}`}>
            <span className="text-[var(--color-phase-red)]" aria-hidden="true">✗</span> {t.file}
            {t.package !== undefined && <span className="text-subtle"> · {t.package}</span>} — {t.test}
          </li>
        ))}
      </ul>
      {evidence.outputTail !== undefined && (
        <p className="mono mt-1 text-[10px] text-subtle">{evidence.outputTail}</p>
      )}
    </div>
  );
}

/**
 * The inline failed-step reason panel — rendered directly BELOW the lane row that
 * owns the failed step (not at the bottom of the panel), so a red step's reason
 * reads next to its cause. One row per failed step in that lane: "<step> failed"
 * plus its recorded reasons (surviving mutants, failing tests, …). An empty
 * reasons list is meaningful — the step failed with no step-level detail — so the
 * reasons line is simply omitted.
 */
function StepFailureReasons({ failures }: { failures: readonly ValidationFailure[] }) {
  return (
    <div data-testid="validation-step-failure" className="flex items-start gap-2 text-[11px]">
      <OctagonAlert
        className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[var(--color-phase-red)]"
        aria-hidden="true"
      />
      <div className="min-w-0 space-y-1">
        {failures.map((f) => (
          <div key={f.step}>
            <p className="font-medium text-foreground">{f.step} failed</p>
            {f.reasons.length > 0 && (
              <p className="mono text-[10px] leading-relaxed text-subtle">{f.reasons.join(' · ')}</p>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * The mutation step's detail strip (mutation-run-board F2 task 3) — rendered
 * directly BELOW the completion lane row that owns a mutation step carrying a
 * folded outcome, in the neutral inline-detail idiom {@link StepFailureReasons}
 * uses (not red — a mutation result is signal, not a failure). Shows the mutant
 * counts as `.chip` pills tinted by outcome tone — killed in the done colour,
 * SURVIVED in red (the actionable signal), no-coverage in warn — plus the mutated
 * scope. It renders whether the lane is live or collapsed to a receipt: the detail
 * is exactly what a reader opens the panel for, so the receipt must not hide it.
 * Task 4 adds the aggregate score (toned by band against the configured thresholds)
 * and the per-file scope breakdown (files / line ranges) below the counts row.
 *
 * The task names a "survivor breakdown"; the `MutationStepOutcome` contract carries
 * the survivor tally as an aggregate count (the chip strip above) and the mutated
 * SCOPE per file — it does not locate individual surviving mutants. So the breakdown
 * here is the per-file mutated scope (the AC's "files / line ranges"), the finest
 * grain the data supports — not a per-mutant survivor list.
 */
const MUTATION_COUNTS: readonly { key: keyof MutationStatusCounts; label: string; tone?: string }[] = [
  { key: 'killed', label: 'killed', tone: 'var(--color-done)' },
  { key: 'survived', label: 'survived', tone: 'var(--color-phase-red)' },
  { key: 'noCoverage', label: 'no coverage', tone: 'var(--color-warn)' },
  { key: 'timeout', label: 'timeout' },
];

/**
 * The score's band tone (task 4) — Stryker's own thresholds: at/above `high` the
 * score reads done, below `low` it reads the actionable red, and between the two
 * it reads warn. Absent thresholds leave the score untoned (there is no band to
 * judge it against — a fabricated colour would lie).
 */
function scoreTone(score: number, thresholds: MutationStepOutcome['thresholds']): string | undefined {
  if (thresholds === null) return undefined;
  if (score >= thresholds.high) return 'var(--color-done)';
  if (score < thresholds.low) return 'var(--color-phase-red)';
  return 'var(--color-warn)';
}

/** `[10, 20] → "10–20"`, `[3, 3] → "3"` — a single-line span collapses to the bare line. */
const formatRange = ([start, end]: readonly [number, number]): string =>
  start === end ? `${start}` : `${start}–${end}`;

/** The per-survivor disposition actions (F4 task 2), threaded from the detail
 *  page down to the SurvivorTriagePanel. Absent on surfaces that don't write. */
interface SurvivorTriageActions {
  readonly onMarkEquivalent?: (identity: MutantIdentity) => void;
  readonly onAccept?: (identity: MutantIdentity, reason: string) => void;
  readonly onHarden?: (identity: MutantIdentity) => void;
}

function MutationStepStrip({
  mutation,
  emoji,
  survivorActions,
}: {
  mutation: MutationStepOutcome;
  emoji: string;
  survivorActions?: SurvivorTriageActions;
}) {
  const files = mutation.scope.length;
  const tone = scoreTone(mutation.score, mutation.thresholds);
  return (
    <div data-testid="validation-mutation-strip" className="text-[11px]">
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
        <span className="inline-flex items-center gap-1 text-subtle">
          {/* The step's OWN emoji (data-driven), so the strip header can't drift from
              the mutation chip above it. */}
          <span aria-hidden="true">{emoji}</span>
          Mutation
        </span>
        <ol className="flex flex-wrap items-center gap-1.5">
          {MUTATION_COUNTS.map(({ key, label, tone: countTone }) => (
            <li
              key={key}
              className="chip"
              style={countTone !== undefined ? ({ '--phase': countTone } as CSSProperties) : undefined}
            >
              <span className="font-medium text-foreground">{mutation.counts[key]}</span>
              <span className="text-subtle">{label}</span>
            </li>
          ))}
        </ol>
        {/* No score chip when nothing was mutated: a legit skip folds to score 0
            with thresholds present, and a red "0% score" beside "no files mutated"
            would flag a non-failure. There is no score to judge without scope. */}
        {files > 0 && (
          <span
            data-testid="validation-mutation-score"
            className="chip"
            style={tone !== undefined ? ({ '--phase': tone } as CSSProperties) : undefined}
          >
            <span className="font-medium text-foreground">{mutation.score}%</span>
            <span className="text-subtle">score</span>
          </span>
        )}
        <div className="ml-auto flex items-center gap-3">
          <span data-testid="validation-mutation-scope" className="text-subtle">
            {files === 0 ? 'no files mutated' : `${files} ${files === 1 ? 'file' : 'files'} mutated`}
          </span>
          {/* The sampled Stryker-subtree footprint (mutation-resource-telemetry
              task 3), reusing the shared RunResourceFootprint. Memory-only
              (validation-surface-misreads-ready-to-land-fix task 2): Stryker is
              multi-core, so its >100% CPU sample is expected, not a runaway — the
              CPU figure and its warn are dropped, the memory near-OOM warn stays.
              Renders nothing when the outcome carried no samples (best-effort). */}
          <RunResourceFootprint resources={mutation.resources} memoryOnly />
        </div>
      </div>
      {/* The mutated scope breakdown — each file with its line ranges — so a reader
          can judge whether the run was scoped correctly. Omitted for a zero-scope
          outcome (the counts row's "no files mutated" already says it). */}
      {files > 0 && (
        <ol data-testid="validation-mutation-breakdown" className="mono mt-1.5 space-y-0.5 text-[10px] text-subtle">
          {mutation.scope.map((f) => (
            <li key={f.file} className="flex items-baseline gap-2">
              <span className="min-w-0 truncate text-muted-foreground">{f.file}</span>
              <span className="tabular-nums">
                {f.ranges.length > 0 ? f.ranges.map(formatRange).join(', ') : '—'}
              </span>
            </li>
          ))}
        </ol>
      )}
      {/* The per-survivor triage surface (mutation-survivor-triage F4). Each
          survivor's disposition is joined against the ledger server-side (F3's
          gateMutationStep) and rides `mutation.survivorTriage`; render it below
          the counts. Present (possibly non-empty) whenever the gate evaluated;
          absent on a display-only fold. */}
      {mutation.survivorTriage !== undefined && mutation.survivorTriage.length > 0 && (
        <div className="mt-2">
          <SurvivorTriagePanel
            rows={mutation.survivorTriage}
            {...(survivorActions?.onMarkEquivalent !== undefined ? { onMarkEquivalent: survivorActions.onMarkEquivalent } : {})}
            {...(survivorActions?.onAccept !== undefined ? { onAccept: survivorActions.onAccept } : {})}
            {...(survivorActions?.onHarden !== undefined ? { onHarden: survivorActions.onHarden } : {})}
          />
        </div>
      )}
    </div>
  );
}

/**
 * The reconcile lane's FAILURE reason section (land-failure-surfacing task 5) —
 * the SAME red inline pattern {@link StepFailureReasons} uses for a failed
 * completion step, rendered directly below the reconcile row: the failing rung + its
 * reason, the conflicting files, and the `/merge` next step on a conflict, so a
 * failed reconcile explicitly says why the row failed and how to recover.
 */
function ReconcileFailureReasons({
  failure,
  onRetryReconcile,
  retryInFlight = false,
}: {
  failure: ReconcileFailure;
  /** Fire a re-reconcile for the failing branch (retry-reconcile-action F4). The
   *  button is presence-gated on this handler AND `failure.branch`; the host POSTs
   *  /reconcile with the id. Absent ⇒ no button, the CLI command stands. */
  onRetryReconcile?: (branch: string) => void;
  /** A reconcile the host already fired is in flight — disables the button as a
   *  best-effort double-dispatch guard (the server's per-item gate is the backstop). */
  retryInFlight?: boolean;
}) {
  // Narrow the failing branch to a const so the Retry button's onClick closure keeps
  // the non-undefined narrowing without an `as` cast (forbidden by ARCHITECTURE).
  const retryBranch = failure.branch;
  return (
    <div data-testid="reconcile-failure" className="flex items-start gap-2 text-[11px]">
      <OctagonAlert className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[var(--color-phase-red)]" aria-hidden="true" />
      <div className="min-w-0 flex-1 space-y-1.5">
        <p className="font-medium text-foreground">
          {failure.rung} failed
          {/* A CATCH-UP conflict (F3) names the WHY — "main moved after this branch was
              reconciled" + the main SHA it moved to — REPLACING the raw exitReason so an
              operator reads the cause, not the `catch-up-conflict` slug. A first-time
              conflict keeps its raw reason. */}
          {failure.mainMoved !== undefined ? (
            <span className="text-subtle">
              : main moved after this branch was reconciled
              {failure.mainMoved.toSha !== undefined && (
                <span className="mono"> · main@{failure.mainMoved.toSha.slice(0, 7)}</span>
              )}
            </span>
          ) : (
            failure.reason !== undefined && <span className="mono text-subtle">: {failure.reason}</span>
          )}
        </p>
        {failure.conflictedFiles !== undefined && failure.conflictedFiles.length > 0 && (
          <p className="mono text-[10px] leading-relaxed text-subtle">{failure.conflictedFiles.join(' · ')}</p>
        )}
        {/* The recovery ACTION (F4) — re-run the deterministic reconcile ladder against
            main's current tip — sits beside the copyable CLI fallback. Presence-gated on
            a wired handler AND a known branch; disabled while a reconcile is in flight so
            a double-click cannot stack a duplicate dispatch. */}
        {onRetryReconcile !== undefined && retryBranch !== undefined && (
          <button
            type="button"
            data-testid="retry-reconcile"
            disabled={retryInFlight}
            onClick={() => onRetryReconcile(retryBranch)}
            className="inline-flex items-center gap-1 rounded border border-[var(--color-border)] px-2 py-0.5 text-[10px] font-medium text-foreground transition-colors hover:bg-[var(--color-hover)] disabled:cursor-not-allowed disabled:opacity-50"
          >
            <RotateCcw className="h-3 w-3" aria-hidden="true" />
            Retry reconcile
          </button>
        )}
        {failure.recoveryCommand !== undefined && (
          <CopyableCommand command={failure.recoveryCommand} label="Copy reconcile command" />
        )}
        {failure.nextStep !== undefined && <p className="text-[10px] text-muted-foreground">{failure.nextStep}</p>}
      </div>
    </div>
  );
}

/**
 * A copyable one-line command with a copy affordance — the SINGLE copy idiom both
 * the completion-failure block (`tiny-brain complete`) and the reconcile-failure block
 * (`tiny-brain reconcile-branch`, land-failure-surfacing task 5) render, so the two
 * cannot drift. The tick reverts after {@link COPIED_FEEDBACK_MS}; a changed command
 * and unmount clear the pending revert. Optional testids preserve the completion
 * block's existing hooks (`validation-complete-cmd` / `validation-complete-copied`).
 */
function CopyableCommand({
  command,
  label,
  codeTestId,
  copiedTestId,
}: {
  command: string;
  label: string;
  codeTestId?: string;
  copiedTestId?: string;
}) {
  const [copied, setCopied] = useState(false);
  const copiedTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => {
    setCopied(false);
    return () => clearTimeout(copiedTimer.current);
  }, [command]);
  return (
    <div className="flex min-w-0 flex-1 items-center gap-2 rounded-lg border border-border bg-background p-1.5 pl-2.5">
      <code
        {...(codeTestId !== undefined ? { 'data-testid': codeTestId } : {})}
        className="mono min-w-0 flex-1 truncate text-[11px] text-foreground"
      >
        {command}
      </code>
      <button
        type="button"
        aria-label={label}
        className="inline-flex shrink-0 items-center gap-1 rounded-md px-2 py-1 text-[10px] text-subtle transition-colors hover:text-foreground"
        onClick={() => {
          void (async () => {
            try {
              await navigator.clipboard.writeText(command);
              clearTimeout(copiedTimer.current);
              setCopied(true);
              copiedTimer.current = setTimeout(() => setCopied(false), COPIED_FEEDBACK_MS);
            } catch {
              // A missing/denied clipboard must not flip to a false tick.
            }
          })();
        }}
      >
        {copied ? (
          <Check
            {...(copiedTestId !== undefined ? { 'data-testid': copiedTestId } : {})}
            className="h-3 w-3 text-green-500"
            aria-hidden="true"
          />
        ) : (
          <Copy className="h-3 w-3" aria-hidden="true" />
        )}
        Copy
      </button>
    </div>
  );
}

/** How long the copy affordance shows its tick before reverting. */
const COPIED_FEEDBACK_MS = 2_000;

/**
 * The bottom failed-run block: the recovery affordances — the in-place re-run
 * (POSTs the F3 revalidate route, disabled while one is in flight so a second
 * click cannot stack the 409-rejected duplicate) and the copyable manual
 * `tiny-brain complete` fallback — preceded by a banner ONLY for failures that
 * did not render inline. Per-step reasons normally render in {@link
 * StepFailureReasons} below their lane; the banner here is the fallback for
 * `unmatched` failures (a non-ok outcome whose label matched no chip, so it has
 * no lane to sit under) and the `laneCrash` case (a `failed` pill with no
 * step-level failures at all — nothing inline to attach to).
 */
function FailureBlock({
  failures,
  laneCrash,
  onRerun,
  rerunning,
  completeCommand,
}: {
  /** Failures that matched no lane chip — rendered here so no reason is dropped. */
  failures: readonly ValidationFailure[];
  /** A `failed` pill with no step-level failures — name it generically. */
  laneCrash: boolean;
  onRerun?: () => void;
  rerunning?: boolean;
  completeCommand?: string;
}) {
  return (
    <div className="border-t border-[var(--color-border)]">
      {(laneCrash || failures.length > 0) && (
        <div
          data-testid="validation-failure"
          className="flex items-start gap-2 px-3 py-2 text-[11px]"
        >
          <OctagonAlert
            className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[var(--color-phase-red)]"
            aria-hidden="true"
          />
          <div className="min-w-0 space-y-1">
            {laneCrash ? (
              <p className="font-medium text-foreground">Validation failed</p>
            ) : (
              failures.map((f) => (
                <div key={f.step}>
                  <p className="font-medium text-foreground">{f.step} failed</p>
                  {f.reasons.length > 0 && (
                    <p className="mono text-[10px] leading-relaxed text-subtle">{f.reasons.join(' · ')}</p>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {(onRerun !== undefined || completeCommand !== undefined) && (
        <div className="flex flex-wrap items-center gap-2 border-t border-[var(--color-border)] px-3 py-2">
          {onRerun !== undefined && (
            <button
              type="button"
              disabled={rerunning}
              onClick={onRerun}
              className={cn(
                'inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-[11px] font-medium transition-colors',
                'text-[var(--color-phase-red)] hover:bg-[color-mix(in_oklab,var(--color-phase-red)_12%,transparent)]',
                'disabled:cursor-not-allowed disabled:opacity-60',
              )}
            >
              <RotateCcw className={cn('h-3 w-3', rerunning && 'animate-spin')} aria-hidden="true" />
              {rerunning ? 'Re-running…' : 'Re-run validation'}
            </button>
          )}
          {completeCommand !== undefined && (
            <CopyableCommand
              command={completeCommand}
              label="Copy complete command"
              codeTestId="validation-complete-cmd"
              copiedTestId="validation-complete-copied"
            />
          )}
        </div>
      )}
    </div>
  );
}

/** One row of the validation step timeline (F6 task 1) — a lane node, a merge
 *  diamond, or a node-less detail/connector row. */
interface TimelineStepDescriptor {
  key: string;
  node?: StepNodeState;
  shape?: 'circle' | 'diamond';
  tint?: string;
  body: ReactNode;
}

const RED_TINT = 'color-mix(in oklab, var(--color-phase-red) 6%, transparent)';
const MERGE_TINT = 'color-mix(in oklab, var(--color-primary) 5%, transparent)';

/**
 * Assemble the ordered timeline steps (validation-panel-step-timeline F6 task 1)
 * from the active panel state: a NODE-bearing step per lane, then its node-less
 * detail rows (mutation strip / failure reasons / conflict block — a connector
 * rail keeps the thread continuous), and the merge DIAMOND step after the
 * reconcile lane. Pure over the already-derived lanes + merge boundary — it
 * invents no state, only arranges what the panel state carries.
 */
function buildTimelineSteps(
  state: Extract<ValidationPanelState, { kind: 'active' }>,
  failuresForLane: (lane: ValidationLane) => ValidationFailure[],
  retry?: { onRetryReconcile?: (branch: string) => void; inFlight?: boolean },
  survivorActions?: SurvivorTriageActions,
): TimelineStepDescriptor[] {
  const steps: TimelineStepDescriptor[] = [];
  for (const lane of state.lanes) {
    const laneFailures = failuresForLane(lane);
    const mutationChip = lane.chips.find((c) => c.mutation !== undefined);
    steps.push({ key: `lane-${lane.kind}`, node: laneNodeState(lane), body: <ValidationLaneRow lane={lane} flush /> });
    if (mutationChip?.mutation !== undefined) {
      steps.push({
        key: `mutation-${lane.kind}`,
        body: (
          <MutationStepStrip
            mutation={mutationChip.mutation}
            emoji={mutationChip.emoji}
            {...(survivorActions !== undefined ? { survivorActions } : {})}
          />
        ),
      });
    }
    if (laneFailures.length > 0) {
      steps.push({ key: `failure-${lane.kind}`, tint: RED_TINT, body: <StepFailureReasons failures={laneFailures} /> });
    }
    if (lane.reconcileFailure !== undefined) {
      steps.push({
        key: `reconcile-failure-${lane.kind}`,
        tint: RED_TINT,
        body: (
          <ReconcileFailureReasons
            failure={lane.reconcileFailure}
            {...(retry?.onRetryReconcile !== undefined ? { onRetryReconcile: retry.onRetryReconcile } : {})}
            retryInFlight={retry?.inFlight ?? false}
          />
        ),
      });
    }
    // The merge boundary sits immediately below the reconcile lane — before the
    // post-merge lane (reconcile-segment task 1), rendered as the diamond node.
    if (lane.kind === 'reconcile' && state.merge !== undefined) {
      steps.push({
        key: 'merge',
        node: mergeNodeState(state.merge),
        shape: 'diamond',
        tint: MERGE_TINT,
        body: <MergeMarker state={state.merge} />,
      });
    }
  }
  return steps;
}

/**
 * The Validation panel (validation-pipeline-visibility F4 task 2) — the pure
 * render of {@link ValidationPanelState} in the ReconcileStrip slot: a header
 * (shield · "Validation" · pill · elapsed · open-run link) and, below it, the
 * lanes as a vertical step timeline (validation-panel-step-timeline F6): one
 * status node per lane, a diamond for the merge step, connected by a single
 * thread. A `hidden` state (the git-terminal predicate said no) renders nothing.
 */
export function ValidationPanel({
  state,
  runHref,
  onRerun,
  rerunning,
  completeCommand,
  landed,
  validation,
  onRetryReconcile,
  retryReconcileInFlight,
  onMarkEquivalentSurvivor,
  onAcceptSurvivor,
  onHardenSurvivor,
}: ValidationPanelProps) {
  if (state.kind === 'hidden') return null;

  const survivorActions: SurvivorTriageActions | undefined =
    onMarkEquivalentSurvivor !== undefined || onAcceptSurvivor !== undefined || onHardenSurvivor !== undefined
      ? {
          ...(onMarkEquivalentSurvivor !== undefined ? { onMarkEquivalent: onMarkEquivalentSurvivor } : {}),
          ...(onAcceptSurvivor !== undefined ? { onAccept: onAcceptSurvivor } : {}),
          ...(onHardenSurvivor !== undefined ? { onHarden: onHardenSurvivor } : {}),
        }
      : undefined;

  // The header pill NAMES the lifecycle phase the board card names — sourced from
  // the server-computed `validation` LifecyclePhase (the detail pages always supply
  // it; the legacy `state.deliveryPill` fallback is retired, fix
  // retire-legacy-deliverypill-from-board-card task 2). An idle / passed / TDD phase
  // names nothing, and the panel's own ValidationPill (which distinguishes passed /
  // pending) stands.
  const phasePill = phasePillFromLifecycle(validation);
  const pill = phasePill ?? { ...PILL[state.pill], testId: undefined };
  // A named delivery FAILURE reds the shield even when the completion pill reads
  // `passed` (a reconcile / merge red rides atop a green suite) — so the shield
  // agrees with the phase pill, never a green shield over "reconcile failed".
  const deliveryFailed = validation?.status === 'failed';
  const isRed = deliveryFailed || state.pill === 'failed' || state.pill === 'regression';
  const Shield = isRed ? ShieldX : ShieldCheck;
  const shieldTone = isRed
    ? 'var(--color-phase-red)'
    : state.pill === 'passed'
      ? 'var(--color-done)'
      : state.pill === 'pending'
        ? 'var(--color-subtle)'
        : 'var(--color-primary)';

  // Failure distribution: each failure whose step matches a failed chip in a lane
  // renders inline below that lane; any failure that matches NO lane chip (the
  // producer builds `failures` from every non-ok completion outcome, independent of
  // the configured step defs that name the chips — so labels can diverge) falls
  // BACK to the bottom block, so a reason is never silently dropped (adversarial
  // review of ba33cdc56). A `failed` pill with no step-level failures is a lane
  // crash — the bottom block names it generically.
  const panelFailures = state.pill === 'failed' ? (state.failures ?? []) : [];
  const failuresForLane = (lane: ValidationLane): ValidationFailure[] =>
    panelFailures.filter((f) => lane.chips.some((c) => c.state === 'failed' && c.label === f.step));
  const matchedSteps = new Set(state.lanes.flatMap((l) => failuresForLane(l).map((f) => f.step)));
  const unmatchedFailures = panelFailures.filter((f) => !matchedSteps.has(f.step));
  const laneCrash = state.pill === 'failed' && panelFailures.length === 0;

  // The footer's "what's next" line is PHASE-AWARE (land-failure-surfacing task 3):
  // the completion suite can read `passed` while the delivery phase (reconcile /
  // merge) has failed or is in flight, and the footer must NEVER read "Ready to land"
  // then. It reuses the SAME shared phase label the header pill shows (`pill.label`,
  // via `describeLifecyclePhasePill`) so the two cannot drift (ADR-0038). Scoped to
  // the delivery stages (reconciliation / merge) — an item_completion failure drives
  // the failed pill (FailureBlock) and post_merge the regression pill, both above.
  // A legacy consumer without `validation` keeps the completion-pill footer below.
  const deliveryPhaseFailed =
    validation !== undefined &&
    (validation.pipeline === 'reconciliation' || validation.pipeline === 'merge') &&
    validation.status === 'failed';
  const deliveryPhaseRunning =
    validation !== undefined &&
    (validation.pipeline === 'reconciliation' || validation.pipeline === 'merge') &&
    validation.status === 'running';

  return (
    <div
      data-testid="validation-panel"
      data-pill={state.pill}
      role="status"
      className="panel-flat overflow-hidden rounded-xl text-xs"
    >
      <div className="flex items-center gap-2 px-3 py-2">
        <Shield className="h-4 w-4 shrink-0" style={{ color: shieldTone }} aria-hidden="true" />
        <h3 className="text-xs font-semibold text-foreground">Validation</h3>
        <span className={cn('pill inline-flex items-center gap-1', pill.cls)} data-testid={pill.testId}>
          {pill.live && <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-current" aria-hidden="true" />}
          {pill.label}
        </span>
        {state.merged === true && <span className="pill pill-blue">merged</span>}
        <div className="ml-auto flex items-center gap-3">
          {/* No `since` ⇒ the all-pending preview stands on config with no run to
              anchor an elapsed readout. */}
          {state.since !== undefined && (
            <Elapsed since={state.since} until={state.until} live={state.pill === 'validating'} />
          )}
          {runHref !== undefined && (
            <a
              href={runHref}
              className="inline-flex items-center gap-1 text-subtle transition-colors hover:text-foreground"
            >
              open run
              <ExternalLink className="h-3 w-3" aria-hidden="true" />
            </a>
          )}
        </div>
      </div>

      <div className="border-t border-[var(--color-border)]">
        {/* Assemble the ordered step timeline (validation-panel-step-timeline F6
            task 1): one NODE-bearing step per lane, each followed by its node-less
            detail rows (mutation strip, failure reasons, conflict block — a
            connector rail with no node so the thread stays unbroken), and the
            merge DIAMOND step after the reconcile lane. First/last flags (computed
            below) trim the thread so it starts and ends at a node. */}
        {(() => {
          const steps = buildTimelineSteps(
            state,
            failuresForLane,
            {
              ...(onRetryReconcile !== undefined ? { onRetryReconcile } : {}),
              inFlight: retryReconcileInFlight ?? false,
            },
            survivorActions,
          );
          // Anchor the thread to NODES, not row positions: it starts at the first
          // node-bearing step and ends at the LAST one, so a trailing node-less
          // detail row (e.g. a completion-only failed panel's failure block) never
          // leaves the thread dangling past the final node.
          const firstNodeIndex = steps.findIndex((s) => s.node !== undefined);
          const lastNodeIndex = steps.reduce((acc, s, i) => (s.node !== undefined ? i : acc), -1);
          return steps.map((step, i) => (
            <TimelineStep
              key={step.key}
              node={step.node}
              shape={step.shape}
              tint={step.tint}
              first={i === firstNodeIndex}
              last={i === lastNodeIndex}
              tail={i > lastNodeIndex}
            >
              {step.body}
            </TimelineStep>
          ));
        })()}
      </div>

      {/* The bottom block depends on the state: a failed completion run shows
          the failure banner + recovery (mock D); a post-merge regression shows
          the failing evidence (mock G); otherwise a one-line footer. */}
      {state.pill === 'failed' ? (
        <FailureBlock
          failures={unmatchedFailures}
          laneCrash={laneCrash}
          onRerun={onRerun}
          rerunning={rerunning}
          completeCommand={completeCommand}
        />
      ) : state.pill === 'regression' ? (
        <>
          {state.evidence !== undefined && <EvidenceBlock evidence={state.evidence} />}
          <div
            data-testid="validation-footer"
            className="flex items-center gap-1.5 border-t border-[var(--color-border)] px-3 py-2 text-[11px] text-muted-foreground"
          >
            <Info className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
            <span>The verdict covers a range of lands on main — a red here triages through the main-broken overlay.</span>
          </div>
        </>
      ) : deliveryPhaseFailed ? (
        // A delivery FAILURE (reconcile / merge red) while the completion suite
        // passed — NAME the failing phase, never "Ready to land" (land-failure-
        // surfacing task 3). The reconcile lane above shows the failing rung; task 5
        // adds the reason + /merge next step there.
        <div
          data-testid="validation-footer"
          className="flex items-center gap-1.5 border-t border-[var(--color-border)] px-3 py-2 text-[11px]"
          style={{ color: 'var(--color-phase-red)' }}
        >
          <ShieldX className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
          <span>
            <span className="font-medium">{sentenceCase(pill.label)}</span> — land is held until it is resolved.
          </span>
        </div>
      ) : deliveryPhaseRunning ? (
        // Reconcile / merge in flight while the suite passed — name the LIVE phase,
        // never "Ready to land" (land-failure-surfacing task 3).
        <div
          data-testid="validation-footer"
          className="flex items-center gap-1.5 border-t border-[var(--color-border)] px-3 py-2 text-[11px] text-muted-foreground"
        >
          <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-current" aria-hidden="true" />
          <span>{sentenceCase(pill.label)}… — land completes when it settles.</span>
        </div>
      ) : state.pill === 'passed' && landed === true ? (
        // A landed + passed item is already on main — there is no pending land, so
        // the "Ready to land — post-merge regression runs after the merge" footer
        // would be a lie. Drop the footer row entirely (fix
        // validation-footer-landed-and-post-land-single-phase task 1). The strip /
        // receipt above already carries the passed-and-done fact.
        null
      ) : (
        <div
          data-testid="validation-footer"
          className="flex items-center gap-1.5 border-t border-[var(--color-border)] px-3 py-2 text-[11px] text-muted-foreground"
        >
          {state.pill === 'pending' ? (
            <>
              <Info className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
              <span>Not yet validated — validation runs when dispatched.</span>
            </>
          ) : state.pill === 'passed' ? (
            <>
              <Check className="h-3.5 w-3.5 shrink-0 text-[var(--color-done)]" aria-hidden="true" />
              {/* Provisional-ready (F2): when F1 supplies the reconciled-against SHA, the
                  footer names the main the item is ready AS OF and warns that Merging
                  re-checks against main's live tip first; absent ⇒ today's plain copy. */}
              {state.reconciledAgainst !== undefined && state.reconciledAgainst.length > 0 ? (
                <span>
                  <span className="font-medium text-[var(--color-done)]">
                    Ready to land as of main@{state.reconciledAgainst.slice(0, 7)}
                  </span>
                  . Merging re-checks against main&apos;s current tip first.
                </span>
              ) : (
                <span>
                  <span className="font-medium text-[var(--color-done)]">Ready to land</span> — post-merge
                  regression runs after the merge.
                </span>
              )}
            </>
          ) : state.merged === true ? (
            <>
              <Info className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
              <span>The verdict covers a range of lands on main, not this item alone.</span>
            </>
          ) : (
            <>
              <Info className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
              <span>Land is held until the work-item suite passes.</span>
            </>
          )}
        </div>
      )}
    </div>
  );
}

export default ValidationPanel;
