/**
 * Fetch ONE feature's server-composed `detail` payload (work-item-detail-service-
 * rewrite / props-in-ui): the same per-feature endpoint that carried the retired
 * `validationInputs` now attaches a `ComposedFixDetail` under `detail` (the shared
 * core producers' outputs), which FeatureDetail assembles the ValidationPanel from
 * straight — the props-in path FixDetail uses. `undefined` when the wire threaded
 * none (older payload / a fail-soft detail-service degrade) — the panel then folds
 * to hidden, never an error surface.
 */
export async function fetchFeatureDetail(
  repoId: string,
  planId: string,
  featureId: string,
): Promise<ComposedFixDetail | undefined> {
  const url = `${API_BASE}/repos/${repoId}/plans/${encodeURIComponent(planId)}/features/${encodeURIComponent(featureId)}`;
  const response = await fetch(url);
  if (!response.ok) {
    const errorBody = (await response.json().catch(() => null)) as { error?: unknown } | null;
    const reason = errorBody && typeof errorBody.error === 'string' ? errorBody.error : `HTTP ${response.status}`;
    throw new Error(reason);
  }
  const data = (await response.json()) as { detail?: ComposedFixDetail };
  return data.detail;
}

