// Delivery surface (delivery-convergence F6) — GET acceptance state and POST the
// land/raise/reject/teardown actions. The UI stays dumb: POSTs carry only the
// work-item id (+ the action's own fields); the server assembles everything.
import type {
  AcceptanceState,
  BranchRunProvenance,
  DeliverByRaiseResult,
  DeliveredTask,
  DeliveryModel,
  DeliveryQueueStatus,
  PrdTeardownModel,
  WorktreeContents,
  WorktreeProvenance,
} from '@magic-ingredients/tiny-brain-core';

export interface DeliveryWorktreeState {
  workItemId: string;
  acceptanceState: AcceptanceState;
  done?: boolean;
  landed?: boolean;
  reviewOutcome?: string;
  /** Whether an actual worker run backs this work item — gates the island's Reject. */
  isWorkerRun?: boolean;
}

/**
 * One deliverable worktree row on the Done tab (F10 task 4): the merge unit,
 * keyed by branch, with its contents (PRD/feature(s)/fix(es) completed on it) and
 * a focal status. The Done tab groups + labels these client-side.
 */
export interface DeliveryWorktreeRow {
  branch: string;
  status: DeliveryQueueStatus;
  /** The branch's work kind from its ref prefix (`fix/`/`spike/`), for the card's type glyph; `undefined` for unprefixed branches. */
  kind?: 'fix' | 'spike';
  /** The branch's derived acceptance state — drives the island's gating directly (no second fetch). */
  acceptanceState: AcceptanceState;
  /** Whether an actual worker run backs this branch — gates the island's Reject. */
  isWorkerRun: boolean;
  /**
   * The ONE derived delivery model for this branch (work-item-provenance F6):
   * done/landed/live/deliveredItems/landAvailability, assembled server-side via
   * `deriveDeliveryModel`. Every delivery pixel (island tally, incomplete-work
   * note, land availability) renders from THIS — never `RunRecord.status`, a
   * contents tally, or a standalone conflict probe. Required so a dropped thread
   * along the wiring is a compile error, not a silently contradictory surface.
   */
  model: DeliveryModel & {
    /**
     * The branch's persisted latest verdict + reason (fix
     * verify-outcomes-invisible-in-ui task 1) — the strip's reconstruction
     * source for the failure family, which `landAvailability` deliberately
     * reads as `unknown`.
     */
    lastReconcile?: LastReconcileFeed;
    /**
     * The branch's LIVE machinery run (an unended reconcile/land — e.g. a CLI
     * `tiny-brain reconcile-branch`); the surface subscribes to its stream so
     * "Verifying…" renders whoever started it (task 2).
     */
    liveReconcileRunId?: string;
  };
  contents: WorktreeContents;
  /** Branch provenance for the Land-this-work island — ahead/behind, mergeability, diff size, on-disk footprint. */
  provenance?: WorktreeProvenance;
  /** The worker run(s) that produced this branch — most-recent first; empty for an interactive worktree. */
  runs?: readonly BranchRunProvenance[];
  /** The tasks completed on this branch with their green SHA — the island's "Tasks delivered" list. */
  tasksDelivered?: readonly DeliveredTask[];
  /** Commits on this branch not yet on main (`base..branch`), most-recent first — what a teardown would discard. */
  unlandedCommits?: readonly { readonly sha: string; readonly subject: string }[];
}

export type DeliveryActionName = 'land' | 'raise' | 'reject' | 'teardown' | 'reconcile' | 'restore';

export async function fetchDeliveryState(repoId: string): Promise<DeliveryWorktreeState[]> {
  const response = await fetch(`${API_BASE}/repos/${repoId}/delivery`);
  if (!response.ok) {
    throw new Error('Failed to fetch delivery state');
  }
  const data = await response.json();
  return data.worktrees ?? [];
}

/**
 * The deliverable worktrees — one row per branch carrying done-but-unlanded work
 * (F10 task 4), assembled server-side. The UI sends only the repo id and groups
 * + labels the rows client-side.
 */
export async function fetchDeliveryWorktrees(repoId: string): Promise<DeliveryWorktreeRow[]> {
  const response = await fetch(`${API_BASE}/repos/${repoId}/delivery/worktrees`);
  if (!response.ok) {
    throw new Error('Failed to fetch delivery worktrees');
  }
  const data = await response.json();
  return data.worktrees ?? [];
}

/**
 * ONE deliverable worktree's full provenance, fetched on demand for the single
 * branch a detail surface has opened (dashboard-landing-perf task 3). The server
 * runs the expensive du+merge-tree walk for only this branch, so the landing
 * surface stays O(1) per opened item. `null` when the branch is not (or no
 * longer) deliverable. The branch may contain slashes (`fix/foo`) — each segment
 * is encoded, the separators preserved as path segments the `:branch{.+}` route
 * captures.
 */
export async function fetchDeliveryWorktree(
  repoId: string,
  branch: string,
): Promise<DeliveryWorktreeRow | null> {
  const encodedBranch = branch.split('/').map(encodeURIComponent).join('/');
  const response = await fetch(`${API_BASE}/repos/${repoId}/delivery/worktrees/${encodedBranch}`);
  if (!response.ok) {
    throw new Error('Failed to fetch delivery worktree');
  }
  const data = await response.json();
  return data.worktree ?? null;
}

