export interface SpikeDetailProps {
  spike: SpikeProgress;
  worktreeStatus: SpikeWorktreeStatus;
  repoId: string;
  /** Repo-wide live telemetry feed, overlaid onto the spike's task rows. */
  telemetry?: readonly TelemetryEvent[];
  /** The spike's live worker run (F1 payload), or null. Drives the running-run
   *  surface; when null the launchable rail leads instead. */
  activeRun?: SpikeActiveRun | null;
  /** The spike's latest resumable/failed run (F1 payload), or null. Drives the
   *  resume/continue affordance; when null it is absent. */
  resumableRun?: SpikeResumableRun | null;
  onWorktreeCleared?: () => void;
  onOutcomeRecorded?: () => void;
  /** Open the WorkerRun island for the spike's live run — the endcap's
   *  click-to-watch (spike-command-surface-parity), mirroring FixDetail's
   *  `onOpenRun`. When wired, the running end-cap becomes a "click to view"
   *  button instead of an inert cap + inline transcript. */
  onOpenRun?: (runId: string) => void;
}

/**
 * Hermetic spike pipeline — see `pipelines/spike.ts` in core. The
 * default spike strategy runs `green → complete` with no review gate,
 * so the dashboard passes an empty pipeline and TaskRow renders just
 * the Green pill per task. Correctness for a spike is captured by the
 * terminal frontmatter status (validated / invalidated / abandoned),
 * not a pipeline review.
 */
const SPIKE_PIPELINE_STEPS: PipelineStep[] = [];

// Lowercase status word for the header eyebrow ("Spike · in progress"),
// mirroring FixDetail. Only the three lifecycle statuses — a terminal spike
// (any verdict) reads as completed; the verdict is not a status.
const SPIKE_EYEBROW_WORD: Record<SpikeStatus, string> = {
  not_started: 'not started',
  in_progress: 'in progress',
  validated: 'completed',
  invalidated: 'completed',
  abandoned: 'completed',
};

// Eyebrow colour per status — live blue for in progress, done for completed,
// neutral otherwise.
const SPIKE_EYEBROW_COLOR: Record<SpikeStatus, string> = {
  not_started: 'text-subtle',
  in_progress: 'text-blue',
  validated: 'text-done',
  invalidated: 'text-done',
  abandoned: 'text-done',
};

/**
 * Map an outcome-table result marker to a badge colour. The well-known
 * tokens (PASS / FAIL / PARTIAL / SKIP) get coloured chips; anything
 * else gets a neutral chip so new vocabulary the author invents on a
 * spike-by-spike basis still renders something readable.
 */
function criterionResultTone(marker: string): string {
  const token = marker.trim().toUpperCase();
  if (token === 'PASS' || token === 'PASSED') {
    return 'border-green-500/40 text-green-600 dark:text-green-400 bg-green-500/10';
  }
  if (token === 'FAIL' || token === 'FAILED') {
    return 'border-red-500/40 text-red-600 dark:text-red-400 bg-red-500/10';
  }
  if (token === 'PARTIAL' || token === 'PARTIALLY') {
    return 'border-amber-500/40 text-amber-600 dark:text-amber-400 bg-amber-500/10';
  }
  if (token === 'SKIP' || token === 'SKIPPED' || token === 'N/A') {
    return 'border-muted-foreground/30 text-muted-foreground';
  }
  return 'border-muted-foreground/30 text-muted-foreground';
}

const VALID_VERDICTS: ReadonlySet<ReviewVerdict> = new Set<ReviewVerdict>([
  'clean',
  'needs-refactoring',
]);

/**
 * SpikeProgressTask carries a wider `verdict?: string` than the
 * dashboard's ReviewRecord (`'clean' | 'needs-refactoring'`). Narrow at
 * the boundary: drop any verdict the renderer doesn't know about rather
 * than smuggle a wider type through with a cast.
 */
function toTaskRowTask(
  task: SpikeProgressTask,
  spikeId: string,
  telemetry: readonly TelemetryEvent[],
): TaskRowTask {
  // Live overlay from the shared telemetry feed (spike task ref), so a
  // pre-commit phase change surfaces on the spike pills without a refetch.
  const derivedState = task.uuid
    ? deriveTaskOverlay(telemetry, { kind: 'spike', spike: spikeId, task: task.uuid })
    : undefined;
  const reviews: TaskRowTask['reviews'] = task.reviews
    ? Object.fromEntries(
        Object.entries(task.reviews).map(([key, value]) => [
          key,
          {
            ...value,
            verdict:
              value.verdict && VALID_VERDICTS.has(value.verdict as ReviewVerdict)
                ? (value.verdict as ReviewVerdict)
                : undefined,
          },
        ]),
      )
    : undefined;
  return {
    ...task,
    status: (task.status as TaskRowTask['status']) ?? 'not_started',
    pipelineType: task.pipelineType ?? 'spike',
    reviews,
    ...(derivedState ? { derivedState } : {}),
  };
}

export function SpikeDetail({
  spike,
  worktreeStatus,
  repoId,
  telemetry = [],
  activeRun = null,
  resumableRun = null,
  onWorktreeCleared,
  onOutcomeRecorded,
  onOpenRun,
}: SpikeDetailProps) {
  const status = narrowSpikeStatus(spike.status);
  const isTerminal = SPIKE_TERMINAL_STATUSES.has(status);
  const [cleanupOpen, setCleanupOpen] = useState(false);
  // A held resume/continue fault — the POST is fire-and-refresh (the new run
  // surfaces as activeRun over the normal SSE tick), so only its failure needs
  // a local slot.
  const [runNotice, setRunNotice] = useState<string | null>(null);

  // The single "has a live run to stream" fact: a non-terminal spike with a run
  // id on the payload. Capturing the id (rather than re-deriving it with a `!`
  // later) proves the stream target is a string; a terminal spike never
  // resurrects the surface from a stale activeRun.
  const liveRunId = !isTerminal ? activeRun?.runId : undefined;
  const hasLiveRun = liveRunId !== undefined;
  // The resumable/failed run to offer resume/continue for: a non-terminal spike
  // with no live run (a live run streams instead) and a resumable projection on
  // the payload. A terminal spike is finished — a lingering resumable run never
  // offers resume/continue.
  const resumable = !isTerminal && !hasLiveRun ? resumableRun : null;
  // The launchable rail leads only when the spike is non-terminal AND has no run
  // to show (live or resumable) — the running / resume surfaces take its place.
  // Derived from the SAME liveRunId / resumable facts so the three surfaces are
  // mutually exclusive and the launch rail can never double up with either.
  const launchable = !isTerminal && !hasLiveRun && resumable === null;

  const onResume = (runId: string) => {
    setRunNotice(null);
    void postRunResume(repoId, runId).catch(() => setRunNotice('Resume failed — try again.'));
  };
  // Continue the item's latest continuable run onto its EXISTING worktree — the
  // POST carries only the spike work-ref; the server resolves the run.
  const onContinue = () => {
    setRunNotice(null);
    void postLaunchContinue(repoId, `spike:${spike.id}`).catch(() =>
      setRunNotice('Continue failed — try again.'),
    );
  };

  // Spikes run the hermetic green→complete pipeline (no review gate), so a
  // task is either done or not — progress is a simple done/total ratio.
  const totalTasks = spike.tasks.length;
  const completedCount = spike.tasks.filter((t) => t.status === 'completed').length;
  const supersededCount = spike.tasks.filter((t) => t.status === 'superseded').length;
  const doneTasks = completedCount + supersededCount;
  const left = totalTasks - doneTasks;
  const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
  const progressDetail =
    supersededCount > 0
      ? `${completedCount} done · ${supersededCount} superseded · ${left} left`
      : `${doneTasks} done · ${left} left`;

  return (
    <div className="h-full flex flex-col">
      <div className="flex-1 overflow-y-auto px-7 py-6">
        <div className="mx-auto max-w-4xl space-y-6">

          {/* Header — the shared DetailHeader shell (eyebrow + title + id copy,
              then the status pill / created / task-count meta). A spike has no
              merge/deliver affordance — its worktree is teardown-only, surfaced
              by the cleanup island below — so no rail. */}
          <DetailHeader
            testId="spike-detail-header"
            eyebrow={
              <p data-testid="spike-eyebrow" className={cn('eyebrow text-[10px]', SPIKE_EYEBROW_COLOR[status])}>
                Spike · {SPIKE_EYEBROW_WORD[status]}
              </p>
            }
            title={<h1 className="display text-2xl font-bold leading-snug">{spike.title}</h1>}
            titleAdornment={<CopyIdButton value={spike.id} kind="Spike" className="flex-shrink-0" />}
            meta={
              // The eyebrow already states the lifecycle status (matching the
              // PRD/fix headers), so the header carries no separate status pill.
              // Timebox rides the meta line here (beside created / task count)
              // rather than a standalone body panel.
              <span className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-muted-foreground">
                <span>created {new Date(spike.created).toLocaleDateString()}</span>
                {totalTasks > 0 && (
                  <>
                    <span aria-hidden="true">·</span>
                    <span>{totalTasks} {totalTasks === 1 ? 'task' : 'tasks'}</span>
                  </>
                )}
                <span data-testid="spike-header-timebox" className="flex items-center gap-2">
                  <span aria-hidden="true">·</span>
                  <TimeboxCountdown created={spike.created} timebox={spike.timebox} status={status} />
                </span>
              </span>
            }
          />

          {/* Run rail — the launch surface (spike-detail-launch-ui F2). The
              kind-agnostic worker dispatch rail replaces the retired provision-
              only launch button + relaunch snippet: dispatching POSTs
              { item: "spike:<id>", workerName } to /launch/dispatch, and the
              rail's own copy-command row renders the `tiny-brain go --spike`
              snippet the old button offered. Per PRD Assumption 1 (spikes are
              green-only and never land) this surface carries launch only — no
              land / merge / validate. A terminal spike is finished: no rail (its
              worktree is teardown-only, handled by Clean up below). Tasks 2/3
              add the running / resume surfaces that take the rail's place. */}
          {/* Live run: F1's payload reports a running worker → the worker/env glyph
              rail names who is running (the spike analogue of FixDetail's live
              MiniStatusRail), and the end-cap carries the click-to-watch that opens
              the run stream (spike-command-surface-parity — no inline transcript).
              Liveness only — the spike's status still settles via its commits. */}
          {liveRunId !== undefined && activeRun !== null && (
            <div className="space-y-3" data-testid="spike-run-live">
              {/* A running spike reads like a running fix (timeline-second-row-
                  and-spike-strip task 3): the live run wraps in the shared
                  FixControlStrip — the worker attribution, the one prominent
                  Running end-cap, and (with a worktree) the second-row Timeline
                  link opening the read-only provenance island. Spikes never
                  land/merge (PRD Assumption 1), so the end-cap is passed live +
                  no land/merge config — it carries only the Running rung. */}
              <FixControlStrip
                attribution={
                  <>
                    {/* The spike kind pill on the live run (spike-command-surface-
                        parity), mirroring the WorkerRun island's own kind pill. */}
                    <span
                      data-testid="spike-run-kind-pill"
                      className="pill flex-none bg-[color-mix(in_oklab,var(--color-warn)_15%,transparent)] text-[var(--color-warn)]"
                    >
                      spike
                    </span>
                    <MiniStatusRail
                      mode="card"
                      isWorkerRun={activeRun.worker !== undefined}
                      workerName={activeRun.worker}
                      workerModel={activeRun.model}
                      where={activeRun.target === 'cloud-remote' ? 'remote' : 'local'}
                      envName={activeRun.envName}
                      activeRunId={liveRunId}
                      branches={[]}
                      className="shrink-0"
                    />
                    {/* The spike command row carries no title/tasks, so the
                        Timeline rides the SAME line as the worker glyph —
                        vertically centered, pushed right — rather than a sparse
                        second row. Present-worktree only: nothing to inspect
                        otherwise. It opens the read-only provenance island. */}
                    {worktreeStatus.kind === 'present' && (
                      <span className="ml-auto shrink-0">
                        <TimelineLink onClick={() => setCleanupOpen(true)} />
                      </span>
                    )}
                  </>
                }
                endcap={
                  <FeatureEndcap
                    repoId={repoId}
                    item={`spike:${spike.id}`}
                    started
                    done={false}
                    landed={false}
                    superseded={false}
                    live
                    liveRunKind="worker"
                    launched={false}
                    // No resumable probe fires: `live` short-circuits it inside
                    // FeatureEndcap, so this end-cap only ever renders the
                    // Running rung — never a land/merge action (spikes don't land).
                    mayHaveRun={false}
                    onLand={() => {}}
                    onTeardown={() => {}}
                    onResume={() => {}}
                    onContinue={() => {}}
                    // Click-to-watch (spike-command-surface-parity): the Running
                    // rung opens the WorkerRun island via the host's onOpenRun,
                    // exactly as FixDetail wires it — replacing the always-on
                    // inline transcript below with an opt-in watch.
                    onOpenRun={onOpenRun !== undefined ? () => onOpenRun(liveRunId) : undefined}
                  />
                }
              />
            </div>
          )}

          {/* Resume / continue (task 3): F1's payload reports a resumable/failed
              run → the resume/continue affordance comes from the SHARED
              FeatureEndcap (fix spike-detail-standalone-resume-continue-buttons),
              mirroring FixDetail rather than a bespoke two-button row. The
              `resumableRun` payload is only the surface hint (launch-vs-endcap);
              the endcap self-probes `/launch/resumable` and its fold picks the
              single contextual cap — Resume when the run is resumable, Continue
              when a worktree is parked. Takes the launch rail's place; the new run
              surfaces as activeRun over the normal SSE tick. */}
          {resumable !== null && (
            <div className="flex flex-col gap-2">
              <div className="flex justify-end">
                <FeatureEndcap
                  repoId={repoId}
                  item={`spike:${spike.id}`}
                  live={false}
                  started
                  done={false}
                  landed={false}
                  superseded={false}
                  launched={false}
                  // Probe `/launch/resumable` so Resume wins the cap exactly when
                  // there is a run to continue; the payload hint only gated us here.
                  mayHaveRun
                  // Continue needs a parked worktree (`started && !done &&
                  // worktree !== undefined`); absent, the cap reads the inert
                  // in-progress fact. Spikes never land, so no land/merge config.
                  worktree={
                    worktreeStatus.kind === 'present'
                      ? { branch: worktreeStatus.branch }
                      : undefined
                  }
                  onLand={() => {}}
                  onTeardown={() => {}}
                  onResume={onResume}
                  onContinue={onContinue}
                />
              </div>
              {runNotice !== null && (
                <span role="alert" className="text-xs text-[var(--color-phase-red)]">
                  {runNotice}
                </span>
              )}
            </div>
          )}

          {/* Right-aligned so LaunchControl's popover — anchored right-0 and
              opening leftward at 380px — renders into the panel instead of off
              its left edge (fix spike-launch-rail-popover-clipped). Mirrors the
              fix detail's right-positioned mount. */}
          {launchable && (
            <div className="flex justify-end">
              <LaunchControl repoId={repoId} item={`spike:${spike.id}`} />
            </div>
          )}

          {/* Worktree teardown affordances — retained, orthogonal to the run
              rail above. A finished spike replaces relaunch with a Clean up
              button that opens the teardown-only merge surface (delete the
              worktree, keep the spike); a live spike with a worktree can Park it
              (remove the worktree, keep the branch — park clears the field, so
              onWorktreeCleared is the right refetch). */}
          {worktreeStatus.kind === 'present' && !isTerminal && (
            <SpikeParkButton
              repoId={repoId}
              spikeId={spike.id}
              onParked={onWorktreeCleared}
            />
          )}
          {worktreeStatus.kind === 'present' && isTerminal && (
            <button
              type="button"
              data-testid="spike-cleanup-button"
              onClick={() => setCleanupOpen(true)}
              className="inline-flex items-center gap-1.5 rounded-xl border border-border px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
            >
              <Trash2 className="h-4 w-4" /> Clean up
            </button>
          )}
          {/* The read-only provenance island — mounted for any present-worktree
              spike so BOTH the terminal Clean up button and the live command
              row's second-row Timeline link (task 3) can open it. */}
          {worktreeStatus.kind === 'present' && (
            <SpikeCleanupIsland
              spikeTitle={spike.title}
              branch={worktreeStatus.branch}
              open={cleanupOpen}
              onClose={() => setCleanupOpen(false)}
              // A running spike opens this from the live Timeline link — the
              // provenance view reads "in progress", not "ready to clean".
              live={!isTerminal}
            />
          )}
          {worktreeStatus.kind === 'orphaned' && (
            <OrphanedWorktreeBanner
              repoId={repoId}
              spikeId={spike.id}
              branch={worktreeStatus.branch}
              onCleared={onWorktreeCleared}
            />
          )}

          {/* Question — the "why" this spike exists (timebox now rides the
              header meta, so the question stands on its own). */}
          <PanelFlat data-testid="spike-question" className="rounded-2xl p-5">
            <p className="eyebrow text-[10px] text-subtle">Question</p>
            <p className="mt-2 whitespace-pre-line text-sm leading-relaxed text-muted-foreground">
              {spike.question}
            </p>
          </PanelFlat>

          {/* Acceptance criteria — recessed panel, with per-criterion result
              badges once the spike is terminal. */}
          <PanelFlat className="rounded-2xl p-5">
            <p className="eyebrow text-[10px] text-subtle">Acceptance criteria</p>
            <ul data-testid="spike-criteria" className="mt-3 space-y-2 text-sm">
              {spike.acceptanceCriteria.map((criterion, i) => {
                const marker = spike.criterionResults?.[i] ?? null;
                return (
                  <li key={i} className="flex items-start gap-2">
                    <span
                      aria-hidden="true"
                      className="mt-1 inline-block w-1.5 h-1.5 rounded-full bg-purple-400 flex-shrink-0"
                    />
                    <span className="flex-1">{criterion}</span>
                    {marker && (
                      <Badge
                        data-testid="spike-criterion-result"
                        variant="outline"
                        className={cn('text-xs flex-shrink-0', criterionResultTone(marker))}
                      >
                        {marker}
                      </Badge>
                    )}
                  </li>
                );
              })}
            </ul>
          </PanelFlat>

          {/* Progress — the KPI rail (StatReadout: gradient bar + done/left
              breakdown), the spike analogue of FixDetail's "Tasks resolved". */}
          {totalTasks > 0 && (
            <div data-testid="spike-progress">
              <StatReadout label="Tasks complete" value={progress} detail={progressDetail} />
            </div>
          )}

          {/* Tasks — heading + the shared TaskRow rows in a raised, divided panel
              (same surface as FixDetail). Spikes run green → complete with no
              review gate. */}
          <div data-testid="spike-tasks">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <h2 className="display text-base font-semibold">Tasks</h2>
              <span className="text-xs text-muted-foreground">
                Spikes run Red → Green only — no review gate.
              </span>
            </div>
            <div className="mt-3">
              {spike.tasks.length === 0 ? (
                <p className="py-4 text-center text-sm text-muted-foreground">
                  No tasks yet — they appear after the first{' '}
                  <code className="font-mono">tiny-brain task sync</code>.
                </p>
              ) : (
                <div className="panel divide-y divide-border overflow-hidden rounded-2xl dark:divide-[oklch(0.5_0.06_282/0.2)]">
                  {spike.tasks.map((task, index) => (
                    <TaskRow
                      key={task.id}
                      task={toTaskRowTask(task, spike.id, telemetry)}
                      repoId={repoId}
                      reviewPipeline={SPIKE_PIPELINE_STEPS}
                      slugPath={formatTaskComponentSlug(index + 1)}
                    />
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Outcome — shown once the doc carries authored findings, or once the
              spike is terminal. The record-outcome control sits BELOW it, so the
              findings read before the control that concludes them. The
              outcomeBody markdown renders inline; a terminal spike with no body
              falls back to a file-pointer hint. */}
          {(isTerminal || spike.outcomeBody) && (
            <PanelFlat data-testid="spike-outcome" data-status={status} className="rounded-2xl p-5">
              <p className="eyebrow text-[10px] text-subtle">Outcome · {SPIKE_STATUS_LABEL[status]}</p>
              <div className="mt-2">
                {spike.outcomeBody ? (
                  <div className="prose prose-sm dark:prose-invert max-w-none text-sm">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{spike.outcomeBody}</ReactMarkdown>
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">
                    See the spike doc body for the outcome narrative
                    (<code className="font-mono">docs/spikes/{spike.id}.md</code>).
                  </p>
                )}
              </div>
            </PanelFlat>
          )}

          {/* Record outcome — the manual terminal-status control, shown only
              while the spike is in_progress; below the outcome it produces. */}
          {status === 'in_progress' && (
            <SpikeOutcomeCapture
              repoId={repoId}
              spikeId={spike.id}
              onCompleted={onOutcomeRecorded}
            />
          )}
        </div>
      </div>
    </div>
  );
}
