// --- Configuration: repo-scoped config editor ---

/**
 * Mounts the shared ConfigEditor in `repo` mode. Writes go through the repo
 * feature-flags PATCH (which core reroutes to setPreferenceByKey at 'repo'
 * scope) and re-render from the returned flags so per-key source badges update
 * in place. Clear-override wiring lands with Task 6.
 *
 * The Validation sidebar item summarises the repo's resolved post-land state
 * (read from the pipeline endpoint), and its Configure link hands off to the
 * Pipeline section — the one editor for that config.
 */
const ConfigurationStep: React.FC<{
  flags: ConfigFlags | null;
  repoId: string;
  onFlagsChange: (flags: ConfigFlags) => void;
  /** Absent when the mount has nowhere to navigate — the Validation item is
   *  withheld rather than rendering a dead Configure link. */
  onOpenPipeline?: () => void;
}> = ({ flags, repoId, onFlagsChange, onOpenPipeline }) => {
  const [writeError, setWriteError] = useState<string | null>(null);
  // The Validation item renders only from a settled successful read: while
  // loading the facts are unknown, and on ANY failure (non-ok or thrown) we
  // must not fabricate an "Off" — both states withhold the item instead.
  const [postLandRead, setPostLandRead] = useState<
    'loading' | 'failed' | { step: PipelineStep | null }
  >('loading');

  useEffect(() => {
    let cancelled = false;
    // Second read of /pipeline in this file (RecommendationsStep owns the
    // editing copy): deliberate — this pane needs one resolved fact, and
    // sharing the editor's mutable pipeline state would couple the two panes.
    // Lift the fetch or resolve server-side if a third consumer appears.
    fetch(`/api/repos/${repoId}/pipeline`)
      .then((r) => {
        if (!r.ok) throw new Error(`pipeline read failed: ${r.status}`);
        return r.json();
      })
      .then((data: { postLandPipeline?: PipelineStep[] }) => {
        if (cancelled) return;
        setPostLandRead({ step: getHookSteps(data?.postLandPipeline ?? [], 'post-land')[0] ?? null });
      })
      .catch(() => {
        if (!cancelled) setPostLandRead('failed');
      });
    return () => {
      cancelled = true;
    };
  }, [repoId]);

  const handleWrite = useCallback(async (key: string, value: boolean | string) => {
    try {
      const res = await fetch(`/api/repos/${repoId}/feature-flags`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key, value }),
      });
      if (!res.ok) {
        const detail = (await res.json().catch(() => null)) as { error?: unknown } | null;
        setWriteError(typeof detail?.error === 'string' ? detail.error : 'Failed to save change');
        return;
      }
      const data = (await res.json()) as { flags: ConfigFlags };
      onFlagsChange(data.flags);
      setWriteError(null);
    } catch {
      setWriteError('Failed to save change');
    }
  }, [repoId, onFlagsChange]);

  const handleClearOverride = useCallback(async (key: string) => {
    try {
      const res = await fetch(`/api/repos/${repoId}/feature-flags/${key}`, { method: 'DELETE' });
      if (!res.ok) {
        const detail = (await res.json().catch(() => null)) as { error?: unknown } | null;
        setWriteError(typeof detail?.error === 'string' ? detail.error : 'Failed to clear override');
        return;
      }
      const data = (await res.json()) as { flags: ConfigFlags };
      onFlagsChange(data.flags);
      setWriteError(null);
    } catch {
      setWriteError('Failed to clear override');
    }
  }, [repoId, onFlagsChange]);

  if (!flags) {
    // In-flight flags fetch: row-shaped skeletons, not a text flash
    // (loading-text-flash-replace-with-skeletons task 1).
    return (
      <div data-testid="config-skeleton" role="status" aria-label="Loading configuration…" className="space-y-2">
        <Skeleton aria-hidden className="h-4 w-full" />
        <Skeleton aria-hidden className="h-4 w-5/6" />
        <Skeleton aria-hidden className="h-4 w-2/3" />
      </div>
    );
  }

  return (
    <div>
      {/* Pane intro moved to the shared RepoSetupTab header (section description);
          the source-badge / reset affordances remain self-describing in the rows. */}
      {writeError && (
        <div role="alert" className="mb-2 text-sm text-destructive">
          {writeError}
        </div>
      )}
      <div className="panel rounded-2xl px-5 py-1">
        <ConfigEditor
          flags={flags}
          mode="repo"
          onWrite={handleWrite}
          onClearOverride={handleClearOverride}
          validation={
            typeof postLandRead === 'object' && onOpenPipeline
              ? {
                  dispatch: resolvePostLandDispatch(postLandRead.step ?? undefined),
                  onConfigureInPipeline: onOpenPipeline,
                }
              : undefined
          }
        />
      </div>
    </div>
  );
};

