// --- Step 2: Analysis ---

// The Analysis page rail items (mockup): Overview + the three agent-ability
// groups, each an anchor into a section on the one scrolling page.
const ANALYSIS_RAIL: ReadonlyArray<{ id: string; label: string; icon: React.ReactNode }> = [
  { id: 'analysis-overview', label: 'Overview', icon: <Code className="h-4 w-4" /> },
  { id: 'analysis-unit-tests', label: 'Unit tests', icon: <TestTube className="h-4 w-4" /> },
  { id: 'analysis-mutation', label: 'Mutation', icon: <Bug className="h-4 w-4" /> },
  { id: 'analysis-static', label: 'Static analysis', icon: <ScanLine className="h-4 w-4" /> },
];

/** Track which section is in view, so the rail can highlight it (scrollspy). */
// Stable id lists (module scope) so the scrollspy effect dep doesn't churn:
// a fresh `railItems.map(...)` array every render would re-subscribe the
// IntersectionObserver on each render (and on each scroll-driven setActive).
const ANALYSIS_RAIL_IDS: readonly string[] = ANALYSIS_RAIL.map((i) => i.id);
const ANALYSIS_OVERVIEW_IDS: readonly string[] = [ANALYSIS_RAIL[0].id];

/** Nearest scrollable ancestor of `node` — the element that actually scrolls in
 *  the live (nested-scroller) layout, so a rail click moves the real scroll
 *  container (the analysis content when it overflows, else the pane up the
 *  chain) rather than a div that happens to carry `overflow-y-auto` but isn't
 *  the one overflowing. */
const getScrollParent = (node: HTMLElement): HTMLElement | null => {
  let el = node.parentElement;
  while (el) {
    const overflowY = getComputedStyle(el).overflowY;
    if ((overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight) {
      return el;
    }
    el = el.parentElement;
  }
  return null;
};

const useScrollSpy = (ids: readonly string[]): string => {
  const [active, setActive] = useState(ids[0]);
  useEffect(() => {
    if (typeof IntersectionObserver === 'undefined') return;
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
        if (visible) setActive(visible.target.id);
      },
      { rootMargin: '-15% 0px -75% 0px', threshold: 0 },
    );
    ids.forEach((id) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, [ids]);
  return active;
};

const AnalysisStep: React.FC<{
  analysisData: { exists: boolean; analysis: RepoAnalysisFile | null };
  analyzing: boolean;
  progressSteps: ProgressStep[];
  analysisError: string | null;
  hasClaudeCli: boolean;
  onRunAnalysis: () => void;
}> = ({ analysisData, analyzing, progressSteps, analysisError, hasClaudeCli, onRunAnalysis }) => {
  const { exists, analysis } = analysisData;
  // Only the Overview rail item is meaningful until the repo is analysed.
  const full = Boolean(exists && analysis);
  const railItems = full ? ANALYSIS_RAIL : ANALYSIS_RAIL.slice(0, 1);
  const active = useScrollSpy(full ? ANALYSIS_RAIL_IDS : ANALYSIS_OVERVIEW_IDS);

  // Rail clicks smooth-scroll the section's real scroll container (not the whole
  // page). Native anchor navigation would walk the nested scroll chain and jump.
  const handleRailClick = (e: React.MouseEvent<HTMLAnchorElement>, id: string) => {
    const el = document.getElementById(id);
    const container = el && getScrollParent(el);
    // No scrollable ancestor → leave the native href fallback to navigate.
    if (!el || !container) return;
    e.preventDefault();
    // Section position within the container's own scroll — rect delta is correct
    // regardless of which ancestor is the offsetParent.
    const top = container.scrollTop + (el.getBoundingClientRect().top - container.getBoundingClientRect().top);
    container.scrollTo({ top, behavior: 'smooth' });
  };

  return (
    <section className="h-full flex flex-col">
      <div className="mb-4 flex-shrink-0">
        <p className="text-sm text-muted-foreground">
          We've analyzed your repo to understand your stack
        </p>
      </div>

      <div className="grid gap-4 md:grid-cols-[13rem_minmax(0,1fr)] flex-1 min-h-0">
        <nav data-testid="analysis-sidebar" className="text-sm md:sticky md:top-3 md:self-start">
          <div className="space-y-1">
            {railItems.map((item) => (
              <a
                key={item.id}
                href={`#${item.id}`}
                onClick={(e) => handleRailClick(e, item.id)}
                aria-current={active === item.id ? 'location' : undefined}
                className={`w-full flex items-center gap-2 px-3 py-2 text-sm rounded-lg transition-colors ${
                  active === item.id ? 'bg-blue/10 text-blue font-medium' : 'text-muted-foreground hover:bg-muted'
                }`}
              >
                <span className="flex-shrink-0 text-subtle">{item.icon}</span>
                <span className="text-left truncate">{item.label}</span>
              </a>
            ))}
          </div>
        </nav>

        {/* One scrolling page: every section is mounted; the rail scrollspies it
            and rail clicks smooth-scroll this container only. */}
        <div data-testid="analysis-scroll" className="min-w-0 space-y-8 overflow-y-auto scroll-smooth">
          <div id="analysis-overview" className="scroll-mt-4">
            <AnalysisOverview
              exists={exists}
              analysis={analysis}
              analyzing={analyzing}
              progressSteps={progressSteps}
              analysisError={analysisError}
              hasClaudeCli={hasClaudeCli}
              onRunAnalysis={onRunAnalysis}
            />
          </div>
          {exists && analysis && (
            <>
              <div className="pt-2">
                <p className="eyebrow text-[10px] text-subtle">Agent abilities</p>
                <p className="mt-1 text-sm text-muted-foreground">
                  Commands extracted from your analysis. The Coverage and Mutation agents run these during the
                  pipeline — a missing command disables the matching step.
                </p>
              </div>
              {deriveAgentAbilities(analysis).map((group) => (
                <AbilityGroupCard key={group.key} group={group} />
              ))}
            </>
          )}
        </div>
      </div>
    </section>
  );
};

