// --- Step 3: Recommendations ---

const RecommendationsStep: React.FC<{
  repoId: string;
  recommendations: DashboardRecommendation[];
  dismissed: DismissedRecommendation[];
  dismissedExpanded: boolean;
  setDismissedExpanded: (expanded: boolean) => void;
  onAccept: (rec: DashboardRecommendation) => void;
  onDismiss: (rec: DashboardRecommendation) => void;
  onRestore: (item: DismissedRecommendation) => void;
  acceptingIds: Set<string>;
  acceptResults: Map<string, AcceptResult>;
  installedCapTypes: string[];
  tddEnabled: boolean;
  analysis: RepoAnalysisFile | null;
  /** Capabilities discovered from the plugin, fetched once by SetupTab. */
  discoveredCapabilities: DiscoveredCapability[];
  /** Which half of the surface to render: the pipeline editors (Pipeline tab)
   *  or the capability/recommendations tabs (Capabilities tab). */
  view: 'pipeline' | 'capabilities';
}> = ({ repoId, recommendations, dismissed, dismissedExpanded, setDismissedExpanded, onAccept, onDismiss, onRestore, acceptingIds, acceptResults, installedCapTypes, tddEnabled, analysis, discoveredCapabilities, view }) => {
  const [validationStates, setValidationStates] = useState<Record<string, RecommendationValidationState>>({});
  const [catalogSearch, setCatalogSearch] = useState('');
  const [commitPipeline, setCommitPipeline] = useState<PipelineStep[]>([ADVERSARIAL_STEP]);
  const [pushPipeline, setPushPipeline] = useState<PipelineStep[]>([]);
  const [qualityPipeline, setQualityPipeline] = useState<PipelineStep[]>([]);
  const [completionPipeline, setCompletionPipeline] = useState<PipelineStep[]>([]);
  const [postLandPipeline, setPostLandPipeline] = useState<PipelineStep[]>([]);
  // The planning gates (deliverability, architecture-alignment) are ordinary
  // configured steps — folded into the palette below like every other lane so
  // their agents surface alongside adversarial, sourced from config (empty →
  // nothing). No second registry.
  const [planningPipeline, setPlanningPipeline] = useState<PipelineStep[]>([]);
  const [userInstalledCapabilities, setUserInstalledCapabilities] = useState<string[]>([]);
  const [pipelineSaving, setPipelineSaving] = useState(false);

  useEffect(() => {
    fetch(`/api/repos/${repoId}/pipeline`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (data?.pipeline) setCommitPipeline(data.pipeline);
        if (data?.pushPipeline) setPushPipeline(data.pushPipeline);
        if (data?.qualityPipeline) setQualityPipeline(data.qualityPipeline);
        if (data?.completionPipeline) setCompletionPipeline(data.completionPipeline);
        if (data?.postLandPipeline) setPostLandPipeline(data.postLandPipeline);
        if (data?.planningPipeline) setPlanningPipeline(data.planningPipeline);
        // Canonicalise installed ids (installed.json may use analyzer-vocab ids
        // like `mutation-testing`) so they join the registry/capability ids.
        if (data?.installedCapabilities) {
          setUserInstalledCapabilities(data.installedCapabilities.map(canonicalStepType));
        }
      })
      .catch(() => {});
  }, [repoId]);

  const savePipeline = async (type: 'commit' | 'push' | 'quality' | 'work-item' | 'post-land', steps: PipelineStep[]) => {
    if (type === 'commit') setCommitPipeline(steps);
    else if (type === 'push') setPushPipeline(steps);
    else if (type === 'work-item') setCompletionPipeline(steps);
    else if (type === 'post-land') setPostLandPipeline(steps);
    else setQualityPipeline(steps);
    setPipelineSaving(true);
    try {
      const body = type === 'commit'
        ? { pipeline: steps }
        : type === 'push'
          ? { pushPipeline: steps }
          : type === 'work-item'
            ? { completionPipeline: steps }
            : type === 'post-land'
              ? { postLandPipeline: steps }
              : { qualityPipeline: steps };
      await fetch(`/api/repos/${repoId}/pipeline`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
    } finally {
      setPipelineSaving(false);
    }
  };

  const handleAnalyse = async (rec: DashboardRecommendation) => {
    // Use cached validation from recommendation data if available
    if (rec.validation) {
      setValidationStates((prev) => ({
        ...prev,
        [rec.id]: { status: 'success', result: rec.validation as SkillValidationResult },
      }));
      return;
    }

    // No cached validation available - show fallback message
    setValidationStates((prev) => ({
      ...prev,
      [rec.id]: { status: 'error', message: 'Validation not available - accept to validate locally' },
    }));
  };
  // Filter out capability recommendations that overlap with pre-installed capabilities
  // Also filter superseded TBR names (security-scanning → security-review)
  const preInstalledIds = new Set(discoveredCapabilities.filter(c => !c.hasInstallSection).map(c => c.id));
  const supersededIds = new Set(['security-scanning']); // TBR names replaced by local capabilities
  const libraryCapRecs = recommendations
    .filter((r): r is CapabilityDashboardRecommendation => r.type === 'capability')
    .filter(r => !preInstalledIds.has(r.installerId) && !supersededIds.has(r.installerId));
  const atomicRecs = recommendations.filter(r => r.type !== 'capability');

  return (
    <section className="space-y-4">
      {/* Pipeline editors (Pipeline tab) */}
      {view === 'pipeline' && (
      <div className="space-y-4">
        {(() => {
          // The `available` palette the builder drags from — see
          // buildPipelinePalette. The one behaviour that used to be buried in
          // this inline map (and so untestable) now lives in that pure helper,
          // including seeding the validation `test` analyser as a runsTests tile.
          const allSteps = buildPipelinePalette({
            // Include EVERY configured lane so a step's configured version (custom
            // scope/label/config) overrides the built-in seed on re-add — the
            // completion and post-land lanes were previously omitted, so re-adding
            // a removed coverage/mutation step reverted it to the default seed.
            activePipelines: collectActivePipelineSteps({
              commit: commitPipeline,
              push: pushPipeline,
              quality: qualityPipeline,
              completion: completionPipeline,
              postLand: postLandPipeline,
              planning: planningPipeline,
            }),
            discoveredCapabilities,
            userInstalledCapabilities,
            installedCapTypes,
            analysis,
          });

          // Step counts for the card group-head badges (mockup). The per-commit
          // lane is the hook steps; the per-task lane is the review steps plus
          // the fixed Red/Green TDD tiles when TDD is on.
          const TDD_PHASE_TILE_COUNT = 2; // Red + Green fixed phases
          const hookCount = commitPipeline.filter((s) => s.hook).length;
          const reviewCount = commitPipeline.filter((s) => !s.hook).length;
          const perTaskCount = reviewCount + (tddEnabled ? TDD_PHASE_TILE_COUNT : 0);
          const plural = (n: number, noun: string) => `${n} ${noun}${n === 1 ? '' : 's'}`;

          return (
            <>
              {/* Hero: what pipelines are + the colour legend the steps use.
                  Legend sits up on the title row so the description spans full width. */}
              <div className="rounded-3xl panel p-6">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="eyebrow text-[10px] text-subtle">Automation</p>
                    <h2 className="display text-2xl font-bold leading-tight">Pipeline</h2>
                  </div>
                  <div className="flex flex-wrap items-center justify-end gap-x-4 gap-y-2 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1.5"><span className="inline-block w-2 h-2 rounded-full" style={{ background: 'color-mix(in oklab, var(--foreground) 35%, transparent)' }} />Static</span>
                    <span className="flex items-center gap-1.5"><span className="inline-block w-2 h-2 rounded-full" style={{ background: 'var(--color-primary)' }} />Agentic</span>
                    <span className="flex items-center gap-1.5"><span className="inline-block w-2 h-2 rounded-full" style={{ background: 'var(--color-warn)' }} />Tollgate</span>
                  </div>
                </div>
                <p className="mt-1 text-sm text-muted-foreground">
                  Quality steps run automatically — per commit, per task, before every push, and on demand.
                  Drag to reorder, <span className="mono">+</span> to add a step, <span className="mono">×</span> to remove.
                </p>
              </div>

              {/* Per commit + Per task project from the one reviewPipeline
                  (commitPipeline): the static hook lane and the review/TDD lane.
                  Each save recombines with the other lane (no clobber). */}
              <div className="rounded-2xl panel overflow-hidden">
                <div className="pipe-group-head">
                  <span className="flex items-center gap-3">
                    <span className="pipe-disc"><GitCommitHorizontal className="h-5 w-5" /></span>
                    <span>
                      <span className="block font-semibold text-sm">Per Commit</span>
                      <span className="block text-xs text-muted-foreground">Static analysers the pre-commit hook runs every commit</span>
                    </span>
                  </span>
                  <span className="mono text-[11px] text-subtle">{plural(hookCount, 'step')}</span>
                </div>
                <div className="p-4">
                  <PipelineEditor
                    pipeline={commitPipeline}
                    available={allSteps}
                    onSave={(p) => savePipeline('commit', p)}
                    saving={pipelineSaving}
                    lane="per-commit"
                    showFixedPhases={false}
                    hookName="pre-commit"
                  />
                </div>
              </div>

              <div className="rounded-2xl panel overflow-hidden">
                <div className="pipe-group-head">
                  <span className="flex items-center gap-3">
                    <span className="pipe-disc"><ListChecks className="h-5 w-5" /></span>
                    <span>
                      <span className="block font-semibold text-sm">Per Task</span>
                      <span className="block text-xs text-muted-foreground">Each task runs TDD — Red, Green and your review stages</span>
                    </span>
                  </span>
                  <span className="mono text-[11px] text-subtle">{plural(perTaskCount, 'step')}</span>
                </div>
                <div className="p-4">
                  <PipelineEditor
                    pipeline={commitPipeline}
                    available={allSteps}
                    onSave={(p) => savePipeline('commit', p)}
                    saving={pipelineSaving}
                    lane="per-task"
                    showFixedPhases={tddEnabled}
                  />
                </div>
              </div>

              {/* Work item — the completion gate (`tb complete`). A hook lane
                  stamping BOTH completion stages (['fix-complete','feature-complete'])
                  on a dropped step; scoped to the item's own commits. Ordered by the
                  work-item lifecycle: per commit → per task → work item → post-land
                  → per push. */}
              <div className="rounded-2xl panel overflow-hidden">
                <div className="pipe-group-head">
                  <span className="flex items-center gap-3">
                    <span className="pipe-disc"><CheckCircle2 className="h-5 w-5" /></span>
                    <span>
                      <span className="block font-semibold text-sm">Work item</span>
                      <span className="block text-xs text-muted-foreground">Runs at completion (tb complete), scoped to the item's own changes. A work item is a fix or feature.</span>
                    </span>
                  </span>
                  <span className="mono text-[11px] text-subtle">{plural(completionPipeline.length, 'step')}</span>
                </div>
                <div className="p-4">
                  <PipelineEditor
                    pipeline={completionPipeline}
                    available={allSteps}
                    onSave={(p) => savePipeline('work-item', p)}
                    saving={pipelineSaving}
                    showFixedPhases={false}
                    lane="work-item"
                  />
                </div>
              </div>

              {/* Post-land — the async validation run that fires after a merge
                  lands on main's tip (split-land-from-validation F8/F10). A hook
                  lane like Per Commit, stamping hook:'post-land'; the placed
                  tile's config popover carries the debounce/seed/timeout knobs.
                  Ordered by the work-item lifecycle: per commit → per task →
                  work item → post-land → per push. */}
              <div className="rounded-2xl panel overflow-hidden">
                <div className="pipe-group-head">
                  <span className="flex items-center gap-3">
                    <span className="pipe-disc"><GitMerge className="h-5 w-5" /></span>
                    <span>
                      <span className="block font-semibold text-sm">Post-land</span>
                      <span className="block text-xs text-muted-foreground">Runs after a merge lands, async on main's tip</span>
                    </span>
                  </span>
                  <span className="mono text-[11px] text-subtle">{plural(postLandPipeline.length, 'step')}</span>
                </div>
                <div className="p-4">
                  <PipelineEditor
                    pipeline={postLandPipeline}
                    available={allSteps}
                    onSave={(p) => savePipeline('post-land', p)}
                    saving={pipelineSaving}
                    showFixedPhases={false}
                    lane="post-land"
                    hookName="post-land"
                  />
                </div>
              </div>

              <div className="rounded-2xl panel overflow-hidden">
                <div className="pipe-group-head">
                  <span className="flex items-center gap-3">
                    <span className="pipe-disc"><Upload className="h-5 w-5" /></span>
                    <span>
                      <span className="block font-semibold text-sm">Per Push</span>
                      <span className="block text-xs text-muted-foreground">Runs before every push to a remote</span>
                    </span>
                  </span>
                  <span className="mono text-[11px] text-subtle">{plural(pushPipeline.length, 'step')}</span>
                </div>
                <div className="p-4">
                  <PipelineEditor
                    pipeline={pushPipeline}
                    available={allSteps}
                    onSave={(p) => savePipeline('push', p)}
                    saving={pipelineSaving}
                    showFixedPhases={false}
                    hookName="pre-push"
                  />
                </div>
              </div>

              <div className="rounded-2xl panel overflow-hidden">
                <div className="pipe-group-head">
                  <span className="flex items-center gap-3">
                    <span className="pipe-disc"><Gauge className="h-5 w-5" /></span>
                    <span>
                      <span className="block font-semibold text-sm">Quality</span>
                      <span className="block text-xs text-muted-foreground">On demand via <span className="mono">/quality</span> · all agents run in parallel</span>
                    </span>
                  </span>
                  <span className="mono text-[11px] text-subtle">{plural(qualityPipeline.length, 'agent')}</span>
                </div>
                <div className="p-4">
                  <PipelineEditor
                    pipeline={qualityPipeline}
                    available={allSteps}
                    onSave={(p) => savePipeline('quality', p)}
                    saving={pipelineSaving}
                    showFixedPhases={false}
                    parallel
                  />
                </div>
              </div>

              {/* Worktree readiness — the ordered commands every worktree runs
                  before its analysers (worktree-readiness-commands F6). A
                  free-command list, not a pipeline of typed steps, so it has its
                  own editor rather than a PipelineEditor lane. */}
              <WorktreeReadinessCard repoId={repoId} />
            </>
          );
        })()}
      </div>
      )}

      {/* Install-only Catalog (Capabilities tab) */}
      {view === 'capabilities' && (() => {
        const query = catalogSearch.trim().toLowerCase();
        const matchesSearch = (text: string) => text.toLowerCase().includes(query);
        // The catalog is install-only: pending recommendations (the stack
        // group) and discovered capabilities that aren't already installed.
        const stackRecs = atomicRecs.filter(r => matchesSearch(r.name));
        const installableCaps = discoveredCapabilities
          .filter(c => c.hasInstallSection && !userInstalledCapabilities.includes(canonicalStepType(c.id)))
          .filter(c => matchesSearch(c.name));
        const moreCapRecs = libraryCapRecs.filter(r => matchesSearch(r.name));
        const isEmpty = stackRecs.length === 0 && installableCaps.length === 0 && moreCapRecs.length === 0;

        return (
        <div data-testid="capabilities-catalog" className="space-y-4">
          {/* Header + search */}
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <span className="text-sm font-semibold flex items-center gap-1.5"><Store className="h-4 w-4 text-blue" /> Catalog</span>
              <span className="text-xs text-muted-foreground">install anything you don't already have.</span>
            </div>
            <div className="flex items-center gap-2 rounded-lg border border-border px-3 py-1.5 text-sm w-full sm:w-64">
              <Search className="h-4 w-4 text-muted-foreground" />
              <input
                data-testid="catalog-search"
                value={catalogSearch}
                onChange={(e) => setCatalogSearch(e.target.value)}
                placeholder="Search the catalog…"
                aria-label="Search the catalog"
                className="w-full bg-transparent focus:outline-none"
              />
            </div>
          </div>

          {/* Recommended for your stack — the install-only stack group */}
          {stackRecs.length > 0 && (
            <div>
              <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wide mb-3 flex items-center gap-2">
                Recommended for your stack
                <Badge variant="secondary" className="ml-1">{stackRecs.length}</Badge>
                <span className="normal-case text-xs text-subtle">— closes a posture gap</span>
              </h3>
              <div className="space-y-3">
                {stackRecs.map(rec => (
                  <RecommendationCard
                    key={rec.id}
                    recommendation={rec}
                    onAccept={() => onAccept(rec)}
                    onDismiss={() => onDismiss(rec)}
                    isAccepting={acceptingIds.has(rec.id)}
                    acceptResult={acceptResults.get(rec.id)}
                    validationState={validationStates[rec.id]}
                    onAnalyse={() => handleAnalyse(rec)}
                  />
                ))}
              </div>
            </div>
          )}

          {/* More in the catalog — installable capabilities not already present */}
          {(installableCaps.length > 0 || moreCapRecs.length > 0) && (
            <div>
              <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wide mb-3">More in the catalog</h3>
              <div className="space-y-3">
                {installableCaps.map(cap => {
                  const isStaticCap = !cap.id.includes('review') && !cap.id.includes('compliance');
                  return (
                    <CapabilityCard
                      key={cap.id}
                      recommendation={{
                        id: `discovered-${cap.id}`,
                        name: cap.name,
                        description: cap.description,
                        category: cap.category,
                        reason: 'Requires installation',
                        tags: [],
                        type: 'capability',
                        installerId: cap.id,
                        version: cap.version,
                        stepDescriptions: [],
                        trigger: 'commit',
                        phaseEmoji: cap.emoji,
                      }}
                      onAccept={() => {}}
                      onDismiss={() => {}}
                      isInstalled={false}
                      variant={isStaticCap ? 'static' : 'agentic'}
                    />
                  );
                })}
                {moreCapRecs.map(rec => (
                  <CapabilityCard
                    key={rec.id}
                    recommendation={rec}
                    onAccept={() => onAccept(rec)}
                    onDismiss={() => onDismiss(rec)}
                    isAccepting={acceptingIds.has(rec.id)}
                  />
                ))}
              </div>
            </div>
          )}

          {isEmpty && (
            <p className="text-sm text-muted-foreground text-center py-8">
              {query ? 'Nothing in the catalog matches your search.' : "Nothing to install — your stack is already covered."}
            </p>
          )}

          {/* Browse the full catalog — clears any search filter so every
              installable item shows (no separate catalog page yet). */}
          <button
            type="button"
            onClick={() => setCatalogSearch('')}
            disabled={!query}
            className="hoverable flex w-full items-center justify-between rounded-xl border border-border px-4 py-2.5 text-xs text-muted-foreground disabled:opacity-60"
          >
            <span className="flex items-center gap-2"><LayoutGrid className="h-3.5 w-3.5" /> Browse the full catalog</span>
            <ArrowRight className="h-4 w-4" />
          </button>

          {/* Dismissed Section */}
          {dismissed.length > 0 && (
            <div className="mt-6 pt-4 border-t border-border">
              <button
                onClick={() => setDismissedExpanded(!dismissedExpanded)}
                className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
              >
                {dismissedExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
                <span>Dismissed</span>
                <Badge variant="secondary">{dismissed.length}</Badge>
              </button>

              {dismissedExpanded && (
                <div className="mt-3 space-y-2">
                  {dismissed.map(item => (
                    <div
                      key={item.recommendation.id}
                      className="flex items-center justify-between p-3 rounded-lg panel-flat"
                    >
                      <div className="flex items-center gap-3">
                        <span className={`text-xs px-2 py-0.5 rounded ${typeBadgeColors[item.recommendation.type]?.bg ?? ''} ${typeBadgeColors[item.recommendation.type]?.text ?? ''}`}>
                          {item.recommendation.type}
                        </span>
                        <span className="text-sm">{item.recommendation.name}</span>
                      </div>
                      <button
                        onClick={() => onRestore(item)}
                        className="text-xs px-2 py-1 rounded border border-border hover:bg-accent transition-colors"
                        aria-label={`Restore ${item.recommendation.name}`}
                      >
                        Restore
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
        );
      })()}
    </section>
  );
};

export default SetupTab;
