import * as React from 'react';
import type { MutantIdentity, SurvivorTriageRow } from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';

/**
 * SurvivorTriagePanel (mutation-survivor-triage F4).
 *
 * The dumb surface for per-mutant triage. It lists the surviving mutants — each
 * with its location, operator→replacement, and disposition state (untriaged /
 * equivalent / accepted) — from server-projected rows, and (task 2) reports the
 * disposition actions as events. It derives nothing: the survivors and their
 * dispositions are joined server-side (F3's `gateMutationStep`) and arrive as
 * props. Untriaged survivors are the blocking state the completion gate fails
 * on; a fully-dispositioned list reads as resolved; no survivors reads as an
 * all-clear.
 */

export interface SurvivorTriagePanelProps {
  /** The per-survivor triage rows, projected server-side (F4). */
  readonly rows: readonly SurvivorTriageRow[];
  /** True while the detail is still loading — distinct from a loaded-empty list. */
  readonly loading?: boolean;
  /** Dispose an untriaged survivor as equivalent (no test can kill it). */
  readonly onMarkEquivalent?: (identity: MutantIdentity) => void;
  /** Accept an untriaged survivor (killable but not worth it) with a reason. */
  readonly onAccept?: (identity: MutantIdentity, reason: string) => void;
  /** Dispatch a harden-test remediation run scoped to an untriaged survivor (F5). */
  readonly onHarden?: (identity: MutantIdentity) => void;
}

/** Badge tone per disposition — untriaged is the blocking (red) state. */
const DISPOSITION_TONE: Readonly<Record<SurvivorTriageRow['disposition'], string>> = {
  untriaged: 'text-[var(--color-phase-red)] border-[var(--color-phase-red)]',
  equivalent: 'text-subtle border-border',
  accepted: 'text-subtle border-border',
};

function rowKey(row: SurvivorTriageRow): string {
  const m = row.identity;
  return `${m.file}:${m.line}:${m.column}:${m.operator}:${m.replacement}`;
}

const ACTION_BTN = 'rounded border border-border px-2 py-0.5 text-[10px] text-foreground hover:bg-muted';

function SurvivorRow({
  row,
  onMarkEquivalent,
  onAccept,
  onHarden,
}: {
  row: SurvivorTriageRow;
  onMarkEquivalent?: (identity: MutantIdentity) => void;
  onAccept?: (identity: MutantIdentity, reason: string) => void;
  onHarden?: (identity: MutantIdentity) => void;
}): React.ReactElement {
  const [accepting, setAccepting] = React.useState(false);
  const [reason, setReason] = React.useState('');
  const blocking = row.disposition === 'untriaged';
  const m = row.identity;
  const showActions =
    blocking && (onMarkEquivalent !== undefined || onAccept !== undefined || onHarden !== undefined);

  return (
    <li
      data-testid="survivor-triage-item"
      data-disposition={row.disposition}
      data-blocking={blocking ? 'true' : 'false'}
      className={cn(
        'flex flex-col gap-1 rounded-md border px-3 py-2 text-[11px]',
        blocking ? 'border-[var(--color-phase-red)]/40 bg-[var(--color-phase-red)]/5' : 'border-border',
      )}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="mono text-foreground">
          {m.file}:{m.line}
        </span>
        <span className={cn('rounded-full border px-2 py-0.5 text-[10px] uppercase tracking-wide', DISPOSITION_TONE[row.disposition])}>
          {row.disposition}
        </span>
      </div>
      {/* operator→replacement IS the actionable guidance: kill the mutant by
          asserting on the behaviour that distinguishes the two. */}
      <div data-testid="survivor-triage-op" className="mono text-[10px] text-subtle">
        {m.operator} → {m.replacement}
      </div>
      {row.disposition === 'accepted' && row.reason !== undefined && (
        <p className="text-[10px] italic text-subtle">accepted: {row.reason}</p>
      )}
      {showActions && (
        <div className="mt-1 flex flex-wrap items-center gap-2">
          {onHarden !== undefined && (
            <button type="button" className={ACTION_BTN} onClick={() => onHarden(m)}>
              Harden test
            </button>
          )}
          {onMarkEquivalent !== undefined && (
            <button type="button" className={ACTION_BTN} onClick={() => onMarkEquivalent(m)}>
              Mark equivalent
            </button>
          )}
          {onAccept !== undefined && !accepting && (
            <button type="button" className={ACTION_BTN} onClick={() => setAccepting(true)}>
              Accept…
            </button>
          )}
          {onAccept !== undefined && accepting && (
            <div className="flex items-center gap-1">
              <input
                type="text"
                aria-label="Accept reason"
                placeholder="Why accept this survivor?"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                className="rounded border border-border bg-transparent px-2 py-0.5 text-[10px] text-foreground"
              />
              <button
                type="button"
                className={ACTION_BTN}
                onClick={() => {
                  const trimmed = reason.trim();
                  if (trimmed !== '') onAccept(m, trimmed);
                }}
              >
                Save
              </button>
            </div>
          )}
        </div>
      )}
    </li>
  );
}

export function SurvivorTriagePanel({ rows, loading = false, onMarkEquivalent, onAccept, onHarden }: SurvivorTriagePanelProps): React.ReactElement {
  if (loading) {
    return (
      <div data-testid="survivor-triage-loading" className="rounded-md border border-border px-3 py-2 text-[11px] text-subtle">
        Loading surviving mutants…
      </div>
    );
  }

  if (rows.length === 0) {
    return (
      <div data-testid="survivor-triage-empty" className="rounded-md border border-border px-3 py-2 text-[11px] text-subtle">
        No surviving mutants — nothing to triage.
      </div>
    );
  }

  const untriagedCount = rows.filter((r) => r.disposition === 'untriaged').length;

  return (
    <div data-testid="survivor-triage-panel" className="space-y-2">
      {untriagedCount > 0 && (
        <p data-testid="survivor-triage-blocking-summary" className="text-[11px] font-medium text-[var(--color-phase-red)]">
          {untriagedCount} untriaged mutation survivor{untriagedCount === 1 ? '' : 's'} — disposition each to pass mutation.
        </p>
      )}
      <ul className="space-y-1.5">
        {rows.map((row) => (
          <SurvivorRow key={rowKey(row)} row={row} onMarkEquivalent={onMarkEquivalent} onAccept={onAccept} onHarden={onHarden} />
        ))}
      </ul>
    </div>
  );
}
