import type { DeliveryModel } from '@magic-ingredients/tiny-brain-core';
import { WorktreeMergeIsland } from './WorktreeMergeIsland';

export interface SpikeCleanupIslandProps {
  /** The spike's title — shown in the island header. */
  spikeTitle: string;
  /** The spike worktree's branch — names the model's ref (the spike doc itself is kept). */
  branch: string;
  open: boolean;
  onClose: () => void;
  /**
   * The spike is still running (timeline-second-row-and-spike-strip task 3): the
   * live command row's Timeline link opens this same read-only provenance view
   * while work is in flight, so the header must read "in progress" — not the
   * finished "ready to clean" a terminal spike's Clean up button opens.
   */
  live?: boolean;
}

/** A spike's placeholder delivery model: nothing is delivered/landed on the
 *  delivery axes (a spike branch never merges), and no reconcile ever runs — a
 *  static literal, not a second derivation. `live` carries the run state through
 *  to the header pill. */
function spikeModel(branch: string, live: boolean): DeliveryModel {
  return {
    workRef: { kind: 'spike', id: branch },
    ref: branch,
    done: false,
    landed: false,
    live,
    deliveredItems: [],
    landAvailability: 'unknown',
  };
}

/**
 * The spike provenance / clean-up surface (worktree-surface-consistency-pass):
 * the shared worktree island for a spike. Since the island became the READ-ONLY
 * provenance view (work-item-provenance F6 task 2), this shows the spike
 * worktree's details only — the former stubbed teardown button is gone (it was
 * a no-op). A RUNNING spike opens it via the command row's Timeline link (reads
 * "in progress"); a FINISHED spike opens it via Clean up (reads "ready to
 * clean"). The real spike teardown action lives with the spike lifecycle work
 * (spike-worktree-lifecycle PRD), where its worktree/branch removal preserves
 * the spike doc and its findings.
 */
export function SpikeCleanupIsland({ spikeTitle, branch, open, onClose, live = false }: SpikeCleanupIslandProps) {
  return (
    <WorktreeMergeIsland
      open={open}
      onClose={onClose}
      title={spikeTitle}
      // Live → "in progress" (pulsing); finished → "ready to clean" (non-pulsing).
      mergeState={live ? 'in-progress' : 'ready-to-clean'}
      model={spikeModel(branch, live)}
    />
  );
}

export default SpikeCleanupIsland;
