import { useSearchParams } from 'react-router';
import { cn } from '@/lib/utils';
import { buildRepoCrumbs, type CrumbTarget } from '@/utils/repo-breadcrumb';

export interface RepoHeaderProps {
  /** Active repo name (the second breadcrumb crumb). */
  repoName: string;
  /** Navigate back to the repos list (the "Repos" crumb). */
  onBack: () => void;
  className?: string;
}

/**
 * The repo workspace breadcrumb: `Repos / <name> / <nav> [/ <detail>]`, derived
 * entirely from the URL nav state (`?view` / `?analyser` / `?settings`). The
 * filesystem path is gone; the nav crumbs (Quality / Settings) and their
 * drill-downs (an analyser, a settings section) make the rail a navigable,
 * deep-linkable path into the repo. Every crumb but the last navigates one
 * level up the hierarchy.
 */
export function RepoHeader({
  repoName,
  onBack,
  className,
}: RepoHeaderProps) {
  const [searchParams, setSearchParams] = useSearchParams();

  const settingsOpen =
    searchParams.get('settings') !== null || searchParams.get('section') !== null;
  const settingsSection = searchParams.get('settings') || searchParams.get('section') || null;

  const crumbs = buildRepoCrumbs({
    repoName,
    view: searchParams.get('view'),
    analyser: searchParams.get('analyser'),
    item: searchParams.get('item'),
    settingsOpen,
    settingsSection,
  });

  // Clear the repo-internal nav params, returning to the default work-area
  // (repo main) while preserving any unrelated query params.
  const goRepoMain = () => {
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.delete('view');
      next.delete('analyser');
      next.delete('settings');
      next.delete('section');
      return next;
    });
  };

  const navigateTo = (target: CrumbTarget) => {
    switch (target.kind) {
      case 'repos':
        onBack();
        return;
      case 'repoMain':
        goRepoMain();
        return;
      case 'qualityTop':
        // Stay in Quality, drop the analyser drill-down.
        setSearchParams((prev) => {
          const next = new URLSearchParams(prev);
          next.set('view', 'quality');
          next.delete('analyser');
          return next;
        });
        return;
      case 'settingsTop':
        // Stay in Settings, drop the section drill-down.
        setSearchParams((prev) => {
          const next = new URLSearchParams(prev);
          next.set('settings', '');
          next.delete('section');
          return next;
        });
        return;
      case 'areaTop':
        // Stay in the work area, drop the selected-item drill-down.
        setSearchParams((prev) => {
          const next = new URLSearchParams(prev);
          next.delete('item');
          return next;
        });
        return;
      case 'current':
        return;
    }
  };

  return (
    <div className={cn('flex min-w-0 items-center justify-between gap-4', className)}>
      <nav aria-label="Breadcrumb" className="flex min-w-0 items-center gap-2.5 text-sm">
        {crumbs.map((crumb, i) => (
          <span key={`${crumb.label}-${i}`} className="flex min-w-0 items-center gap-2.5">
            {i > 0 && (
              <span className="text-border-strong" aria-hidden="true">
                /
              </span>
            )}
            {crumb.target.kind === 'current' ? (
              <span className="truncate font-medium">{crumb.label}</span>
            ) : (
              <button
                onClick={() => navigateTo(crumb.target)}
                className="truncate text-subtle transition-colors hover:text-foreground"
              >
                {crumb.label}
              </button>
            )}
          </span>
        ))}
      </nav>
    </div>
  );
}

export default RepoHeader;
