import React from 'react';
import { cn } from '@/lib/utils';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { CheckCircle2, XCircle, Clock } from 'lucide-react';
import type { TestPlan, TestCase } from '../types';

interface TestPlanDetailProps {
  testPlan?: TestPlan;
  className?: string;
}

interface TestCategoryProps {
  title: string;
  emoji: string;
  tests: TestCase[];
  showChange?: boolean;
}

const StatusIcon: React.FC<{ status: TestCase['status'] }> = ({ status }) => {
  switch (status) {
    case 'passing':
      return <CheckCircle2 className="h-4 w-4 text-green-500" />;
    case 'failing':
      return <XCircle className="h-4 w-4 text-red-500" />;
    case 'pending':
    default:
      return <Clock className="h-4 w-4 text-muted-foreground" />;
  }
};

const TestCategory: React.FC<TestCategoryProps> = ({ title, emoji, tests, showChange }) => {
  if (tests.length === 0) return null;

  const passing = tests.filter(t => t.status === 'passing').length;

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-medium flex items-center gap-2">
          <span>{emoji}</span>
          <span>{title}</span>
        </h4>
        <span className={cn(
          'text-xs px-2 py-0.5 rounded',
          passing === tests.length
            ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300'
            : 'bg-muted text-muted-foreground'
        )}>
          {passing}/{tests.length} passing
        </span>
      </div>
      <div className="space-y-1">
        {tests.map((test, index) => (
          <div
            key={`${test.file}-${test.case || index}`}
            className="flex items-start gap-2 text-sm p-2 rounded bg-muted/50"
          >
            <StatusIcon status={test.status} />
            <div className="flex-1 min-w-0">
              <div className="font-mono text-xs text-muted-foreground truncate">
                {test.file}
              </div>
              {test.case && (
                <div className="text-sm">{test.case}</div>
              )}
              {showChange && test.change && (
                <div className="text-xs text-amber-600 dark:text-amber-400 mt-0.5">
                  Change: {test.change}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const TestPlanDetail: React.FC<TestPlanDetailProps> = ({ testPlan, className }) => {
  if (!testPlan) {
    return null;
  }

  const regression = testPlan.regression || [];
  const amended = testPlan.amended || [];
  const newTests = testPlan.newTests || [];

  const totalTests = regression.length + amended.length + newTests.length;

  if (totalTests === 0) {
    return null;
  }

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Test Plan</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <TestCategory
          title="Regression Tests"
          emoji="🔒"
          tests={regression}
        />
        <TestCategory
          title="Amended Tests"
          emoji="✏️"
          tests={amended}
          showChange
        />
        <TestCategory
          title="New Tests"
          emoji="🆕"
          tests={newTests}
        />
      </CardContent>
    </Card>
  );
};

export default TestPlanDetail;
