import { useState, type ReactNode } from 'react';
import {
  Info, PencilRuler, CheckCheck, Rocket, CircleX, Loader, TriangleAlert, Pause,
  Activity, RefreshCw, GitMerge, Shield, CircleCheck, Clock, GitPullRequest,
  CheckCircle2, Trash2, X, Archive, Siren, CircleDashed,
} from 'lucide-react';

// board-states-legend F6 task 3 — the lane-header (i) opens a states reference
// listing every state per lane with its reason, ported from the approved asset
// docs/prd/plan-readiness-indicators/assets/board-states-legend.html. The
// vocabulary is the served one (board-lane / lifecycle-phase / delivery-phase +
// provisioning / delivery-queue / validation-panel / attention); the reasons are
// the legend's own documentation.

/** Pill tone — maps to a CSS variable in board.css (`.tb-slg__pill[data-tone]`). */
export type StateTone =
  | 'plan' | 'blue' | 'primary' | 'review' | 'done'
  | 'red' | 'warn' | 'stalled' | 'orange' | 'neutral';

/**
 * The single source of truth for a phase/state's tone. A phase the map does not
 * know falls through to `neutral` — the dumb-UI extensibility rule (AC): a later
 * phase renders neutrally with no code change, never throws or mis-colours.
 */
const STATE_TONE: Readonly<Record<string, StateTone>> = {
  // Backlog
  planning: 'plan', planned: 'blue', launched: 'blue', 'run-failed': 'red',
  'setting-up': 'neutral', 'setup-failed': 'warn',
  // In progress
  working: 'primary', stalled: 'stalled',
  // In review
  validating: 'review', 'validation-failed': 'red', reconciling: 'blue',
  'reconcile-failed': 'red', merging: 'primary', 'merge-failed': 'red',
  'validating-on-main': 'review', 'post-merge-failed': 'red',
  'ready-to-land': 'done', 'validation-pending': 'neutral', 'pr-raised': 'review',
  // Done
  landed: 'done', cleanup: 'warn',
  // Off-board
  superseded: 'orange', archived: 'neutral',
  // Overlays
  regression: 'red', 'red-main-banner': 'red', 'run-failed-badge': 'red',
};

export function stateTone(key: string): StateTone {
  return STATE_TONE[key] ?? 'neutral';
}

interface StateDef {
  key: string;
  label: string;
  icon: ReactNode;
  why: string;
}
interface LaneDef {
  label: string;
  dot: string;
  states: readonly StateDef[];
  subnote?: string;
}

const ICON = { width: 12, height: 12 };

const LANES: readonly LaneDef[] = [
  {
    label: 'Backlog', dot: 'var(--color-subtle)',
    states: [
      { key: 'planning', label: 'Planning', icon: <PencilRuler {...ICON} />, why: 'Readiness gates pending, in rework, or stale' },
      { key: 'planned', label: 'Planned', icon: <CheckCheck {...ICON} />, why: 'All gates passed — ready to dispatch' },
      { key: 'launched', label: 'Launched', icon: <Rocket {...ICON} />, why: 'Dispatched; worker running, no first commit yet' },
      { key: 'run-failed', label: 'Run failed', icon: <CircleX {...ICON} />, why: 'Dispatched worker died before its first commit' },
      { key: 'setting-up', label: 'Setting up…', icon: <Loader {...ICON} />, why: 'Launch worktree being provisioned' },
      { key: 'setup-failed', label: 'Setup failed', icon: <TriangleAlert {...ICON} />, why: 'A worktree setup step failed (environment)' },
    ],
    subnote: 'gate checks · outstanding · passed · needs-rework · stale',
  },
  {
    label: 'In progress', dot: 'var(--color-blue)',
    states: [
      { key: 'working', label: 'Working', icon: <Loader {...ICON} />, why: 'A run is executing (or recent activity)' },
      { key: 'stalled', label: 'Stalled', icon: <Pause {...ICON} />, why: 'In progress but nothing attached — parked' },
      { key: 'run-failed', label: 'Run failed', icon: <CircleX {...ICON} />, why: 'Worker run failed / stalled, not resumed' },
    ],
    subnote: 'TDD · red → green → adversarial → mutation → complete',
  },
  {
    label: 'In review', dot: 'var(--color-phase-review)',
    states: [
      { key: 'validating', label: 'Validating', icon: <Activity {...ICON} />, why: 'Completion suite running' },
      { key: 'validation-failed', label: 'Validation failed', icon: <CircleX {...ICON} />, why: 'Completion suite failed — the work is wrong' },
      { key: 'reconciling', label: 'Reconciling', icon: <RefreshCw {...ICON} />, why: 'Rebasing onto main' },
      { key: 'reconcile-failed', label: 'Reconcile failed', icon: <CircleX {...ICON} />, why: 'Reconcile red — build / verify failed' },
      { key: 'merging', label: 'Merging', icon: <GitMerge {...ICON} />, why: 'Land / merge run executing' },
      { key: 'merge-failed', label: 'Merge failed', icon: <TriangleAlert {...ICON} />, why: 'Reconcile hit conflicts — handed to /merge' },
      { key: 'validating-on-main', label: 'Validating on main', icon: <Shield {...ICON} />, why: 'Post-merge full regression running' },
      { key: 'post-merge-failed', label: 'Post-merge failed', icon: <CircleX {...ICON} />, why: 'Post-merge regression failed' },
      { key: 'ready-to-land', label: 'Ready to land', icon: <CircleCheck {...ICON} />, why: 'Validated — awaiting the Merge action (± main@sha)' },
      { key: 'validation-pending', label: 'Validation pending', icon: <Clock {...ICON} />, why: 'Completion coming, no run yet' },
      { key: 'pr-raised', label: 'PR raised', icon: <GitPullRequest {...ICON} />, why: 'PR-mode follow-on (defined, not yet emitted)' },
    ],
    subnote: 'reconcile detail · queued · rebasing · agent resolving · verifying · conflicts',
  },
  {
    label: 'Done', dot: 'var(--color-done)',
    states: [
      { key: 'landed', label: 'Landed', icon: <CheckCircle2 {...ICON} />, why: 'Merged + main-validated — regression green (no pill on the card)' },
      { key: 'cleanup', label: 'Cleanup', icon: <Trash2 {...ICON} />, why: 'Delivered; worktrees / attachments unreaped' },
    ],
  },
];

const OFF_BOARD: readonly StateDef[] = [
  { key: 'superseded', label: 'Superseded', icon: <X {...ICON} />, why: 'Human closed it (duplicate / resolved elsewhere) → Archive' },
  { key: 'archived', label: 'Archived', icon: <Archive {...ICON} />, why: 'PRD / fix hidden from active views entirely' },
];

const OVERLAYS: readonly StateDef[] = [
  { key: 'regression', label: 'Regression', icon: <TriangleAlert {...ICON} />, why: 'This card is the attributed culprit of a red main' },
  { key: 'red-main-banner', label: 'Red-main banner', icon: <Siren {...ICON} />, why: 'Board-wide alarm while any regression fix is open' },
  { key: 'run-failed-badge', label: 'Run-failed badge', icon: <CircleX {...ICON} />, why: 'Crashed-run badge beside the phase pill' },
];

function Pill({ state }: { state: StateDef }) {
  return (
    <span className="tb-slg__pill" data-tone={stateTone(state.key)}>
      {state.icon}
      {state.label}
    </span>
  );
}

function State({ state }: { state: StateDef }) {
  return (
    <div className="tb-slg__state">
      <Pill state={state} />
      <span className="tb-slg__why">{state.why}</span>
    </div>
  );
}

/**
 * The board lane-header (i) affordance and the states reference it opens. The
 * (i) toggles the panel; the panel enumerates every state per lane with its
 * reason, plus off-board and cross-lane overlay bands.
 */
export function BoardStatesLegend({ defaultOpen = false }: { defaultOpen?: boolean } = {}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <span className="tb-slg">
      <button
        type="button"
        className="tb-slg__trigger"
        aria-label="What do the states mean?"
        aria-expanded={open}
        // The mount is wrapped in <FilterSeam> (BoardView), which stops clicks in
        // the trigger and the open panel short of the lane-focus handler.
        onClick={() => setOpen((v) => !v)}
      >
        <Info width={14} height={14} />
      </button>

      {open && (
        <div className="tb-slg__panel" role="region" aria-label="Board states reference">
          <p className="tb-slg__eyebrow">states reference · every phase &amp; why</p>

          <div className="tb-slg__lanes">
            {LANES.map((lane) => (
              <div key={lane.label} className="tb-slg__lane">
                <div className="tb-slg__lane-hdr">
                  <span className="tb-slg__dot" style={{ background: lane.dot }} aria-hidden />
                  {lane.label}
                </div>
                {lane.states.map((s, i) => (
                  <State key={`${s.key}-${i}`} state={s} />
                ))}
                {lane.subnote && <div className="tb-slg__subnote">{lane.subnote}</div>}
              </div>
            ))}
          </div>

          <p className="tb-slg__eyebrow tb-slg__band-hdr">off the board</p>
          <div className="tb-slg__band">
            {OFF_BOARD.map((s) => <State key={s.key} state={s} />)}
          </div>

          <p className="tb-slg__eyebrow tb-slg__band-hdr">overlays · ride on any lane</p>
          <div className="tb-slg__band">
            {OVERLAYS.map((s) => <State key={s.key} state={s} />)}
          </div>

          <p className="tb-slg__foot">
            An <span className="tb-slg__pill" data-tone="neutral"><CircleDashed {...ICON} /> Unknown</span>{' '}
            phase the reference does not know maps to a neutral pill with no colour and no code change.
          </p>
        </div>
      )}
    </span>
  );
}
