/**
 * The message a refused API response carries: the server's `{ error }` body
 * when it sent one, else `fallback` (by default the bare HTTP status). A body
 * that isn't JSON degrades to the fallback rather than throwing.
 */
export async function responseError(
  res: Response,
  fallback: string = `HTTP ${res.status}`,
): Promise<string> {
  const body = (await res.json().catch(() => ({}))) as { error?: string };
  return body.error ?? fallback;
}
