import React, { useState } from 'react';
import { AlertCircle, Bot, Cloud, GitBranch, RotateCcw, Square } from 'lucide-react';
import { Skeleton } from './ui/skeleton';
import type { RunStatus, DerivedRunWorktree } from '@magic-ingredients/tiny-brain-core';
import { Island } from './Island';
import WorkerRunActivity from './WorkerRunActivity';
import { useRunDetail } from '../hooks/useRunDetail';
import { formatRelativeTime } from '../utils/relative-time';
import { formatRunDuration, formatDurationMs } from '../utils/run-duration';
import { runHeadingTitle, runFeatureLabel } from '../features/runs/run-title';

interface WorkerRunIslandProps {
  repoId: string;
  runId: string;
  onClose: () => void;
  /**
   * Follow a continued run: called with the NEW runId after a successful
   * resume POST so the mount can re-key the island (RepoDetailPage sets
   * the `?run=` param; the runs lens sets its selected row).
   */
  onContinued?: (newRunId: string) => void;
  /**
   * Open the worktree the run ran in: called with the run's branch so the host
   * can route to the worktree view (RepoDetailPage sets `?island=<branch>`).
   * Only wired for a LIVE derived worktree — a reaped one is named, not linked.
   */
  onOpenWorktree?: (branch: string) => void;
}

/**
 * The run's status is live only while it's `running` or `cancelling`; every
 * other status is terminal (settled). The header pill and any live affordance
 * follow this — a settled run shows no spinner, matching the run-island mock.
 */
const isRunLive = (status: RunStatus): boolean =>
  status === 'running' || status === 'cancelling';

/**
 * Mirrors the server's RESUMABLE_STATUSES predicate (run-record-store):
 * only these terminal states can be continued. Spelled locally because
 * client code must not value-import the core barrel (it drags node
 * built-ins into the Vite bundle); the resume route re-checks the same
 * predicate server-side, so drift fails loud with a 409, not silently.
 */
const isRunResumable = (status: RunStatus): boolean =>
  status === 'failed' || status === 'cancelled' || status === 'stalled';

/** A labelled metric cell (the mock's `.vital`): mono uppercase term + value. */
const Vital: React.FC<{ term: string; className?: string; children: React.ReactNode }> = ({
  term,
  className,
  children,
}) => (
  <div className={`min-w-0 ${className ?? ''}`}>
    <dt className="mono text-[9px] uppercase tracking-[0.14em] text-subtle">{term}</dt>
    <dd className="mono mt-0.5 flex min-w-0 items-center gap-1.5 truncate text-xs text-foreground">
      {children}
    </dd>
  </div>
);

/**
 * The Worktree vital (derive-worktree-from-run): the worktree the run ran in,
 * rendered by liveness. A live worktree with a handler is a link into the
 * worktree view; a live worktree with no handler, or a reaped one, is named
 * (the reaped name greyed) rather than presented as a clickable-looking control
 * that would no-op. Rendered only when the run HAS a derived worktree — a
 * non-worktree (machinery) run shows no Worktree vital at all.
 */
const WorktreeVital: React.FC<{
  worktree: DerivedRunWorktree;
  onOpen?: (branch: string) => void;
}> = ({ worktree, onOpen }) => {
  const canLink = worktree.live && onOpen !== undefined;
  return (
    <Vital term="Worktree" className="col-span-2 sm:col-span-4">
      <GitBranch className="h-3.5 w-3.5 flex-none" style={{ color: 'var(--color-primary)' }} aria-hidden />
      {canLink ? (
        <button
          type="button"
          data-testid="worker-run-worktree-link"
          onClick={() => onOpen?.(worktree.branch)}
          className="truncate text-left underline decoration-dotted underline-offset-2 hover:decoration-solid"
          style={{ color: 'var(--color-primary)' }}
          title="Open the worktree view"
        >
          {worktree.branch}
        </button>
      ) : (
        <span
          data-testid={worktree.live ? 'worker-run-worktree-name' : 'worker-run-worktree-reaped'}
          className={worktree.live ? 'truncate' : 'truncate text-subtle'}
          {...(worktree.live ? {} : { title: 'Worktree reaped — no longer on disk' })}
        >
          {worktree.branch}
        </span>
      )}
    </Vital>
  );
};

/**
 * The WorkerRun island (F12 task-4). Opened from the MiniStatusRail's Running
 * pill, it shows a run's vitals — worker · model · target, the workRef it acts
 * on, its worktree branch, and its retry parent, read from the
 * T1 run-detail contract (`useRunDetail`) so it survives navigation — plus the
 * LIVE streamed terminal by mounting {@link WorkerRunActivity} over the run
 * SSE. A running run tails live and shows a status pill; a settled run shows
 * neither pill nor live spinner. The terminal mounts on runId alone, so it
 * tails even while the vitals are still loading (or failed to load). Dismiss is
 * the shared {@link Island} click-away / Escape — no close button.
 */
const WorkerRunIsland: React.FC<WorkerRunIslandProps> = ({
  repoId,
  runId,
  onClose,
  onContinued,
  onOpenWorktree,
}) => {
  const { detail, loading, error } = useRunDetail(repoId, runId);
  const record = detail?.record;
  const workRef = record?.workRef;
  // The feature label beneath the heading (shared title-over-slug rule) — null
  // unless this is a PRD run carrying a feature, so the subtitle line renders
  // only when there is a feature to name.
  const featureLabel = record ? runFeatureLabel(record.workRef, detail?.titles) : null;
  const live = record ? isRunLive(record.status) : false;
  const resumable = record ? isRunResumable(record.status) : false;
  const budgetLine =
    record?.timeoutMs !== undefined ? formatDurationMs(record.timeoutMs) : null;

  // Dumb POST: the route resolves the target and cancels; the button fires it
  // by id and latches while in flight so it can't be double-sent. On success it
  // stays latched — the record's status settles via the git-fetch projection,
  // not here. A rejected or non-ok cancel un-latches to an error so the user
  // can retry, rather than latching "Cancelling…" forever on a failed request.
  const [cancelState, setCancelState] = useState<'idle' | 'requesting' | 'error'>('idle');
  const requestCancel = () => {
    setCancelState('requesting');
    void (async () => {
      try {
        const res = await fetch(
          `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(runId)}/cancel`,
          { method: 'POST' },
        );
        if (!res.ok) setCancelState('error');
      } catch {
        setCancelState('error');
      }
    })();
  };
  const cancelLabel =
    cancelState === 'requesting'
      ? 'Cancelling…'
      : cancelState === 'error'
        ? 'Retry cancel'
        : 'Cancel run';

  // Continue a resumable run (fix failed-run-continue-relaunch task 2):
  // the same dumb-POST shape as cancel. The route re-dispatches via the
  // resume mechanics (same worktree + branch) and answers the NEW runId,
  // which goes to the mount's follow callback — the island itself stays
  // keyed by its prop. Success stays latched (the follow re-keys or the
  // projection settles); a failed POST un-latches to a retry.
  const [continueState, setContinueState] = useState<
    'idle' | 'requesting' | 'done' | 'error'
  >('idle');
  // WHY a Continue failed — the route answers a structured { error }
  // (e.g. the CLI spawn's exit diagnosis); swallowing it leaves a bare
  // "Retry continue" nobody can act on (fix resume-route-cli-contract-
  // mismatch task 2, found live).
  const [continueError, setContinueError] = useState<string | null>(null);
  const requestContinue = () => {
    setContinueState('requesting');
    setContinueError(null);
    void (async () => {
      try {
        const res = await fetch(
          `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(runId)}/resume`,
          { method: 'POST' },
        );
        if (!res.ok) {
          const body = (await res.json().catch(() => ({}))) as { error?: string };
          setContinueError(
            typeof body.error === 'string' ? body.error : `Continue failed (HTTP ${res.status})`,
          );
          setContinueState('error');
          return;
        }
        const data = (await res.json()) as { runId?: string };
        if (typeof data.runId !== 'string') {
          // A 200 that violates the { runId } contract must un-latch to a
          // retry, not wedge "Continuing…" forever.
          setContinueError('Continue failed — no run id returned');
          setContinueState('error');
          return;
        }
        // Settle BEFORE following: a mount without a follow callback still
        // exits the latch honestly ("Continued", stays disabled — the child
        // run exists, a second POST would fork it again).
        setContinueState('done');
        onContinued?.(data.runId);
      } catch (e) {
        setContinueError(e instanceof Error ? e.message : 'Continue failed');
        setContinueState('error');
      }
    })();
  };
  const continueLabel =
    continueState === 'requesting'
      ? 'Continuing…'
      : continueState === 'done'
        ? 'Continued'
        : continueState === 'error'
          ? 'Retry continue'
          : 'Continue run';

  // The accessible name pairs the run's kind with the work it acts on, so the
  // dialog is announced as e.g. "fix run — dashboard-sse-drops-events".
  const heading = workRef ? `${workRef.kind} run — ${workRef.id}` : 'Worker run';

  return (
    // Keep the shared island top gap (fix feature-card-live-glyph-and-run-watch-
    // surface task 3): rendered flush, the watch surface ran to the very top of
    // the page. Reserving the same top gap every other island leaves sits it below
    // the page top, matching these pages' convention. (This reverses the earlier
    // run-dispatch-stale-dashboard `flush` call, per an explicit user request.)
    <Island open onClose={onClose} ariaLabel={heading}>
      <header className="shrink-0 border-b border-border px-6 pt-5 pb-4">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <span className="eyebrow text-[10px] text-subtle">worker run</span>
            {live && (
              <span
                data-testid="worker-run-island-running"
                className="inline-flex flex-shrink-0 items-center gap-1.5 rounded-lg bg-[color-mix(in_oklab,#3b82f6_12%,transparent)] px-2 py-0.5 text-[11px] font-medium text-blue-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,#3b82f6_38%,transparent)] dark:text-blue-300"
              >
                <span
                  className="h-1.5 w-1.5 flex-shrink-0 rounded-full bg-blue-500 motion-safe:animate-pulse"
                  aria-hidden
                />
                Running
              </span>
            )}
          </div>
          <span className="mono text-xs text-subtle">{runId}</span>
        </div>

        {record ? (
          <>
            <h2
              className="display mt-2 flex min-w-0 items-center gap-2 text-xl font-bold leading-snug"
              style={{ color: 'var(--foreground)' }}
            >
              <span className="pill flex-none bg-[color-mix(in_oklab,var(--color-warn)_15%,transparent)] text-[var(--color-warn)]">
                {record.workRef.kind}
              </span>
              {/* Titles over slugs (task 8): the shared title-over-slug rule —
                  the PRD title for feature work, the fix title for fix work,
                  slug fallback. The feature title gets its OWN line below (task
                  9) — two titles inline ellide each other. */}
              <span className="truncate">{runHeadingTitle(record.workRef, detail.titles, record.kind)}</span>
            </h2>

            {/* The feature half, stacked and slightly smaller so each title
                gets the full row width. `runFeatureLabel` is null unless this is
                a PRD run carrying a feature, and falls back to the feature slug
                on a half-resolved read — both halves stay named. */}
            {featureLabel !== null && (
              <p
                data-testid="worker-run-feature-subtitle"
                className="mt-1 flex min-w-0 items-center gap-2 text-sm font-medium text-muted-foreground"
              >
                {/* Mirrors the h2's kind pill so the two lines read PRD → feature. */}
                <span className="pill flex-none bg-[color-mix(in_oklab,var(--color-warn)_15%,transparent)] text-[10px] text-[var(--color-warn)]">
                  feature
                </span>
                <span className="truncate">{featureLabel}</span>
              </p>
            )}

            <div className="mt-2 flex items-center justify-between gap-3">
              <div className="mono flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground">
                <Bot className="h-4 w-4 flex-none" style={{ color: 'var(--color-primary)' }} aria-hidden />
                <span className="truncate">{record.worker}</span>
                <span className="text-subtle">·</span>
                <span className="truncate">{record.model}</span>
                <span className="text-subtle">·</span>
                <Cloud className="h-3.5 w-3.5 flex-none text-subtle" aria-hidden />
                <span className="truncate">{record.target}</span>
                {/* Effort is the WORKER's attribute (task 12), so it rides
                    this row rather than the run vitals. */}
                <span className="text-subtle">·</span>
                <span className="effort flex-none">{record.effort}</span>
              </div>
              {live && (
                <button
                  type="button"
                  data-testid="worker-run-island-cancel"
                  onClick={requestCancel}
                  disabled={cancelState === 'requesting'}
                  aria-invalid={cancelState === 'error'}
                  className="mono inline-flex flex-none items-center gap-1.5 rounded-lg border border-border px-2.5 py-1 text-[11px] font-semibold text-[var(--color-warn)] transition-colors hover:bg-[color-mix(in_oklab,var(--color-warn)_12%,transparent)] disabled:opacity-50"
                >
                  <Square className="h-3.5 w-3.5" aria-hidden />
                  {cancelLabel}
                </button>
              )}
              {resumable && (
                <button
                  type="button"
                  data-testid="worker-run-island-continue"
                  onClick={requestContinue}
                  disabled={continueState === 'requesting' || continueState === 'done'}
                  aria-invalid={continueState === 'error'}
                  className="mono inline-flex flex-none items-center gap-1.5 rounded-lg bg-[color-mix(in_oklab,#3b82f6_14%,transparent)] px-2.5 py-1 text-[11px] font-semibold text-blue-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,#3b82f6_38%,transparent)] transition-colors hover:bg-[color-mix(in_oklab,#3b82f6_22%,transparent)] disabled:opacity-50 dark:text-blue-300"
                >
                  <RotateCcw className="h-3.5 w-3.5" aria-hidden />
                  {continueLabel}
                </button>
              )}
            </div>

            {/* The reason a Continue failed — actionable, not just a retry
                label. Mirrors LaunchControl's dispatchError honesty. */}
            {continueError !== null && (
              <p
                data-testid="worker-run-island-continue-error"
                className="mono mt-1.5 text-right text-[11px] text-red-500 dark:text-red-300"
              >
                {continueError}
              </p>
            )}

            {/* WHY a failed run failed — the record's diagnosis, previously
                never rendered, so a failed run read as an unexplained blank.
                An unclassified failure (spawn-time ENOENT etc.) says so
                honestly rather than omitting the block (|| so an empty-string
                exitReason gets the placeholder too). The other read-as-failure
                terminal states (stalled/rejected) show the block only when a
                reason was actually recorded. */}
            {(record.status === 'failed' ||
              ((record.status === 'stalled' || record.status === 'rejected') &&
                Boolean(record.exitReason))) && (
              <div
                data-testid="worker-run-island-failure"
                className="mt-3 flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20"
              >
                <AlertCircle className="mt-0.5 h-4 w-4 flex-none text-red-500" aria-hidden />
                <div className="min-w-0 text-sm text-red-700 dark:text-red-300">
                  {/* Detail-first (fix process-died-reason-lacks-diagnostic-
                      detail): the captured death evidence replaces the bare
                      reason, which an evidence-less settle still falls back to. */}
                  <span className="mono break-words">
                    {record.exitReasonDetail ||
                      record.exitReason ||
                      'Run failed — no exit reason recorded'}
                  </span>
                  {/* The pill wears the server RE-DERIVED verdict (task 5) —
                      today's classifier over the recorded reason. The
                      record.failureClass arm is unreachable against a
                      current server (it folds the fallback in) — it exists
                      for VERSION SKEW: a stale dashboard backend that
                      predates displayFailureClass must keep showing the
                      stored pill, not none at all. */}
                  {(detail.displayFailureClass ?? record.failureClass) && (
                    <span className="pill ml-2 bg-[color-mix(in_oklab,#ef4444_15%,transparent)] text-[11px] text-red-600 dark:text-red-300">
                      {detail.displayFailureClass ?? record.failureClass}
                    </span>
                  )}
                  {/* The budget the dispatch computed (fix worker-run-timeouts
                      task 3) — "killed at some cap" becomes "killed at its 2h
                      budget". ONLY on a timeout: every record now carries
                      timeoutMs, so attributing it to a spawn crash or a stall
                      would imply a deadline kill that never happened. */}
                  {budgetLine !== null &&
                    record.exitReason?.startsWith('claude-timeout') === true && (
                      <span className="mono mt-1 block text-xs text-red-600/80 dark:text-red-300/80">
                        {`${budgetLine} budget`}
                      </span>
                    )}
                </div>
              </div>
            )}

            <dl className="mt-4 grid grid-cols-2 gap-x-6 gap-y-3 sm:grid-cols-4">
              <Vital term="Started">
                <span className="truncate">{formatRelativeTime(record.startedAt) ?? '—'}</span>
              </Vital>
              {/* Present-tense while the run is LIVE (running/cancelling) —
                  the duration is still elapsing; past-tense once settled. */}
              <Vital term={live ? 'Running for' : 'Ran for'}>
                <span className="truncate">
                  {formatRunDuration(record.startedAt, record.endedAt) ?? '—'}
                </span>
              </Vital>
              <Vital term="Retry of">
                <span className="truncate text-subtle">
                  {detail.history[0]?.runId ?? '— (top-level run)'}
                </span>
              </Vital>
              {/* The worktree the run ran in (derive-worktree-from-run). Full
                  row (task 10): the on-disk Path vital duplicated the branch and
                  truncated anyway — the branch gets the width. */}
              {detail.worktree !== null && (
                <WorktreeVital worktree={detail.worktree} onOpen={onOpenWorktree} />
              )}
            </dl>
          </>
        ) : error ? (
          <div
            data-testid="worker-run-island-error"
            className="mt-3 flex items-start gap-2 text-sm text-red-600 dark:text-red-300"
          >
            <AlertCircle className="mt-0.5 h-4 w-4 flex-none" aria-hidden />
            <span>{error}</span>
          </div>
        ) : loading ? (
          // In-flight run fetch: a vitals-line-shaped skeleton, not a text
          // flash (loading-text-flash-replace-with-skeletons task 1).
          <div
            data-testid="worker-run-island-vitals-loading"
            role="status"
            aria-label="Loading run…"
            className="mt-3 flex items-center gap-2"
          >
            <Skeleton aria-hidden className="h-4 w-40" />
          </div>
        ) : null}
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto px-6 py-5">
        <WorkerRunActivity repoId={repoId} runId={runId} />
      </div>
    </Island>
  );
};

export default WorkerRunIsland;
