import React from 'react';
import type { TaskRowTask, TddPhase } from '../types';
import type { PipelineStep, ReviewVerdict } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { ADVERSARIAL_STEP } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';
import {
  buildPipelinePhases,
  derivePhaseChipState,
  getPhaseCommitSha,
  isRefactorInProgress,
  type PhaseChipState,
} from '../utils/pipeline-phases';
import { PipelineChip, type ChipPhase } from './PipelineChip';

interface CommitPipelineProps {
  task: TaskRowTask;
  reviewPipeline?: PipelineStep[];
}

/** Map a TDD phase to its chip colour. Refactor phases fold into their review
 *  chip (Task 3) and are never rendered as standalone chips here. */
const chipPhaseFor = (phase: TddPhase): ChipPhase => {
  if (phase === 'red') return 'red';
  if (phase === 'green') return 'green';
  return 'review';
};

const PHASE_BLURB: Record<string, string> = {
  red: 'failing test written',
  green: 'test passing',
};

const short = (sha: string): string => sha.substring(0, 7);

const chipTitle = (label: string, phase: TddPhase, state: PhaseChipState, sha: string | undefined): string => {
  if (state === 'done' && sha) {
    const blurb = PHASE_BLURB[phase];
    return blurb ? `${label} · ${blurb} · ${short(sha)}` : `${label} · ${short(sha)}`;
  }
  if (state === 'current') return `${label} · in progress`;
  return `${label} · not started`;
};

// A refactor SHA that represents real follow-up work (not an auto-skip sentinel).
const isRealRefactor = (sha: string | undefined): sha is string =>
  sha !== undefined && sha !== 'skipped' && sha !== 'max-attempts-exceeded';

interface ChipContent {
  label: React.ReactNode;
  title: string;
  secondaryPhase?: ChipPhase;
}

const withSha = (text: string, sha: string | undefined): string =>
  sha ? `${text} · ${short(sha)}` : text;

/**
 * The visible label, tooltip and optional second dot for a completed review
 * gate. A needs-refactoring verdict that drove a real refactor commit is the
 * two-dot "Review + refactor"; a clean verdict is the single-dot "Review ·
 * clean". The not-clean terminal states are surfaced honestly rather than
 * masked as clean: a needs-refactoring verdict with no landed refactor (auto-
 * skipped / max-attempts-exceeded) reads "refactor required", and a failed
 * gate (its tool could not run) reads "review failed".
 */
const completedReviewChip = (gateLabel: string, reviewSha: string | undefined, refactorSha: string | undefined, verdict: ReviewVerdict | undefined): ChipContent => {
  if (verdict === 'needs-refactoring') {
    if (isRealRefactor(refactorSha)) {
      return {
        label: <>Review<span className="rf">+</span><span className="rf">Refactor</span></>,
        title: `${gateLabel} → refactor required · ${reviewSha ? short(reviewSha) : '—'} → ${short(refactorSha)}`,
        secondaryPhase: 'refactor',
      };
    }
    return { label: <span className="review-label">Review</span>, title: withSha(`${gateLabel} → refactor required`, reviewSha) };
  }
  if (verdict === 'failed') {
    return { label: <span className="review-label">Review</span>, title: withSha(`${gateLabel} review failed`, reviewSha) };
  }
  return {
    label: <span className="clean-label">Review<span className="dim">&gt;</span><span className="dim">Clean</span></span>,
    title: withSha(`${gateLabel} — no refactor needed`, reviewSha),
  };
};

/**
 * The per-task commit-pipeline row — the signature element. Renders the
 * git-sourced phases (Red → Green → review gate per pipeline step) as
 * phase-coloured chips in an ordered list, separated by `›`. A completed chip
 * carries its commit SHA in the tooltip and routes a click to `onPhaseClick`.
 */
const CommitPipeline: React.FC<CommitPipelineProps> = ({ task, reviewPipeline }) => {
  const effectivePipeline = reviewPipeline ?? [ADVERSARIAL_STEP];
  const phases = buildPipelinePhases(effectivePipeline, task.pipelineType, task.pipelineSnapshot);
  // Always derive state under the resolved pipeline so the default and explicit
  // paths behave identically (combineRedGreenCommits stays false — red and green
  // are distinct chips).
  const config = { combineRedGreenCommits: false, reviewPipeline: effectivePipeline };

  const items: React.ReactNode[] = [];
  phases.forEach((p, i) => {
    const state = derivePhaseChipState(task, p.phase, config);
    const commitSha = getPhaseCommitSha(task, p.phase);
    const isReview = p.phase.startsWith('review:');

    // Default: Red/Green show their own name; a review chip reads the generic
    // "Review" with the gate name (p.label) in the tooltip.
    let content: ChipContent = {
      label: isReview ? <span className="review-label">Review</span> : p.label,
      title: chipTitle(p.label, p.phase, state, commitSha),
    };
    if (p.phase === 'red' && state === 'skipped') {
      content = { label: <span className="line-through">Red</span>, title: 'Red phase skipped' };
    } else if (isReview && state === 'current' && isRefactorInProgress(task, p.phase.slice(7))) {
      // A review chip is 'current' in TWO sub-states: the review itself running
      // (no verdict yet) and the refactor running (needs-refactoring verdict,
      // refactor not committed). The isRefactorInProgress re-check is NOT
      // redundant — it picks the refactor sub-state out so it renders the live
      // two-dot "Review + refactor" rather than the default review-in-progress
      // chip. Verdict landed needs-refactoring + refactor in flight: show it
      // live rather than as a static "refactor required".
      content = {
        label: <>Review<span className="rf">+</span><span className="rf">Refactor</span></>,
        title: `${p.label} → refactor in progress`,
        secondaryPhase: 'refactor',
      };
    } else if (isReview && state === 'done') {
      const review = task.reviews?.[p.phase.slice(7)];
      content = completedReviewChip(p.label, commitSha, review?.refactorCommitSha, review?.verdict);
    }

    if (i > 0) {
      items.push(
        <li key={`sep-${p.phase}`} aria-hidden="true" className="sep">
          ›
        </li>,
      );
    }
    items.push(
      <li key={p.phase}>
        <PipelineChip
          label={content.label}
          phase={chipPhaseFor(p.phase)}
          state={state}
          title={content.title}
          secondaryPhase={content.secondaryPhase}
          className={isReview ? 'chip-review' : undefined}
        />
      </li>,
    );
  });

  return (
    <ol aria-label="Commit pipeline" className="flex shrink-0 flex-wrap items-center gap-1.5">
      {items}
    </ol>
  );
};

export default CommitPipeline;
