// In-flight board-item fetch: a skeleton frame approximating the detail
// island's header + body — at sub-second latencies loading text reads as
// flicker where a stable frame reads as continuity. The flash is
// skeleton-ONLY (operator ruling, fix superseded-feature-endcap-and-skeleton-title-nits
// task 2): no visible text renders. The sr-only node is what the status
// region actually announces on insertion — an aria-label alone names a live
// region but is commonly not read out, and every visible child is hidden.
function BoardDetailSkeleton({ title }: { title: string }) {
  return (
    <div
      data-testid="board-detail-skeleton"
      role="status"
      aria-label={`Loading ${title}…`}
      className="flex flex-col gap-4 p-6"
    >
      <span className="sr-only">{`Loading ${title}…`}</span>
      <div aria-hidden className="flex flex-col gap-4">
        <Skeleton className="h-5 w-1/3" />
        <div className="flex gap-2">
          <Skeleton className="h-5 w-16" />
          <Skeleton className="h-5 w-16" />
          <Skeleton className="h-5 w-16" />
        </div>
        <Skeleton className="h-24 w-full" />
        <Skeleton className="h-16 w-full" />
        <Skeleton className="h-16 w-full" />
      </div>
    </div>
  )
}

// The selectable work views (board-first-chrome F3). The board is the sole work
// area; the retired kind lists (plans/fixes/spikes) and the absorbed In-flight
// view redirect to it (resolveWorkView), so they are not tabs. Quality, Decisions
// and Settings live in the top rail; agents/skills/plugins/hooks are their own views.
type TabType = 'board' | 'quality' | 'decisions' | 'agents' | 'skills' | 'plugins' | 'hooks'

// Helper to get/set localStorage with prefix
const getStorageKey = (repoId: string, key: string) => `tiny-brain:repo:${repoId}:${key}`

const getStoredValue = <T,>(repoId: string, key: string, defaultValue: T): T => {
  try {
    const stored = localStorage.getItem(getStorageKey(repoId, key))
    return stored ? JSON.parse(stored) : defaultValue
  } catch {
    return defaultValue
  }
}

const setStoredValue = <T,>(repoId: string, key: string, value: T): void => {
  try {
    localStorage.setItem(getStorageKey(repoId, key), JSON.stringify(value))
  } catch {
    // Ignore storage errors
  }
}

export default function RepoDetailPage() {
  const { repoId } = useParams<{ repoId: string }>()
  const [searchParams, setSearchParams] = useSearchParams()
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId ?? '')
  const { setRepo: setCurrentRepo } = useCurrentRepo()
  // repoId is always present on the /repos/:repoId route; `?? ''` mirrors the
  // file's existing fallback convention (see usePipelineConfig above).
  const workspacePanels = usePanelSizeMemory(`repo-workspace:${repoId ?? ''}`)

  // A ?section= deep-link (from a repo-card badge) opens the Setup tab at
  // that section, overriding the stored tab preference.
  const deepLinkSection = searchParams.get('section') ?? undefined

  // The full task detail view is an in-place view of this same route — opening
  // a task sets `?task=<id>&tab=<phase>` rather than navigating away, so the
  // workspace stays mounted and its plans/fixes/spikes data stays warm (no
  // refetch on open/close). When `?task` is absent the normal workspace renders.
  const selectedTaskId = searchParams.get('task')
  // The worktree-merge island is a content-replacing view keyed by branch (like
  // ?task=), so its transparent backdrop shows the single app wash.
  const islandBranch = searchParams.get('island')
  // A `prd:<id>` island is the PRD teardown surface (worktree-teardown-surface) —
  // a distinct content-replacing view keyed by PRD id, not a single branch.
  const teardownPrdId = islandBranch?.startsWith('prd:') ? islandBranch.slice('prd:'.length) : null
  // The WorkerRun island (F12) is a content-replacing view keyed by runId, like
  // ?task= / ?island=. Opened from a feature rail's Running pill; round-trips on
  // a bookmark and survives navigation because the island reads the run record.
  const selectedRunId = searchParams.get('run')
  const openRun = (runId: string) =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.set('run', runId)
      // Clear the selected board item (and its focused lane) so a board-launched
      // run — which reuses openRun while `?item=` is still set — renders the
      // island with `selectedItemId` null, byte-identical to the runs-list path.
      // Leaving `?item=` set keeps useBoardItemDetail active behind the island,
      // driving an extra run-change re-render storm. `closeRun` only touches
      // `run`; this makes open symmetric.
      next.delete('item')
      next.delete('lane')
      return next
    })
  const closeRun = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.delete('run')
      return next
    })
  // The design-assets view (surface-design-assets F4) is a MODE of the open
  // fix/PRD, so `?assets` is a bare marker: the item is already identified by
  // `?view=<area>&item=<slug>`, and the kind is derived from the active area.
  // Both still live in the URL, so the view round-trips on a bookmark.
  const assetsOpen = searchParams.has('assets')
  // The Archive view (board-first-chrome T3) is a content-replacing surface keyed
  // by the bare `?archive` marker (opened from the top-rail Archive control in
  // RepoViewControls). The board is active work only, so archived plans + fixes
  // live here, off-board.
  const archiveOpen = searchParams.has('archive')
  // The Runs lens (repo-header-runs-launcher) is a per-repo view keyed by the
  // bare `?runs` marker (opened from the top-rail Runs control in
  // RepoViewControls). It renders in the workspace body — NOT a `?view=` work
  // area — fed by the repo's live useRepoRuns data. Selecting a run deep-links
  // it (`?run=<id>`, parent-owned); the shared WorkerRun island (the early
  // return further up) then renders the detail over this browse-home lens.
  const runsOpen = searchParams.has('runs')
  const closeArchive = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.delete('archive')
      return next
    })
  // The raw `?tab=` value — TaskDetailPage resolves it against the task's pinned
  // gate-set (the gate-set isn't known here).
  const selectedTaskRawTab = searchParams.get('tab')
  const openTaskTab = (tab: TaskTab) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        next.set('tab', tab)
        return next
      },
      { replace: true },
    )
  }
  const closeTask = () => {
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.delete('task')
      next.delete('tab')
      return next
    })
  }

  // Repo Settings is an inline view that renders in the workspace content area
  // with the stage rail still visible — opened via the top-rail Settings control
  // (RepoViewControls) or a `?section=` badge deep-link, both of which set/imply
  // `?settings`. The rest of the workspace stays mounted; selecting a work area /
  // Quality clears the params and restores it with no refetch.
  const settingsOpen = searchParams.get('settings') !== null || deepLinkSection !== undefined
  const settingsSection = searchParams.get('settings') || deepLinkSection || undefined
  // Selecting a Settings section writes it to `?settings=<id>` so the section is
  // deep-linkable, survives reload, and shows in the breadcrumb. Drop the legacy
  // `?section=` alias so the two can't disagree. Replace — switching sections is
  // not a distinct history entry.
  const setSettingsSection = (id: string) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        next.set('settings', id)
        next.delete('section')
        return next
      },
      { replace: true },
    )
  }

  // The active work area is URL-driven via `?view=<area>` so it is deep-linkable
  // and survives reload. localStorage is only a fallback for the initial area
  // when the URL carries no `?view=`. The board is the sole work area: the
  // retired kind lists / In-flight view redirect to it (resolveWorkView), and a
  // malformed value lands on the board. The board's kind filter round-trips in
  // `?type=`; a kind-list redirect seeds it (plans → type=prd, etc.).
  const viewParam = searchParams.get('view')
  const storedTab = repoId ? getStoredValue<string>(repoId, 'activeTab', '') : ''
  const resolvedView = resolveWorkView(viewParam, storedTab || null)
  // The resolved work view — always one of the selectable TabType values.
  const activeTab: TabType = resolvedView.tab
  const boardType = coerceBoardType(searchParams.get('type'))
  const setBoardType = (next: BoardTypeFilter) => {
    setSearchParams(
      (prev) => {
        const params = new URLSearchParams(prev)
        if (next === 'all') params.delete('type')
        else params.set('type', next)
        // Selecting a board kind filter dismisses the runs lens: the runs surface
        // and the board filters are different flavours, so a filter chip switches
        // back to the board rather than filtering underneath it — the Runs toggle
        // remains the other way to dismiss it.
        params.delete('runs')
        // Defensive island cleanup, mirroring onRunsToggle: leaving the runs
        // surface must not strand its `?run` island. It is not reachable via this
        // gesture on its own (the run island is a full-page takeover, so a chip is
        // never rendered while `?run` is set), but clearing it keeps the invariant
        // "no runs surface ⇒ no runs island" total.
        params.delete('run')
        return params
      },
      { replace: true },
    )
  }
  // Attention mode (attention-filter F5) round-trips in the `?attention` marker
  // (presence ⇒ on; serialises as `attention=`) so the filtered board survives a
  // reload and back/forward. `has()` matches it regardless of the empty value.
  const boardAttention = searchParams.has('attention')
  const setBoardAttention = (on: boolean) => {
    setSearchParams(
      (prev) => {
        const params = new URLSearchParams(prev)
        if (on) params.set('attention', '')
        else params.delete('attention')
        return params
      },
      { replace: true },
    )
  }
  // Normalise / redirect the URL so it always carries the canonical resolved
  // view (and, for a kind-list redirect, its seed `?type=`). The breadcrumb in
  // the global header reads the area from the URL alone, so a bare load must
  // write `?view=board`; a legacy `?view=plans|fixes|spikes|in-flight|setup`
  // (or an unknown value) is rewritten to the board so no deep-link dead-ends.
  // The redirect only seeds `?type=` — once the URL is `?view=board`, the type
  // filter is user-controlled and this effect leaves it alone. Replace, so it
  // adds no history entry.
  const { tab: resolvedTab, boardType: redirectType } = resolvedView
  useEffect(() => {
    if (selectedTaskId) return
    if (searchParams.get('settings') !== null || searchParams.get('section') !== null) return
    // Every redirect target is the board and no redirected source is 'board', so
    // a raw view that differs from the resolved tab is exactly the redirect /
    // normalise trigger — this converges in one write.
    const needsView = searchParams.get('view') !== resolvedTab
    const needsType = redirectType !== undefined && searchParams.get('type') !== redirectType
    // A `?type=` that isn't a kind filter (fix/prd/spike) is garbage — the board
    // coerces it to 'all' for render, so scrub it from the URL rather than let it
    // linger (unless a redirect is about to overwrite it with the seed type).
    const rawType = searchParams.get('type')
    const typeIsGarbage = rawType !== null && rawType !== 'fix' && rawType !== 'prd' && rawType !== 'spike'
    const needsScrub = typeIsGarbage && redirectType === undefined
    if (!needsView && !needsType && !needsScrub) return
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        next.set('view', resolvedTab)
        if (redirectType) next.set('type', redirectType)
        else if (typeIsGarbage) next.delete('type')
        return next
      },
      { replace: true },
    )
  }, [selectedTaskId, searchParams, resolvedTab, redirectType, setSearchParams])
  // The selected Plan / Fix / Spike is URL-driven via `?item=<slug>` so a
  // specific item is deep-linkable and rendered as a breadcrumb drill-down
  // crumb. One param serves all three work areas because only one area is active
  // at a time; the value is scoped to the active area below. Switching area
  // clears it (see setActiveTab) so a stale slug can't leak across areas.
  const selectedItemId = searchParams.get('item')
  const setSelectedItemId = (id: string | null) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        if (id) next.set('item', id)
        else next.delete('item')
        return next
      },
      { replace: true },
    )
  }
  // board-surface task 2: the isolated lane (`?lane=`), round-tripped in the URL
  // alongside `?item=` so a focused board is deep-linkable and back/forward works.
  // Validate the raw param against the known keys (no blind cast) — a bogus
  // `?lane=` resolves to null and the board renders the grid.
  const rawLane = searchParams.get('lane')
  const focusedLane: BoardLaneKey | null = BOARD_LANE_KEYS.find((k) => k === rawLane) ?? null
  const setFocusedLane = (lane: BoardLaneKey | null) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        if (lane) {
          next.set('lane', lane)
        } else {
          // Returning to the full board (lane header / All-lanes crumb) also
          // deselects: clearing only `?lane` left `?item` set, so the grid came
          // back with a stale highlighted card that took two clicks to re-focus.
          next.delete('lane')
          next.delete('item')
        }
        return next
      },
      // push, not replace, so browser back returns to the grid / prior lane.
      { replace: false },
    )
  }
  // A board card click selects the item AND focuses its lane in ONE navigation —
  // two separate setSearchParams calls read the same stale params and the second
  // clobbers the first, dropping `?item=`.
  const selectBoardItem = (row: BoardRow) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        next.set('item', boardRowKey(row))
        next.set('lane', boardLaneKeyForRow(row))
        return next
      },
      { replace: false },
    )
  }

  const [selectedAgentId, setSelectedAgentIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedAgentId', null) : null
  )
  const [selectedSkillId, setSelectedSkillIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedSkillId', null) : null
  )
  const [selectedPluginId, setSelectedPluginIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedPluginId', null) : null
  )
  const [selectedQualityRunId, setSelectedQualityRunIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedQualityRunId', null) : null
  )

  // Wrapped setters that persist to localStorage
  // Selecting a work area / Quality writes `?view=<area>` (and closes any open
  // Settings view) in a single URL update, so the area round-trips through the
  // URL. The stored value keeps the "remember my last tab" behaviour for the
  // next visit that arrives without a `?view=`.
  const setActiveTab = (tab: TabType) => {
    if (repoId) setStoredValue(repoId, 'activeTab', tab)
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.set('view', tab)
      next.delete('settings')
      next.delete('section')
      // Drop the previous area's drill-downs so a stale item/analyser can't leak
      // into the newly selected area.
      next.delete('item')
      next.delete('analyser')
      return next
    })
  }
  const setSelectedAgentId = (id: string | null) => {
    setSelectedAgentIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedAgentId', id)
  }
  const setSelectedSkillId = (id: string | null) => {
    setSelectedSkillIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedSkillId', id)
  }
  const setSelectedPluginId = (id: string | null) => {
    setSelectedPluginIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedPluginId', id)
  }
  const setSelectedQualityRunId = (id: string | null) => {
    setSelectedQualityRunIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedQualityRunId', id)
  }
  const [viewMode] = useState<'summary' | 'details' | 'json'>('details')
  const [repoPlans, setRepoPlans] = useState<Plan[]>([])
  const [repoFixes, setRepoFixes] = useState<Fix[]>([])
  const [deliveryWorktrees, setDeliveryWorktrees] = useState<DeliveryWorktreeRow[]>([])
  // Whether the delivery queue has resolved at least once — distinguishes "still
  // loading" (a ?island= deep-link/reload before the fetch lands) from "no such
  // branch", so the island view shows the right state instead of silently
  // falling through to the workspace.
  const [deliveryLoaded, setDeliveryLoaded] = useState(false)
  // The PRD teardown model for the active ?island=prd:<id> view — fetched on
  // demand, keyed by the target PRD id (worktree-teardown-surface task 8).
  const [prdTeardown, setPrdTeardown] = useState<PrdTeardownModel | null>(null)
  const [prdTeardownLoaded, setPrdTeardownLoaded] = useState(false)
  // The teardown island's last non-success action outcome (F5 task 1) — a
  // conflicts/pending/failed land is surfaced, never silently discarded.
  const [teardownNotice, setTeardownNotice] = useState<string | null>(null)
  const [repoAgents, setRepoAgents] = useState<Agent[]>([])
  const [repoSkills, setRepoSkills] = useState<Skill[]>([])
  const [repoPlugins, setRepoPlugins] = useState<RepoPlugin[]>([])
  const [repoHooks, setRepoHooks] = useState<AllHooks>({ pluginHooks: [], repoHooks: [], gitHooks: [] })
  const [repoQualityRuns, setRepoQualityRuns] = useState<QualityRunSummary[]>([])
  const [, setLatestQualityGrade] = useState<string | null>(null)
  const [, setLatestQualityScore] = useState<number | null>(null)
  const [, setQualityCriteria] = useState<{ passing: number; total: number } | null>(null)
  const [selectedQualityRun, setSelectedQualityRun] = useState<QualityRunDetail | null>(null)
  const [repoInfo, setRepoInfo] = useState<RepoInfo | null>(null)
  const [, setLoading] = useState(true)
  const [, setFixesLoading] = useState(false)
  const [agentsLoading, setAgentsLoading] = useState(false)
  const [skillsLoading, setSkillsLoading] = useState(false)
  const [pluginsLoading, setPluginsLoading] = useState(false)
  const [hooksLoading, setHooksLoading] = useState(false)
  const [, setQualityLoading] = useState(false)
  const [selectedHook, setSelectedHook] = useState<Hook | null>(null)
  const [, setSetupComplete] = useState(false)

  // Every run across all states. Failed runs surface as a flash + inline Resume;
  // `refresh` is re-run after a resume/cancel so the list reflects the change.
  const repoRuns = useRepoRuns(repoId ?? null)
  // task 9: live OS-resource footprints for the running cards. A running run's
  // record carries no `resources` until its terminal fold, so we ride the per-run
  // `resource` event stream for the live-running runs and overlay the folded
  // footprint (peak RSS · last CPU%) onto their rows before the runs lens reads
  // them — so RunResourceFootprint updates live instead of staying blank.
  const liveRunningIds = useMemo(
    () => repoRuns.runs.filter((r) => r.live && !r.endedAt).map((r) => r.runId),
    [repoRuns.runs],
  )
  const liveResources = useLiveRunResources(repoId ?? '', liveRunningIds)
  // runs-card-uplift task 1: the runs list is a ONE-SHOT read (useRepoRuns never
  // re-fetches), so without a live overlay a running card's stall clock climbs
  // forever and a since-ended run keeps ticking "Running for {N}". Ride the same
  // per-run event stream as the resources overlay to keep `lastActivityAt` honest
  // and SETTLE a run (live=false, elapsed frozen at endedAt) once its stream hits
  // a terminal exit — folded onto the rows below before the runs lens reads them.
  const liveActivity = useLiveRunActivity(repoId ?? '', liveRunningIds)
  // The configured environments (Environments registry, global) the runs board
  // renders a standing band for — local + each remote env — even when idle.
  const { environments: configuredEnvironments } = useEnvironments()
  const runsWithLiveResources = useMemo(
    () =>
      liveResources.size === 0 && liveActivity.size === 0
        ? repoRuns.runs
        : repoRuns.runs.map((run) => {
            const res = liveResources.get(run.runId)
            const withRes = res ? { ...run, resources: res } : run
            return overlayLiveRunActivity(withRes, liveActivity.get(run.runId))
          }),
    [repoRuns.runs, liveResources, liveActivity],
  )
  // The work board (work-board board-lane-projection): every fix/plan/spike
  // folded to a lane server-side, invalidated on the run-change SSE signal.
  // Reachable at ?view=board; the four-lane surface renders via BoardView.
  const board = useBoard(repoId ?? null)
  // A refused re-validation (no post-land step configured, one already
  // running) must reach the USER, not die in the console — the route's 409s
  // exist to be read (red-main-banner-stale-without-revalidation-path).
  // Cleared on the next successful schedule.
  const [revalidateNotice, setRevalidateNotice] = useState<string | null>(null)
  // land-dashboard task 1: the In-review Land button's wiring — POSTs the land
  // action keyed on the row's worktree branch, with the busy / failed feedback
  // the button reflects. Fire-and-forget: the board (above) self-invalidates on
  // the land run's SSE and re-derives the card In review → Done.
  const boardLand = useBoardLand(repoId ?? null)
  // board-surface task 25: the SELECTED card's full detail, fetched on demand
  // from the single-item endpoints (keyed by the board's `?item=` value) rather
  // than eagerly for every card. Feeds both the board detail pane and the ?task=
  // container resolution below; nothing is fetched until a card is selected.
  const itemDetail = useBoardItemDetail(repoId ?? null, selectedItemId)
  // Keep the OPEN item's board card progress in lockstep with its detail header:
  // override that one row's summary.progress with the value the header shows — the
  // shared settled-aware wrapper (deriveFixDisplayProgress for a fix,
  // derivePlanDisplayProgress for a PRD), both read from the SAME fresh itemDetail,
  // so one statusChange moves both bars (fixes:
  // board-card-progress-not-synced-with-open-detail, unify-settled-progress-short-circuit).
  const boardLanes = useMemo(
    () => applyOpenItemProgress(board.lanes, itemDetail.fix ?? null, itemDetail.plan ?? null, reviewPipeline),
    [board.lanes, itemDetail.fix, itemDetail.plan, reviewPipeline],
  )
  // The SELECTED fix's worktree branch (fix failed-run-invisible-on-board-fix-detail
  // task 1) — the ONE branch identity both the delivery-model fetch below and the
  // strip's three derivations key on, so the fetch can never key branch A while a
  // derivation keys branch B (which would silently idle the strip — the bug this
  // fixes). Resolved from the fix's own task lattice, the SAME fallback the
  // derivations use; the board summary carries no worktree for a fix, so there is
  // nothing else to prefer.
  const selectedFixBranch = useMemo(
    () => (itemDetail.fix ? deriveFixWorktreeBranches(itemDetail.fix)[0]?.branch : undefined),
    [itemDetail.fix],
  )
  // The selected fix's branch delivery model, fetched on demand for THAT ONE
  // branch (`/delivery/worktrees/:branch`) — NOT a revert to the eager
  // whole-queue fetch (board-view-overfetches-all-tab-data task 26's lazy stance
  // stands). Held as a rows array so the existing branch-keyed derivations
  // (deriveFixLastReconcile / …LandAvailability / …LiveReconcileRunId) consume it
  // unchanged. Empty until a fix with a branch is selected.
  const [boardItemDelivery, setBoardItemDelivery] = useState<DeliveryWorktreeRow[]>([])
  // Live liveness for the delivery model (fix endcap-land-availability-stale-no-sse-
  // refetch): this model carries the endcap's `landAvailability` conflict-veto
  // (endcap-state.ts:204), but its fetch keyed only on `[repoId, selectedFixBranch]`
  // — subscribed to NO SSE event. A reconcile/land does not move the branch, so a
  // failed land's `conflicts` outlived a later clean reconcile and vetoed a fresh
  // `mergeAvailable`, hiding the Land CTA until a full reload. Re-pull the model on
  // the SAME signals useBoardItemDetail refreshes `mergeAvailable` on, so the two
  // endcap inputs stay in lockstep: the repo's run-change — DEBOUNCED through the
  // shared useDebouncedRefetch (a reconcile's run-record burst folds into one
  // re-pull) — and a post-drop `reconnected` resync (SSE has no replay, so an open
  // that follows a drop must re-read; mirrors useBoardItemDetail.ts:185).
  const [deliveryRefreshNonce, setDeliveryRefreshNonce] = useState(0)
  const bumpDeliveryRefresh = useCallback(() => setDeliveryRefreshNonce((n) => n + 1), [])
  const scheduleDeliveryRefresh = useDebouncedRefetch(bumpDeliveryRefresh, 250)
  useRunLive(repoId ?? null, scheduleDeliveryRefresh)
  useSSEEvent<ReconnectedEvent>('reconnected', scheduleDeliveryRefresh)
  useEffect(() => {
    if (!repoId || !selectedFixBranch) {
      setBoardItemDelivery([])
      return
    }
    let cancelled = false
    void fetchDeliveryWorktree(repoId, selectedFixBranch)
      .then((row) => {
        if (!cancelled) setBoardItemDelivery(row ? [row] : [])
      })
      .catch((error) => {
        if (!cancelled) {
          // Fail-soft, deliberately: an idle strip is the honest fallback when the
          // model can't be reached, and it matches the file's other fetchers (they
          // log + reset, never throw). A stale prior value is not preserved — the
          // re-pull that follows a run-change (deliveryRefreshNonce) is exactly how
          // a cleared reconcile axis reaches the endcap.
          console.error('[RepoDetailPage] Error fetching board item delivery model:', error)
          setBoardItemDelivery([])
        }
      })
    return () => {
      cancelled = true
    }
    // `deliveryRefreshNonce` re-runs this on the repo's run-change (via useRunLive
    // above), so a reconcile/land terminal re-pulls the model that feeds the endcap.
  }, [repoId, selectedFixBranch, deliveryRefreshNonce])
  // Render the selected in-flight row's detail in the board's main pane: a
  // worker/failed run opens the WorkerRun island; a delivery worktree opens the
  // Land-this-work detail (land or cleanup by its own state).
  // board-surface task 2: the focused lane's detail main renders the same island
  // the lists use — FixDetail / PlanDetails for the full payload the board row
  // already carries. A spike only carries a summary on the board, so it links out
  // to the Spikes tab for the full pipeline detail.
  // The who/landed facts the selected row already carries, shaped for the
  // provenance seed (fix board-detail-provenance-not-seeded-from-summary). A
  // row is `settled` — the detail WILL resolve a who — once it reaches the In
  // review or Done lane; only then does an item with no producing run seed
  // `interactive` (see the seed builder for why unsettled work seeds no who).
  const rowProvenanceFacts = (row: BoardRow) => ({
    producingRun: row.producingRun,
    landed: row.landed,
    settled: row.lane === 'in-review' || row.lane === 'done',
  })

  const renderBoardDetail = (row: BoardRow) => {
    if (!repoId) return null
    // The board list ships lean SUMMARY rows (no full `card`); the heavy record
    // is fetched on selection (useBoardItemDetail), keyed by the same `?item=`
    // value. So the pane discriminates on `row.summary.kind` — the 3-way card
    // kind (fix/prd/spike), NOT the 4-way `WorkRef.kind` whose `task` arm the
    // board never yields — and sources the full fix/plan from `itemDetail` for
    // THIS row. A summary row has no record to fall back to, so a light
    // placeholder covers the in-flight fetch. (A stale `row.card` read used to
    // crash the deep-link here.)
    const panel = (child: ReactNode) => (
      <div className="panel flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl">{child}</div>
    )
    if (row.summary.kind === 'fix') {
      const fix = itemDetail.fix?.id === row.workRef.id ? itemDetail.fix : null
      if (!fix) return panel(<BoardDetailSkeleton title={row.summary.title} />)
      // The branch's MODELED land availability (the F6 delivery model) — the
      // reconcile-strip's reconstruction source and the end-cap's conflicts
      // gate (F7 task 2). Matched on the fix's worktree branch when the
      // delivery rows carry it; absent rows leave the client edge in place.
      // On the board the whole delivery queue is never loaded (task 26); the
      // strip's feed comes from the SELECTED branch's model fetched on demand
      // (boardItemDelivery, fix failed-run-invisible-on-board-fix-detail task 1),
      // keyed on the same branch identity so a failed verify SAYS so instead of
      // falling through to an idle strip.
      // Keyed on `selectedFixBranch` — the SAME identity boardItemDelivery was
      // fetched for (the fix rendered here IS itemDetail.fix), so fetch and
      // derivations can never key different branches.
      const fixAvailability = deriveFixLandAvailability(fix, selectedFixBranch, boardItemDelivery)
      // The persisted verdict + reason (lastReconcile axis) rides beside the
      // availability so a failed verify SAYS so after refresh (fix
      // verify-outcomes-invisible-in-ui task 1).
      const fixLastReconcile = deriveFixLastReconcile(fix, selectedFixBranch, boardItemDelivery)
      // The live machinery run (a CLI reconcile) — the strip subscribes and
      // renders it with no click here (task 2).
      const fixLiveReconcileRunId = deriveFixLiveReconcileRunId(fix, selectedFixBranch, boardItemDelivery)
      return panel(
        <FixDetail
          fix={fix}
          repoId={repoId}
          onArchive={() => handleArchiveFix(fix.id)}
          onUnarchive={() => handleUnarchiveFix(fix.id)}
          onOpenRun={openRun}
          landAvailability={fixAvailability}
          lastReconcile={fixLastReconcile}
          liveReconcileRunId={fixLiveReconcileRunId}
          // The row's server-derived cleanup signal (done-lane-cleanup task
          // 10) — the swap's only reliable trigger for a real landed fix.
          cleanup={row.cleanup === true}
          // Seed the who glyph + delivery state from the facts the row already
          // showed (fix board-detail-provenance-not-seeded-from-summary), so
          // they paint on the first frame instead of flashing behind the fetch.
          provenanceSeed={seedFixProvenance(fix.id, rowProvenanceFacts(row))}
        />,
      )
    }
    if (row.summary.kind === 'prd') {
      const plan = itemDetail.plan?.id === row.workRef.id ? itemDetail.plan : null
      if (!plan) return panel(<BoardDetailSkeleton title={row.summary.title} />)
      return panel(
        <PlanDetails
          plan={plan}
          viewMode={viewMode}
          repoId={repoId}
          onArchive={() => handleArchivePlan(plan.id)}
          onUnarchive={() => handleUnarchivePlan(plan.id)}
          onOpenRun={openRun}
          reviewPipeline={reviewPipeline}
          // The row's server-attributed cleanup branches (fix
          // prd-cleanup-pill-not-attributed-to-features task 1) — the PRD
          // counterpart of FixDetail's `cleanup` prop on the fix arm above.
          cleanupBranches={row.cleanupBranches}
          // Seed each feature row's who glyph from the container who the board
          // card already showed (fix board-detail-provenance-not-seeded-from-
          // summary), keyed to the plan's real feature ids so the fetch replaces
          // it in place.
          provenanceSeed={seedPrdProvenance(
            plan.prdId ?? plan.id,
            (plan.features ?? []).map((f) => f.id),
            rowProvenanceFacts(row),
          )}
          // The delivery rows a feature's expanded reconcile lane resolves its
          // LIVE run from (fix feature-detail-live-reconcile-parity). The fix arm
          // reads the fix-scoped `boardItemDelivery`; a PRD's features span
          // branches, so the repo-wide Done queue (`deliveryWorktrees`) is the
          // right source — PlanFeatureRow keys into it per feature branch.
          deliveryWorktrees={deliveryWorktrees}
        />,
      )
    }
    // A spike sources its full record from the same on-demand fetch (fix
    // board-spike-detail-panel-stubbed): mount the existing SpikeDetail island
    // behind the shared skeleton, matching the fix/prd arms. The retired Spikes
    // tab's placeholder link-out is dead — the board is the only spike surface now.
    const spike = itemDetail.spike?.id === row.workRef.id ? itemDetail.spike : null
    if (!spike) return panel(<BoardDetailSkeleton title={row.summary.title} />)
    return panel(
      <SpikeDetail
        spike={spike}
        worktreeStatus={itemDetail.spikeWorktreeStatus}
        repoId={repoId}
        // F1's run-state seam feeds the F2 launch/running/resume surfaces as
        // props — the component stays a pure function of its inputs.
        activeRun={itemDetail.spikeActiveRun}
        resumableRun={itemDetail.spikeResumableRun}
        // A launch / park / outcome mutation refetches the pane (and its worktree
        // status) via the on-demand hook's refresh, as the retired tab did.
        onWorktreeCleared={itemDetail.refresh}
        onOutcomeRecorded={itemDetail.refresh}
        // Click-to-watch: the running end-cap opens the shared WorkerRun island,
        // same as FixDetail (spike-command-surface-parity).
        onOpenRun={openRun}
      />,
    )
  }

  // Render the server projection directly (live-frontier-projection F4-T1). The
  // composer already merged git + the event overlay (redStartedAt / greenStartedAt
  // / reviews) into each task's flat fields, and a pre-commit phase pulse rides the
  // per-entity `status-change` SSE that patches the affected fix/plan by id (F3-T1)
  // — so the client no longer re-folds the telemetry feed into a parallel
  // `derivedState`. `toEffectiveTask` reads the server-projected fields directly.
  const fixes = repoFixes
  const plans = repoPlans

  // The ?task= detail view resolves the open item's container (resolveTaskLocation)
  // from the on-demand single-item fetch (task 25), not the eagerly-fetched
  // plans/fixes lists — useBoardItemDetail already scopes its result to the
  // selected `?item=` kind (prd:/fix:; a spike carries no board detail). This
  // decouples the ?task= view from the sibling list fetches (removed in task 26).
  const selectedPlan = itemDetail.plan
  const selectedFix = itemDetail.fix

  // Fetch repo info
  const fetchRepoInfo = async () => {
    try {
      console.log('[RepoDetailPage] Fetching repo info for:', repoId);
      const response = await fetch(`/api/repos/${repoId}`)
      console.log('[RepoDetailPage] Repo info response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received repo info:', data);
        setRepoInfo(data.repo || null)
        setCurrentRepo(data.repo || null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo info:', error)
    }
  }


  // Fetch plans for this repo
  const fetchRepoPlans = async () => {
    try {
      console.log('[RepoDetailPage] Fetching plans for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/plans`)
      console.log('[RepoDetailPage] Response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received data:', data);
        console.log('[RepoDetailPage] Plans count:', data.plans?.length);
        setRepoPlans(data.plans || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo plans:', error)
    } finally {
      setLoading(false)
    }
  }

  // Fetch fixes for this repo
  const fetchRepoFixes = async () => {
    try {
      setFixesLoading(true)
      console.log('[RepoDetailPage] Fetching fixes for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/fixes`)
      console.log('[RepoDetailPage] Fixes response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received fixes:', data);
        console.log('[RepoDetailPage] Fixes count:', data.fixes?.length);
        setRepoFixes(data.fixes || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo fixes:', error)
    } finally {
      setFixesLoading(false)
    }
  }

  // The cross-kind Done queue — fixes + PRDs needing a git move. Feeds both the
  // rail's `to merge` count and the Worktrees Done tab. Assembled server-side;
  // the page just holds + forwards it (the dumb-UI rule).
  const fetchRepoDeliveryQueue = async () => {
    if (!repoId) return
    try {
      setDeliveryWorktrees(await fetchDeliveryWorktrees(repoId))
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching delivery queue:', error)
    } finally {
      setDeliveryLoaded(true)
    }
  }

  // One fetch-and-set for the teardown model, shared by the initial-load effect
  // and the post-action refresh. `isStale` lets the effect drop a result that a
  // fast prd/repo switch has superseded, so a stale fetch never lands.
  const loadTeardownModel = async (isStale: () => boolean = () => false): Promise<void> => {
    if (!teardownPrdId || !repoId) return
    try {
      const model = await fetchPrdTeardown(repoId, teardownPrdId)
      if (!isStale()) setPrdTeardown(model)
    } catch (error) {
      if (!isStale()) console.error('[RepoDetailPage] Error loading PRD teardown:', error)
    }
  }

  // Re-fetch after a remediation action changes a branch's state (a reconcile can
  // flip conflict → ready → merged), so the island reflects the new posture
  // without a manual reload.
  const refreshTeardown = () => loadTeardownModel()

  // The island's live per-feature land run (adversarial review of 1f5170911,
  // MEDIUM): the land is a STREAMED run and the island renders no strip, so
  // the page folds the run's terminal itself — refresh the model with the
  // just-persisted state and surface the exit outcome as the notice (the
  // failed exit's reason is the sanitised display prose the server streamed;
  // a completed land clears the "started" acknowledgement).
  const [islandLandRunId, setIslandLandRunId] = useState<string | null>(null)
  const { events: islandLandEvents } = useRunStream(repoId ?? '', islandLandRunId ?? '')
  useEffect(() => {
    if (islandLandRunId === null) return
    const exit = islandLandEvents
      .filter((e): e is Extract<RunEvent, { type: 'exit' }> => e.type === 'exit' && e.runId === islandLandRunId)
      .at(-1)
    if (exit === undefined) return
    setIslandLandRunId(null)
    setTeardownNotice(exit.status === 'completed' ? null : (exit.reason ?? LAND_FEATURE_NOTICES.failed))
    void refreshTeardown()
    // refreshTeardown is a per-render closure over stable ids — a dep on it
    // would refire the effect every render (the useWorkItemProvenance pattern).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [islandLandEvents, islandLandRunId])

  // Load the teardown model when the ?island=prd:<id> view is active. Cancels a
  // stale fetch on prd/repo change so a fast switch never lands the wrong model.
  useEffect(() => {
    if (!teardownPrdId || !repoId) {
      setPrdTeardown(null)
      setPrdTeardownLoaded(false)
      setTeardownNotice(null)
      return
    }
    let cancelled = false
    setPrdTeardown(null)
    setPrdTeardownLoaded(false)
    setTeardownNotice(null)
    void loadTeardownModel(() => cancelled).finally(() => {
      if (!cancelled) setPrdTeardownLoaded(true)
    })
    return () => {
      cancelled = true
    }
  }, [teardownPrdId, repoId])

  // Fetch agents for this repo
  const fetchRepoAgents = async () => {
    try {
      setAgentsLoading(true)
      console.log('[RepoDetailPage] Fetching agents for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/agents`)
      console.log('[RepoDetailPage] Agents response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received agents:', data);
        console.log('[RepoDetailPage] Agents count:', data.agents?.length);
        setRepoAgents(data.agents || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo agents:', error)
    } finally {
      setAgentsLoading(false)
    }
  }

  // Fetch skills for this repo
  const fetchRepoSkills = async () => {
    try {
      setSkillsLoading(true)
      console.log('[RepoDetailPage] Fetching skills for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/skills`)
      console.log('[RepoDetailPage] Skills response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received skills:', data);
        console.log('[RepoDetailPage] Skills count:', data.skills?.length);
        setRepoSkills(data.skills || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo skills:', error)
    } finally {
      setSkillsLoading(false)
    }
  }

  // Fetch plugins for this repo
  const fetchRepoPlugins = async () => {
    try {
      setPluginsLoading(true)
      console.log('[RepoDetailPage] Fetching plugins for repo:', repoId);
      // Use the repo path from repoInfo, or decode the repoId
      const repoPath = repoInfo?.path || decodeURIComponent(repoId || '')
      const response = await fetch(`/api/plugins/repo/${encodeURIComponent(repoPath)}`)
      console.log('[RepoDetailPage] Plugins response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received plugins:', data);
        console.log('[RepoDetailPage] Plugins count:', data.plugins?.length);
        setRepoPlugins(data.plugins || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo plugins:', error)
    } finally {
      setPluginsLoading(false)
    }
  }

  // Fetch hooks for this repo
  const fetchRepoHooks = async () => {
    try {
      setHooksLoading(true)
      console.log('[RepoDetailPage] Fetching hooks for repo:', repoId);
      const repoPath = repoInfo?.path || decodeURIComponent(repoId || '')
      const response = await fetch(`/api/hooks?repoPath=${encodeURIComponent(repoPath)}`)
      console.log('[RepoDetailPage] Hooks response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received hooks:', data);
        setRepoHooks(data)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo hooks:', error)
    } finally {
      setHooksLoading(false)
    }
  }

  // Fetch the quality readiness criteria (loaded lazily with the Quality tab —
  // task 2; the result feeds QualityTab's onCriteriaChange, not a board badge).
  const fetchQualityCriteria = async () => {
    try {
      const response = await fetch(`/api/repos/${repoId}/quality-scores`)
      if (response.ok) {
        const data = await response.json()
        if (data.readiness) {
          setQualityCriteria(data.readiness)
        }
      }
    } catch {
      // Ignore — criteria will be set when QualityTab renders
    }
  }

  // Fetch quality runs for this repo
  const fetchRepoQualityRuns = async () => {
    try {
      setQualityLoading(true)
      console.log('[RepoDetailPage] Fetching quality runs for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/quality`)
      console.log('[RepoDetailPage] Quality response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received quality runs:', data);
        console.log('[RepoDetailPage] Quality runs count:', data.runs?.length);
        setRepoQualityRuns(data.runs || [])
        setLatestQualityGrade(data.latestGrade || null)
        setLatestQualityScore(data.latestScore ?? null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo quality runs:', error)
    } finally {
      setQualityLoading(false)
    }
  }

  // Fetch quality run details
  const fetchQualityRunDetail = async (runId: string) => {
    try {
      console.log('[RepoDetailPage] Fetching quality run detail:', runId);
      const response = await fetch(`/api/repos/${repoId}/quality/${runId}`)
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received quality run detail:', data);
        setSelectedQualityRun(data.run || null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching quality run detail:', error)
    }
  }

  // Check setup status (lightweight: 3 small fetches)
  const checkSetupStatus = async () => {
    try {
      const [healthRes, analysisRes, recsRes] = await Promise.all([
        fetch(`/api/repos/${repoId}/config-health`),
        fetch(`/api/repos/${repoId}/analysis`),
        fetch(`/api/repos/${repoId}/recommendations`),
      ])
      const isHealthy = healthRes.ok && (await healthRes.json()).health?.status === 'healthy'
      const analysisExists = analysisRes.ok && (await analysisRes.json()).exists
      const noRecs = recsRes.ok && ((await recsRes.json()).recommendations ?? []).length === 0
      setSetupComplete(isHealthy && analysisExists && noRecs)
    } catch {
      // Silently handle — setupComplete stays false
    }
  }

  useEffect(() => {
    if (repoId) fetchRepoInfo()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId])

  // board-view-overfetches-all-tab-data task 3: checkSetupStatus fans out to
  // /config-health, /analysis and /recommendations, all board-irrelevant — the
  // result feeds write-only setupComplete state that only the Settings panel
  // reads. Run it only when Settings is open, mirroring the tab-gated fetches.
  useEffect(() => {
    if (repoId && settingsOpen) checkSetupStatus()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, settingsOpen])

  // Quality tab data (task 2): the runs list + criteria (the ~642KB history) are
  // board-irrelevant, so load them only when the Quality tab is active.
  useEffect(() => {
    if (repoId && activeTab === 'quality') {
      fetchRepoQualityRuns()
      fetchQualityCriteria()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, activeTab])

  // board-view-overfetches-all-tab-data task 1: the Agents / Skills tab lists are
  // board-irrelevant, so load each only when its tab is active (the board is one
  // tab in this page; the mount used to fetch every tab's data regardless).
  // Gating on activeTab means the list re-fetches each time its tab is
  // (re)activated — chosen deliberately for freshness (agents/skills/plugins/
  // hooks change as they're installed), and cheap: one tab-scoped fetch per open.
  useEffect(() => {
    if (repoId && activeTab === 'agents') fetchRepoAgents()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, activeTab])
  useEffect(() => {
    if (repoId && activeTab === 'skills') fetchRepoSkills()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, activeTab])

  // board-surface task 26: the plans/fixes lists and the delivery queue are the
  // board's expensive siblings (~2s + ~3.5s + ~7s, serial) and the board never
  // shows them — after task 25 the board detail + ?task= container read the
  // on-demand item fetch, so plans/fixes now feed ONLY the Archive view, and the
  // delivery queue only the worktree-merge island. Load each lazily when its
  // consumer opens rather than on every board mount.
  useEffect(() => {
    if (repoId && archiveOpen) {
      fetchRepoPlans()
      fetchRepoFixes()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, archiveOpen])

  useEffect(() => {
    // The worktree-merge island (?island=<branch>) reads the delivery queue; the
    // teardown island (?island=prd:<id>) has its own fetch, so exclude it.
    if (repoId && islandBranch && !teardownPrdId) {
      fetchRepoDeliveryQueue()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, islandBranch, teardownPrdId])

  // Clear current-repo context when leaving the page so the header reverts.
  // NB: the STALE-name-on-switch guard (task 3) lives in Header as a render-time
  // check (currentRepo.name only when its id matches the URL) — no clear effect
  // here, which would run post-paint and flash the previous name for one frame.
  useEffect(() => {
    return () => setCurrentRepo(null)
  }, [setCurrentRepo])

  // Live overlay (Fix: dashboard-drops-filewatcher-sse-events): a markdown edit
  // to a PRD/feature or fix doc emits prd-doc-change / fix-doc-change. Refetch
  // only while the Archive is open (task 26) — its the sole consumer of the
  // plans/fixes lists now, so on the board these events must NOT re-trigger the
  // expensive list fetches.
  usePrdDocLive(repoId ?? null, () => { if (archiveOpen) fetchRepoPlans() })
  useFixDocLive(repoId ?? null, () => { if (archiveOpen) fetchRepoFixes() })

  // Live overlay (Fix: run-dispatch-stale-dashboard): a run record write emits
  // run-change. The board self-invalidates via useBoard; the plans list only
  // needs refreshing while the Archive shows it (task 26).
  useRunLive(repoId ?? null, () => { if (archiveOpen) fetchRepoPlans() })

  // Plugins / Hooks tab data (task 1): board-irrelevant and needing the repo
  // path, so load each only when its own tab is active AND repoInfo has resolved.
  useEffect(() => {
    if (repoInfo?.path && activeTab === 'plugins') fetchRepoPlugins()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoInfo?.path, activeTab])
  useEffect(() => {
    if (repoInfo?.path && activeTab === 'hooks') fetchRepoHooks()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoInfo?.path, activeTab])

  // Auto-select first agent or validate persisted selection
  useEffect(() => {
    if (repoAgents.length > 0) {
      if (!selectedAgentId || !repoAgents.find(a => a.id === selectedAgentId)) {
        setSelectedAgentId(repoAgents[0].id)
      }
    }
  }, [repoAgents, selectedAgentId])

  // Auto-select first skill or validate persisted selection
  useEffect(() => {
    if (repoSkills.length > 0) {
      if (!selectedSkillId || !repoSkills.find(s => s.id === selectedSkillId)) {
        setSelectedSkillId(repoSkills[0].id)
      }
    }
  }, [repoSkills, selectedSkillId])

  // Auto-select first plugin or validate persisted selection
  useEffect(() => {
    if (repoPlugins.length > 0) {
      if (!selectedPluginId || !repoPlugins.find(p => p.path === selectedPluginId)) {
        setSelectedPluginId(repoPlugins[0].path)
      }
    }
  }, [repoPlugins, selectedPluginId])

  // Auto-select first quality run or validate persisted selection
  useEffect(() => {
    if (repoQualityRuns.length > 0) {
      if (!selectedQualityRunId || !repoQualityRuns.find(r => r.runId === selectedQualityRunId)) {
        setSelectedQualityRunId(repoQualityRuns[0].runId)
      }
    }
  }, [repoQualityRuns, selectedQualityRunId])

  // Auto-select first hook when hooks load
  useEffect(() => {
    const allHooks = [...repoHooks.pluginHooks, ...(repoHooks.repoHooks ?? []), ...repoHooks.gitHooks]
    if (allHooks.length > 0 && !selectedHook) {
      setSelectedHook(allHooks[0])
    }
  }, [repoHooks, selectedHook])

  // Fetch quality run details when selection changes — only while the Quality
  // tab is active (quality-run-detail-fetched-on-every-mount): the selection
  // rehydrates from localStorage at mount, so without the gate every board
  // mount paid a /quality/:runId fetch for a tab that isn't open.
  useEffect(() => {
    if (activeTab !== 'quality') return
    if (selectedQualityRunId) {
      fetchQualityRunDetail(selectedQualityRunId)
    } else {
      setSelectedQualityRun(null)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedQualityRunId, repoId, activeTab])

  // Patch the single affected fix/plan on a granular status push
  // (live-frontier-projection F3-T1). The event carries only the changed
  // entities (adds + modifications); merge them by id rather than refetching.
  useSSEEvent<StatusChangeEvent>('statusChange', (event) => {
    // Only process events for this repo
    if (event.repoId && !sseEventMatchesRepo(event, repoId)) {
      return;
    }

    // Entities are Plan[] when resource is 'plan', Fix[] when 'fix'.
    // TypeScript can't narrow the union from the resource discriminant, so we cast.
    if (event.resource === 'plan') {
      setRepoPlans(prevPlans => {
        const updatedPlans = [...prevPlans];
        for (const entity of event.entities as Plan[]) {
          const idx = updatedPlans.findIndex(p => p.id === entity.id);
          if (idx !== -1) {
            updatedPlans[idx] = entity;
          } else {
            updatedPlans.push(entity);
          }
        }
        return updatedPlans;
      });
    } else if (event.resource === 'fix') {
      setRepoFixes(prevFixes => {
        const updatedFixes = [...prevFixes];
        for (const entity of event.entities as Fix[]) {
          const idx = updatedFixes.findIndex(f => f.id === entity.id);
          if (idx !== -1) {
            updatedFixes[idx] = entity;
          } else {
            updatedFixes.push(entity);
          }
        }
        return updatedFixes;
      });
    }
  });

  // Listen to SSE quality-change events and refetch quality data
  useSSEEvent('qualityChange', (event: any) => {
    console.log('[RepoDetailPage] Received quality-change event:', event.eventType, event);

    // Only process events for this repo
    if (event.repoId && !sseEventMatchesRepo(event, repoId)) {
      console.log('[RepoDetailPage] Ignoring quality event for different repo:', event.repoId);
      return;
    }

    // Refetch quality runs to get the latest data — only while the Quality tab is
    // active (task 2), so a quality event received on the board doesn't pull the
    // runs list. The useSSEEvent callback re-binds each render, so this reads the
    // current activeTab.
    if (activeTab === 'quality') {
      console.log('[RepoDetailPage] Refetching quality runs after SSE event');
      fetchRepoQualityRuns();
    }
  });

  const handleAgentSelect = (agentId: string) => {
    setSelectedAgentId(agentId)
  }

  const handleSkillSelect = (skillId: string) => {
    setSelectedSkillId(skillId)
  }

  const handlePluginSelect = (pluginId: string) => {
    setSelectedPluginId(pluginId)
  }

  const handleHookSelect = (hook: Hook) => {
    setSelectedHook(hook)
  }

  const handleArchivePlan = async (planId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/plans/${planId}/archive`, { method: 'POST' })
      if (response.ok) {
        setRepoPlans(prev => prev.map(p =>
          p.id === planId ? { ...p, type: 'archived' } : p
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error archiving plan:', error)
    }
  }

  const handleUnarchivePlan = async (planId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/plans/${planId}/unarchive`, { method: 'POST' })
      if (response.ok) {
        setRepoPlans(prev => prev.map(p =>
          p.id === planId ? { ...p, type: 'active' } : p
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error unarchiving plan:', error)
    }
  }

  const handleArchiveFix = async (fixId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}/archive`, { method: 'POST' })
      if (response.ok) {
        setRepoFixes(prev => prev.map(f =>
          f.id === fixId ? { ...f, archived: true } : f
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error archiving fix:', error)
    }
  }

  const handleUnarchiveFix = async (fixId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}/unarchive`, { method: 'POST' })
      if (response.ok) {
        setRepoFixes(prev => prev.map(f =>
          f.id === fixId ? { ...f, archived: false } : f
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error unarchiving fix:', error)
    }
  }

  const selectedAgent = selectedAgentId ? repoAgents.find((a: Agent) => a.id === selectedAgentId) : null
  const selectedSkill = selectedSkillId ? repoSkills.find((s: Skill) => s.id === selectedSkillId) : null
  const selectedPlugin = selectedPluginId ? repoPlugins.find((p: RepoPlugin) => p.path === selectedPluginId) : null

  // In-place task detail view — replaces the stage rail + workspace body while
  // keeping RepoDetailPage (and its warm data) mounted. The task is resolved
  // from the already-loaded, server-projected plan/fix so its phase commit
  // SHAs (e.g. the RED commit) are available to the tab content without a
  // refetch.
  if (selectedTaskId && repoId) {
    // Resolve the task plus, for the header meta line, its 1-based ordinal and
    // container id (feature id for a plan task, fix id for a fix task).
    const location = resolveTaskLocation(selectedPlan, selectedFix, selectedTaskId)
    // Lift the launch-ref pinned pipeline plan onto the task so the detail's
    // tab bar surfaces every pinned gate (task-pipeline-shows-pinned-gates),
    // matching the per-task strip.
    const detailTask = location?.task ? applyWorktreePhaseShas(location.task) : undefined
    return (
      <DetailsPopoverProvider>
        <div className="flex flex-col h-full overflow-hidden">
          <TaskDetailPage
            repoId={repoId}
            taskId={selectedTaskId}
            task={detailTask}
            taskNumber={location?.taskNumber}
            container={location?.container}
            tab={selectedTaskRawTab}
            onTabChange={openTaskTab}
            onBack={closeTask}
            reviewPipeline={reviewPipeline}
          />
        </div>
      </DetailsPopoverProvider>
    )
  }

  // In-place WorkerRun island (F12) — the run drill-down opened from a feature
  // rail's Running pill. A content-replacing view keyed by runId, like the task
  // / worktree-merge islands; the island reads the run record + tails its SSE.
  if (selectedRunId && repoId) {
    return (
      <div className="flex flex-col h-full overflow-hidden">
        <WorkerRunIsland
          repoId={repoId}
          runId={selectedRunId}
          onClose={() => { closeRun(); repoRuns.refresh(); }}
          onContinued={(newRunId) => { openRun(newRunId); repoRuns.refresh(); }}
          // Route to the run's worktree view: swap ?run= for ?island=<branch>,
          // the content-replacing worktree-merge island keyed by branch.
          onOpenWorktree={(branch) => setSearchParams((prev) => worktreeIslandParams(prev, branch))}
        />
      </div>
    )
  }

  // In-place PRD teardown island — the ?island=prd:<id> content-replacing view.
  // Keyed by PRD id (not a branch), hydrated from the fetched teardown model,
  // reusing the shared Island shell. Checked before the branch island so a
  // `prd:` id never falls through to the branch match.
  if (teardownPrdId && repoId) {
    const closeIsland = () =>
      setSearchParams((prev) => {
        const next = new URLSearchParams(prev)
        next.delete('island')
        return next
      })
    return (
      <div className="flex flex-col h-full overflow-hidden">
        {prdTeardown ? (
          <PrdTeardownIsland
            open
            model={prdTeardown}
            onClose={closeIsland}
            // Re-check a conflicted branch = reconcile it, then refresh the model.
            // A failed reconcile is logged, never an unhandled rejection.
            onRecheck={(branch) => {
              void postDeliveryAction(repoId, 'reconcile', { branch })
                .then(refreshTeardown)
                .catch((error) => console.error('[RepoDetailPage] Re-check reconcile failed:', error))
            }}
            // Land ONE ready feature via the CLI land pipeline. The land is a
            // STREAMED run (fix feature-land-has-no-live-feedback): the POST
            // resolves {runId}, the page's fold above watches that run, and
            // the terminal exit refreshes the model + settles the notice. The
            // body-level notice is the honest "started" acknowledgement; only
            // a POST fault reads failed here.
            onLandFeature={(featureId) => {
              setTeardownNotice(null)
              void postLandFeature(repoId, teardownPrdId, featureId)
                .then(({ runId }) => {
                  setIslandLandRunId(runId)
                  setTeardownNotice(LAND_FEATURE_STARTED_NOTICE)
                })
                .catch((error) => {
                  console.error('[RepoDetailPage] Land feature failed:', error)
                  setTeardownNotice(LAND_FEATURE_NOTICES.failed)
                })
            }}
            actionNotice={teardownNotice}
            // Clear down a merged reclaimable worktree (F5 task 2): the
            // branch-keyed teardown selecting worktree + branch + run record —
            // the reap a raw-landed worktree never got — then refresh.
            onClearDown={(branch, runId) => {
              setTeardownNotice(null)
              void postDeliveryAction(repoId, 'teardown', {
                workItemId: branch,
                worktree: true,
                branch: true,
                ...(runId !== undefined ? { runIds: [runId] } : {}),
              })
                .then(refreshTeardown)
                .catch((error) => {
                  // Surfaced like a failed land — parts are independent
                  // server-side, so the operator can simply re-run the reap.
                  console.error('[RepoDetailPage] Clear down failed:', error)
                  setTeardownNotice('Clear down failed — nothing reclaimed; try again.')
                })
            }}
          />
        ) : (
          <div className="grid h-full place-items-center px-6 pb-6 pt-[8vh] text-center">
            {!prdTeardownLoaded ? (
              <div role="status" aria-label="Loading teardown…" data-testid="teardown-skeleton" className="w-full max-w-md space-y-3">
                <Skeleton aria-hidden className="mx-auto h-6 w-1/2" />
                <Skeleton aria-hidden className="h-24 w-full" />
              </div>
            ) : (
              <div className="panel max-w-md rounded-2xl p-6">
                <p className="display text-lg font-bold">No teardown for this PRD</p>
                <p className="mono mt-1 truncate text-xs text-muted-foreground">{teardownPrdId}</p>
                <button
                  type="button"
                  onClick={closeIsland}
                  className="btn-primary mt-4 inline-flex items-center rounded-lg px-3 py-1.5 text-sm font-semibold"
                >
                  Back to workspace
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  // In-place worktree-merge island — replaces the stage rail + body like the task
  // view, so only the top rail shows and the single app wash shows through the
  // island's transparent backdrop (nothing opaque behind to bleed).
  if (islandBranch && repoId) {
    const row = deliveryWorktrees.find((w) => w.branch === islandBranch)
    const closeIsland = () =>
      setSearchParams((prev) => {
        const next = new URLSearchParams(prev)
        next.delete('island')
        return next
      })
    return (
      <div className="flex flex-col h-full overflow-hidden">
        {row ? (
          <WorktreeDeliveryIsland
            repoId={repoId}
            worktree={row}
            open
            onClose={closeIsland}
            onActionComplete={fetchRepoDeliveryQueue}
          />
        ) : (
          // No matching row. While the delivery queue is still resolving (a
          // ?island= deep-link or reload lands here first), show a loading state;
          // once it's loaded the branch genuinely isn't deliverable — say so with
          // a way back, rather than silently dropping to the workspace.
          <div className="grid h-full place-items-center px-6 pb-6 pt-[8vh] text-center">
            {!deliveryLoaded ? (
              <div role="status" aria-label="Loading worktree…" data-testid="worktree-skeleton" className="w-full max-w-md space-y-3">
                <Skeleton aria-hidden className="mx-auto h-6 w-1/2" />
                <Skeleton aria-hidden className="h-24 w-full" />
              </div>
            ) : (
              <div className="panel max-w-md rounded-2xl p-6">
                <p className="display text-lg font-bold">No deliverable worktree here</p>
                <p className="mono mt-1 truncate text-xs text-muted-foreground">{islandBranch}</p>
                <p className="mt-2 text-sm text-muted-foreground">
                  It may have already landed or been torn down.
                </p>
                <button
                  type="button"
                  onClick={closeIsland}
                  className="btn-primary mt-4 inline-flex items-center rounded-lg px-3 py-1.5 text-sm font-semibold"
                >
                  Back to workspace
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  // In-place design-assets view (surface-design-assets F4) — a content-replacing
  // island like ?island / ?task: the shared Island shell shows the single app
  // wash through its transparent backdrop and dismisses on backdrop-click /
  // Escape, returning to the detail it was opened from.
  //
  // Kind + bare slug come from the kind-prefixed board item ref (`prd:<slug>` /
  // `fix:<slug>`), not the area name — the board is the sole work area now, so
  // an area-derived kind was always null and the panel was unreachable (fix:
  // assets-view-unreachable-from-board). For the `decisions` area the item is a
  // bare ADR slug, mapped to 'adr'. Either missing → fall through.
  const assetsTarget = assetsOpen ? deriveAssetsTarget(activeTab, selectedItemId) : null
  if (assetsOpen && assetsTarget && repoId) {
    const closeAssets = () =>
      setSearchParams((prev) => {
        const next = new URLSearchParams(prev)
        next.delete('assets')
        return next
      })
    return (
      <div className="flex flex-col h-full overflow-hidden">
        <AssetsIsland repoId={repoId} kind={assetsTarget.kind} slug={assetsTarget.slug} onClose={closeAssets} />
      </div>
    )
  }

  // In-place Archive view (board-first-chrome T3) — a content-replacing surface
  // (bare `?archive` marker) for the archived plans + fixes the board projection
  // drops. Opened from the board header's Archive glyph; the detail's Unarchive
  // action returns an item to the active board.
  if (archiveOpen && repoId) {
    return (
      <DetailsPopoverProvider>
        <div className="flex flex-col h-full overflow-hidden">
          <ArchiveView
            plans={plans}
            fixes={fixes}
            repoId={repoId}
            reviewPipeline={reviewPipeline}
            viewMode={viewMode}
            onUnarchivePlan={handleUnarchivePlan}
            onUnarchiveFix={handleUnarchiveFix}
            onClose={closeArchive}
          />
        </div>
      </DetailsPopoverProvider>
    )
  }

  return (
    <DetailsPopoverProvider>
    <div className="flex flex-col h-full overflow-hidden">
      {/* board-first-chrome F3: the board is the sole work area, so there is no
          stage rail — the board (or the active non-board view) renders directly
          under the repo header. The retired Plans/Fixes/Spikes lists and the
          absorbed In-flight view redirect to the board (resolveWorkView).
          Quality and Settings live in the top breadcrumb rail (RepoViewControls). */}

      {/* Content. Settings renders inline in place of the workspace body. */}
      <div className="flex-1 overflow-hidden">
        {settingsOpen && repoId ? (
          <SetupTab
            repoId={repoId}
            repoPath={repoInfo?.path}
            initialSection={settingsSection}
            onSectionChange={setSettingsSection}
            onNavigateToPlans={() => { setActiveTab('board'); }}
            onSetupComplete={setSetupComplete}
          />
        ) : !runsOpen && activeTab === 'quality' ? (
          repoId ? (
            <QualityTab
              repoId={repoId}
              runs={repoQualityRuns}
              selectedRun={selectedQualityRun}
              selectedRunId={selectedQualityRunId}
              onCriteriaChange={setQualityCriteria}
              onRunDeleted={() => {
                setSelectedQualityRunId(null)
                setSelectedQualityRun(null)
                fetchRepoQualityRuns()
              }}
            />
          ) : null
        ) : !runsOpen && activeTab === 'decisions' ? (
          repoId ? (
            // The Decisions surface: a list of ALL ADRs beside a detail pane
            // (list-all, not the with-assets gallery). Selecting a row sets
            // ?item=<slug>; the detail pane renders that ADR's markdown.
            <DecisionsView
              repoId={repoId}
              selectedSlug={selectedItemId}
              onSelect={(slug) => setSelectedItemId(slug)}
              onOpenAssets={() =>
                // The ADR is already selected (?item is set — that's what renders
                // the detail + its affordance), so this only adds the ?assets
                // marker; deriveAssetsTarget('decisions', <adr-slug>) → adr opens
                // the island.
                setSearchParams((prev) => {
                  const next = new URLSearchParams(prev)
                  next.set('assets', '')
                  return next
                })
              }
            />
          ) : null
        ) : runsOpen || activeTab === 'board' ? (
          // The four-lane work board (board-surface F1): every fix/plan/spike
          // folded to a lane from the projection, cards reused unchanged.
          // When `?runs` is set the same board renders with its Runs sub-mode
          // active — the environment-laned runs board fills the body under the
          // persistent filter rail (the Runs toggle lives in that rail).
          // Selecting a row deep-links via ?item=; card click focuses its lane.
          // Land history lives on each item's detail provenance (work-item-
          // provenance F4 task 4), not in a board-level footer.
          <div className="flex h-full min-h-0 flex-col">
            {revalidateNotice !== null && (
              <div
                role="alert"
                className="border-b border-border bg-background px-5 py-2 text-xs text-muted-foreground"
              >
                Re-validate: {revalidateNotice}
              </div>
            )}
            <div className="min-h-0 flex-1">
              <BoardView
                lanes={boardLanes}
                selectedKey={selectedItemId}
                onSelect={selectBoardItem}
                onLand={boardLand.landItem}
                onOpenRun={openRun}
                landStateFor={boardLand.landStateFor}
                // The revert affordance's last mile (split-land-from-validation
                // F5 task 2). The overlay hands back the sha of the land the
                // operator picked — in the ambiguous case that choice exists
                // nowhere else — and the outcome arrives over the run stream,
                // so there is nothing to await here beyond the dispatch.
                onRevert={(sha) => {
                  if (repoId === undefined) return
                  void postRevert(repoId, sha).catch((error) => {
                    console.error('[RepoDetailPage] Revert failed:', error)
                  })
                }}
                // The banner's Re-validate lever (red-main-banner-stale-
                // without-revalidation-path). The 202 races the detached
                // spawn, so the refresh here rarely sees the running record —
                // the banner flips its rail optimistically on click and the
                // run-change SSE invalidation confirms it; the refresh just
                // narrows the window (the route's already-running 409 guards
                // double-scheduling). A refusal (no post-land step, already
                // running) surfaces as the notice strip AND rejects the
                // returned promise so the banner restores its alarm rail
                // (revalidate-click-rail-not-instant).
                onRevalidate={() => {
                  // Reject rather than return undefined: the banner treats a
                  // rejected schedule as "restore the alarm rail" — a bare
                  // undefined would leave its optimistic state to time out.
                  if (repoId === undefined) return Promise.reject(new Error('repository not resolved'))
                  return postRevalidateMain(repoId)
                    .then(() => {
                      setRevalidateNotice(null)
                      board.refresh()
                    })
                    .catch((error: unknown) => {
                      setRevalidateNotice(error instanceof Error ? error.message : String(error))
                      throw error
                    })
                }}
                focusedLane={focusedLane}
                onFocusLane={setFocusedLane}
                renderDetail={renderBoardDetail}
                health={board.health}
                doneCount={board.doneCount}
                cleanupCount={board.cleanupCount}
                onExpandDone={board.loadDone}
                doneLoading={board.doneLoading}
                loading={board.loading}
                type={boardType}
                onTypeChange={setBoardType}
                attention={boardAttention}
                onAttentionChange={setBoardAttention}
                // Runs sub-mode (repo-header-runs-launcher): the toggle lives in
                // the board's filter rail, not the top nav. Toggling sets/clears
                // the `?runs` marker (and drops any open `?run=` island); when
                // active the runs board renders as the board body.
                runsActive={runsOpen}
                runsCount={repoRuns.runs.filter((r) => r.live && !r.endedAt).length}
                onRunsToggle={() =>
                  setSearchParams((prev) => {
                    const next = new URLSearchParams(prev)
                    if (next.has('runs')) {
                      next.delete('runs')
                      next.delete('run')
                    } else {
                      next.set('runs', '')
                    }
                    return next
                  })
                }
                runsBody={
                  runsOpen && repoId ? (
                    repoRuns.loading && repoRuns.runs.length === 0 ? (
                      <div
                        data-testid="runs-loading"
                        role="status"
                        aria-label="Loading runs…"
                        className="flex h-full items-center justify-center"
                      >
                        <div aria-hidden className="h-8 w-8 animate-spin rounded-full border-b-2 border-primary" />
                      </div>
                    ) : (
                      <RunsListDetailView
                        runs={runsWithLiveResources}
                        environments={configuredEnvironments}
                        repoId={repoId}
                        error={repoRuns.error}
                        onSelectRun={openRun}
                      />
                    )
                  ) : undefined
                }
              />
            </div>
          </div>
        ) : (
        <ResizablePanelGroup direction="horizontal" onLayout={workspacePanels.onLayout}>
          {/* Sidebar */}
          <ResizablePanel defaultSize={workspacePanels.defaultSize(0, 30)} minSize={20} maxSize={40}>
            <div className="h-full flex flex-col">
              <div className="flex-1 overflow-auto">
                {activeTab === 'agents' && (
                  agentsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <AgentList
                      agents={repoAgents}
                      selectedAgentId={selectedAgentId}
                      onSelectAgent={handleAgentSelect}
                    />
                  )
                )}
                {activeTab === 'skills' && (
                  skillsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <SkillList
                      skills={repoSkills}
                      selectedSkillId={selectedSkillId}
                      onSelectSkill={handleSkillSelect}
                      repoId={repoId || ''}
                    />
                  )
                )}
                {activeTab === 'plugins' && (
                  pluginsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <RepoPluginList
                      plugins={repoPlugins}
                      selectedPluginId={selectedPluginId}
                      onSelectPlugin={handlePluginSelect}
                    />
                  )
                )}
                {activeTab === 'hooks' && (
                  hooksLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <HooksList
                      hooks={repoHooks}
                      selectedHook={selectedHook}
                      onSelectHook={handleHookSelect}
                    />
                  )
                )}
              </div>
            </div>
          </ResizablePanel>

          {/* The divider line is transparent for the top 60px (behind the
              header bar) and the real border colour below, so the splitter
              starts beneath the header — the header reads as one continuous
              strip while the list/detail divider stays visible and draggable. */}
          <ResizableHandle
            withHandle
            className="!bg-transparent bg-[linear-gradient(to_bottom,transparent_60px,#e5e7eb_60px)] dark:bg-[linear-gradient(to_bottom,transparent_60px,#252d3a_60px)]"
          />

          {/* Details */}
          <ResizablePanel defaultSize={workspacePanels.defaultSize(1, 70)}>
            <div className="h-full flex flex-col">
              {activeTab === 'agents' && (
                selectedAgent ? (
                  <AgentDetail agent={selectedAgent} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {agentsLoading ? 'Loading agents...' : 'No agents installed in this repository'}
                  </div>
                )
              )}
              {activeTab === 'skills' && (
                selectedSkill ? (
                  <SkillDetail skill={selectedSkill} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {skillsLoading ? 'Loading skills...' : 'No skills installed in this repository'}
                  </div>
                )
              )}
              {activeTab === 'plugins' && (
                selectedPlugin ? (
                  <RepoPluginDetail plugin={selectedPlugin} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {pluginsLoading ? 'Loading plugins...' : 'No plugins available for this repository'}
                  </div>
                )
              )}
              {activeTab === 'hooks' && (
                <HookDetail
                  hook={selectedHook}
                  repoPath={repoInfo?.path || decodeURIComponent(repoId || '')}
                />
              )}
            </div>
          </ResizablePanel>
        </ResizablePanelGroup>
        )}
      </div>

    </div>
    </DetailsPopoverProvider>
  )
}
