import React, { useEffect, useRef, useState } from 'react';
import { Plus, X, ArrowUp, ArrowDown } from 'lucide-react';
import type { WorktreeReadinessCommand } from '@magic-ingredients/tiny-brain-core';

interface WorktreeReadinessEditorProps {
  /** The ordered, resolved readiness commands (stored set, or the analysis seed). */
  readiness: WorktreeReadinessCommand[];
  /** Persist the edited list. Called only with a fully-valid set — a half-typed
   *  blank row is held locally until filled, since core rejects empty entries. */
  onSave: (readiness: WorktreeReadinessCommand[]) => void;
  saving?: boolean;
}

/** A row carries a stable local id so React keys survive reorders and the row's
 *  input keeps focus/identity when it moves (a plain index key does not). */
interface Row extends WorktreeReadinessCommand {
  _id: number;
}

const strip = (rows: Row[]): WorktreeReadinessCommand[] => rows.map(({ label, command }) => ({ label, command }));

const isValid = (rows: WorktreeReadinessCommand[]): boolean =>
  rows.every((r) => r.label.trim() !== '' && r.command.trim() !== '');

/**
 * Readiness-commands editor (worktree-readiness-commands F6). Renders the
 * ordered `{ label, command }` list and lets the user edit, reorder, add, and
 * remove entries. Thin: every committed change POSTs the whole list up through
 * `onSave`; the server + core schema own validation and persistence.
 */
export const WorktreeReadinessEditor: React.FC<WorktreeReadinessEditorProps> = ({ readiness, onSave, saving }) => {
  const nextId = useRef(0);
  const withIds = (list: WorktreeReadinessCommand[]): Row[] => list.map((r) => ({ ...r, _id: nextId.current++ }));
  const [rows, setRows] = useState<Row[]>(() => withIds(readiness));

  // Re-sync when the resolved list arrives / changes upstream (e.g. after fetch
  // or a successful save). A committed save re-sends the same values, so this is
  // idempotent and never clobbers an in-progress edit (edits commit on blur).
  useEffect(() => {
    setRows(withIds(readiness));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [readiness]);

  /** Apply a structural change and persist immediately when the set is valid. */
  const commit = (next: Row[]) => {
    setRows(next);
    const stripped = strip(next);
    if (isValid(stripped)) onSave(stripped);
  };

  const editField = (index: number, field: keyof WorktreeReadinessCommand, value: string) => {
    setRows((prev) => prev.map((r, i) => (i === index ? { ...r, [field]: value } : r)));
  };

  const commitEdits = () => {
    const stripped = strip(rows);
    if (isValid(stripped)) onSave(stripped);
  };

  const remove = (index: number) => commit(rows.filter((_, i) => i !== index));

  const move = (index: number, delta: number) => {
    const target = index + delta;
    if (target < 0 || target >= rows.length) return;
    const next = [...rows];
    [next[index], next[target]] = [next[target], next[index]];
    commit(next);
  };

  // A blank row is added locally only — not persisted until the user fills it in.
  const add = () => setRows([...rows, { label: '', command: '', _id: nextId.current++ }]);

  return (
    <div data-testid="worktree-readiness-editor" className="space-y-2">
      {rows.length === 0 && (
        <p className="text-xs text-muted-foreground italic">
          No readiness commands — add the install / build steps a fresh worktree needs.
        </p>
      )}

      {rows.map((row, index) => (
        <div
          key={row._id}
          data-testid={`readiness-row-${index}`}
          className="flex items-center gap-2"
        >
          <input
            aria-label={`Label for readiness command ${index + 1}`}
            value={row.label}
            disabled={saving}
            placeholder="label"
            onChange={(e) => editField(index, 'label', e.target.value)}
            onBlur={commitEdits}
            className="w-32 shrink-0 rounded border px-2 py-1 text-sm"
          />
          <input
            aria-label={`Command for readiness command ${index + 1}`}
            value={row.command}
            disabled={saving}
            placeholder="command"
            onChange={(e) => editField(index, 'command', e.target.value)}
            onBlur={commitEdits}
            className="flex-1 rounded border px-2 py-1 font-mono text-sm"
          />
          <button
            type="button"
            aria-label={`Move ${row.label || `command ${index + 1}`} up`}
            disabled={saving || index === 0}
            onClick={() => move(index, -1)}
            className="p-1 rounded text-subtle hover:text-foreground disabled:opacity-30 disabled:cursor-not-allowed"
          >
            <ArrowUp className="h-4 w-4" />
          </button>
          <button
            type="button"
            aria-label={`Move ${row.label || `command ${index + 1}`} down`}
            disabled={saving || index === rows.length - 1}
            onClick={() => move(index, 1)}
            className="p-1 rounded text-subtle hover:text-foreground disabled:opacity-30 disabled:cursor-not-allowed"
          >
            <ArrowDown className="h-4 w-4" />
          </button>
          <button
            type="button"
            aria-label={`Remove ${row.label || `command ${index + 1}`}`}
            disabled={saving}
            onClick={() => remove(index)}
            className="p-1 rounded-full text-subtle hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      ))}

      <button
        type="button"
        aria-label="Add readiness command"
        disabled={saving}
        onClick={add}
        className="flex items-center gap-1 px-2 py-1 text-sm text-muted-foreground hover:text-foreground rounded border border-dashed transition-colors disabled:opacity-40"
      >
        <Plus className="h-4 w-4" />
        Add command
      </button>
    </div>
  );
};

export default WorktreeReadinessEditor;
