import { useEffect, useState } from 'react';
import { parseDiff } from 'react-diff-view';

type DiffFile = ReturnType<typeof parseDiff>[number];

export interface CommitDiff {
  readonly files: DiffFile[];
  readonly loading: boolean;
  readonly error: string | null;
}

/**
 * Fetch a commit's own changes (parent..sha) as parsed react-diff-view files.
 * `sha` of `undefined` or the literal `'skipped'` sentinel (skip-RED tasks)
 * yields an empty, non-loading result and issues no request. Used by the task
 * detail tabs (Red/Green) to render a single commit's diff.
 */
export function useCommitDiff(repoId: string, sha: string | undefined): CommitDiff {
  const [files, setFiles] = useState<DiffFile[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!sha || sha === 'skipped') {
      setFiles([]);
      setLoading(false);
      setError(null);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetch(`/api/repos/${repoId}/git/diff/${sha}~1/${sha}`)
      .then((res) => {
        if (!res.ok) throw new Error(`Failed to load diff (${res.status})`);
        return res.json();
      })
      .then((data: { diff?: string }) => {
        if (cancelled) return;
        setFiles(data.diff ? parseDiff(data.diff) : []);
      })
      .catch((e: unknown) => {
        if (!cancelled) setError(e instanceof Error ? e.message : 'Failed to load diff');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [repoId, sha]);

  return { files, loading, error };
}
