import type { Feature, Task } from '../types';
import { deriveEffectiveStatus, deriveFeatureEffectiveStatus } from './effective-task-status';

/**
 * Worktree-aware done/skipped/left rollup for a plan's features and tasks.
 * "done" = effective status completed, "skipped" = superseded, "left" =
 * everything else; a feature is superseded only when all its tasks are
 * (deriveFeatureEffectiveStatus). Shared by the plan-detail stat readouts and
 * the compact header so both read the same numbers.
 */
export interface PlanStatCounts {
  totalFeatures: number;
  completedFeatures: number;
  supersededFeatures: number;
  /** completed + superseded */
  doneFeatures: number;
  totalTasks: number;
  completedTasks: number;
  supersededTasks: number;
  /** completed + superseded */
  doneTasks: number;
}

export function derivePlanStats(features: readonly Feature[]): PlanStatCounts {
  const tasks: Task[] = features.flatMap((f) => f.tasks ?? []);
  const taskStatus = (t: Task) => deriveEffectiveStatus(t).status;
  const completedTasks = tasks.filter((t) => taskStatus(t) === 'completed').length;
  const supersededTasks = tasks.filter((t) => taskStatus(t) === 'superseded').length;

  const featureStatus = (f: Feature) => deriveFeatureEffectiveStatus(f.tasks ?? []);
  const completedFeatures = features.filter((f) => featureStatus(f) === 'completed').length;
  const supersededFeatures = features.filter((f) => featureStatus(f) === 'superseded').length;

  return {
    totalFeatures: features.length,
    completedFeatures,
    supersededFeatures,
    doneFeatures: completedFeatures + supersededFeatures,
    totalTasks: tasks.length,
    completedTasks,
    supersededTasks,
    doneTasks: completedTasks + supersededTasks,
  };
}

const percent = (done: number, total: number): number =>
  total > 0 ? Math.round((done / total) * 100) : 0;

/**
 * Completion percents for the compact headline bars (label + % only). The old
 * per-readout "N done · N skipped · N left" breakdown was subsumed by the
 * provenance status distribution (detail-provenance-restyle task 1), so these
 * return the bare percent — nothing else is computed.
 */
export function featuresBuiltReadout(c: PlanStatCounts): number {
  return percent(c.doneFeatures, c.totalFeatures);
}

export function tasksResolvedReadout(c: PlanStatCounts): number {
  return percent(c.doneTasks, c.totalTasks);
}
