import React, { useEffect, useRef } from 'react';
import type { RunActivityEntry } from '../utils/run-activity';

export interface RunTerminalProps {
  /** The folded transcript, in arrival order (see deriveRunActivity). */
  entries: RunActivityEntry[];
  /** Whether the run is still streaming — picks the empty-state copy. */
  live: boolean;
}

/**
 * The run terminal scrollback (fix run-dispatch-stale-dashboard task 6,
 * extracted in task 14): the stream in ARRIVAL order — assistant text and
 * landed commits interleaved — tail-pinned until the user scrolls up into the
 * history. Tool calls are not in the transcript; they live in the Tool calls
 * section (fix live-activity-transcript-duplicates-tool-calls). Purely
 * presentational so any run surface
 * (live activity, reconcile output, future remote tails) can reuse it.
 * Commits to a dark terminal look in both themes, as terminals do.
 */
const RunTerminal: React.FC<RunTerminalProps> = ({ entries, live }) => {
  // Pinned to the tail while the user hasn't scrolled up; a scroll away from
  // the bottom unpins, scrolling back near the bottom re-pins. Refs (not
  // state) — pinning must not re-render.
  const terminalRef = useRef<HTMLDivElement>(null);
  const tailRef = useRef<HTMLDivElement>(null);
  const pinnedRef = useRef(true);
  const handleScroll = (): void => {
    const el = terminalRef.current;
    if (!el) return;
    pinnedRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 40;
  };
  const entryCount = entries.length;
  // deriveRunActivity grows a streaming assistant paragraph by appending to
  // the LAST text entry — the array length never changes, so the count alone
  // would let the tail drift below the fold mid-paragraph.
  const lastEntry = entries[entryCount - 1];
  const lastTextLength = lastEntry?.kind === 'text' ? lastEntry.text.length : 0;
  useEffect(() => {
    // Keyed on the RENDERED transcript, not the raw event count — a
    // tool_result/pipeline/exit event changes nothing visible. Optional-call:
    // jsdom has no scrollIntoView, so tests without the spy must not crash.
    if (pinnedRef.current) tailRef.current?.scrollIntoView?.({ block: 'end' });
  }, [entryCount, lastTextLength]);

  return (
    <div
      data-testid="run-terminal"
      ref={terminalRef}
      onScroll={handleScroll}
      className="max-h-[360px] overflow-y-auto rounded-lg bg-zinc-950 p-4 font-mono text-[13px] leading-relaxed"
    >
      {entries.length > 0 ? (
        <>
          {entries.map((entry, i) => {
            // Index keys: the transcript is append-only and order-stable.
            if (entry.kind === 'text') {
              return (
                <pre key={i} className="whitespace-pre-wrap break-words text-zinc-100">
                  {entry.text}
                </pre>
              );
            }
            return (
              <div key={i} className="text-emerald-300">
                {`✓ ${entry.prefix} ${entry.sha.slice(0, 9)}`}
              </div>
            );
          })}
          <div ref={tailRef} data-testid="run-terminal-tail" aria-hidden />
        </>
      ) : (
        <p className="italic text-zinc-500">{live ? 'Waiting for activity…' : 'No activity yet'}</p>
      )}
    </div>
  );
};

export default RunTerminal;
