import { useCallback, useState } from 'react';
import type { SmokeTestPhaseEvent, SmokeTestResult } from '@magic-ingredients/tiny-brain-core';
import { parseSSEStream } from '../utils/sse-parser';

/**
 * Drive the environment smoke-run (workers / env-smoke-test task 2): POST the
 * selected model to the environment's smoke-test route and read the SSE stream
 * it returns, accumulating each `phase` frame as it arrives and settling on the
 * final `result` frame (the echoed model identity on success, or the phase that
 * died on failure). One-shot per `run` — a fresh run clears the prior phases and
 * result so the panel never shows a stale echo.
 */
export interface UseEnvironmentSmokeTestResult {
  /** Phase transitions received so far, in arrival order. */
  phases: SmokeTestPhaseEvent[];
  /** The terminal result once the `result` frame arrives, else null. */
  result: SmokeTestResult | null;
  /** True while a run's stream is open. */
  running: boolean;
  /** A request-level failure (non-2xx, transport), distinct from a smoke-run
   * `failure` result (which is a normal outcome, carried on `result`). */
  error: string | null;
  run: (name: string, model: string) => Promise<void>;
}

function isPhaseEvent(data: unknown): data is SmokeTestPhaseEvent {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as { phase?: unknown }).phase === 'string' &&
    typeof (data as { status?: unknown }).status === 'string'
  );
}

function isResult(data: unknown): data is SmokeTestResult {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as { outcome?: unknown }).outcome === 'string'
  );
}

export function useEnvironmentSmokeTest(): UseEnvironmentSmokeTestResult {
  const [phases, setPhases] = useState<SmokeTestPhaseEvent[]>([]);
  const [result, setResult] = useState<SmokeTestResult | null>(null);
  const [running, setRunning] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const run = useCallback(async (name: string, model: string) => {
    // A fresh run wipes the prior phases/result so the panel never shows a
    // stale echo while the new run streams in.
    setPhases([]);
    setResult(null);
    setError(null);
    setRunning(true);
    try {
      const res = await fetch(`/api/environments/${encodeURIComponent(name)}/smoke-test`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ model }),
      });
      if (!res.ok || !res.body) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        setError(body.error ?? `Smoke test request failed (HTTP ${res.status})`);
        return;
      }
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      // eslint-disable-next-line no-constant-condition
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const { events, buffer: remaining } = parseSSEStream(buffer);
        buffer = remaining;
        for (const frame of events) {
          if (frame.event === 'phase' && isPhaseEvent(frame.data)) {
            const phase = frame.data;
            setPhases((prev) => [...prev, phase]);
          } else if (frame.event === 'result' && isResult(frame.data)) {
            setResult(frame.data);
          }
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Smoke test failed');
    } finally {
      setRunning(false);
    }
  }, []);

  return { phases, result, running, error, run };
}
