import { useCallback, useEffect, useRef, useState } from 'react';
import type { Fix, Plan } from '../types';
import type { SpikeProgress, SpikeWorktreeStatus, Worktree } from '@magic-ingredients/tiny-brain-core';
// Value-imported from the node-free subpath (not the barrel): core's
// `getSpikeWorktreeStatus` lives in a module with no `child_process` dependency
// so the browser bundle can carry it, the way `reconcile-strip` imports
// `./reconcile-stream`. Keeps the present/orphaned/unconfigured derivation
// single-sourced instead of re-implemented client-side.
import { getSpikeWorktreeStatus } from '@magic-ingredients/tiny-brain-core/spike-worktree-status';
import { sseEventMatchesRepo } from '../services/SSEManager';
import type { ReconnectedEvent, StatusChangeEvent, ValidationChangeEvent } from '../services/SSEManager';
import { useSSEEvent } from './useSSE';
import { useRunLive } from './useRunLive';

/**
 * The selected spike's live worker run, attached server-side by the spike detail
 * route's activeRun enrichment (spike-detail-run-state F1). Structurally the wire
 * `ActiveRunLink` — declared client-side so the browser bundle carries no server
 * type, mirroring the inline `activeRun` shape on the Fix / Feature types. */
export interface SpikeActiveRun {
  runId?: string;
  target?: 'local-worktree' | 'cloud-remote';
  worker?: string;
  model?: string;
  envName?: string;
  state?: 'launched' | 'in_progress';
  worktreePath?: string;
}

/**
 * The selected spike's latest resumable run — the same projection
 * `GET /launch/resumable` serves (`ResumableRunView`). Carried so Feature 2's
 * SpikeDetail can offer Continue on a terminal-but-resumable spike run. */
export interface SpikeResumableRun {
  runId: string;
  status: string;
  exitReason?: string;
}

export interface UseBoardItemDetailResult {
  fix: Fix | null;
  plan: Plan | null;
  /** The selected spike's full record (fix board-spike-detail-panel-stubbed), and
   * its worktree status derived from the git inventory — mirrors the retired
   * Spikes tab so the board pane can mount the same `SpikeDetail` island. */
  spike: SpikeProgress | null;
  spikeWorktreeStatus: SpikeWorktreeStatus;
  /** The selected spike's active worker run, or null (non-spike selection, or a
   * spike with no live run). Feature 2's SpikeDetail reads this for run state. */
  spikeActiveRun: SpikeActiveRun | null;
  /** The selected spike's latest resumable run, or null. */
  spikeResumableRun: SpikeResumableRun | null;
  /** Re-fetch the selected item on demand — the board pane's spike affordances
   * (launch / park / outcome) call it after a mutation to refresh the pane. */
  refresh: () => void;
}

/** The single-item detail wire shapes: `/fixes/:id` returns `{ fix }`,
 * `/plans/:id` returns `{ plan }` (board-surface task 25), `/spikes/:id` returns
 * `{ spike }` (the retired Spikes tab's endpoint). */
interface FixDetailResponse {
  fix?: Fix;
}
interface PlanDetailResponse {
  plan?: Plan;
}
interface SpikeDetailResponse {
  /** The spike doc, enriched by the F1 server route with its live worker run. */
  spike?: SpikeProgress & { activeRun?: SpikeActiveRun };
  /** The spike's latest resumable run (F1 server seam), or null when none. */
  resumable?: SpikeResumableRun | null;
}
interface WorktreesResponse {
  worktrees?: readonly Worktree[];
}

const UNCONFIGURED_WORKTREE: SpikeWorktreeStatus = { kind: 'unconfigured' };

/**
 * Trailing-debounce window for a repo `run-change` re-pull (delivery-surface-
 * refetch-storm). A reconcile/land rewrites its `runs/<id>.json` through a rapid
 * run of lifecycle writes (queued → replaying → agent → verifying → rebase →
 * merge …); one window folds that burst into a SINGLE re-pull instead of ~12,
 * so the validation control stops flipping per write. Mirrors useBoard's own
 * `SSE_REFRESH_DEBOUNCE_MS` — long enough to swallow a same-reconcile burst.
 */
const RUN_REFRESH_DEBOUNCE_MS = 250;

/** Parse the board's kind-prefixed `?item=` value (`fix:<id>` / `prd:<id>` /
 * `spike:<id>`); anything else has no board detail, so it resolves to null. */
function parseSelection(
  selectedItemId: string | null,
): { kind: 'fix' | 'prd' | 'spike'; id: string } | null {
  if (!selectedItemId) return null;
  if (selectedItemId.startsWith('fix:')) return { kind: 'fix', id: selectedItemId.slice(4) };
  if (selectedItemId.startsWith('prd:')) return { kind: 'prd', id: selectedItemId.slice(4) };
  if (selectedItemId.startsWith('spike:')) return { kind: 'spike', id: selectedItemId.slice(6) };
  return null;
}

/**
 * board-surface-defects task 25 — fetch the SELECTED board item's full detail on
 * demand. The board card face is cheap; the heavy per-item payload (features /
 * tasks, statusByRef, provenance) is fetched only for the shown item, keyed by
 * the board's kind-prefixed `?item=` value: `fix:<id>` → `/fixes/:id`,
 * `prd:<id>` → `/plans/:id`. Nothing is fetched until a card is selected ("not
 * eagerly for every card"), and a `cancelled` guard drops a response a fast
 * re-selection has superseded so the detail pane never shows the wrong item.
 *
 * No loading flag is exposed: the consumer always has the board card to render
 * as the in-flight fallback, so there is no blank state to guard.
 */
export function useBoardItemDetail(
  repoId: string | null,
  selectedItemId: string | null,
): UseBoardItemDetailResult {
  const [fix, setFix] = useState<Fix | null>(null);
  const [plan, setPlan] = useState<Plan | null>(null);
  const [spike, setSpike] = useState<SpikeProgress | null>(null);
  const [spikeWorktreeStatus, setSpikeWorktreeStatus] =
    useState<SpikeWorktreeStatus>(UNCONFIGURED_WORKTREE);
  const [spikeActiveRun, setSpikeActiveRun] = useState<SpikeActiveRun | null>(null);
  const [spikeResumableRun, setSpikeResumableRun] = useState<SpikeResumableRun | null>(null);
  // A monotonic nonce that, when bumped, re-runs the fetch effect below. This is
  // the detail pane's liveness (board-item-detail-not-live-on-sse): the on-demand
  // fetch dropped the live refresh the always-loaded card had via the board's
  // run-change SSE (task 25), so the pane's task pills froze at fetch time. We
  // restore it by re-fetching the SELECTED item on the same liveness signals the
  // board list uses.
  const [refreshNonce, setRefreshNonce] = useState(0);
  const refresh = useCallback(() => setRefreshNonce((n) => n + 1), []);

  // A status-change (a commit/phase moved a task) re-fetches ONLY when it names
  // the selected item — a sibling item's change must not churn this fetch.
  useSSEEvent<StatusChangeEvent>(
    'statusChange',
    useCallback(
      (event) => {
        if (!sseEventMatchesRepo(event, repoId)) return;
        const selection = parseSelection(selectedItemId);
        if (!selection) return;
        // A spike carries no per-entity `statusChange` resource (the event stream
        // only re-projects fixes/plans by id), so its live refresh rides the
        // repo-wide `runChange` / `reconnected` signals below, not this handler.
        if (selection.kind === 'spike') return;
        // `resource` is the load-bearing kind discriminant: a fix id and a PRD id
        // are both bare kebab slugs with no cross-kind namespace, so match the
        // event's kind to the selection's (`prd` selection ↔ `plan` resource)
        // before the id check — else a `fix:foo` change would refetch a `prd:foo`.
        const expectedResource = selection.kind === 'prd' ? 'plan' : 'fix';
        if (event.resource !== expectedResource) return;
        if (event.entities.some((e) => e.id === selection.id)) refresh();
      },
      [repoId, selectedItemId, refresh],
    ),
  );
  // A SCOPED validation-change (live-run-overlay task 1) fires only when the named
  // item's server-recomputed validation phase actually moved. It is the client
  // consumer of the server's validation signal: the pane re-pulls the finished
  // server payload and renders it as props, deriving the phase NOWHERE client-side.
  //
  // These scoped handlers (with `statusChange` above) are the PRECISE re-pull
  // path: they fire only when the named item's own status/validation actually
  // moves, so a reconcile's intermediate run-record churn does not ride them. The
  // blanket `run-change` re-pull below is retained for run-pill liveness but
  // DEBOUNCED (delivery-surface-refetch-storm), so it can no longer flip the
  // control per write. Matching is by repo + resource + id — a
  // feature-scoped event (`resource: 'plan'` + `feature`) re-pulls the whole plan
  // pane, so `feature` is carried but not part of the match. A spike has no
  // validation surface, so it early-returns.
  useSSEEvent<ValidationChangeEvent>(
    'validationChange',
    useCallback(
      (event) => {
        if (!sseEventMatchesRepo(event, repoId)) return;
        const selection = parseSelection(selectedItemId);
        if (!selection || selection.kind === 'spike') return;
        const expectedResource = selection.kind === 'prd' ? 'plan' : 'fix';
        if (event.resource !== expectedResource) return;
        if (event.id === selection.id) refresh();
      },
      [repoId, selectedItemId, refresh],
    ),
  );

  // A run lifecycle move (dispatch/exit) for the repo re-derives the item's run
  // pills — the Launch↔Running flip rides `fix.activeRun`, which only a re-pull
  // refreshes, and a spike (no scoped status/validation signal) has this as its
  // ONLY liveness path. `runChange` carries no work-ref, so (like useBoard) any
  // repo run-change refreshes.
  //
  // But it is DEBOUNCED (delivery-surface-refetch-storm): a reconcile/land rewrites
  // its `runs/<id>.json` through a rapid burst of lifecycle writes, and re-pulling
  // per write reset/blanked the validation control ~12× per reconcile. A trailing
  // window folds that burst into one re-pull, keeping run-pill liveness while the
  // control stops flipping. The precise per-item moves still ride the immediate
  // scoped handlers above.
  const runRefreshTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const scheduleRunRefresh = useCallback(() => {
    if (runRefreshTimer.current !== null) clearTimeout(runRefreshTimer.current);
    runRefreshTimer.current = setTimeout(() => {
      runRefreshTimer.current = null;
      refresh();
    }, RUN_REFRESH_DEBOUNCE_MS);
  }, [refresh]);
  // Drop any pending run-refresh on unmount so a timer can't fire into an
  // unmounted hook.
  useEffect(
    () => () => {
      if (runRefreshTimer.current !== null) clearTimeout(runRefreshTimer.current);
    },
    [],
  );
  useRunLive(repoId, scheduleRunRefresh);

  // Reconnect resync (sse-client-gives-up-and-never-resyncs task 3): the
  // selected item's statusChange may have fired while the tab was deaf, so a
  // reopen after a drop refetches unconditionally — the fetch effect already
  // no-ops when nothing is selected.
  useSSEEvent<ReconnectedEvent>('reconnected', refresh);

  useEffect(() => {
    const selection = parseSelection(selectedItemId);
    // No repo or nothing selectable (cleared) → clear all three and stop.
    if (!repoId || !selection) {
      setFix(null);
      setPlan(null);
      setSpike(null);
      setSpikeWorktreeStatus(UNCONFIGURED_WORKTREE);
      setSpikeActiveRun(null);
      setSpikeResumableRun(null);
      return;
    }

    const { kind, id } = selection;

    // A spike sources its full record from the retired Spikes tab's endpoint,
    // and — like that tab — pairs it with the git worktree inventory to derive
    // the launch/park/cleanup status `SpikeDetail` renders. Fetched together so
    // the pane never renders the island against a stale worktree status.
    if (kind === 'spike') {
      setFix(null);
      setPlan(null);
      let spikeCancelled = false;
      const spikeUrl = `/api/repos/${encodeURIComponent(repoId)}/spikes/${encodeURIComponent(id)}`;
      const worktreesUrl = `/api/repos/${encodeURIComponent(repoId)}/worktrees`;
      void (async () => {
        try {
          const [spikeRes, worktreesRes] = await Promise.all([fetch(spikeUrl), fetch(worktreesUrl)]);
          if (spikeCancelled) return;
          if (!spikeRes.ok) {
            setSpike(null);
            setSpikeWorktreeStatus(UNCONFIGURED_WORKTREE);
            setSpikeActiveRun(null);
            setSpikeResumableRun(null);
            return;
          }
          const spikeData: SpikeDetailResponse = await spikeRes.json();
          const worktreesData: WorktreesResponse = worktreesRes.ok
            ? await worktreesRes.json()
            : {};
          if (spikeCancelled) return;
          const record = spikeData.spike ?? null;
          setSpike(record);
          setSpikeWorktreeStatus(
            record ? getSpikeWorktreeStatus(record.worktree, worktreesData.worktrees ?? []) : UNCONFIGURED_WORKTREE,
          );
          // Surface the F1 run-state seam: the live run rides on the enriched
          // spike doc, the resumable projection on the response's top-level field.
          // Both are gated on a present spike record — a run without a spike to
          // render it against is meaningless, so an absent doc yields null runs.
          setSpikeActiveRun(record?.activeRun ?? null);
          setSpikeResumableRun(record ? spikeData.resumable ?? null : null);
        } catch {
          if (!spikeCancelled) {
            setSpike(null);
            setSpikeWorktreeStatus(UNCONFIGURED_WORKTREE);
            setSpikeActiveRun(null);
            setSpikeResumableRun(null);
          }
        }
      })();
      return () => {
        spikeCancelled = true;
      };
    }

    // Drop the other kinds' stale detail up front so the pane can't show two
    // while the new item is in flight. A fix/prd selection carries no spike run
    // state, so the F1 run fields reset to null here (result shape unchanged).
    setSpike(null);
    setSpikeWorktreeStatus(UNCONFIGURED_WORKTREE);
    setSpikeActiveRun(null);
    setSpikeResumableRun(null);
    if (kind === 'fix') setPlan(null);
    else setFix(null);

    let cancelled = false;
    const url =
      kind === 'fix'
        ? `/api/repos/${encodeURIComponent(repoId)}/fixes/${encodeURIComponent(id)}`
        : `/api/repos/${encodeURIComponent(repoId)}/plans/${encodeURIComponent(id)}`;
    void (async () => {
      try {
        const res = await fetch(url);
        if (cancelled) return;
        if (!res.ok) {
          if (kind === 'fix') setFix(null);
          else setPlan(null);
          return;
        }
        if (kind === 'fix') {
          const data: FixDetailResponse = await res.json();
          if (cancelled) return;
          setFix(data.fix ?? null);
          setPlan(null);
        } else {
          const data: PlanDetailResponse = await res.json();
          if (cancelled) return;
          setPlan(data.plan ?? null);
          setFix(null);
        }
      } catch {
        if (!cancelled) {
          if (kind === 'fix') setFix(null);
          else setPlan(null);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
    // `refreshNonce` re-runs this effect on a liveness SSE for the selected item,
    // re-fetching its detail; the `cancelled` guard still drops a superseded response.
  }, [repoId, selectedItemId, refreshNonce]);

  return {
    fix,
    plan,
    spike,
    spikeWorktreeStatus,
    spikeActiveRun,
    spikeResumableRun,
    refresh,
  };
}
