import React, { useEffect, useState } from 'react';
import { Link } from 'react-router';
import { Plus, RefreshCw } from 'lucide-react';
import { Button } from '../components/ui/button';
import { HeaderActions } from '../components/layout/header-actions';
import { WorkerCrudBody, useWorkerCrud } from '../components/workers/WorkerCrud';
import { ModelsPanel } from '../components/workers/ModelsPanel';

/**
 * Client view of one registered repo's committed workers, as
 * GET /api/workers/repo-workers returns it (repo-scope-worker-crud task 4).
 */
interface RepoWorkersEntry {
  repoId: string;
  repoName: string;
  workers: string[];
}

/**
 * Execution › Workers — the global surface over /api/workers
 * (workers PRD, worker-visibility task 2).
 *
 * A worker is a named (agent · model · effort · environment) profile; the
 * environment decides WHERE it runs, so the same model gives you a local
 * and a remote worker. Probe status is MANUAL — rows start unchecked and
 * probe only on the per-row Re-check / top-bar Reload; nothing polls. The UI
 * stays dumb: it renders what the routes return and POSTs raw fields for
 * the server to validate.
 *
 * The table + draft panel live in the shared `WorkerCrud` surface (the repo
 * Settings › Workers section mounts the same one against the repo-scoped
 * API); this page only wires the global feed and its page chrome.
 */

const WorkersPage: React.FC = () => {
  const { body, modelsPanel, error, loading, reload, newWorker } = useWorkerCrud();

  // Read-only pointer to committed repo-level workers (ADR-0025's primary
  // team channel). CRUD lives in each repo's Settings › Workers section; here
  // we only name them and link across. A failed fetch leaves the pointer
  // absent — it's a convenience, never a gate on the global surface. Fetched
  // once on mount by design: the top-bar Reload refreshes the global list,
  // not this cross-repo pointer (a full navigation re-reads it).
  const [repoWorkers, setRepoWorkers] = useState<RepoWorkersEntry[]>([]);
  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch('/api/workers/repo-workers');
        if (!res.ok) return;
        const data = (await res.json()) as { repoWorkers?: RepoWorkersEntry[] };
        if (!cancelled) setRepoWorkers(data.repoWorkers ?? []);
      } catch {
        // Leave the pointer absent on transport failure.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);
  // A registered repo that has committed nothing is omitted — there is
  // nothing to point at, and counting it would read "0 … in 1 repos".
  const pointerRepos = repoWorkers.filter((repo) => repo.workers.length > 0);
  const totalRepoWorkers = pointerRepos.reduce((sum, repo) => sum + repo.workers.length, 0);

  return (
    <div className="w-full p-4 md:p-6 lg:p-8">
      {/* Page identity lives in the top rail (task 11); the actions portal
          into the rail's slot. New worker is also the way OUT of edit mode —
          the panels have no Cancel (task 7). */}
      <HeaderActions>
        <Button variant="outline" size="sm" onClick={() => void reload()}>
          <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
          Reload
        </Button>
        <Button size="sm" onClick={newWorker}>
          <Plus className="mr-1.5 h-3.5 w-3.5" />
          New worker
        </Button>
      </HeaderActions>
      <p className="text-sm text-muted-foreground">
        A worker is a named{' '}
        <span className="font-mono text-xs">(agent · model · effort · environment)</span> profile.
        The environment decides <em>where</em> it runs. These are your{' '}
        <strong className="font-medium text-foreground">machine-global</strong> workers, available
        across every repo you work on.
      </p>
      <p className="mt-1 text-sm text-muted-foreground">
        You can share workers with your team at a repo level — add one under{' '}
        <span className="font-medium text-foreground">Repo → Settings → Workers</span> and commit
        that repo's <span className="font-mono text-xs">.tiny-brain</span> directory to git.
      </p>

      {pointerRepos.length > 0 && (
        <div className="mt-3 rounded-xl border border-[var(--ds-border)] p-3">
          <p className="text-sm text-foreground">
            {totalRepoWorkers} repo-level worker{totalRepoWorkers === 1 ? '' : 's'} in{' '}
            {pointerRepos.length} repo{pointerRepos.length === 1 ? '' : 's'}
          </p>
          <ul className="mt-2 grid gap-1">
            {pointerRepos.map((repo) => (
              <li key={repo.repoId} className="text-sm">
                <Link
                  to={`/repos/${encodeURIComponent(repo.repoId)}?settings=workers`}
                  className="font-medium text-foreground hover:underline"
                >
                  {repo.repoName}
                </Link>
                <span className="text-muted-foreground"> — {repo.workers.join(', ')}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {error && <p className="mt-4 text-sm text-red-500">{error}</p>}
      {loading && <p className="mt-4 text-sm text-muted-foreground">Loading workers…</p>}

      <WorkerCrudBody
        {...body}
        emptyHint="No workers yet — create one to dispatch work to."
        belowList={<ModelsPanel {...modelsPanel} />}
      />
    </div>
  );
};

export default WorkersPage;
