import React from 'react';
import { Archive } from 'lucide-react';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from './ui/alert-dialog';

interface ArchiveConfirmDialogProps {
  /** Noun for the confirmation copy, e.g. "fix" or "PRD". */
  itemKind: string;
  /** The item's display name, quoted in the dialog body. */
  itemName: string;
  /** Fires only on the dialog's confirm action — never on open or cancel. */
  onConfirm: () => void;
  /** Class for the trigger button, so each surface keeps its own action styling. */
  triggerClassName?: string;
}

/**
 * The shared "Are you sure?" gate for the Archive action
 * (fix archive-button-no-confirmation). Archiving is a deliberate state change,
 * so the trigger opens an AlertDialog and `onConfirm` fires only on confirm;
 * cancel is a no-op. Unarchive is NOT routed through here — restoring is the
 * undo, so it stays immediate on every surface.
 */
const ArchiveConfirmDialog: React.FC<ArchiveConfirmDialogProps> = ({
  itemKind,
  itemName,
  onConfirm,
  triggerClassName,
}) => (
  <AlertDialog>
    <AlertDialogTrigger asChild>
      <button type="button" aria-label="Archive" className={triggerClassName}>
        <Archive className="h-3.5 w-3.5" />
        Archive
      </button>
    </AlertDialogTrigger>
    <AlertDialogContent>
      <AlertDialogHeader>
        <AlertDialogTitle>Archive this {itemKind}?</AlertDialogTitle>
        <AlertDialogDescription>
          This moves &quot;{itemName}&quot; to the Archive view. You can unarchive it later.
        </AlertDialogDescription>
      </AlertDialogHeader>
      <AlertDialogFooter>
        <AlertDialogCancel>Cancel</AlertDialogCancel>
        <AlertDialogAction onClick={onConfirm}>Archive</AlertDialogAction>
      </AlertDialogFooter>
    </AlertDialogContent>
  </AlertDialog>
);

export default ArchiveConfirmDialog;
