import React from 'react';
import { cn } from '@/lib/utils';

export interface DetailHeaderProps {
  /** data-testid for the header root (e.g. `plan-detail-header`, `fix-detail-header`). */
  testId: string;
  /** Top-row left: the status eyebrow (caller supplies the tone colour + label). */
  eyebrow: React.ReactNode;
  /** Top-row right: the MiniStatusRail (merge mode), RHS-aligned in the eyebrow row. */
  rail?: React.ReactNode;
  /** The header title. */
  title: React.ReactNode;
  /** Beside the title — a copy-id affordance / small marker. */
  titleAdornment?: React.ReactNode;
  /** A full-width row rendered between the title and the meta row — the
   *  planning-checks pills (plan-readiness-indicators F3). Omit ⇒ no row. */
  belowTitle?: React.ReactNode;
  /** Meta line — "{n} features · last updated …" / severity · opened · tasks. */
  meta?: React.ReactNode;
  /** Right-aligned header actions — Archive / Source / Unarchive. */
  actions?: React.ReactNode;
}

/**
 * The shared detail-header shell for the fix / prd / spike detail surfaces, so
 * the three never drift:
 *
 *   eyebrow · status                         ‹MiniStatusRail merge›
 *   Title                                            (copy-id)
 *   meta · line ································· [ actions ]
 *
 * The rail sits RHS-aligned in the eyebrow row (the delivery affordance lives at
 * the top of the header); the title row carries a touch more padding beneath the
 * top row. Presentational — each surface computes its own eyebrow, rail, and
 * actions and drops the nodes into the slots.
 */
export const DetailHeader: React.FC<DetailHeaderProps> = ({
  testId,
  eyebrow,
  rail,
  title,
  titleAdornment,
  belowTitle,
  meta,
  actions,
}) => {
  const showMetaRow = meta !== undefined || actions !== undefined;
  return (
    <div data-testid={testId}>
      {/* Reserve the rail's height even with no rail, so navigating between an
          item with a rail and one without doesn't shift the title (no judder). */}
      <div className="flex min-h-7 items-center justify-between gap-3">
        {eyebrow}
        {rail && <div className="flex-shrink-0">{rail}</div>}
      </div>

      <div className="mt-3.5 flex items-center gap-2.5">
        {title}
        {titleAdornment}
      </div>

      {/* The planning-checks pills (readiness-rail-ui F3) sit under the title,
          above the meta line — persisting for the whole life of the item, unlike
          the Backlog-only card row. */}
      {belowTitle && <div className="mt-2.5">{belowTitle}</div>}

      {showMetaRow && (
        <div
          data-testid="detail-header-meta-row"
          className="mt-2 flex flex-wrap items-center justify-between gap-3"
        >
          {meta}
          {actions && (
            // Right-align a lone actions node (no meta) — justify-between alone
            // would left-align a single child.
            <div className={cn('flex items-center gap-1', meta === undefined && 'ml-auto')}>{actions}</div>
          )}
        </div>
      )}
    </div>
  );
};

export default DetailHeader;
