import { useCallback, useEffect, useRef, useState } from 'react';
import type { RunEvent } from '@magic-ingredients/tiny-brain-core';
import type { BoardRow } from './useBoard';
import { postDeliveryAction } from '../services/api';
import { subscribeRunStream } from './run-stream-core';
import { foldRunOutcome, runIdOf, type RunOutcome } from './run-outcome';

/**
 * The land state of a single In-review board card, or undefined when idle. Drives
 * the card's Land button: `landing` disables it and reads "Landing…"; `error`
 * flips it to a re-fireable "Retry land".
 */
export type BoardLandState = 'landing' | 'error';

export interface BoardLand {
  /**
   * Fire the land action for an In-review row. The land unit is the row's
   * worktree BRANCH (the delivery route keys on it); a row with no branch — or
   * no repo — is a silent no-op (the card gates its button on the same branch, so
   * this is defence-in-depth, not the primary guard). A land is a RUN: the POST
   * returns `{ runId }` and the real outcome rides that run's terminal exit, so
   * this stays "landing" until the run terminates and flips to "error" (with a
   * reason) when it fails — the board also self-invalidates on the land run's SSE
   * and re-derives the card In review → Done on success.
   */
  landItem: (row: BoardRow) => void;
  /** The land state for a row (keyed on its branch), or undefined when idle. */
  landStateFor: (row: BoardRow) => BoardLandState | undefined;
  /**
   * Why the row's land failed — the failed run's exit `reason` (a diverged
   * ff-land carries reason + rebase hint), the stream fault, or undefined when
   * the POST itself faulted before a run started. Undefined when the row is not
   * in the error state.
   */
  landFailureFor: (row: BoardRow) => string | undefined;
}

const EMPTY: ReadonlySet<string> = new Set();
const EMPTY_MAP: ReadonlyMap<string, string | undefined> = new Map();

const without = (set: ReadonlySet<string>, key: string): ReadonlySet<string> => {
  if (!set.has(key)) return set;
  const next = new Set(set);
  next.delete(key);
  return next;
};

const withoutKey = <K, V>(map: ReadonlyMap<K, V>, key: K): ReadonlyMap<K, V> => {
  if (!map.has(key)) return map;
  const next = new Map(map);
  next.delete(key);
  return next;
};

/**
 * Watch ONE land run's stream to its terminal outcome, then report it. The
 * board's multiplexed subscriber (N cards can land at once) — deliberately NOT
 * the island's single-run {@link useRunStream} hook, which cannot fan out over a
 * dynamic set of runs. It shares the SAME wire mechanics via
 * {@link subscribeRunStream} (fetch, decode, dedup, reconnect-with-replay) and
 * the SAME terminal fold via {@link foldRunOutcome}, so a live exit, a synthetic
 * terminal exit (a run already terminal at subscribe), a transient drop
 * (reconnected, not failed), and a permanent break are all read exactly the way
 * the island reads them. Returns an abort function; an aborted watch reports
 * nothing (the run outlives the board card).
 */
function watchLandRun(
  repoId: string,
  runId: string,
  onTerminal: (outcome: RunOutcome) => void,
): () => void {
  const events: RunEvent[] = [];
  let streamError: string | null = null;
  return subscribeRunStream(repoId, runId, {
    onEvents: (fresh) => events.push(...fresh),
    onError: (error) => {
      streamError = error;
    },
    onEnd: () => onTerminal(foldRunOutcome(events, runId, streamError)),
  });
}

/**
 * The board's Land-action wiring, extracted from RepoDetailPage so the branch
 * derivation, the POST target/body, the busy guard, and the failure channel are
 * unit-testable without rendering the page (mirrors {@link useDeliveryActions},
 * the worktree-island equivalent, and shares its {@link runIdOf} /
 * {@link foldRunOutcome} land-run lifecycle). A land is a run: `landItem` POSTs,
 * captures the returned `runId`, and subscribes to that run per branch; the
 * card's error / "Retry land" state and its failure reason are derived from the
 * run's failed terminal, NOT from the POST `.catch` (which now covers only a
 * fault before any run started). The board self-invalidates on the land run's
 * SSE and re-derives the card In review → Done on success.
 */
export function useBoardLand(repoId: string | null): BoardLand {
  const [landing, setLanding] = useState<ReadonlySet<string>>(EMPTY);
  const [failed, setFailed] = useState<ReadonlyMap<string, string | undefined>>(EMPTY_MAP);
  // branch → runId for lands whose POST returned a runId and whose run is being
  // watched to its terminal. The subscriber effect reconciles subscriptions
  // against this set.
  const [activeRuns, setActiveRuns] = useState<ReadonlyMap<string, string>>(new Map());
  // A synchronous in-flight guard (a ref, not the render state): a double-click
  // fires two handlers in one tick, before a state update could flush, so the
  // second must see the first already in flight and bail — else two POSTs race.
  const inFlight = useRef<Set<string>>(new Set());
  // Live run subscriptions, keyed by branch → { runId, cancel }. Keyed on the
  // runId too so a RETRY that mints a new runId for the same branch re-subscribes
  // (a branch-only guard would strand the retry's run unwatched).
  const subs = useRef<Map<string, { runId: string; cancel: () => void }>>(new Map());

  // Reset on a repo switch (the React-blessed "adjust state when a prop changes"
  // pattern — runs during render, before the effects, so the reconcile effect
  // below sees the cleared set and tears the old repo's watches down). An
  // in-flight land belongs to the old board and must not bleed into the new one.
  const prevRepo = useRef(repoId);
  if (prevRepo.current !== repoId) {
    prevRepo.current = repoId;
    inFlight.current.clear();
    setLanding(EMPTY);
    setFailed(EMPTY_MAP);
    setActiveRuns(new Map());
  }

  const landItem = useCallback(
    (row: BoardRow) => {
      const branch = row.summary.worktree?.branch;
      if (!repoId || branch === undefined || inFlight.current.has(branch)) return;
      inFlight.current.add(branch);
      setLanding((s) => new Set(s).add(branch));
      // Clear any prior failure — this is a retry (or a first attempt).
      setFailed((m) => withoutKey(m, branch));
      void postDeliveryAction(repoId, 'land', { workItemId: branch })
        .then((res) => {
          const runId = runIdOf(res);
          if (runId) {
            // Hand off to the run watcher. The guard HOLDS — it is released only
            // when the run reaches its terminal (in the subscriber's onTerminal
            // below), never on POST resolution. This closes the double-dispatch
            // window: a second click during the still-running land is rejected.
            // Trade-off (adversarial review, LOW): a genuinely HUNG run — stream
            // open and OK but no exit ever emitted — holds the guard until it
            // terminates, with no client timeout. This is the run-tracking
            // model's intended stance and mirrors the island (useDeliveryActions
            // holds `busy` on a hung run the same way); a client-side timeout
            // would risk re-opening the double-dispatch it exists to close.
            setActiveRuns((m) => new Map(m).set(branch, runId));
          } else {
            // A no-run short-circuit (already-landed / nothing to stream): there
            // is no run to await, so release the guard and clear the card now.
            inFlight.current.delete(branch);
            setLanding((s) => without(s, branch));
          }
        })
        // The POST itself faulted before a run started — the only case the
        // `.catch` still owns. No run to await, so release the guard here and
        // flip the card to its re-fireable error state.
        .catch(() => {
          inFlight.current.delete(branch);
          setLanding((s) => without(s, branch));
          setFailed((m) => new Map(m).set(branch, undefined));
        });
    },
    [repoId],
  );

  // The multiplexed subscriber: one run-stream watch per active land. Reconcile
  // incrementally against `activeRuns` — start a watch for each new (branch,
  // runId), re-subscribe when a branch's runId changes (a retry), and cancel the
  // watch for any branch that left the set — so a still-live land is never torn
  // down and re-fetched.
  useEffect(() => {
    if (!repoId) return;
    for (const [branch, runId] of activeRuns) {
      const existing = subs.current.get(branch);
      if (existing && existing.runId === runId) continue;
      if (existing) existing.cancel();
      const cancel = watchLandRun(repoId, runId, (outcome) => {
        // The run terminated (live/synthetic exit or a broken stream): RELEASE
        // the guard (task 2 — held since the POST so a mid-run re-click was a
        // no-op), clear the spinner, record a failure (with its reason), and drop
        // the branch from the active set (which cancels its now-finished watch on
        // the next reconcile). A retry from here dispatches a fresh run.
        inFlight.current.delete(branch);
        setLanding((s) => without(s, branch));
        if (outcome.failed) {
          setFailed((m) => new Map(m).set(branch, outcome.reason));
        }
        setActiveRuns((m) => withoutKey(m, branch));
      });
      subs.current.set(branch, { runId, cancel });
    }
    for (const [branch, sub] of subs.current) {
      if (!activeRuns.has(branch)) {
        sub.cancel();
        subs.current.delete(branch);
      }
    }
  }, [repoId, activeRuns]);

  // Abort every live subscription on unmount.
  useEffect(() => {
    const live = subs.current;
    return () => {
      for (const sub of live.values()) sub.cancel();
      live.clear();
    };
  }, []);

  const landStateFor = useCallback(
    (row: BoardRow): BoardLandState | undefined => {
      const branch = row.summary.worktree?.branch;
      if (branch === undefined) return undefined;
      if (landing.has(branch)) return 'landing';
      if (failed.has(branch)) return 'error';
      return undefined;
    },
    [landing, failed],
  );

  const landFailureFor = useCallback(
    (row: BoardRow): string | undefined => {
      const branch = row.summary.worktree?.branch;
      if (branch === undefined || landing.has(branch) || !failed.has(branch)) return undefined;
      return failed.get(branch);
    },
    [landing, failed],
  );

  return { landItem, landStateFor, landFailureFor };
}
