/**
 * The worktree-merge island is a content-replacing view keyed by branch
 * (`?island=<branch>`), so routing to a run's worktree from the open run
 * drill-down swaps the `?run=` param for `?island=<branch>`. Pure so the
 * run→worktree routing (WorkerRunIsland's `onOpenWorktree`, wired in
 * RepoDetailPage) is verifiable without rendering the whole page: given the
 * current params, it returns the next set.
 */
export function worktreeIslandParams(
  prev: URLSearchParams,
  branch: string,
): URLSearchParams {
  const next = new URLSearchParams(prev);
  next.delete('run');
  next.set('island', branch);
  return next;
}
