import { useEffect, useState } from 'react';
import { Loader2 } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

/**
 * The shared machinery of the source sheets (FixSourceSheet, PlanSourceSheet)
 * — extracted by the adversarial review of prd-source-not-viewable task 2,
 * which found the fetch-lifecycle state and the loading/error/prose block
 * copied line-for-line (and the copy already drifting).
 */

/**
 * Lazy document fetch while a sheet is open. Refetches whenever `deps` change
 * while open — KEEPING the previous content until the new document arrives,
 * so header chrome derived from it (the plan sheet's frontmatter strip) holds
 * steady instead of unmounting per switch (user: "frontmatter header is
 * reloaded each feature click — this causes judder"); the body swaps to the
 * loading state via the `loading` flag. On close, content/error/loading all
 * drop so a reopen (often for a different document) never flashes the prior
 * markdown before its fetch starts.
 */
export function useLazySourceContent(
  isOpen: boolean,
  fetchDoc: () => Promise<string>,
  deps: readonly unknown[],
): { content: string | null; loading: boolean; error: boolean } {
  const [content, setContent] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!isOpen) {
      setContent(null);
      setLoading(false);
      setError(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(false);
    fetchDoc()
      .then((c) => { if (!cancelled) setContent(c); })
      .catch(() => { if (!cancelled) setError(true); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
    // fetchDoc is a fresh closure every render; the caller names its real
    // inputs via `deps` instead.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, ...deps]);

  return { content, loading, error };
}

export interface SourceSheetBodyProps {
  /** Copy noun for the loading/error lines, e.g. "fix source". */
  noun: string;
  /** data-testid of the rendered prose container. */
  testId: string;
  loading: boolean;
  error: boolean;
  /** The markdown to render, or null when nothing is loaded yet. */
  markdown: string | null;
}

/** The loading / error / rendered-markdown block both source sheets share. */
export function SourceSheetBody({ noun, testId, loading, error, markdown }: SourceSheetBodyProps) {
  if (loading) {
    return (
      <p className="flex items-center gap-2 py-4 text-sm text-muted-foreground">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading {noun}…
      </p>
    );
  }
  if (error) {
    return <p className="py-4 text-sm text-red-600 dark:text-red-400">Failed to load {noun}.</p>;
  }
  if (markdown === null) return null;
  return (
    <div
      data-testid={testId}
      className="panel-flat prose prose-sm max-w-none overflow-auto rounded-xl p-4 dark:prose-invert"
    >
      <ReactMarkdown remarkPlugins={[remarkGfm]}>{markdown}</ReactMarkdown>
    </div>
  );
}
