/**
 * work-item-detail-service-rewrite / props-in-ui (F3a) — the CLIENT reconcile
 * overlay for the validation panel.
 *
 * The reconcile lane + merge boundary are LIVE, client-derived state (from
 * `useDeliveryActions`), so — per the settled reconcile-split — the server derives
 * the panel SANS reconcile ({@link assembleValidationPanel}) and this overlay
 * layers the reconcile lane + colour-coded merge boundary on top. A faithful port
 * of the old fold's `withReconcileLane`: insert a reconcile lane after the
 * work-item lane, un-collapse that lane's receipt (full strip in this surface),
 * ensure a downstream post-merge lane exists, and stamp the merge boundary.
 */

import type { ReconcileStripState, ReconcileTerminal } from './reconcile-strip';
import type {
  MergeBoundaryState,
  ReconcileFailure,
  ValidationChip,
  ValidationLane,
  ValidationPanelState,
  ValidationStepDef,
} from './validation-panel-state';

const RECONCILE_REBASE: ValidationStepDef = { type: 'rebase', label: 'Rebase', emoji: '🔀' };
const RECONCILE_AGENT: ValidationStepDef = { type: 'agent', label: 'Resolve', emoji: '🤖' };
// Verify wears its own icon (🔎), distinct from the regression suite's test-tube
// (🧪) below — a reconcile verify is the rebase-then-check rung, not the full suite.
const RECONCILE_VERIFY: ValidationStepDef = { type: 'verify', label: 'Verify', emoji: '🔎' };
const RECONCILE_SUBTITLE = 'Rebase onto main, then verify';

/** The post-merge lane's sub-line — the approved redesign asset's copy
 *  (validation-panel-step-timeline F6 task 2), the final timeline step's bespoke
 *  subtitle overriding the generic full-scope sentence. Kept in lockstep with the
 *  legacy stories fold's POST_MERGE_SUBTITLE in validation-panel-state.ts. */
const POST_MERGE_SUBTITLE = 'Full suite on main after merge';

/** The pending post-merge lane shown pre-land beside the reconcile lane, so the
 *  merge boundary always has a downstream stage. Once the item lands, the real
 *  main-validation lane replaces it. */
const PENDING_POST_MERGE_LANE: ValidationLane = {
  kind: 'main-validation',
  title: 'Post-merge regression test',
  scope: 'full',
  subtitle: POST_MERGE_SUBTITLE,
  chips: [{ type: 'testing', label: 'Regression', emoji: '🧪', state: 'pending' }],
};

/** The reconcile lane's chips, folded from the live strip state (+ landed). */
function reconcileLaneChips(strip: ReconcileStripState, landed: boolean): readonly ValidationChip[] {
  if (landed) {
    return [
      { ...RECONCILE_REBASE, state: 'passed' },
      { ...RECONCILE_VERIFY, state: 'passed' },
    ];
  }
  if (strip.kind === 'terminal') {
    switch (strip.terminal) {
      case 'ready-to-land':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_VERIFY, state: 'passed' },
        ];
      case 'conflict':
        // A rebase conflict reds the rebase pill (land-failure-surfacing task 5) — a
        // red border/pill on the failed rung, not a warning glyph; the reason section
        // below names why. Verify never ran.
        return [
          { ...RECONCILE_REBASE, state: 'failed' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
      case 'verify-failed':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_VERIFY, state: 'failed' },
        ];
      case 'failed':
        return [
          { ...RECONCILE_REBASE, state: 'failed' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
    }
  }
  if (strip.kind === 'running') {
    switch (strip.phase) {
      case 'replaying':
        return [
          { ...RECONCILE_REBASE, state: 'running' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
      case 'agent':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_AGENT, state: 'running' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
      case 'verifying':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_VERIFY, state: 'running' },
        ];
      case 'queued':
        return [
          { ...RECONCILE_REBASE, state: 'pending' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
    }
  }
  // idle — reconcile not yet entered on a passed work-item (both stages pending).
  return [
    { ...RECONCILE_REBASE, state: 'pending' },
    { ...RECONCILE_VERIFY, state: 'pending' },
  ];
}

/** The named ladder rung behind each failure terminal (task 5). `ready-to-land` is
 *  no failure; running/idle carry no terminal so they attach nothing. */
const FAILURE_RUNG: Record<Exclude<ReconcileTerminal, 'ready-to-land'>, string> = {
  conflict: 'Rebase',
  'verify-failed': 'Verify',
  failed: 'Reconcile',
};

/**
 * The recovery hint per failure terminal. Every failure re-verifies with the SAME
 * `tiny-brain reconcile-branch <branch>` command (it re-runs rebase + verify), so the
 * hint names that action — sensible whether or not the copyable command is shown, and
 * never dangling a "Run it" with nothing to run. Only a CONFLICT points at `/merge`
 * (rerere/recipes/agent could not resolve it); a verify/build failure is fixed in the
 * code, not by `/merge`.
 */
const FAILURE_HINT: Record<Exclude<ReconcileTerminal, 'ready-to-land'>, string> = {
  conflict: 'Reconcile the branch (runs from anywhere); /merge resolves a residual conflict.',
  'verify-failed': 'Fix the build or tests, then reconcile the branch to re-verify.',
  failed: 'Reconcile the branch to re-run.',
};

/**
 * The reconcile lane's FAILURE detail (land-failure-surfacing task 5): map a terminal
 * FAILURE to its failing rung, merge in the reason + conflicting files from the item's
 * `lastReconcile` axis, and attach the copyable re-verify incantation (`tiny-brain
 * reconcile-branch <branch>`, runnable from anywhere) plus a per-terminal hint. A clean
 * / running / idle strip attaches nothing.
 */
function reconcileFailureFor(
  strip: ReconcileStripState,
  detail: ReconcileOverlayInput['failureDetail'],
): ReconcileFailure | undefined {
  if (strip.kind !== 'terminal' || strip.terminal === 'ready-to-land') return undefined;
  // A CATCH-UP conflict (persistent-catch-up-conflict F3): main advanced AFTER this
  // branch was reconciled, so the fresh catch-up rebase re-conflicted. The land
  // catch-up path stamps `exitReason: 'catch-up-conflict'` — the discriminator that
  // separates it from a first-time reconcile conflict — and carries the main SHA it
  // moved to (surface-reconciled-main-sha F1). Its presence drives the "main moved"
  // reason copy in place of the raw exitReason; the SHA rides along when known.
  const mainMoved =
    detail?.reason === 'catch-up-conflict'
      ? { mainMoved: detail?.reconciledAgainst !== undefined ? { toSha: detail.reconciledAgainst } : {} }
      : {};
  return {
    rung: FAILURE_RUNG[strip.terminal],
    ...(detail?.reason !== undefined ? { reason: detail.reason } : {}),
    ...(detail?.conflictedFiles !== undefined && detail.conflictedFiles.length > 0
      ? { conflictedFiles: detail.conflictedFiles }
      : {}),
    // The copyable re-verify command applies to EVERY failure terminal — a conflict, a
    // verify/build red, or a ladder fault all re-run through reconcile-branch. Omitted
    // only when the failing branch is unknown. The structured `branch` is the id the
    // Retry-reconcile button posts (F4) — same branch, carried unparsed.
    ...(detail?.branch !== undefined
      ? { branch: detail.branch, recoveryCommand: `tiny-brain reconcile-branch ${detail.branch}` }
      : {}),
    nextStep: FAILURE_HINT[strip.terminal],
    ...mainMoved,
  };
}

/** The merge boundary colour code folded from the reconcile strip + gates. */
function mergeBoundary(strip: ReconcileStripState, gated: boolean, landed: boolean): MergeBoundaryState {
  if (landed) return 'merged';
  if (gated) return 'blocked';
  if (strip.kind === 'terminal') return strip.terminal === 'ready-to-land' ? 'ready' : 'blocked';
  // idle / running — reconcile has not reached a verdict yet.
  return 'pending';
}

/** The facts the overlay needs beyond the live strip — all payload-derived. */
export interface ReconcileOverlayInput {
  readonly reconcile: ReconcileStripState;
  /** The item is merged onto main. */
  readonly landed: boolean;
  /** The work-item completion suite passed — reconcile is GATED until it does. */
  readonly workItemPassed: boolean;
  /** The repo configures a post-land pipeline — gates the pending post-merge lane. */
  readonly postMergeConfigured: boolean;
  /**
   * The main SHA the item's latest settled reconcile rebased onto (surface-reconciled-
   * main-sha F1) — threaded onto the panel state so the passed footer names the main
   * the item is ready AS OF (provisional-ready-badge-and-footer F2). Absent-safe.
   */
  readonly reconciledAgainst?: string;
  /**
   * The persisted failure detail behind a FAILURE terminal (land-failure-surfacing
   * task 5) — the reason + conflicting files from the item's `lastReconcile` axis.
   * The strip terminal carries the verdict; this carries the WHY + files the lane
   * names below the reconcile row (a `conflict` terminal reconstructs without them).
   * Absent ⇒ no reason/files rendered (the rung + next step still stand).
   */
  readonly failureDetail?: {
    readonly reason?: string;
    readonly conflictedFiles?: readonly string[];
    /** The failing branch — builds the copyable `tiny-brain reconcile-branch <branch>`
     *  re-verify incantation on ANY failure terminal. Absent ⇒ no command shown. */
    readonly branch?: string;
    /**
     * The main SHA the item's latest reconcile settled against (surface-reconciled-main-
     * sha F1). Used ONLY on a `catch-up-conflict` reason to name the main it moved to;
     * a first-time conflict ignores it. Absent-safe.
     */
    readonly reconciledAgainst?: string;
  };
}

export function withReconcileOverlay(base: ValidationPanelState, input: ReconcileOverlayInput): ValidationPanelState {
  if (base.kind !== 'active') return base;
  const { reconcile, landed, workItemPassed, postMergeConfigured } = input;
  const gated = !workItemPassed && !landed;

  // The lane's second-row helper text NARRATES the live ladder rung (land-failure-
  // surfacing task 4): while the reconcile streams, its running label ("Rebasing onto
  // main…" → "Agent resolving…" → "Verifying…") is the subtitle, so the single rebase
  // pill reads its current step instead of a static caption. Idle / terminal keeps the
  // static "Rebase onto main, then verify". A GATED lane (the work-item suite has not
  // passed, so reconcile is NOT-YET-REACHED) always keeps the static caption — it must
  // never narrate a live rung, even on an out-of-order running strip.
  const liveSubtitle = !gated && reconcile.kind === 'running' ? reconcile.label : RECONCILE_SUBTITLE;

  // The FAILURE detail (land-failure-surfacing task 5): a terminal failure attaches
  // the failing rung + reason + files + the copyable re-verify command (plus a
  // per-terminal hint — /merge only on a conflict) to the lane, rendered below the row
  // in the SAME red reason-section pattern a failed completion step uses. Not on a
  // gated lane (reconcile has not been reached).
  const reconcileFailure = gated ? undefined : reconcileFailureFor(reconcile, input.failureDetail);

  // Shared identity — only `subtitle` / `chips` / the `gated` flag differ between the
  // two reconcile-lane shapes. No `scope`: the reconcile subtitle always overrides it.
  const reconcileBase = { kind: 'reconcile' as const, title: 'Reconcile', subtitle: liveSubtitle };
  const reconcileLane: ValidationLane = gated
    ? { ...reconcileBase, gated: true, chips: [] }
    : {
        ...reconcileBase,
        chips: reconcileLaneChips(reconcile, landed),
        ...(reconcileFailure !== undefined ? { reconcileFailure } : {}),
      };

  // Un-collapse the work-item lane (full strip in this surface) and insert the
  // reconcile lane immediately after it.
  const lanes: ValidationLane[] = base.lanes.map((lane) =>
    lane.kind === 'completion' && lane.receipt === true ? { ...lane, receipt: false } : lane,
  );
  const completionIdx = lanes.findIndex((l) => l.kind === 'completion');
  if (completionIdx >= 0) lanes.splice(completionIdx + 1, 0, reconcileLane);
  else lanes.unshift(reconcileLane);

  // The pending post-merge lane previews the post-land regression, so the merge
  // boundary has a downstream stage — but only when the repo configures one and the
  // real main-validation lane is not already present (the landed panel rides that).
  if (postMergeConfigured && !lanes.some((l) => l.kind === 'main-validation')) {
    lanes.push(PENDING_POST_MERGE_LANE);
  }

  return {
    ...base,
    lanes,
    merge: mergeBoundary(reconcile, gated, landed),
    // Thread F1's reconciled-against SHA onto the panel state so the passed footer
    // reads the PROVISIONAL "ready as of main@<sha7>" promise (provisional-ready-badge-
    // and-footer F2). Absent-safe — omitted when no reconcile recorded a tip.
    ...(input.reconciledAgainst !== undefined ? { reconciledAgainst: input.reconciledAgainst } : {}),
  };
}
