import { useEffect, useRef, useState } from 'react';
import type { LandAvailability } from '@magic-ingredients/tiny-brain-core';
import { postDeliveryAction, postLandFeature, type DeliveryActionName } from '../services/api';
import type { TeardownPartSelection } from '../components/WorktreeMergeContent';
import { useRunStream } from './useRunStream';
import { foldRunOutcome, runIdOf } from './run-outcome';
import { deriveRunActivity, type RunPhase } from '../utils/run-activity';
import { deriveReconcileStrip, type ReconcileStripState, type LastReconcileFeed } from '../utils/reconcile-strip';
import { LAND_ALREADY_ON_MAIN_NOTICE } from '../utils/land-notices';

/**
 * delivery-lifecycle-pill-taxonomy F3 — the remediation a failure pill routes to.
 *
 * A failure pill is ACTIONABLE: clicking it takes the operator to the fix, not
 * just names it. The card stays dumb — it computes this INTENT purely from F1's
 * `{ phase, state }` and fires it; the host owns the POST / navigation (the
 * established dumb-UI split). The mapping is table-driven here so no delivery
 * logic leaks into the component.
 *
 *   - `open-runs`          — `run-failed`         → the Runs view (restart / resume the crashed run)
 *   - `open-detail`        — `validation-failed`  → the item detail's ValidationPanel (names the red steps + re-run)
 *   - `dispatch-reconcile` — `reconcile-failed`   → re-run reconcile
 *   - `dispatch-merge`     — `merge-failed`       → the `/merge` hand-off (topology already routes a conflict there)
 *   - `post-merge`         — `post-merge-failed`  → the (future) post-merge pipeline UI — a labelled PLACEHOLDER,
 *                                                   never a dead or misleading click
 */
export type PillRemediationKind =
  | 'open-runs'
  | 'open-detail'
  | 'dispatch-reconcile'
  | 'dispatch-merge'
  | 'post-merge';

export interface PillRemediation {
  readonly kind: PillRemediationKind;
  /** The CTA's accessible name / tooltip — what clicking it does. */
  readonly label: string;
  /**
   * The target is not yet built (`post-merge` only today) — the card renders it
   * INERT-but-labelled, never a dispatchable click. Every deliverable target is
   * `false`.
   */
  readonly placeholder: boolean;
}

/**
 * The orthogonal crashed-run badge always routes to the Runs view — a failed
 * run can co-occur with any phase, so it carries its own fixed remediation
 * rather than riding the phase mapping below.
 */
export const RUN_FAILED_REMEDIATION: PillRemediation = {
  kind: 'open-runs',
  label: 'Open the run to restart it',
  placeholder: false,
};

// The phase→remediation table (formerly `pillRemediation`, reading a
// `DeliveryPill`) was retired with the board card's legacy `row.deliveryPill`
// consumers (fix retire-legacy-deliverypill-from-board-card task 1): the card now
// derives its failure-pill remediation from the shared `row.lifecycle`
// (LifecyclePhase) via `lifecyclePhaseRemediation` in BoardCard.tsx, so no
// production consumer maps a `DeliveryPill` to a remediation any more.

export interface UseDeliveryActionsOptions {
  /** Called after a land/raise/reject/teardown SUCCEEDS — the overlay closes; an
   *  inline pane refetches the git-derived state. For a streamed land/teardown
   *  this fires when the run's terminal exit is `completed`, not on the POST. */
  onSuccess?: () => void;
  /** Title for the raise-PR action (defaults to a branch-derived title). */
  raiseTitle?: string;
  /** Body for the raise-PR action (defaults to a branch-derived body). */
  raiseBody?: string;
  /**
   * This worktree's cleanup is a DISCARD of unmerged work (fix task 14) — send the
   * explicit `discard` opt-in (on BOTH the plain and force teardown paths) so the
   * orchestrator bypasses the landed gate. Set by the parent for an unmerged,
   * non-spike worktree; a landed worktree's cleanup is NOT a discard, so this stays
   * false there. Tied to discard-eligibility, not to whether force happens to be
   * needed, so a cleanup the UI offered is never refused by the gate.
   */
  discardable?: boolean;
  /**
   * The branch's persisted reconcile verdict — the F6 model's availability
   * axis, when the host knows it. The reconcile strip machine reconstructs its
   * terminal state from this on refresh / reconnect (F7 task 2), so a missed
   * terminal frame never strands a spinner.
   */
  landAvailability?: LandAvailability;
  /**
   * The branch's persisted latest verdict + reason (the model's lastReconcile
   * axis) — the strip machine's reconstruction source for the failure family
   * (fix verify-outcomes-invisible-in-ui task 1).
   */
  lastReconcile?: LastReconcileFeed;
  /**
   * The branch's LIVE machinery run the model named (an unended
   * reconcile/land this client did NOT start — e.g. a CLI reconcile). The
   * hook subscribes to its stream so the strip renders it like a Re-check
   * (fix verify-outcomes-invisible-in-ui task 2). A self-started action's
   * stream always wins over this.
   */
  liveReconcileRunId?: string;
}

export interface DeliveryActions {
  busy: boolean;
  landError: boolean;
  /**
   * Why the last land did not complete — the failed run's exit `reason` (for a
   * diverged / conflicting ff-land this carries the refused-land reason + rebase
   * hand-off), or a generic message when the POST itself faulted. Undefined when
   * no land has failed (fix: worktree-ff-land-without-run-record, carried into
   * the streamed-land model). Rendered by WorktreeMergeContent on `landError`.
   */
  landFailure: string | undefined;
  /**
   * A self-started LAND run is IN FLIGHT — its stream is live (subscribed, no
   * terminal exit, not broken). Server-derived off the run, not a client flag,
   * and land-only: a streaming teardown/reconcile lights neither this nor
   * `landed`. Drives the click site's live in-progress surface so a land is
   * never silent between the click and its outcome (fix dashboard-land-silent-
   * and-run-record-lies task 2).
   */
  landing: boolean;
  /**
   * The self-started LAND run reached a COMPLETED exit — the land settled
   * successfully. The POSITIVE terminal signal the click site announces, so a
   * successful land is never a silent settle (a completed land emits no
   * reconcile terminal, so the strip alone went idle and success read as a
   * silent death). Land-only, and mutually exclusive with `landing` — a
   * terminal is not in flight. Gated to a CLEAN merge (a completed exit with no
   * caveat reason): a land that settles `completed` having moved nothing to main
   * (already-delivered / already-landed) must NOT claim a merge — that is the
   * run-record lie this fix kills — so it rides {@link landNotice} instead.
   */
  landed: boolean;
  /**
   * The land's HONEST no-merge terminal message, or undefined. Set when a land
   * settles WITHOUT merging: the streamed already-delivered exit (`completed`
   * with a caveat reason — nothing reached main) or the already-landed POST
   * short-circuit. The click site announces this instead of the false "merged"
   * claim {@link landed} would otherwise imply, so a no-op land is neither a lie
   * nor a silent settle.
   */
  landNotice: string | undefined;
  cleanedUp: boolean;
  teardownError: string | undefined;
  /** Live pipeline phases of the in-flight land/teardown run, in order (empty when idle). */
  phases: RunPhase[];
  /**
   * The active run's concatenated output text (build/test stdout + error lines like
   * `spawn turbo ENOENT`), or undefined when there is none. The strip renders it
   * inline so a failed reconcile shows WHY without leaving the surface — the
   * missing feedback that let a broken verify hide as a blank "reconcile failed".
   */
  runOutput: string | undefined;
  onLand: (method: 'ff-only' | 'merge') => void;
  /**
   * Land ONE prd-scoped feature as a streamed run (fix
   * feature-land-has-no-live-feedback task 2): posts the ids to
   * `/delivery/land-feature`, then folds the returned run EXACTLY as a land —
   * same busy/landError/strip channels, so the PRD detail streams a feature
   * land the way the fix detail streams a whole-item one.
   */
  onLandFeature: (prdId: string, featureId: string, method: 'ff-only' | 'merge') => void;
  onRaise: () => void;
  onReject: (reason: string) => void;
  onTeardown: (selection: TeardownPartSelection) => void;
  onForceTeardown: (selection: TeardownPartSelection) => void;
  // ── The reconcile ladder, re-fronted (work-item-provenance F7 task 2) ───────
  // `onPrepare` (and the `runOutput` reconcile stream) were the backend of the
  // retired StagedLandingControl strip and sat UI-orphaned for a while. The
  // ReconcileStrip's Re-check now fires `onPrepare` on a conflicted branch and
  // the `reconcile` machine below renders the streamed run, settling that debt.
  // `onRestore` remains without a UI entry point (restore is reachable via the
  // server route only).
  /** "Prepare to land" — reconcile the branch onto main as a live run (streamed). Fired
   *  by the strip's Re-check (no arg ⇒ this hook's bound branch) and by the failed-panel
   *  Retry-reconcile action, which passes the branch the panel emitted (retry-reconcile-
   *  action F4) so the named and reconciled branch cannot diverge. */
  onPrepare: (branch?: string) => void;
  /** "Restore pre-rebase" — reset the branch to its pre-reconcile backup (synchronous). No UI entry point today. */
  onRestore: () => void;
  /**
   * The in-flight reconcile run's id WHILE it streams, else undefined — drove the
   * retired strip's live `preparing` state. UI-orphaned; see the note above.
   * Reconcile-only: a streaming land/teardown does not set it.
   */
  reconcileRunId: string | undefined;
  /**
   * The landing strip's reconcile state machine (F7 task 2): the honest running
   * phase while the reconcile streams, the typed terminal the moment its frame
   * arrives, and — with no live stream — the reconstruction from the on-disk
   * result (`opts.landAvailability`). Never a running state off a dead stream.
   */
  reconcile: ReconcileStripState;
}

/**
 * The worktree delivery action wiring, container-agnostic. Each action POSTs to
 * `/delivery/<action>` carrying only the branch as `workItemId` (the dumb-UI
 * rule).
 *
 * `land` and `teardown` are LIVE RUNS (stream-merge-teardown task 3): the POST
 * returns a `runId`, the hook subscribes over {@link useRunStream}, the phases
 * render live, and the outcome is derived from the run's terminal `exit` event —
 * `completed` refetches the git-derived state (onSuccess), `failed` leaves the
 * surface in place with the exit `reason` as the error. (An already-landed land
 * short-circuits to `{ landed: true }` — nothing to stream, refetch straight
 * away.) `raise`/`reject` emit no run events, so they stay synchronous: onSuccess
 * on the 200.
 */
export function useDeliveryActions(
  repoId: string,
  branch: string,
  opts: UseDeliveryActionsOptions = {},
): DeliveryActions {
  const [activeRun, setActiveRun] = useState<{ runId: string; action: 'land' | 'teardown' | 'reconcile' } | null>(null);
  // Sync channels cover the POST itself (a fault before any run starts) and the
  // synchronous raise/reject path; the streamed outcome is folded from the run.
  const [syncBusy, setSyncBusy] = useState(false);
  const [syncLandError, setSyncLandError] = useState(false);
  const [syncTeardownError, setSyncTeardownError] = useState<string | undefined>(undefined);
  // The no-merge note set on the already-landed POST short-circuit (a land that
  // returns `{landed:true}` with no run to stream) — so that path, like the
  // streamed already-delivered exit, tells the user "already on main" instead of
  // resolving to a silent endcap swap.
  const [syncLandNotice, setSyncLandNotice] = useState<string | undefined>(undefined);
  const notifiedRunId = useRef<string | null>(null);

  // The stream to watch: a SELF-started action's run always wins; with none in
  // flight, the model-named live machinery run (a CLI reconcile this client
  // did not start — fix verify-outcomes-invisible-in-ui task 2) is watched so
  // the strip renders it like a Re-check. DELIBERATE: the watch stays pinned
  // to a self run even after its terminal — switching to a foreign run would
  // flush the stream and with it the exit evidence the landError/teardownError
  // channels render (adversarial review of 4f79d6c4a, LOW — pinned in the
  // suite). A foreign run started after a self terminal surfaces on the next
  // mount/refresh cycle, which the terminal's own onSuccess refetch triggers.
  const watchedRunId = activeRun?.runId ?? opts.liveReconcileRunId;
  const { events, error: streamError } = useRunStream(repoId, watchedRunId ?? '');
  const activity = deriveRunActivity(events);
  // The run's terminal, read through the SHARED fold (run-outcome.ts) so the
  // board and this island cannot drift on how a land failure is surfaced. The
  // fold matches the exit to the WATCHED run (useRunStream flushes events on a
  // runId change, so a stale prior-run exit can't leak), takes the LATEST exit,
  // and folds a broken stream (no exit + `error`) in as a terminal failure.
  const outcome = foldRunOutcome(events, watchedRunId, streamError);
  const exit = outcome.exit;
  const streamBroke = outcome.streamBroke;
  // Self liveness (feeds `busy` — a foreign run must never lock this client's
  // buttons) vs foreign liveness (feeds only the strip machine below).
  const streaming = activeRun !== null && exit === undefined && !streamBroke;
  const foreignStreaming = activeRun === null && watchedRunId !== undefined && exit === undefined && !streamBroke;
  // The land run's own live/terminal signals (fix dashboard-land-silent-and-run-
  // record-lies task 2): `landing` while a self LAND streams, `landed` on its
  // completed exit. Land-only — a teardown/reconcile stream moves neither, and
  // the completed exit makes them mutually exclusive (a terminal is not live).
  const landing = activeRun?.action === 'land' && streaming;
  const landCompleted = activeRun?.action === 'land' && exit?.status === 'completed';
  // A CLEAN merge vs a no-op completed land (adversarial MEDIUM): deliverByLand
  // exits `completed` for a real merge (no reason) AND for already-delivered (a
  // caveat reason, nothing moved to main). Keying `landed` off the completed
  // status alone would announce a merge that never happened — the run-record lie
  // this fix kills. A completed exit carrying prose is the deliberate not-a-clean
  // -merge signal (the only completed-with-reason path deliverByLand emits), so
  // the merge claim is gated on a reason-less completed exit; the no-op rides
  // `landNotice`.
  const landed = landCompleted && exit?.reason === undefined;
  const landSettledNoMerge = landCompleted && exit?.reason !== undefined;
  // The honest no-merge message: the already-landed short-circuit (sync) OR a
  // streamed already-delivered exit. Undefined for a clean merge and for every
  // non-land action.
  const landNotice = syncLandNotice ?? (landSettledNoMerge ? LAND_ALREADY_ON_MAIN_NOTICE : undefined);

  // A completed LAND or TEARDOWN refetches the git-derived state exactly once (the
  // outcome is git's to settle — ADR-0017 keeps the exit activity-only, so it
  // triggers the fetch, never settles tracked status). Teardown MUST refetch too:
  // it removed the worktree, so the list has to drop the now-deleted row — else it
  // lingers as a stale, re-cleanable sidebar entry. A failed/broken run leaves the
  // surface up so its error shows. onSuccess never double-fires for a run.
  useEffect(() => {
    if (watchedRunId === undefined || notifiedRunId.current === watchedRunId) return;
    // A run is TERMINAL on its exit, OR when the stream broke before one. A
    // reconcile must refetch on the broken-stream case too: without it the strip
    // clears `preparing` (streaming went false) but never re-derives, stranding it
    // on the stale `prepare` button with no feedback — the exact bug this surface
    // fixes, in the stream-broke corner.
    const terminated = exit !== undefined || streamBroke;
    if (!terminated) return;
    notifiedRunId.current = watchedRunId;
    // A FOREIGN machinery run (CLI reconcile) refetches on any terminal end so
    // its persisted verdict reaches the model-backed reconstruction (task 2).
    if (activeRun === null) {
      opts.onSuccess?.();
      return;
    }
    // A reconcile ("Prepare to land") AND a land refetch on ANY terminal end —
    // the verdict is persisted server-side (a conflicted land writes
    // reconcileOutcome on its record, fix merge-click-bypasses-reconcile-strip),
    // so the refetched model must reach the strip's reconstruction or the
    // on-disk truth never backs the streamed terminal. Teardown alone keeps the
    // completed-only refetch (a failed teardown stays up with its exit reason).
    if (exit?.status === 'completed' || activeRun.action !== 'teardown') opts.onSuccess?.();
  }, [watchedRunId, activeRun, exit, streamBroke, opts]);

  // A run FAILED when its exit is `failed` or its stream broke before any exit;
  // the reason is the exit's, else the stream fault. `activeRun !== null` scopes
  // this to a SELF-started run — a foreign run must never light this client's
  // land/teardown error channels.
  const runFailed = activeRun !== null && outcome.failed;
  const runFailReason = outcome.reason;

  const busy = syncBusy || streaming;
  // The reconcile run to surface as `preparing` — only while it is genuinely
  // streaming (an exited/broken run drops back to the refetched server state).
  const reconcileRunId = activeRun?.action === 'reconcile' && streaming ? activeRun.runId : undefined;
  // The strip machine folds a reconcile OR a land run's stream — the merge
  // click drives the same ladder as Re-check (fix merge-click-bypasses-
  // reconcile-strip task 3): the land emits the typed F7 frames, and the
  // machine's core guard filters its private transcript phases. A teardown's
  // vocabulary stays foreign and never moves it. With no live stream the
  // machine reconstructs from the on-disk verdict.
  const stripActive = activeRun?.action === 'reconcile' || activeRun?.action === 'land';
  // A watched FOREIGN machinery run also drives the machine (task 2) — it IS a
  // reconcile/land stream, just not one this client started.
  const machineActive = stripActive || (activeRun === null && watchedRunId !== undefined);
  const reconcile = deriveReconcileStrip({
    events: machineActive ? events : [],
    streaming: (stripActive && streaming) || foreignStreaming,
    ...(opts.landAvailability !== undefined ? { onDisk: opts.landAvailability } : {}),
    ...(opts.lastReconcile !== undefined ? { lastReconcile: opts.lastReconcile } : {}),
  });
  // A land whose OWN STREAM settled a typed terminal is owned by the strip —
  // that surface (label, Re-check, hand-off) replaces the raw free-text banner,
  // and owning EVERY streamed terminal (not just conflict) means a future land
  // vocabulary growth can never double-surface. Today a land emits exactly one
  // terminal, `conflict` (pinned by deliver-land's typed-frame tests). The
  // source gate is the correctness edge (adversarial MEDIUM): a DISK-
  // reconstructed terminal is the branch's standing verdict, not this run's
  // conclusion — a land that faults under a stale on-disk `conflicts` keeps
  // its real error on the banner channel.
  const stripOwnsLandOutcome =
    activeRun?.action === 'land' && reconcile.kind === 'terminal' && reconcile.source === 'stream';
  const landError = syncLandError || (activeRun?.action === 'land' && runFailed && !stripOwnsLandOutcome);
  // The reason surfaced beneath a failed land, mirroring teardownError: the
  // streamed exit's reason (a diverged ff-land carries reason + rebase hint),
  // falling back to a generic message when the POST faulted before any run.
  const landFailure = landError
    ? runFailReason || 'Land could not complete — see the server log.'
    : undefined;
  const cleanedUp = activeRun?.action === 'teardown' && exit?.status === 'completed';
  const teardownError =
    syncTeardownError ??
    (activeRun?.action === 'teardown' && runFailed ? runFailReason || 'Clean up failed — see the server log.' : undefined);

  // Reset every channel on a fresh action — this hook is shared across the land
  // and teardown surfaces, so a stale error / prior run must not survive.
  const resetChannels = () => {
    notifiedRunId.current = null;
    setActiveRun(null);
    setSyncLandError(false);
    setSyncTeardownError(undefined);
    setSyncLandNotice(undefined);
  };

  // A streamed action (land/teardown): POST, then subscribe to the returned
  // run. The poster is a thunk so a differently-shaped POST (the per-feature
  // land, which carries ids rather than a branch workItemId) folds through the
  // same channels as the branch-keyed actions.
  const startRun = async (action: 'land' | 'teardown' | 'reconcile', post: () => Promise<unknown>) => {
    resetChannels();
    setSyncBusy(true);
    try {
      const runId = runIdOf(await post());
      setSyncBusy(false);
      if (runId) {
        setActiveRun({ runId, action });
      } else {
        // Short-circuit (already-landed / nothing to stream) — refetch straight
        // away. A land that short-circuits is already on main: say so, so the
        // click is not silent while the surface refetches to Already merged.
        if (action === 'land') setSyncLandNotice(LAND_ALREADY_ON_MAIN_NOTICE);
        opts.onSuccess?.();
      }
    } catch {
      // The POST itself faulted before a run started — surface it on the action's
      // own channel and clear busy so the user can retry. Server already logged it.
      setSyncBusy(false);
      if (action === 'land') setSyncLandError(true);
      else if (action === 'teardown') setSyncTeardownError('Clean up failed — see the server log.');
      // reconcile: no dedicated error channel — the Prepare button re-enables for retry.
    }
  };

  // A synchronous action (raise/reject): no run events, close on the 200.
  const runSync = async (action: DeliveryActionName, body: Record<string, unknown>) => {
    resetChannels();
    setSyncBusy(true);
    try {
      await postDeliveryAction(repoId, action, { workItemId: branch, ...body });
      setSyncBusy(false);
      opts.onSuccess?.();
    } catch {
      setSyncBusy(false);
      setSyncLandError(true);
    }
  };

  const teardownBody = (selection: TeardownPartSelection, force: boolean, discard?: boolean): Record<string, unknown> => ({
    ...(selection.worktree ? { worktree: true } : {}),
    ...(selection.branch ? { branch: true } : {}),
    ...(selection.runIds.length > 0 ? { runIds: selection.runIds } : {}),
    ...(force ? { force: true } : {}),
    ...(discard ? { discard: true } : {}),
  });

  const raiseTitle = opts.raiseTitle ?? `Deliver ${branch}`;
  const raiseBody = opts.raiseBody ?? `Deliver ${branch}`;

  return {
    busy,
    landError,
    landFailure,
    landing,
    landed,
    landNotice,
    cleanedUp,
    teardownError,
    phases: activity.phases,
    // Trimmed gate — whitespace-only output is "nothing to show" (the strip's
    // RunOutputLog trims the same way, so the two never disagree).
    runOutput: activity.output.trim().length > 0 ? activity.output : undefined,
    onLand: (method) => startRun('land', () => postDeliveryAction(repoId, 'land', { workItemId: branch, method })),
    // The per-feature land rides the SAME land fold — only the POST differs.
    onLandFeature: (prdId, featureId, method) =>
      startRun('land', () => postLandFeature(repoId, prdId, featureId, method)),
    onRaise: () => runSync('raise', { title: raiseTitle, body: raiseBody }),
    onReject: (reason) => runSync('reject', { reason }),
    onTeardown: (selection) =>
      startRun('teardown', () =>
        postDeliveryAction(repoId, 'teardown', { workItemId: branch, ...teardownBody(selection, false, opts.discardable) }),
      ),
    onForceTeardown: (selection) =>
      startRun('teardown', () =>
        postDeliveryAction(repoId, 'teardown', { workItemId: branch, ...teardownBody(selection, true, opts.discardable) }),
      ),
    onPrepare: (overrideBranch?: string) => {
      // Retry-reconcile (F4) posts the branch the panel EMITTED — the same failing
      // branch the button showed the user — so the id the UI names and the id the
      // POST reconciles cannot diverge. The strip's Re-check fires with no override
      // and reconciles this hook's bound branch.
      const target = overrideBranch ?? branch;
      return startRun('reconcile', () => postDeliveryAction(repoId, 'reconcile', { workItemId: target, branch: target }));
    },
    onRestore: () => runSync('restore', { branch }),
    reconcileRunId,
    reconcile,
  };
}
