import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet';
import { fetchFixContent } from '../services/api';
import { useLazySourceContent, SourceSheetBody } from './source-sheet-content';

export interface FixSourceSheetProps {
  repoId: string;
  fixId: string;
  isOpen: boolean;
  onClose: () => void;
}

/**
 * Right-side slide-over showing a fix's raw markdown source — the view the
 * Tasks/Details tabs used to host, relocated behind the detail header's
 * "View source" action so it no longer competes with the single-column layout.
 * Content is fetched lazily the first time (and whenever) the sheet opens;
 * the fetch lifecycle and prose block are the shared source-sheet machinery.
 */
export const FixSourceSheet: React.FC<FixSourceSheetProps> = ({ repoId, fixId, isOpen, onClose }) => {
  const { content, loading, error } = useLazySourceContent(
    isOpen,
    () => fetchFixContent(repoId, fixId),
    [repoId, fixId],
  );

  return (
    <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="flex w-[640px] flex-col sm:max-w-[640px]">
        <SheetHeader>
          <SheetTitle className="display">Fix source</SheetTitle>
          <SheetDescription className="mono truncate text-xs">{fixId}</SheetDescription>
        </SheetHeader>
        <div className="min-h-0 flex-1 overflow-auto px-4 pb-4">
          <SourceSheetBody
            noun="fix source"
            testId="fix-source"
            loading={loading}
            error={error}
            markdown={content}
          />
        </div>
      </SheetContent>
    </Sheet>
  );
};

export default FixSourceSheet;
