import { useCallback, useRef } from 'react';

/**
 * Persist resizable-panel-group sizes across reloads, keyed per group.
 *
 * `react-resizable-panels` resets to each panel's `defaultSize` on every mount.
 * This hook mirrors the group's layout to localStorage on drag and hands back
 * the stored sizes as the defaults on the next mount, so a dragged splitter
 * survives a reload. Sizes are view-local layout — they live in localStorage,
 * never the URL.
 *
 * Why not the library's built-in `autoSaveId`? It persists via a ResizeObserver
 * measurement, and our jsdom test setup mocks ResizeObserver as a no-op — so
 * `autoSaveId` never measures, never persists, and is untestable here (verified:
 * it writes nothing on mount under our suite). This explicit hook keeps the
 * read/write/rehydrate/fallback logic in plain, unit-testable code.
 *
 * Wire it into a group as:
 *   const panels = usePanelSizeMemory('worktrees');
 *   <ResizablePanelGroup onLayout={panels.onLayout}>
 *     <ResizablePanel defaultSize={panels.defaultSize(0, 30)} .../>
 *     <ResizablePanel defaultSize={panels.defaultSize(1, 70)} .../>
 */
export function usePanelSizeMemory(groupId: string): {
  onLayout: (sizes: number[]) => void;
  defaultSize: (index: number, fallback: number) => number;
} {
  const storageKey = `tiny-brain:panel-sizes:${groupId}`;

  // Read once per mount: the stored layout is the starting point; later drags
  // update storage but should not retroactively change this mount's defaults.
  const storedRef = useRef<number[] | null>(null);
  if (storedRef.current === null) {
    storedRef.current = readSizes(storageKey);
  }

  const onLayout = useCallback(
    (sizes: number[]) => {
      try {
        window.localStorage.setItem(storageKey, JSON.stringify(sizes));
      } catch {
        // Storage unavailable (private mode / quota) — sizes just won't persist.
      }
    },
    [storageKey],
  );

  const defaultSize = useCallback((index: number, fallback: number): number => {
    const stored = storedRef.current;
    const value = stored?.[index];
    return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
  }, []);

  return { onLayout, defaultSize };
}

function readSizes(storageKey: string): number[] {
  try {
    const raw = window.localStorage.getItem(storageKey);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.every((n) => typeof n === 'number') ? parsed : [];
  } catch {
    return [];
  }
}
