import React, { useState } from 'react';
import { AlertTriangle, Bot, Cloud, HardDrive, Lock, RefreshCw, Trash2 } from 'lucide-react';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '../ui/alert-dialog';
import { Button } from '../ui/button';
import { FieldLabel } from '../ui/field-label';
import {
  useWorkerFormOptions,
  useWorkers,
  type CreateWorkerInput,
  type WorkerProbeView,
  type WorkerView,
} from '../../hooks/useWorkers';
import { useEnvironments } from '../../hooks/useEnvironments';
import {
  useModels,
  type CustomModelView,
  type ModelMutationResult,
} from '../../hooks/useModels';

/**
 * Shared worker CRUD surface (workers PRD).
 *
 * The global /workers page and the repo Settings › Workers section render
 * the same table + draft panel — only the API root differs (user-scope
 * `/api/workers` vs repo-scoped `/api/repos/:repoId/workers`). These are
 * the presentational pieces both mount:
 *
 * - `WorkerRow` — one click-to-edit table row, badging a dangling
 *   environment (repo-scoped rows only) rather than hiding it.
 * - `WorkerDraftPanel` — the always-visible create/edit panel.
 * - `WorkerCrudBody` — the table + panel + edit wiring, given the data and
 *   handlers a `useWorkers(basePath)` feed provides.
 *
 * The container (page or section) owns the hook + its own chrome; this
 * module owns the surface itself.
 */

/**
 * Container glue for a `WorkerCrudBody`: one `useWorkers(basePath)` feed, the
 * global environment registry (environments stay global-only in the UI —
 * ADR-0024), and the editing selection — including the delete-clears-edit
 * invariant — bundled so the global /workers page and the repo Settings
 * section share the wiring, not just the presentational body. The container
 * spreads `body` into `WorkerCrudBody` and drives its chrome from `reload` /
 * `error` / `loading` / `newWorker`.
 */
export function useWorkerCrud(basePath: string = '/api/workers') {
  const { workers, probes, loading, error, create, update, remove, probe, reload } =
    useWorkers(basePath);
  const { environments } = useEnvironments();
  const [editingWorker, setEditingWorker] = useState<WorkerView | undefined>(undefined);
  const registry = useModels(basePath);
  // Bumped after a model is added or removed, so the draft panel refetches
  // its form options and the Model dropdown reflects the change in place.
  const [formOptionsKey, setFormOptionsKey] = useState(0);
  const refreshOptionsOnSuccess = async (
    pending: Promise<ModelMutationResult>,
  ): Promise<ModelMutationResult> => {
    const result = await pending;
    if (result.ok) setFormOptionsKey((key) => key + 1);
    return result;
  };

  // Props for the scope's ModelsPanel — the container decides where it sits.
  const modelsPanel = {
    models: registry.models,
    providers: registry.providers,
    loading: registry.loading,
    error: registry.error,
    onAdd: (model: CustomModelView) => refreshOptionsOnSuccess(registry.add(model)),
    onRemove: (id: string) => refreshOptionsOnSuccess(registry.remove(id)),
    onRetry: () => void registry.reload(),
  };

  const body = {
    basePath,
    formOptionsKey,
    workers,
    probes,
    loading,
    environmentNames: environments.map(({ name, provider }) => ({ name, provider })),
    editingWorker,
    onEdit: setEditingWorker,
    onProbe: (uuid: string) => void probe(uuid),
    onCreate: create,
    onUpdate: update,
    // Deleting the worker being edited must not leave the panel patching a
    // ghost — drop back to create mode first.
    onDelete: (uuid: string) => {
      setEditingWorker(undefined);
      void remove(uuid);
    },
  };

  // `newWorker` is the manual way out of edit mode (the global page's header
  // button); the rest drives the container's own chrome.
  return {
    body,
    modelsPanel,
    error,
    loading,
    reload,
    newWorker: () => setEditingWorker(undefined),
  };
}

/** The manual probe cell: unchecked until the user asks. */
const ProbeStatus: React.FC<{ probe?: WorkerProbeView }> = ({ probe }) => {
  if (probe === undefined) {
    return <span className="text-xs text-muted-foreground">Not checked</span>;
  }
  if (probe.ok) {
    return <span className="text-xs text-[var(--ds-done)]">Ready</span>;
  }
  return (
    <span className="min-w-0 truncate text-xs text-[var(--ds-warn,orange)]" title={probe.reason}>
      {probe.reason ?? 'Probe failed'}
    </span>
  );
};

/**
 * One table row per worker. The whole row is the edit affordance — click
 * it to load the worker into the draft panel; there is no edit glyph
 * (fix worker-env-pages-table-and-click-to-edit). Re-check and Delete stop
 * propagation so they never double as an edit click.
 *
 * A committed worker may reference an environment a teammate hasn't
 * configured (repo scope); `worker.danglingEnvironment` badges that row
 * rather than hiding it, matching the launch menu's exclusion.
 */
export const WorkerRow: React.FC<{
  worker: WorkerView;
  probe?: WorkerProbeView;
  onProbe: (uuid: string) => void;
  onEdit: (worker: WorkerView) => void;
}> = ({ worker, probe, onProbe, onEdit }) => {
  const EnvIcon = worker.environment === 'local' ? HardDrive : Cloud;
  return (
    <div
      role="button"
      tabIndex={0}
      aria-label={`Edit ${worker.name}`}
      onClick={() => onEdit(worker)}
      onKeyDown={(e) => {
        // Only keys pressed ON the row edit — keydowns bubbling from the
        // nested Re-check/Delete buttons must not double as an edit.
        if (e.target !== e.currentTarget) return;
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onEdit(worker);
        }
      }}
      className="grid cursor-pointer grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)_minmax(0,0.7fr)_minmax(0,1fr)_10rem] items-center gap-3 rounded-lg border-b border-[var(--ds-border)] py-3 last:border-b-0 hover:bg-[color-mix(in_oklab,var(--ds-fg)_4%,transparent)]"
    >
      <div className="flex min-w-0 items-center gap-2.5">
        <Bot className="h-4 w-4 shrink-0 text-muted-foreground" />
        <span className="truncate text-sm font-semibold">{worker.name}</span>
      </div>
      <span className="truncate font-mono text-xs text-muted-foreground">{worker.model}</span>
      <span className="eyebrow rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_7%,transparent)] px-2 py-0.5 text-[10px] justify-self-start">
        {worker.effort}
      </span>
      <span className="inline-flex min-w-0 items-center gap-1.5 truncate font-mono text-xs text-muted-foreground">
        <EnvIcon className="h-3 w-3 shrink-0" />
        <span className="truncate">{worker.environment}</span>
        {worker.danglingEnvironment && (
          <span
            className="inline-flex shrink-0 items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-warn,orange)_15%,transparent)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--ds-warn,orange)]"
            title="This environment isn't configured on this machine — the worker can't launch until it is."
          >
            <AlertTriangle className="h-2.5 w-2.5" />
            Environment missing
          </span>
        )}
      </span>
      <div className="flex w-full min-w-0 items-center justify-end gap-2">
        <ProbeStatus probe={probe} />
        <Button
          variant="ghost"
          size="sm"
          className="shrink-0"
          aria-label={`Re-check ${worker.name}`}
          onClick={(e) => {
            e.stopPropagation();
            onProbe(worker.uuid);
          }}
        >
          <RefreshCw className="h-3.5 w-3.5" />
        </Button>
      </div>
    </div>
  );
};

/**
 * The always-visible draft panel (workers-page.html keeps it in the fixed
 * right-hand column). One panel serves both CREATE and EDIT: pass a `worker`
 * to edit it — every field prefills and the CTA becomes Save. Environment
 * options come from /api/environments; the model is gated server-side.
 *
 * The name is EDITABLE in edit mode: the store is keyed by the worker's uuid
 * (ADR-0027), so a rename is a plain field patch on the same PUT — no re-key.
 */
export const WorkerDraftPanel: React.FC<{
  worker?: WorkerView;
  environmentNames: { name: string; provider: string }[];
  // The scope the form options resolve against (custom models differ per
  // scope), and a key whose bump refetches them.
  basePath?: string;
  formOptionsKey?: number;
  onCreate: (input: CreateWorkerInput) => Promise<{ ok: boolean; error?: string }>;
  onUpdate: (
    uuid: string,
    input: Partial<CreateWorkerInput>,
  ) => Promise<{ ok: boolean; error?: string }>;
  // Leave edit mode — the page clears its editing selection. Called after a
  // successful save; the page's New worker header button is the manual way
  // out (the footer has no Cancel). A create-only host passes a no-op.
  onExitEdit: () => void;
  // Delete the edited worker — the destructive action lives HERE, not on the
  // table row (fix: env-edit-keys-and-table-nits task 2).
  onDelete: (uuid: string) => void;
}> = ({
  worker,
  environmentNames,
  basePath,
  formOptionsKey,
  onCreate,
  onUpdate,
  onExitEdit,
  onDelete,
}) => {
  const editing = worker !== undefined;
  const [name, setName] = useState(worker?.name ?? '');
  const [environment, setEnvironment] = useState(worker?.environment ?? '');
  const [adapter, setAdapter] = useState(worker?.adapter ?? '');
  const [model, setModel] = useState(worker?.model ?? '');
  const [effort, setEffort] = useState<WorkerView['effort']>(worker?.effort ?? 'medium');
  const [error, setError] = useState<string | null>(null);
  const [confirmingDelete, setConfirmingDelete] = useState(false);

  // Re-seed when the edited worker changes — the natural way to drive edit
  // from a list is to swap this prop (select A, then B). useState initializers
  // run only on mount, so without this the panel would keep A's fields and PUT
  // against A. React's supported "reset on prop change" pattern: key on the
  // worker identity held in state and reset in-render when it changes.
  // Key the re-seed on the uuid, not the name — the name is now editable, so
  // keying on it would reset the form mid-rename (ADR-0027).
  const identity = worker?.uuid;
  const [seededFor, setSeededFor] = useState(identity);
  if (identity !== seededFor) {
    setSeededFor(identity);
    setName(worker?.name ?? '');
    setEnvironment(worker?.environment ?? '');
    setAdapter(worker?.adapter ?? '');
    setModel(worker?.model ?? '');
    setEffort(worker?.effort ?? 'medium');
    setError(null);
    setConfirmingDelete(false);
  }

  // `environment` seeds from '' when the form mounts before the
  // environments fetch resolves — resolve everything environment-shaped
  // through the first listed environment, never a hardcoded name. The
  // agent resolves the same way against the server-gated options (the agent
  // list is env-stable — keys only lock a group, never drop the agent — so a
  // stored agent is always present); a stale pick falls back rather than
  // POSTing an incoherent triple.
  const effectiveEnvironment = environment || (environmentNames[0]?.name ?? '');
  const { agents } = useWorkerFormOptions(effectiveEnvironment, basePath, formOptionsKey);
  const effectiveAgent = agents.some((a) => a.agent === adapter)
    ? adapter
    : (agents[0]?.agent ?? '');
  const groups = agents.find((a) => a.agent === effectiveAgent)?.groups ?? [];
  const selectableModels = groups.filter((g) => g.enabled).flatMap((g) => g.models);
  // In EDIT mode, keep the worker's stored model even when the environment no
  // longer offers it (its provider key was removed → the group locked). Falling
  // back to the first selectable model would silently rewrite a field the user
  // never touched while saving an unrelated change; preserving it means the
  // server returns a clear 400 instead. Create still falls back to a coherent
  // default.
  const preservedModel =
    editing && model !== '' && !selectableModels.includes(model) ? model : undefined;
  const effectiveModel = selectableModels.includes(model)
    ? model
    : (preservedModel ?? selectableModels[0] ?? '');
  const lockedGroups = groups.filter((g) => !g.enabled);

  const save = async () => {
    // Edit keys on the worker's uuid (the route) and sends the (possibly
    // renamed) name in the body — a rename is a plain field patch (ADR-0027).
    // Create sends the full triple. Either way the server owns validation.
    const result =
      worker !== undefined
        ? await onUpdate(worker.uuid, {
            name: name.trim(),
            adapter: effectiveAgent,
            environment: effectiveEnvironment,
            model: effectiveModel,
            effort,
          })
        : await onCreate({
            name: name.trim(),
            adapter: effectiveAgent,
            environment: effectiveEnvironment,
            model: effectiveModel,
            effort,
          });
    if (result.ok) {
      setError(null);
      if (worker === undefined) {
        // Create clears its fields for the next worker.
        setName('');
        setModel('');
      } else {
        // A saved edit exits back to create mode — the refreshed row now
        // shows the new values, so there's nothing left to edit here.
        onExitEdit();
      }
    } else {
      setError(result.error ?? 'Failed to save worker');
    }
  };

  const field =
    'w-full rounded-md border border-[var(--ds-border)] bg-transparent px-2 py-1.5 text-sm';

  return (
    <aside
      aria-label={editing ? 'Edit worker' : 'New worker'}
      className="panel h-fit rounded-2xl p-5"
    >
      <h2 className="text-sm font-semibold">{editing ? 'Edit worker' : 'New worker'}</h2>
      <div className="mt-3 grid gap-3">
        {/* Mandatory only where the user can actually type it; defaulted
            selects (Agent / Model / Environment) are intentionally unmarked —
            they always hold a valid value the user cannot empty. */}
        <FieldLabel label="Name" required subtitle="How you'll refer to this worker when dispatching runs.">
          {/* Editable in both create and edit: the worker is keyed by its uuid
              (ADR-0027), so a rename is a plain field patch, not a re-key. */}
          <input
            className={field}
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
        </FieldLabel>
        <label className="text-xs">
          <span className="text-muted-foreground">Environment</span>
          <select
            className={field}
            value={effectiveEnvironment}
            onChange={(e) => setEnvironment(e.target.value)}
          >
            {environmentNames.map((env) => (
              <option key={env.name} value={env.name}>
                {env.name === env.provider ? env.name : `${env.name} · ${env.provider}`}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs">
          <span className="text-muted-foreground">Agent</span>
          <select
            className={field}
            value={effectiveAgent}
            onChange={(e) => setAdapter(e.target.value)}
          >
            {agents.map((agent) => (
              <option key={agent.agent} value={agent.agent}>
                {agent.agentLabel}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs">
          <span className="text-muted-foreground">Model</span>
          <select
            className={field}
            value={effectiveModel}
            onChange={(e) => setModel(e.target.value)}
          >
            {/* The stored model is no longer offered by this environment (its
                provider lost its key, or it is a retired built-in) — show it so
                the field isn't silently rewritten. */}
            {preservedModel !== undefined && (
              <option value={preservedModel}>{preservedModel} (current)</option>
            )}
            {groups.map((group) => (
              <optgroup
                key={group.provider}
                label={
                  group.enabled ? group.providerLabel : `${group.providerLabel} — no key`
                }
              >
                {/* A native <option> carries text only, so a user-declared
                    model is marked by suffix; its value stays the bare id. */}
                {group.models.map((m) => (
                  <option key={m} value={m} disabled={!group.enabled}>
                    {group.customModels.includes(m) ? `${m} · custom` : m}
                  </option>
                ))}
              </optgroup>
            ))}
          </select>
        </label>
        {lockedGroups.length > 0 && (
          <p className="flex items-start gap-1.5 text-xs text-muted-foreground">
            <Lock className="mt-0.5 h-3 w-3 shrink-0" />
            <span>
              {lockedGroups.map((g) => g.providerLabel).join(', ')} models are locked — add a
              key in <span className="font-mono">{effectiveEnvironment}</span> on the
              Environments page to unlock them.
            </span>
          </p>
        )}
        <div className="text-xs">
          <span className="text-muted-foreground">Effort</span>
          <div className="mt-1 flex gap-0.5 rounded-xl border border-[var(--ds-border)] p-1">
            {(['low', 'medium', 'high'] as const).map((level) => (
              <button
                key={level}
                type="button"
                className={`flex-1 rounded-lg px-3 py-1.5 ${
                  effort === level
                    ? 'bg-[color-mix(in_oklab,var(--ds-fg)_6%,transparent)] font-semibold'
                    : 'text-muted-foreground'
                }`}
                onClick={() => setEffort(level)}
              >
                {level.charAt(0).toUpperCase() + level.slice(1)}
              </button>
            ))}
          </div>
        </div>
      </div>
      {error && <p className="mt-2 text-xs text-red-500">{error}</p>}
      <div className="mt-4 flex gap-2">
        {editing && (
          <Button
            variant="ghost"
            size="sm"
            className="shrink-0 text-red-500 hover:bg-red-500/10 hover:text-red-500"
            aria-label={`Delete ${worker.name}`}
            onClick={() => setConfirmingDelete(true)}
          >
            <Trash2 className="mr-1.5 h-3.5 w-3.5" />
            Delete
          </Button>
        )}

        <Button
          size="sm"
          className={editing ? 'ml-auto shrink-0' : 'min-w-0 flex-1'}
          onClick={() => void save()}
          // Empty pieces mean a fetch failed or nothing is selectable —
          // a POST/PUT with a hole would just 400. The name gates both create
          // and edit now that it is editable (ADR-0027) — an empty rename is
          // rejected server-side, so block it here.
          disabled={
            name.trim().length === 0 ||
            effectiveModel === '' ||
            effectiveAgent === '' ||
            effectiveEnvironment === ''
          }
        >
          {editing ? 'Save changes' : 'Create worker'}
        </Button>
      </div>
      {/* Confirmation gate — one stray click destroys nothing (task 4);
          the trigger lives left-aligned in the footer row (task 7). */}
      {editing && (
        <>
          <AlertDialog
            open={confirmingDelete}
            onOpenChange={(open) => {
              if (!open) setConfirmingDelete(false);
            }}
          >
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>Delete worker</AlertDialogTitle>
                <AlertDialogDescription>
                  Delete &quot;{worker.name}&quot;? Runs it already made keep their history;
                  the worker just stops being dispatchable.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Cancel</AlertDialogCancel>
                <AlertDialogAction
                  onClick={() => {
                    setConfirmingDelete(false);
                    onDelete(worker.uuid);
                  }}
                >
                  Delete
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </>
      )}
    </aside>
  );
};

/**
 * The shared table + draft-panel surface. The container supplies the data
 * and handlers from its own `useWorkers(basePath)` feed (and owns the
 * editing selection), so this stays a pure presentation of the worker list
 * beside the create/edit panel — identical on the global page and the repo
 * Settings section.
 */
export const WorkerCrudBody: React.FC<{
  basePath?: string;
  formOptionsKey?: number;
  workers: WorkerView[];
  probes: Record<string, WorkerProbeView>;
  loading: boolean;
  environmentNames: { name: string; provider: string }[];
  editingWorker?: WorkerView;
  onEdit: (worker: WorkerView | undefined) => void;
  onProbe: (uuid: string) => void;
  onCreate: (input: CreateWorkerInput) => Promise<{ ok: boolean; error?: string }>;
  onUpdate: (
    uuid: string,
    input: Partial<CreateWorkerInput>,
  ) => Promise<{ ok: boolean; error?: string }>;
  onDelete: (uuid: string) => void;
  emptyHint: React.ReactNode;
  // Rendered in the list column under the worker table (the Workers page puts
  // its models panel here, as the mockup does).
  belowList?: React.ReactNode;
}> = ({
  basePath,
  formOptionsKey,
  workers,
  probes,
  loading,
  environmentNames,
  editingWorker,
  onEdit,
  onProbe,
  onCreate,
  onUpdate,
  onDelete,
  emptyHint,
  belowList,
}) => (
  // Panel stacks below the table until xl so column 1 (the worker list)
  // keeps full width on normal laptop widths — the 360px draft panel was
  // squeezing the mono name/model into an unreadable truncation.
  <div className="mt-6 grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
    <div className="min-w-0 space-y-4">
      <div className="panel h-fit min-w-0 rounded-2xl p-4">
        <div className="grid grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)_minmax(0,0.7fr)_minmax(0,1fr)_10rem] gap-3 pb-2 eyebrow text-[10px] text-muted-foreground">
          <span>Worker</span>
          <span>Model</span>
          <span>Effort</span>
          <span>Environment</span>
          <span />
        </div>
        {!loading && workers.length === 0 && (
          <p className="py-3 text-sm text-muted-foreground">{emptyHint}</p>
        )}
        {workers.map((worker) => (
          <WorkerRow
            key={worker.uuid}
            worker={worker}
            probe={probes[worker.uuid]}
            onProbe={onProbe}
            onEdit={onEdit}
          />
        ))}
      </div>
      {belowList}
    </div>
    {/* One shared panel: a clicked-row worker drives edit mode, else it
        creates. The panel re-seeds in-render when this worker prop changes,
        so switching rows resets the form without a remount — and skips a
        form-options refetch when the new worker shares the environment. */}
    <WorkerDraftPanel
      worker={editingWorker}
      environmentNames={environmentNames}
      basePath={basePath}
      formOptionsKey={formOptionsKey}
      onCreate={onCreate}
      onUpdate={onUpdate}
      onExitEdit={() => onEdit(undefined)}
      onDelete={onDelete}
    />
  </div>
);
