import React, { createContext, useContext } from 'react';
import { createPortal } from 'react-dom';

/**
 * Top-rail actions slot (fix: env-edit-keys-and-table-nits task 11). Pages
 * declare their header actions (New environment, Reload, …) with
 * `<HeaderActions>…</HeaderActions>`; when the app chrome has mounted its
 * host element the children PORTAL into the top rail, and when there is no
 * host they render inline where declared — the affordances never vanish.
 * No-host cases are real, not just unit tests: the repo-detail chrome
 * intentionally carries no actions slot (its rail is the breadcrumb +
 * RepoViewControls), so a repo-scoped page using HeaderActions renders its
 * actions in the page body. Portal, not state-lifting, so no render-loop
 * bookkeeping; the first mount renders inline for one commit until the
 * ref-driven host state lands — paint-invisible for buttons.
 */
const HeaderActionsHostContext = createContext<HTMLElement | null>(null);

export const HeaderActionsHostProvider = HeaderActionsHostContext.Provider;

export const HeaderActions: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const host = useContext(HeaderActionsHostContext);
  if (host === null) return <>{children}</>;
  return createPortal(children, host);
};
