import React from 'react';
import type { Instrument } from '../utils/quality-instruments';
import type { TrendColour } from '../utils/instrument-trend';
import { TREND_COLOR, type DotState } from '../utils/instrument-palette';

/** How a run-over-run change reads once classified by the keep-low invariant:
 *  a falling lower-better metric is improving, a rising one regressing. */
const MOVER_WORD: Record<TrendColour, string> = {
  good: 'improving',
  bad: 'regressing',
  neutral: 'flat',
};

/** Trend text-colour utility (globals.css) by the keep-low invariant. */
const TREND_TEXT: Record<TrendColour, string> = {
  good: 't-good',
  bad: 't-bad',
  neutral: 't-flat',
};

const SPARK_W = 72;
const SPARK_H = 24;
const SPARK_PAD = 3;

/** The status-dot utility classes (globals.css) for a given risk state. */
const dotClass = (state: DotState): string => `dot d-${state}`;

/** Map a series to a polyline `points` string within the sparkline viewbox. */
function sparklinePoints(series: ReadonlyArray<number>): string {
  if (series.length < 2) return '';
  const min = Math.min(...series);
  const max = Math.max(...series);
  const range = max - min || 1;
  const usableW = SPARK_W - SPARK_PAD * 2;
  const usableH = SPARK_H - SPARK_PAD * 2;
  return series
    .map((v, i) => {
      const x = SPARK_PAD + (i / (series.length - 1)) * usableW;
      const y = SPARK_PAD + usableH - ((v - min) / range) * usableH;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');
}

function InstrumentCard({
  instrument,
  onSelect,
}: {
  instrument: Instrument;
  onSelect?: (key: string) => void;
}) {
  const points = instrument.series ? sparklinePoints(instrument.series) : '';
  // A placeholder slot has no run data yet: a neutral (flat) dot and a muted
  // value, so it reads as "not measured" rather than a real low number.
  const dotState: DotState = instrument.placeholder ? 'flat' : instrument.dotState ?? 'flat';
  // Only a backed instrument drills into a detail view — a placeholder has no
  // analyser data to show, so it stays an inert div.
  const selectable = !instrument.placeholder && !!onSelect;
  const body = (
    <>
      <div className="flex items-center justify-between">
        <p className="eyebrow text-[10px] text-subtle">{instrument.label}</p>
        <span
          data-testid={`instrument-dot-${instrument.key}`}
          data-state={dotState}
          className={dotClass(dotState)}
          aria-hidden
        />
      </div>
      <div className="mt-2 flex items-end justify-between gap-2">
        <span
          className={`display text-2xl font-bold leading-none${instrument.placeholder ? ' text-border-strong' : ''}`}
        >
          {instrument.value}
        </span>
        {/* The sparkline and delta render only when the instrument carries a
            series / deltaLabel — i.e. the metric has >=2 runs of history.
            Single-run metrics show only the value + dot. */}
        <span className="flex flex-col items-end">
          {points && (
            <svg viewBox={`0 0 ${SPARK_W} ${SPARK_H}`} className="h-6 w-16" fill="none" preserveAspectRatio="none">
              <polyline
                points={points}
                stroke={TREND_COLOR[instrument.trend.colour]}
                strokeWidth={1.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          )}
          {instrument.deltaLabel && (
            <span
              data-testid={`instrument-delta-${instrument.key}`}
              data-trend={instrument.trend.colour}
              className={`mono text-[10px] ${TREND_TEXT[instrument.trend.colour]}`}
            >
              {instrument.deltaLabel}
            </span>
          )}
        </span>
      </div>
      {instrument.sublabel && <p className="mt-2.5 text-xs text-muted-foreground">{instrument.sublabel}</p>}
    </>
  );

  const cardClass = 'panel-flat rounded-2xl p-4';
  if (selectable) {
    return (
      <button
        type="button"
        data-testid={`instrument-${instrument.key}`}
        onClick={() => onSelect?.(instrument.key)}
        className={`${cardClass} lift block w-full cursor-pointer text-left`}
      >
        {body}
      </button>
    );
  }
  return (
    <div
      data-testid={`instrument-${instrument.key}`}
      data-placeholder={instrument.placeholder ? 'true' : undefined}
      className={cardClass}
    >
      {body}
    </div>
  );
}

/**
 * The trajectory band — the reimagined mockup's two-column row under the section
 * header: an "Open issues over runs" trajectory tile beside a "Moved since last
 * run" movers panel. The trajectory tile shows an honest empty state until a
 * persisted total-open-issues series exists (we do not fabricate one — summing a
 * coverage % with lint counts is meaningless). The whole band only renders once
 * some instrument has run-over-run history; a single run has nothing to move.
 */
function TrendsBand({ instruments }: { instruments: ReadonlyArray<Instrument> }) {
  const movers = instruments.filter((i) => i.series && i.series.length >= 2);
  if (movers.length === 0) return null;

  return (
    <div className="mt-3 grid gap-3 lg:grid-cols-[1.5fr_1fr]">
      <div data-testid="quality-trajectory" className="panel flex flex-col rounded-2xl p-4">
        <p className="eyebrow text-[10px] text-subtle">Open issues over runs</p>
        <div className="flex flex-1 items-center justify-center py-8 text-center">
          <p className="max-w-xs text-xs text-muted-foreground">
            A run-spanning trend isn't available yet — it needs a persisted total across runs, not
            a fabricated one.
          </p>
        </div>
      </div>

      <div data-testid="quality-movers" className="panel-flat rounded-2xl p-4">
        <p className="eyebrow text-[10px] text-subtle">Moved since last run</p>
        <ul className="mt-2.5 space-y-2 text-sm">
          {movers.map((m) => {
            const dotState: DotState = m.dotState ?? 'flat';
            return (
              <li
                key={m.key}
                data-testid={`mover-${m.key}`}
                className="flex items-center justify-between gap-2"
              >
                <span className="flex items-center gap-2">
                  <span className={dotClass(dotState)} aria-hidden />
                  {m.label}
                </span>
                <span className={`mono text-xs ${TREND_TEXT[m.trend.colour]}`}>
                  {m.deltaLabel ?? '—'}&nbsp;&nbsp;{MOVER_WORD[m.trend.colour]}
                </span>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

/**
 * The Quality "Static Analysis Trends" section — raw analyser facts as
 * instruments, each a quantity to keep low so the trend colour is invariant (a
 * falling line is an improvement). Leads with the keep-low framing and a run/
 * analyser meta line, a trajectory band (open-issues trend + movers), then the
 * per-instrument cards. No grades, no fill-to-100 bars.
 */
export const QualityMeasured: React.FC<{
  instruments: ReadonlyArray<Instrument>;
  onSelectInstrument?: (key: string) => void;
}> = ({ instruments, onSelectInstrument }) => {
  if (instruments.length === 0) return null;

  // Honest meta: the run count is the longest real history any instrument
  // carries; the analyser count is the backed (non-placeholder) instruments.
  const runCount = instruments.reduce((max, i) => Math.max(max, i.series?.length ?? 0), 0);
  const analyserCount = instruments.filter((i) => !i.placeholder).length;
  const meta = [runCount >= 2 ? `${runCount} runs` : null, `${analyserCount} analysers`]
    .filter(Boolean)
    .join(' · ');

  return (
    <section data-testid="quality-measured">
      <div className="flex items-end justify-between gap-2">
        <div>
          <h2 className="display text-base font-semibold">Static Analysis Trends</h2>
          <p className="text-xs text-muted-foreground">
            Each signal is a quantity to <span className="font-medium text-foreground">keep low</span> —
            falling is improving, rising is regressing.
          </p>
        </div>
        <span className="mono shrink-0 text-[11px] text-subtle">{meta}</span>
      </div>

      <TrendsBand instruments={instruments} />

      <div
        data-testid="quality-measured-grid"
        className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"
      >
        {instruments.map((instrument) => (
          <InstrumentCard key={instrument.key} instrument={instrument} onSelect={onSelectInstrument} />
        ))}
      </div>
    </section>
  );
};
