import { useCallback, useEffect, useState } from 'react';
import type { SandboxProviderCatalogEntry } from '@magic-ingredients/tiny-brain-core';

/**
 * Client view of an environment as the global /api/environments routes
 * return it: credential key references never reach the client — only the
 * provider names that hold one (`keyedProviders`) — plus the probed
 * connection status.
 */
export interface EnvironmentView {
  name: string;
  provider: string;
  account?: string;
  keyedProviders: string[];
  policy?: {
    idleTimeoutMinutes?: number;
    networkIsolation?: 'isolated' | 'private';
    preWarm?: boolean;
  };
  connection:
    | { status: 'ready'; account?: string }
    | { status: 'connect-needed'; instruction: string }
    | { status: 'unavailable'; reason: string };
}

/**
 * A sandbox provider an environment can be configured on — the core
 * catalog entry verbatim (`import type` keeps the wire shape from
 * drifting; the barrel is safe for types only in client code).
 */
export type SandboxProviderView = SandboxProviderCatalogEntry;

export interface CreateEnvironmentInput {
  name: string;
  provider: string;
  account?: string;
  credentials?: Record<string, string>;
  policy?: EnvironmentView['policy'];
}

/**
 * PUT patch: like create minus the name, plus the PUT-only additive
 * `addCredentials` — new key references the server merges into the stored
 * map (existing references never reach the client, so they can't be resent).
 */
export type UpdateEnvironmentPatch = Omit<CreateEnvironmentInput, 'name'> & {
  addCredentials?: Record<string, string>;
  /** PUT-only subtractive edit — provider slots whose references drop (fix task 12). */
  removeCredentials?: string[];
};

/**
 * The Environments page's data feed: list on mount, `refresh` for the
 * connect-flow Re-check, and dumb create/update/remove that POST/PUT/DELETE
 * ids and fields for the server to validate (ADR-0021; the environment
 * surface is global — no repo in sight, only a run binds one).
 */
export function useEnvironments() {
  const [environments, setEnvironments] = useState<EnvironmentView[]>([]);
  const [providers, setProviders] = useState<SandboxProviderView[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch('/api/environments/providers');
        if (!res.ok) return; // the form degrades to no provider options
        const data = (await res.json()) as { providers: SandboxProviderView[] };
        if (!cancelled) setProviders(data.providers ?? []);
      } catch {
        // Catalog is static config — a failed fetch just leaves the
        // draft form without provider options; the list still renders.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const refresh = useCallback(async () => {
    try {
      const res = await fetch('/api/environments');
      if (!res.ok) {
        setError(`Failed to load environments (HTTP ${res.status})`);
        return;
      }
      const data = (await res.json()) as { environments: EnvironmentView[] };
      setEnvironments(data.environments ?? []);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load environments');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Shared submit for create (POST /api/environments) and update
  // (PUT /api/environments/:name): the body is sent raw for the server to
  // narrow and validate; the hook stays dumb, reporting the server's
  // { ok, error } and refreshing on success. Transport-level failure stays
  // inside the {ok,error} contract — the form renders it; nothing escapes
  // as an unhandled rejection.
  const submitEnvironment = useCallback(
    async (
      method: 'POST' | 'PUT',
      url: string,
      body: unknown,
    ): Promise<{ ok: boolean; error?: string }> => {
      try {
        const res = await fetch(url, {
          method,
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        if (!res.ok) {
          const errBody = (await res.json().catch(() => ({}))) as { error?: string };
          return { ok: false, error: errBody.error ?? `HTTP ${res.status}` };
        }
      } catch (err) {
        return {
          ok: false,
          error: err instanceof Error ? err.message : 'Failed to save environment',
        };
      }
      await refresh();
      return { ok: true };
    },
    [refresh],
  );

  const create = useCallback(
    (input: CreateEnvironmentInput) => submitEnvironment('POST', '/api/environments', input),
    [submitEnvironment],
  );

  // Edit keys on the name PARAMETER (the route), so the body carries only
  // the mutable fields — a rename is not expressible here (the server's
  // patch parser has no name field). The edit panel therefore LOCKS the name.
  const update = useCallback(
    (name: string, patch: UpdateEnvironmentPatch) =>
      submitEnvironment('PUT', `/api/environments/${encodeURIComponent(name)}`, patch),
    [submitEnvironment],
  );

  const remove = useCallback(
    async (name: string): Promise<void> => {
      try {
        const res = await fetch(`/api/environments/${encodeURIComponent(name)}`, {
          method: 'DELETE',
        });
        if (!res.ok) {
          const body = (await res.json().catch(() => ({}))) as { error?: string };
          setError(body.error ?? `Failed to delete ${name} (HTTP ${res.status})`);
          return;
        }
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : `Failed to delete ${name}`);
        return;
      }
      await refresh();
    },
    [refresh],
  );

  return { environments, providers, loading, error, refresh, create, update, remove };
}
